			name = "Camp Narache",
			short = "Verwundete Krieger ruhen im Hauptzelt von Camp Narache, dem Hauptdorf des Stammes der Hawkwind, am Nordrand der Red Cloud Mesa im Süden von Mulgore.",
			full = "Verwundete Krieger ruhen im Hauptzelt von Camp Narache, dem Hauptdorf des Stammes der Hawkwind, am Nordrand der Red Cloud Mesa im Süden von Mulgore. Um die Mitte des Lagers stehen die Lehrer des Stammes im Kreis und erweisen der gefallenen Großmutter Hawkwind ihre Ehre.\n\nHäuptling Hawkwind bildet hier die jungen Tauren aus und schickt die vielversprechenden hinaus in die Welt.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Narache",
		},
		["galak camp"] = {
			name = "Lager der Galak",
			short = "Zentauren des Stammes der Galak haben in Mulgore ein Lager aufgeschlagen. Sie erheben Anspruch auf diese Ebenen und schwören, dass die Dörfer der Tauren brennen werden.",
			full = "Zentauren des Stammes der Galak haben in Mulgore ein Lager aufgeschlagen. Sie erheben Anspruch auf diese Ebenen und schwören, dass die Dörfer der Tauren brennen werden.",
			source = "",
		},
		["gloomrise"] = {
			name = "Düsteranhöhe",
			short = "Spinnen streifen durch die Düsteranhöhe, darunter Kristallspinnen. Auch untote Tauren wandern dort umher.",
			full = "Spinnen streifen durch die Düsteranhöhe, darunter Kristallspinnen. Auch untote Tauren wandern dort umher.",
			source = "",
		},
		["golden plains"] = {
			name = "Die goldenen Ebenen",
			short = "Große Kodoherden versammeln sich auf den goldenen Ebenen, einem Becken aus wogendem grünem Gras südöstlich von Thunder Bluff.",
			full = "Große Kodoherden versammeln sich auf den goldenen Ebenen, einem Becken aus wogendem grünem Gras südöstlich von Thunder Bluff. Die Tauren zählen sie zu den wertvollsten Teilen ihrer Heimat und zu ihren liebsten Jagdgründen. Irgendwo im Gras, so heißt es, lebt die berühmte Arra'chea.",
			source = "https://warcraft.wiki.gg/wiki/Golden_Plains",
		},
		["kodo rock"] = {
			name = "Kodofels",
			short = "Der Kodofels, ein natürliches Denkmal aus Stein, steht etwa auf halbem Weg zwischen Camp Narache und der Dornrankenklamm. Man sieht ihn nicht von Weitem, deshalb muss ein Reisender genau hinsehen, um ihn zu finden.",
			full = "Der Kodofels, ein natürliches Denkmal aus Stein, steht etwa auf halbem Weg zwischen Camp Narache und der Dornrankenklamm. Man sieht ihn nicht von Weitem, deshalb muss ein Reisender genau hinsehen, um ihn zu finden.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Rock",
		},
		["palemane rock"] = {
			name = "Bleichmähnenfels",
			short = "Die Gnolle des Stammes der Bleichmähnen leben im Bleichmähnenfels, einer Höhle, die tief in den Berghang im Westen von Mulgore führt.",
			full = "Die Gnolle des Stammes der Bleichmähnen leben im Bleichmähnenfels, einer Höhle, die tief in den Berghang im Westen von Mulgore führt. Sie unterhalten auch draußen ein Lager neben der Behausung im Inneren. Sie sind aggressiv und greifen jeden an, der sich zu nahe heranwagt.",
			source = "https://warcraft.wiki.gg/wiki/Palemane_Rock",
		},
		["ravaged caravan"] = {
			name = "Überfallene Karawane",
			short = "Am nordöstlichen Ufer des Stonebullsees liegt eine Karawane der Venture Co. verbrannt auf einem Hügel, und schwarzer Rauch steigt noch immer aus dem Wrack.",
			full = "Am nordöstlichen Ufer des Stonebullsees liegt eine Karawane der Venture Co. verbrannt auf einem Hügel, und schwarzer Rauch steigt noch immer aus dem Wrack. Sie brachte Vorräte zum Bergbaubetrieb von Vorsteher Zischelspross, als die Tauren, die Goblins überall durch Mulgore hatten ziehen sehen, sie überfielen. Die Goblins, die überlebten, bleiben beim Wrack. Sie bewachen die schwelende Ladung und vertreiben jeden, der zu nahe kommt.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Caravan",
		},
		["red cloud mesa"] = {
			name = "Red Cloud Mesa",
			short = "Die Red Cloud Mesa breitet sich als offene Ebene auf den hohen Klippen im Süden von Mulgore aus und ist für ihre stille Schönheit bekannt.",
			full = "Die Red Cloud Mesa breitet sich als offene Ebene auf den hohen Klippen im Süden von Mulgore aus und ist für ihre stille Schönheit bekannt. Camp Narache liegt in ihrer Nordwestecke, das wichtigste Ausbildungslager für die Jungen der Tauren. Hier bewähren sie sich gegen die Borstennacken-Stacheleber, die im Nordosten die Dornrankenklamm halten.",
			source = "https://warcraft.wiki.gg/wiki/Red_Cloud_Mesa",
		},
		["red rocks"] = {
			name = "Teufelsfelsen",
			short = "Roter Sandstein erhebt sich im Nordosten von Mulgore. Die Tauren schicken ihre tapfersten Toten hierher, zur Erdenmutter und zum Himmelsvater, durch läuterndes Feuer.",
			full = "Roter Sandstein erhebt sich im Nordosten von Mulgore. Die Tauren schicken ihre tapfersten Toten hierher, zur Erdenmutter und zum Himmelsvater, durch läuterndes Feuer. Nur Krieger, die halfen, Thunder Bluff zu gründen und zu verteidigen, oder ihr Leben für ihre Stämme und Häuptlinge gaben, erhalten diese Ehre. Auch junge Krieger kommen zu den Steinen, um ins Erwachsenenalter einzutreten und im Wind auf den Segen ihrer Ahnen zu lauschen. Borstennacken-Stacheleber sind kürzlich eingebrochen und haben den heiligen Boden besudelt, und die Tauren von Thunder Bluff sind wütend.",
			source = "https://warcraft.wiki.gg/wiki/Red_Rocks",
		},
		["rolling plains"] = {
			name = "Die wogenden Ebenen",
			short = "Wölfe, Kodos, Weitschreiter und Pumas teilen sich das Gras der wogenden Ebenen, die einen großen Teil des südlichen Mulgore bedecken und von Bloodhoof bis zur Grenze des Brachlands reichen.",
			full = "Wölfe, Kodos, Weitschreiter und Pumas teilen sich das Gras der wogenden Ebenen, die einen großen Teil des südlichen Mulgore bedecken und von Bloodhoof bis zur Grenze des Brachlands reichen. Zentaurenspäher streifen über die offenen Felder. Ein Nest von Windfurienharpyien liegt im östlichen Teil.",
			source = "https://warcraft.wiki.gg/wiki/Rolling_Plains",
		},
		["skywatcher plateau"] = {
			name = "Himmelsschauerplateau",
			short = "Ein Pfad steigt zu einem hohen Plateau nordwestlich von Thunder Bluff und endet an einem bemalten Fels. Kleine Tiere drängen sich auf dem Gipfel, wo der Irdene Ring ein Lager unterhält.",
			full = "Ein Pfad steigt zu einem hohen Plateau nordwestlich von Thunder Bluff und endet an einem bemalten Fels. Kleine Tiere drängen sich auf dem Gipfel, wo der Irdene Ring ein Lager unterhält.",
			source = "",
		},
		["stonebull lake"] = {
			name = "Stonebullsee",
			short = "Ein langes Hufeisen aus kühlem Wasser umschließt Bloodhoof im Zentrum von Mulgore auf drei Seiten. Fische gibt es reichlich, und viele Stunden vergehen damit, Angeln in den See zu werfen.",
			full = "Ein langes Hufeisen aus kühlem Wasser umschließt Bloodhoof im Zentrum von Mulgore auf drei Seiten. Fische gibt es reichlich, und viele Stunden vergehen damit, Angeln in den See zu werfen. An der schmalsten Stelle führt eine Brücke hinüber, und die Straße über die Brücke verbindet Thunder Bluff mit dem Dorf.",
			source = "https://warcraft.wiki.gg/wiki/Stonebull_Lake",
		},
		["thunderhorn water well"] = {
			name = "Wasserbrunnen von Thunderhorn",
			short = "Im offenen Gras neben der Nordstraße zwischen Thunder Bluff und Bloodhoof steht der Wasserbrunnen von Thunderhorn, einer der drei heiligen Brunnen der Tauren.",
			full = "Im offenen Gras neben der Nordstraße zwischen Thunder Bluff und Bloodhoof steht der Wasserbrunnen von Thunderhorn, einer der drei heiligen Brunnen der Tauren. Die Venture Co. hat ihn besetzt, um die Wasserversorgung zu kontrollieren.",
			source = "https://warcraft.wiki.gg/wiki/Thunderhorn_Water_Well",
		},
		["venture co mine"] = {
			name = "Die Mine der Venture Co.",
			short = "Der Venture Co. wurden die Schürfrechte in Mulgore verweigert, und sie grub trotzdem. Ihre Mine schneidet in die östlichen Klippen, und Vorsteher Zischelspross leitet sie.",
			full = "Der Venture Co. wurden die Schürfrechte in Mulgore verweigert, und sie grub trotzdem. Ihre Mine schneidet in die östlichen Klippen, und Vorsteher Zischelspross leitet sie. Mogul Razdunk und der Beirat drängen ihn nun, auch das Holz von Mulgore zu nehmen. Sie wollen ihm ihre neuesten Schredder und das Material für den Bau eines Sägewerks schicken. Die Tauren sind über den Eingriff zornig.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Mine",
		},
		["wildmane water well"] = {
			name = "Wasserbrunnen von Wildmane",
			short = "Nördlich von Thunder Bluff liegt der nördlichste der heiligen Wasserbrunnen der Tauren, der Wasserbrunnen von Wildmane. Auch ihn hat die Venture Co. besetzt.",
			full = "Nördlich von Thunder Bluff liegt der nördlichste der heiligen Wasserbrunnen der Tauren, der Wasserbrunnen von Wildmane. Auch ihn hat die Venture Co. besetzt.",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "Windfurienkamm",
			short = "Harpyien nisten in der Höhe des Windfurienkamms und stürzen herab, um jeden zu töten oder zu verschleppen, der sich in die Nähe ihrer Nester verirrt.",
			full = "Harpyien nisten in der Höhe des Windfurienkamms und stürzen herab, um jeden zu töten oder zu verschleppen, der sich in die Nähe ihrer Nester verirrt. Wilde Pumas und Wölfe streifen durch die Hügel ringsum. Die Tauren von Thunder Bluff jagen die Harpyien noch immer, weil ihre schillernden Federn Hochzeiten und Feste schmücken.",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "Wasserbrunnen von Winterhoof",
			short = "Der Wasserbrunnen von Winterhoof liegt am Rand der wogenden Ebenen im Süden von Mulgore.",
			full = "Der Wasserbrunnen von Winterhoof liegt am Rand der wogenden Ebenen im Süden von Mulgore. Jahre nach dem Dritten Krieg riss die Venture Co. ihn an sich und vergiftete sein Wasser, um die Versorgung der Tauren abzuschnüren. Mull Thunderhorn fertigt Totems, um die Verseuchung zu reinigen, doch der Brunnen ist noch nicht rein.",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- Das Brachland: 31 subzones
	[1413] = {
		["agamagor"] = {
			name = "Agama'gor",
			short = "Die Borstennacken-Stacheleber halten hier eine große Siedlung, nördlich der Straße, die von Camp Taurajo nach Westen führt.",
			full = "Die Borstennacken-Stacheleber halten hier eine große Siedlung, nördlich der Straße, die von Camp Taurajo nach Westen führt. Sie graben Blutscherben aus dem Boden und tragen sie als Totems der Stärke und Magie in den Kampf.",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "Bael Modan",
			short = "Die steinerne Burg Bael'dun erhebt sich dort, wo einst ein Dorf der Stonespire-Tauren stand, und daneben haben die Zwerge von Ironforge eine Grabungsstätte eröffnet.",
			full = "Die steinerne Burg Bael'dun erhebt sich dort, wo einst ein Dorf der Stonespire-Tauren stand, und daneben haben die Zwerge von Ironforge eine Grabungsstätte eröffnet. Unter dem Hügel liegt eine uralte Forschungsanlage der Titanen. Die Zwerge graben darauf zu, und ihre Relikte liegen größtenteils unberührt im Dunkeln.\n\nDie Zwerge graben mit Sprengstoff, und die Stonespire hielten diesen Boden für heilig. Der größte Teil des Stammes wurde getötet oder vertrieben, und das alte Dorf ist von Grabungsmaschinen zerrissen. Gann Stonespire, ein Tauren, der auf den Straßen in der Nähe wandert, versuchte, die Sache im Gespräch zu klären, und kam nicht weiter. Jetzt sinnt er auf Rache.",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "Burg Bael'dun",
			short = "General Twinbraid, ein listiger Kommandant, beherrscht die Zwergenfestung, die über der Grabungsstätte von Bael Modan im südlichen Brachland aufragt.",
			full = "General Twinbraid, ein listiger Kommandant, beherrscht die Zwergenfestung, die über der Grabungsstätte von Bael Modan im südlichen Brachland aufragt. Die Zwerge unter ihm sind der Horde feindlich gesinnt. Als die Gräber einen Stein namens Träne der Monde zutage förderten, machte er einen Zwerg namens Feegly wahnsinnig, und Twinbraid verbannte ihn aus der Burg.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "Schwarzdorngrat",
			short = "Dornen drängen sich in diesem Tal, gleich nördlich vom Kral von Razorfen, der Hauptstadt der Stacheleber, und Grimmhauer-Stacheleber halten den Boden.",
			full = "Dornen drängen sich in diesem Tal, gleich nördlich vom Kral von Razorfen, der Hauptstadt der Stacheleber, und Grimmhauer-Stacheleber halten den Boden. Auf einem Hügel am Nordende des Grats hat eine Orc-Schamanin namens Brine ihr Lager. Sie ist Expertin für die Geister und die Natur des Wassers. Direkt unterhalb des Lagers liegt ein Teich mit auffallend klarem, reinem Wasser.",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "Felsadermine",
			short = "Die Venture Co. hält diese Mine im Nordosten des Brachlands, und Boss Kupferdraht leitet sie. Kupferdraht war einst der beste Ingenieur der Tüftlerunion.",
			full = "Die Venture Co. hält diese Mine im Nordosten des Brachlands, und Boss Kupferdraht leitet sie. Kupferdraht war einst der beste Ingenieur der Tüftlerunion. Er lief zur Venture Co. über und nahm seine besten Verfahren mit, darunter die Samophlange, ein Gerät, das er erfunden hat und dessen Geheimnisse er in Stücken an wenige vertraute Goblins weitergibt.\n\nOrcische Stützbalken und Banner der Horde hängen noch in den Stollen, und die Mine scheint einst der Horde gehört zu haben.",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "Dornennarbe",
			short = "Ein Stamm der Grimmhauer-Stacheleber hat seinen Bau in der Dornennarbe. Auf der anderen Seite der Straße bei Agama'gor hält der Stamm der Borstennacken eine Siedlung, und die beiden Stämme befinden sich im Krieg.",
			full = "Ein Stamm der Grimmhauer-Stacheleber hat seinen Bau in der Dornennarbe. Auf der anderen Seite der Straße bei Agama'gor hält der Stamm der Borstennacken eine Siedlung, und die beiden Stämme befinden sich im Krieg. Die Grimmhauer greifen jeden an, der sich in die Nähe ihres Baus verirrt.",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "Camp Taurajo",
			short = "Tauren unterhalten hier im Brachland, nahe dem Gebirgspass, der nach Mulgore führt, einen Außenposten. Er hat ein Gasthaus für Reisende, die aus der Heimat der Tauren kommen.",
			full = "Tauren unterhalten hier im Brachland, nahe dem Gebirgspass, der nach Mulgore führt, einen Außenposten. Er hat ein Gasthaus für Reisende, die aus der Heimat der Tauren kommen. Das Lager hält auch einen Gefangenen, den Grimmhauer-Stacheleber Quetschzahn, den die Orcs und Tauren gefangen nahmen und der auf seine Hinrichtung wartet.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["crossroads"] = {
			name = "Crossroads",
			short = "Zwei Straßen kreuzen sich hier, die Goldstraße, die nach Norden und Süden verläuft, und die Straße, die von Ratchet zum Steinkrallengebirge führt.",
			full = "Zwei Straßen kreuzen sich hier, die Goldstraße, die nach Norden und Süden verläuft, und die Straße, die von Ratchet zum Steinkrallengebirge führt. Crossroads ist die größte Stadt der Horde im Brachland, mit wenigen Unterkünften und sehr viel Handel, und Händler rufen ihre Waren über die Stände.\n\nThork, ein Orc, leitet ihre Verteidigung. Raptoren stahlen einst eine Silberlieferung aus dem Wachturm, den Sold für die Wachen. Gleich hinter der Siedlung liegt ein Begräbnisplatz, wo die Horde ihren Toten die Ehre erweist.",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "Glutnebelbau",
			short = "Im Inneren des Glutnebelgipfels unterhält die Burning Blade einen Bau, eingehüllt in einen dunkelroten Nebel und ein endloses Zwielicht.",
			full = "Im Inneren des Glutnebelgipfels unterhält die Burning Blade einen Bau, eingehüllt in einen dunkelroten Nebel und ein endloses Zwielicht. Die Kultisten, die dort leben, beten Dämonen an, und der Nebel verhüllt sie. Im Inneren liegt der Dämonensamen, ein Artefakt, das der Kult für unschätzbar hält.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "Glutnebelgipfel",
			short = "Nordwestlich von Crossroads steigt der Glutnebelgipfel in einen roten Nebel hinauf. Der Nebel wird zum Gipfel hin dichter und ist alles, was von einem uralten Dämonenfluch geblieben ist.",
			full = "Nordwestlich von Crossroads steigt der Glutnebelgipfel in einen roten Nebel hinauf. Der Nebel wird zum Gipfel hin dichter und ist alles, was von einem uralten Dämonenfluch geblieben ist. Kultisten der Burning Blade haben dort oben ihre Heimat.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "Die trockenen Hügel",
			short = "Trotz ihres Namens gehören die trockenen Hügel zu den grüneren Gegenden des Brachlands. Sie liegen in der äußersten Nordwestecke, im Vorgebirge des Steinkrallengebirges.",
			full = "Trotz ihres Namens gehören die trockenen Hügel zu den grüneren Gegenden des Brachlands. Sie liegen in der äußersten Nordwestecke, im Vorgebirge des Steinkrallengebirges. Hexenschwingen-Harpyien halten sie unter Serena Blutfeder und haben in letzter Zeit die Karawanen auf der nördlichen Goldstraße überfallen. Ein verlassener Orc-Wachturm und ein paar Katapulte stehen mitten in den Hügeln.",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "Farwatch-Posten",
			short = "Gleich westlich der Brücke zwischen Durotar und dem Brachland unterhält die Horde einen Wachturm und ein paar Katapulte.",
			full = "Gleich westlich der Brücke zwischen Durotar und dem Brachland unterhält die Horde einen Wachturm und ein paar Katapulte. Daneben steht ein Orc-Bau, und zwei Peons versorgen ein Gehege für Reitwölfe ein kurzes Stück südlich. Es ist kein angenehmer Posten. Versorgungskarawanen sind auf ihn angewiesen, und er hilft, Durotar vor der Allianz und den Stachelebern sicher zu halten.",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "Feld der Riesen",
			short = "Herden von Donnerechsen und Kodos streifen über das Feld der Riesen, über die südlichsten Ebenen des Brachlands. Der südliche Abschnitt der Goldstraße führt mitten hindurch, schlechter verteidigt als der nördliche.",
			full = "Herden von Donnerechsen und Kodos streifen über das Feld der Riesen, über die südlichsten Ebenen des Brachlands. Der südliche Abschnitt der Goldstraße führt mitten hindurch, schlechter verteidigt als der nördliche. Seine Wachtürme wirken verlassen.\n\nDie Horde hat das Feld nicht aufgegeben. Der weise Schamane Brine lebt auf einem Grat an seiner Südgrenze. Der Tauren Gann Stonespire, dessen Stamm sein Dorf an die Zwerge verlor, sinnt hier auf Rache.",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "Die vergessenen Teiche",
			short = "Die vergessenen Teiche liegen nördlich der westlichen Straße aus Crossroads, die nördlichste der Oasen, die über den Norden des Brachlands verstreut sind.",
			full = "Die vergessenen Teiche liegen nördlich der westlichen Straße aus Crossroads, die nördlichste der Oasen, die über den Norden des Brachlands verstreut sind. Ihre Ufer bleiben grün, gesäumt von Beladenen Pilzen, die nirgendwo sonst zu finden sind, und ihr Wasser birgt Deviatfische, die keinem anderen Fang im Brachland gleichen.\n\nKolkarzentauren streifen am Ufer entlang, neben den Schildkröten und Tieren, die dort Zuflucht suchen.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "Prügel-Eiland",
			short = "Krieger aller Völker und Bekenntnisse trainieren auf dem Prügel-Eiland unter einem Menschen namens Klannoc Macleod. Die Insel ist klein und trocken und liegt vor der Ostküste des Brachlands.",
			full = "Krieger aller Völker und Bekenntnisse trainieren auf dem Prügel-Eiland unter einem Menschen namens Klannoc Macleod. Die Insel ist klein und trocken und liegt vor der Ostküste des Brachlands.",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "Goldstraße",
			short = "Die lange Fernstraße des Brachlands, die Goldstraße, beginnt am Mor'shan-Schutzwall im Norden und führt nach Süden durch das Land bis zu einer Brücke, die die nördliche Hälfte des Brachlands mit der südlichen verbindet.",
			full = "Die lange Fernstraße des Brachlands, die Goldstraße, beginnt am Mor'shan-Schutzwall im Norden und führt nach Süden durch das Land bis zu einer Brücke, die die nördliche Hälfte des Brachlands mit der südlichen verbindet. Hinter der Brücke heißt sie Südliche Goldstraße.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "Grol'doms Hof",
			short = "Kranal Fiss und seine Kinder züchten auf Grol'doms Hof Schweine, einem der vielen Orc-Höfe, die seit der Gründung von Orgrimmar entstanden sind.",
			full = "Kranal Fiss und seine Kinder züchten auf Grol'doms Hof Schweine, einem der vielen Orc-Höfe, die seit der Gründung von Orgrimmar entstanden sind. Grimmhauer-Stacheleber überfallen ihn ständig.",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["lushwater oasis"] = {
			name = "Die blühende Oase",
			short = "Die blühende Oase liegt gleich südlich von Crossroads, eine der drei großen Oasen des Brachlands. Wilde Tiere kommen an ihre Teiche zum Trinken, und Kolkar-Zentauren pirschen zwischen den Bäumen und jagen sie.",
			full = "Die blühende Oase liegt gleich südlich von Crossroads, eine der drei großen Oasen des Brachlands. Wilde Tiere kommen an ihre Teiche zum Trinken, und Kolkar-Zentauren pirschen zwischen den Bäumen und jagen sie.\n\nEin Höhleneingang hier öffnet sich in die Höhlen des Wehklagens, die verflucht genannt werden. Die Lebensenergie im Wasser der Oase soll aus ihnen fließen.",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "Die Händlerküste",
			short = "Die Händlerküste verdankt ihren Namen dem Handel, der an ihr entlang läuft, und all das geht durch die sparsamen Hände der Goblins von Ratchet.",
			full = "Die Händlerküste verdankt ihren Namen dem Handel, der an ihr entlang läuft, und all das geht durch die sparsamen Hände der Goblins von Ratchet. Die Südmeerfreibeuter halten den südlichen Küstenabschnitt. Gazlowe, der Ratchet führt, hat ein Kopfgeld auf Baron Küstenschipper ausgesetzt, wegen Piraterie und weil er Schiffe der Freibeuter anführt.",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "Mor'shan-Stützpunkt",
			short = "Der Mor'shan-Stützpunkt liegt gleich südlich der Grenze zu Ashenvale, nahe dem Mor'shan-Schutzwall. Er ist eine der größeren Siedlungen der Horde im Brachland und der Stützpunkt der Warsongvorhut.",
			full = "Der Mor'shan-Stützpunkt liegt gleich südlich der Grenze zu Ashenvale, nahe dem Mor'shan-Schutzwall. Er ist eine der größeren Siedlungen der Horde im Brachland und der Stützpunkt der Warsongvorhut.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "Der Mor'shan-Schutzwall",
			short = "Wo die Goldstraße im Norden endet, errichtete die Horde den Mor'shan-Schutzwall, um den Vorstoß der Allianz aus Ashenvale aufzuhalten.",
			full = "Wo die Goldstraße im Norden endet, errichtete die Horde den Mor'shan-Schutzwall, um den Vorstoß der Allianz aus Ashenvale aufzuhalten. Es ist ein behelfsmäßiger Verteidigungsposten, der um Wachtürme herum gebaut wurde. Die Orcs nutzen ihn auch als Ausgangspunkt für Überfälle auf Astranaar, die Nachtelfenstadt im Norden.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "Raptorgründe",
			short = "Sonnenschuppenraptoren drängen sich in einem winzigen Tal im südlichen Brachland, und sie sind eigentümlich unter ihresgleichen. Sie zeigen eine unnatürliche Intelligenz.",
			full = "Sonnenschuppenraptoren drängen sich in einem winzigen Tal im südlichen Brachland, und sie sind eigentümlich unter ihresgleichen. Sie zeigen eine unnatürliche Intelligenz. Sie bauen grobe Hütten und stellen eigene Werkzeuge her. Alles, was glänzt oder auch nur ungewöhnlich ist, zieht sie an, und sie haben viele Dinge aus den Siedlungen der Horde in der Nähe gestohlen.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "Ratchet",
			short = "Gazlowe wurde von Kriegshäuptling Thrall gut bezahlt für die Hilfe, die er und seine Arbeiter beim Aufbau von Orgrimmar nach dem Dritten Krieg leisteten.",
			full = "Gazlowe wurde von Kriegshäuptling Thrall gut bezahlt für die Hilfe, die er und seine Arbeiter beim Aufbau von Orgrimmar nach dem Dritten Krieg leisteten. Einige Zeit nach der Fertigstellung der Stadt gründete er Ratchet an der Ostküste des Brachlands. Schmuggler machten den Anfang, und der Ort füllte sich mit all jenen, die andere Gesellschaften ausgestoßen hatten.\n\nHeute ist es ein Hafen der Goblins, und der größte Teil seines Handels läuft über Booty Bay und Baron Revilgaz auf der anderen Seite des Meeres. Ein Koven von Hexenmeistern lebt in einem Turm über der Stadt.",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["shrine of the fallen warrior"] = {
			name = "Schrein des gefallenen Kriegers",
			short = "Ein kurzer Pfad führt einen kleinen Hügel westlich von Crossroads hinauf zu einem Schrein. Es ist ein steinerner Obelisk mit den Initialen M K, in seinen Sockel geritzt.",
			full = "Ein kurzer Pfad führt einen kleinen Hügel westlich von Crossroads hinauf zu einem Schrein. Es ist ein steinerner Obelisk mit den Initialen M K, in seinen Sockel geritzt. Ein Geistheiler namens Koiter steht davor.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "Das Schlickermoor",
			short = "Ein Teich aus kristallblauem Wasser lag einst hier. Dann baute die Venture Co. eine Ölbohrinsel darauf und verwandelte ihn in einen Sumpf aus Industrieabfall.",
			full = "Ein Teich aus kristallblauem Wasser lag einst hier. Dann baute die Venture Co. eine Ölbohrinsel darauf und verwandelte ihn in einen Sumpf aus Industrieabfall. Vorsteher Lugwizz, ein Goblin, leitet den Betrieb.\n\nDie Tüftlerunion in Ratchet beneidet die Firma um ihre neueren Schredder. Stotterspritter, der ihre Schredderarbeiten leitet, würde den Entwurf lieber stehlen als verbessern, und er hat einen Goblin namens Wizzlecrank geschickt, um eine der Maschinen an sich zu bringen.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "Südliche Goldstraße",
			short = "Handelskarawanen geben der Südlichen Goldstraße ihren Namen. Sie führt vom Großen Aufzug am Südende des Brachlands bis zu der Brücke, die die nördliche und die südliche Hälfte des Landes verbindet.",
			full = "Handelskarawanen geben der Südlichen Goldstraße ihren Namen. Sie führt vom Großen Aufzug am Südende des Brachlands bis zu der Brücke, die die nördliche und die südliche Hälfte des Landes verbindet. Nördlich der Brücke heißt sie einfach Goldstraße.\n\nHändler kommen auf ihr aus so fernen Orten wie Gadgetzan in Tanaris, Auberdine an der Dunkelküste und Nighthaven im Norden.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "Der Südstrom",
			short = "Auf der Seite des Brachlands bildet der Südstrom die Grenze zu Durotar, und eine seiner drei Brücken trägt die Straße von Durotar ins Brachland hinüber.",
			full = "Auf der Seite des Brachlands bildet der Südstrom die Grenze zu Durotar, und eine seiner drei Brücken trägt die Straße von Durotar ins Brachland hinüber. An seiner Mündung stürzt der Fluss über einen gestuften Wasserfall ins Große Meer, nordöstlich von Ratchet.\n\nGleich nördlich der westlichen Brücke nach Orgrimmar gibt es einen Flussabschnitt, an dem Ashenvale, Azshara, Durotar und das Brachland alle zusammentreffen.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "Die brackige Oase",
			short = "Kolkar-Zentauren lagern am Rand der brackigen Oase, die zwischen der Händlerküste und der Goldstraße liegt.",
			full = "Kolkar-Zentauren lagern am Rand der brackigen Oase, die zwischen der Händlerküste und der Goldstraße liegt. Verirrte Kodos des Brachlands streifen hier umher, geschwächt und einzeln, und weit leichter zu jagen als die Kodos des Südens. Deviatfische schwimmen im Wasser, und auch Oasen-Schnappkiefer leben dort.",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "Dornenhügel",
			short = "Tortusk führt die Grimmhauer-Stacheleber auf dem Dornenhügel, einer ansehnlichen Siedlung an der Nordflanke eines Berggipfels zwischen Crossroads und Durotar.",
			full = "Tortusk führt die Grimmhauer-Stacheleber auf dem Dornenhügel, einer ansehnlichen Siedlung an der Nordflanke eines Berggipfels zwischen Crossroads und Durotar. In letzter Zeit haben seine Leute Karawanen der Horde in der Region überfallen, und die Wachen vor Ort sind darüber zornig.",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "Die Tidusstaffel",
			short = "Breite Steinterrassen erheben sich über der Küste südöstlich von Ratchet, wie eine riesige Treppe aufgeschichtet, die über einen Teil der Händlerküste blickt.",
			full = "Breite Steinterrassen erheben sich über der Küste südöstlich von Ratchet, wie eine riesige Treppe aufgeschichtet, die über einen Teil der Händlerküste blickt. Zwei Tauren, Islen Wasserdeuter und Mahren Himmelsdeuter, sitzen dort, um zu fischen und mit den Wassergeistern zu sprechen.",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "Die Höhlen des Wehklagens",
			short = "Der Nachtelfen-Druide Naralex fand diese Höhlen und benannte sie nach dem klagenden Heulen von Wind und Dampf im Fels.",
			full = "Der Nachtelfen-Druide Naralex fand diese Höhlen und benannte sie nach dem klagenden Heulen von Wind und Dampf im Fels. Unterirdische Flüsse laufen meilenweit unter der Savanne und sprudeln als kleine Oasen quer durch das Brachland empor. Von vorn sieht der Eingang vage wie ein Schlangenschädel aus.\n\nNaralex glaubte, dass die Verbindung dieser Wasser mit dem Smaragdgrünen Traum das Land wieder grün machen würde. Er stieg mit seinen treuen Schülern hinab und versank in Meditation und ließ den Traum durch seinen Körper nach Azeroth reichen. Stattdessen überwältigte ihn der Smaragdgrüne Alptraum. Die Wasser wurden verdorben, die Tierwelt verwandelte sich in Deviatformen, und die meisten seiner Schüler verfielen dem Wahnsinn und wurden zu den Druiden des Giftzahns.",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- Alteracgebirge: 6 subzones
	[1416] = {
		["dalaran"] = {
			name = "Dalaran",
			short = "Magier des Imperiums von Arathor gründeten Dalaran nach den Trollkriegen, und es wuchs zu einer Nation heran, die von den Kirin Tor unter dem Rat der Sechs regiert wurde.",
			full = "Magier des Imperiums von Arathor gründeten Dalaran nach den Trollkriegen, und es wuchs zu einer Nation heran, die von den Kirin Tor unter dem Rat der Sechs regiert wurde. Seine Violette Zitadelle war das Heiligtum derer, die das Arkane studierten, und keine Stadt außerhalb von Quel'Thalas besaß eine so große Ansammlung magischer Macht. Die meisten menschlichen und hochelfischen Magier beugten sich der Oberhoheit der Kirin Tor.\n\nDie Geißel belagerte die Stadt, und der Dämonenlord Archimonde zerstörte sie. Die überlebenden Zauberer kehrten zurück und errichteten eine riesige Kuppel aus Magie über dem Herzen der Stadt. Nichts Bekanntes kann sie durchdringen. Manche sagen, die Zauberer wollten Schutz, andere, sie wollten Einsamkeit zum Studieren und Ränkeschmieden.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "Dandreds Senke",
			short = "Ein kleiner Hof mit Herrenhaus liegt am Westrand des Oberlands, wo sich ein Hafen zum Lordameresee öffnet. Lord Aliden Perenolde lebt hier.",
			full = "Ein kleiner Hof mit Herrenhaus liegt am Westrand des Oberlands, wo sich ein Hafen zum Lordameresee öffnet. Lord Aliden Perenolde lebt hier. Er ist der älteste Sohn von König Aiden Perenolde von Alterac und der letzte bekannte Anführer des Syndikats. Er bezeichnet sich als Herr der Berge und will die Orcs wieder in Ketten legen.\n\nSeine Geliebte Elysa lebt bei ihm, und Meuchelmörder und Schläger des Syndikats sind in der Nähe einquartiert.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["lordamere internment camp"] = {
			name = "Lordamere-Internierungslager",
			short = "Das Lordamere-Internierungslager steht auf einem Hügel mit Blick auf Dalaran, das einzige Internierungslager im Alteracgebirge. Zauberer von Dalaran halten es, und Aufseherin Belamoor befehligt die Garnison.",
			full = "Das Lordamere-Internierungslager steht auf einem Hügel mit Blick auf Dalaran, das einzige Internierungslager im Alteracgebirge. Zauberer von Dalaran halten es, und Aufseherin Belamoor befehligt die Garnison.\n\nVier desertierte Verlassene unter Kegan Dunkelmar stahlen die Blutsteinartefakte aus einem Gewölbe in Undercity. Die Steine gehören Fürstin Sylvanas Windrunner. Die Zauberer halten sie hier unter Quarantäne, und die Aufseherin studiert sie. Sie hat herausgefunden, dass sie weder lebendig noch tot sind und dass sie Blut trinken.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["old dalaran ruins"] = {
			name = "Die Ruinen des alten Dalaran",
			short = "Zerbrochene Häuser, Scheunen, Türme und Mauern liegen verstreut um den Rand der violetten Kuppel, die Dalaran verbirgt. Zauberer der Kirin Tor und ihre Erdelementare patrouillieren in den zerstörten Außenbezirken.",
			full = "Zerbrochene Häuser, Scheunen, Türme und Mauern liegen verstreut um den Rand der violetten Kuppel, die Dalaran verbirgt. Zauberer der Kirin Tor und ihre Erdelementare patrouillieren in den zerstörten Außenbezirken.",
			source = "",
		},
		["ruins of alterac"] = {
			name = "Die Ruinen von Alterac",
			short = "König Aiden Perenolde von Alterac verlor im Zweiten Krieg die Hoffnung auf einen Sieg der Menschen und schloss einen Pakt mit der Horde.",
			full = "König Aiden Perenolde von Alterac verlor im Zweiten Krieg die Hoffnung auf einen Sieg der Menschen und schloss einen Pakt mit der Horde. Die Orcs konnten sein Land ungehindert durchqueren, und er würde im Gegenzug geschützt werden. Soldaten aus Alterac wurden dabei entdeckt, wie sie an der Seite der Orcs kämpften, und ein Gefangenenlager nahe der Stadt hielt gefangene Bürger von Dalaran fest. Als der Verrat herauskam, marschierten die anderen Menschenkönigreiche gegen seine Stadt. König Terenas Menethil II. von Lordaeron stellte sie unter Kriegsrecht und warf ihn ins Gefängnis.\n\nCrushridge-Oger unter dem Kriegsherrn Mug'thol leben jetzt in den Ruinen. Der Palast steht halb unversehrt, auch wenn Kirche und Rathaus in Trümmern liegen, und das Tor ist ähnlich gebaut wie das in Stormwind. Zerstörte Fleischwagen liegen am Tor, und zerschmetterte Ballisten bedecken den Schutt.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "Das Oberland",
			short = "Diese Hügel waren die Kornkammer des Königreichs Alterac. Als das Königreich fiel, übernahm das Syndikat sie und schlug hier mehrere Lager auf.",
			full = "Diese Hügel waren die Kornkammer des Königreichs Alterac. Als das Königreich fiel, übernahm das Syndikat sie und schlug hier mehrere Lager auf. Nirgendwo in den Bergen sind sie stärker.\n\nBaron Vardus, einst ein Adliger aus Alterac und jetzt Quartiermeister des Syndikats, ist in diesen Lagern zu finden.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- Arathihochland: 19 subzones
	[1417] = {
		["boulderfist hall"] = {
			name = "Halle der Felsfäuste",
			short = "Kor'gresh Frostzorn, ein Ogermagier und Häuptling des Klans der Felsfäuste, hält die größere Höhle in diesem stark befestigten Hügel der Oger.",
			full = "Kor'gresh Frostzorn, ein Ogermagier und Häuptling des Klans der Felsfäuste, hält die größere Höhle in diesem stark befestigten Hügel der Oger. Er liegt im Süden, nahe dem Thandol-Übergang und Witherbark. Der Stab, den er trägt, schleudert Frost.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
		},
		["bouldergor"] = {
			name = "Fels'gor",
			short = "Ein rauer, zerklüfteter Hügel erhebt sich nördlich von Burg Stromgarde. Oger der Felsfäuste haben dort ihren Hort, und Bleichborke-Waldtrolle lungern neben ihnen an den Hängen.",
			full = "Ein rauer, zerklüfteter Hügel erhebt sich nördlich von Burg Stromgarde. Oger der Felsfäuste haben dort ihren Hort, und Bleichborke-Waldtrolle lungern neben ihnen an den Hängen.",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["circle of east binding"] = {
			name = "Kreis der östlichen Bindung",
			short = "Der Stein der östlichen Bindung steht im Osten des Arathihochlands, nahe Hammerfall, bewacht von Wasserelementaren.",
			full = "Der Stein der östlichen Bindung steht im Osten des Arathihochlands, nahe Hammerfall, bewacht von Wasserelementaren. Die Berggiganten stellten ihn hier mit drei weiteren Steinen auf, um Myzrael zu binden, eine Elementarprinzessin.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of inner binding"] = {
			name = "Kreis der inneren Bindung",
			short = "Der stärkste der vier Steine liegt hier, im Süden nahe Burg Stromgarde. Erdelementare bewachen den Stein der inneren Bindung.",
			full = "Der stärkste der vier Steine liegt hier, im Süden nahe Burg Stromgarde. Erdelementare bewachen den Stein der inneren Bindung. Durch seine Scherbe hat Myzrael, die Elementarprinzessin, die die Berggiganten gebunden haben, einen Weg gefunden, mit sterblichen Reisenden zu sprechen.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "Kreis der äußeren Bindung",
			short = "Luftelementare kreisen um den Stein der äußeren Bindung in der Mitte des Hochlands, nahe der Zuflucht. Er ist einer von vier Steinen, die die Berggiganten aufstellten, um die Elementarprinzessin Myzrael festzuhalten.",
			full = "Luftelementare kreisen um den Stein der äußeren Bindung in der Mitte des Hochlands, nahe der Zuflucht. Er ist einer von vier Steinen, die die Berggiganten aufstellten, um die Elementarprinzessin Myzrael festzuhalten.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "Kreis der westlichen Bindung",
			short = "Feuerelementare bewachen den Stein der westlichen Bindung im Westen des Hochlands, nahe Thoradinswall. Die Berggiganten stellten ihn mit drei weiteren auf, um Myzrael zu binden, eine Elementarprinzessin.",
			full = "Feuerelementare bewachen den Stein der westlichen Bindung im Westen des Hochlands, nahe Thoradinswall. Die Berggiganten stellten ihn mit drei weiteren auf, um Myzrael zu binden, eine Elementarprinzessin.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["dabyries farmstead"] = {
			name = "Bauernhof der Dabyries",
			short = "Kenata Dabyrie bewirtschaftet mit ihren Kindern Fardel und Marcel den Norden des Arathihochlands. Sie sind Bürger von Stromgarde und der Allianz treu ergeben, und eine Miliz bewacht ihre Felder.",
			full = "Kenata Dabyrie bewirtschaftet mit ihren Kindern Fardel und Marcel den Norden des Arathihochlands. Sie sind Bürger von Stromgarde und der Allianz treu ergeben, und eine Miliz bewacht ihre Felder.\n\nSie überstanden den Dritten Krieg und kamen zu Wohlstand. Genavie Kahler, eine Verlassene, die ihre Familie durch die Seuche und ihr Anwesen durch Plünderer und Feuer verlor, hegt einen Groll gegen sie.",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "Das versunkene Riff",
			short = "Eine zerstörte Elfenstadt liegt versunken unter der Bucht an der Südküste, und die Säbelflossen-Naga unter Prinz Nazjak haben sie zu ihrer gemacht.",
			full = "Eine zerstörte Elfenstadt liegt versunken unter der Bucht an der Südküste, und die Säbelflossen-Naga unter Prinz Nazjak haben sie zu ihrer gemacht. Das Riff darüber hat viele Schiffe zerschellen lassen, darunter die Maiden's Folly und die Spirit of Silverpine.\n\nDie Naga scheinen die Gezeiten der Bucht wenden zu können. Besatzungen, die in die Faldirbucht segeln und glauben, einen sicheren Hafen gefunden zu haben, werden auf die Steine geworfen.",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "Schlucht der Trockenstoppel",
			short = "Eine Schlucht schneidet durch die Berge im östlichen Arathihochland, nordöstlich von Hammerfall, und endet in einer Höhle. Dort leben Trockenstoppel-Kobolde, Verbündete der Giganten.",
			full = "Eine Schlucht schneidet durch die Berge im östlichen Arathihochland, nordöstlich von Hammerfall, und endet in einer Höhle. Dort leben Trockenstoppel-Kobolde, Verbündete der Giganten. Sie bewachen eine Steinscherbe, in der ein Stück der Essenz von Prinzessin Myzrael gefangen ist.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "Die Faldirbucht",
			short = "Eine seltsame Flut empfing die Schwarzmeerräuber, als sie mit drei Schiffen für einen Elfenschatz in diese Bucht segelten, angeführt von Kapitän Steelgut und Kapitän O'Breen.",
			full = "Eine seltsame Flut empfing die Schwarzmeerräuber, als sie mit drei Schiffen für einen Elfenschatz in diese Bucht segelten, angeführt von Kapitän Steelgut und Kapitän O'Breen. Die Naga, die die versunkenen Ruinen vor der Küste bewachen, ließen sie aufsteigen, und zwei der Schiffe gingen unter. Nur die Harbinger erreichte das Ufer. Ihre Besatzung ist in der Bucht gefangen, und die Navigationsbücher liegen noch in den Wracks unten.\n\nDie Bucht ist nach Faldir benannt, der diese Stelle markiert haben soll, als er und seine Anhänger über das Meer aufbrachen.",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "Go'Sheks Hof",
			short = "Primwell Skye, ein Veteran des Zweiten Krieges, bewirtschaftete diesen Hof einst. Nach dem Dritten Krieg nahmen ihn Verlassene und Orcs aus Hammerfall ein.",
			full = "Primwell Skye, ein Veteran des Zweiten Krieges, bewirtschaftete diesen Hof einst. Nach dem Dritten Krieg nahmen ihn Verlassene und Orcs aus Hammerfall ein. Die Orcs beziehen von ihm Vorräte für Hammerfall, und die Verlassenen nutzen ihn als Testgelände für alchemistische Experimente. Grunzer von Hammerfall bewachen den Ort.\n\nZwei Agenten der Allianz, Quae und Kinelory, sind gekommen, um herauszufinden, was die Verlassenen hier zusammenbrauen. Die Forschungsnotizen von Apotheker Jorell werden auf dem Hof aufbewahrt.",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "Hammerfall",
			short = "Orgrim Schicksalshammer fiel hier. Nach dem Zweiten Krieg hielt die Allianz von Lordaeron auf diesem Boden gefangene Orcs in einem ihrer größten Internierungslager.",
			full = "Orgrim Schicksalshammer fiel hier. Nach dem Zweiten Krieg hielt die Allianz von Lordaeron auf diesem Boden gefangene Orcs in einem ihrer größten Internierungslager. Thrall und Schicksalshammer führten die Horde, um sie zu befreien, und im Chaos stieß ein angreifender Ritter dem Kriegshäuptling von hinten eine Lanze durch den Leib.\n\nNach dem Dritten Krieg nahm die Horde die Ruinen als vorgeschobene Basis und nannte sie zu seinen Ehren Hammerfall. Es wurde zu einer Zuflucht für alle, die glaubten, in der Welt keinen Platz zu haben. Oger der Felsfäuste und Bleichborke-Trolle haben sich verbündet, um es auszulöschen.",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "Northfold-Anwesen",
			short = "Ein Hof am nordwestlichen Rand des Arathihochlands wurde nach dem Fall von Stromgarde zu einem Außenposten des Syndikats.",
			full = "Ein Hof am nordwestlichen Rand des Arathihochlands wurde nach dem Fall von Stromgarde zu einem Außenposten des Syndikats. Der Trollschamane Tor'gan spürte etwas Falsches in der Luft und folgte der Spur bis zum Herrenhaus, wo noch Spuren dämonischer Beschwörung am Boden haften. Als er näher kam, begann sein Blut vor Wut zu kochen.\n\nAm Boden fand er ein Blutsteinamulett, wie man es nutzt, um Dämonen beschwören zu helfen, wenn auch dieses hier verbraucht war. Er will herausfinden, was das Syndikat jenseits des Banditentums vorhat.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "Die Zuflucht",
			short = "Als Stromgardes Hauptstadt nach dem Dritten Krieg in Trümmer fiel, floh der größte Teil ihres Volkes nach Süden.",
			full = "Als Stromgardes Hauptstadt nach dem Dritten Krieg in Trümmer fiel, floh der größte Teil ihres Volkes nach Süden. Die Reste der Armee blieben zurück, entschlossen, ihr Land zurückzugewinnen, und sie halten diesen Außenposten. Von hier aus will die Allianz Burg Stromgarde zurückerobern.\n\nAls Zwerge vom Thandol-Übergang um Soldaten baten, um Dun Modr zurückzuerobern, lehnte Hauptmann Nials ab. Jede Hand hier sei an Stromgarde gebunden, sagte sie, und Ehre und Pflicht hielten sie im Hochland, bis es zurückgewonnen sei. Longbraid der Grimmige müsse allein zurechtkommen.",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "Burg Stromgarde",
			short = "Der Legende nach sah König Thoradin einen schwarzen Wolf durch dieses trockene Land streifen und wählte den Ort für seine Hauptstadt.",
			full = "Der Legende nach sah König Thoradin einen schwarzen Wolf durch dieses trockene Land streifen und wählte den Ort für seine Hauptstadt. Mit seinem Schwert Strom'kar zog er die Grenzen einer Stadt in den Staub, und seine Steinmetze begannen, Strom zu errichten, den Sitz des ersten Menschenkönigreichs.\n\nIm Zweiten Krieg und danach stand die Stadt als Macht unter der Allianz von Lordaeron. Nun ist sie geplündert und dreifach geteilt. Das Syndikat hält die innere Burg. Oger der Felsfäuste, unterstützt von Bleichborke-Trollen, halten das alte Magierviertel. Prinz Galen Trollbann befehligt das letzte Viertel mit dem, was von seiner Armee geblieben ist.",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "Thandol-Übergang",
			short = "Zwei große steinerne Bögen tragen die Straße zwischen dem Sumpfland von Khaz Modan und dem Arathihochland.",
			full = "Zwei große steinerne Bögen tragen die Straße zwischen dem Sumpfland von Khaz Modan und dem Arathihochland. Die Zwerge von Ironforge errichteten sie nach dem Krieg der Drei Hämmer, um den Wildhammer-Vettern die Treue zu halten und Handel zu treiben, und die Familie Anvilmar bewacht sie seit drei Generationen. Die Brücken konnten das Gewicht ganzer Armeen tragen und waren die wichtigste Handelsstraße zwischen Zwergen und Menschen. Als die Orcs die Schlacht um Lordaeron verloren, trieb Anduin Lothar die Alte Horde über den Übergang zurück nach Khaz Modan.\n\nNun hat ein Angriff der Dunkeleisenzwerge, geplant von Kam Tiefenzorn und Balgaras dem Niederträchtigen, eine Brücke fast zerstört. Die Zwerge kämpfen darum, die andere zu halten und die Stadt Dun Modr zurückzuerobern. Viele sind gestorben, darunter Sully Balloo, Ebenezer Rustlocke und der Bruder von Longbraid dem Grimmigen.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "Thoradinswall",
			short = "Gegen die Amani-Trolle ließ König Thoradin kurz nach der Gründung von Strom, der Hauptstadt von Arathor, eine große Mauer errichten. Über Generationen hielt sie Wache an der Grenze zwischen dem Arathihochland und dem Vorgebirge von Hillsbrad.",
			full = "Gegen die Amani-Trolle ließ König Thoradin kurz nach der Gründung von Strom, der Hauptstadt von Arathor, eine große Mauer errichten. Über Generationen hielt sie Wache an der Grenze zwischen dem Arathihochland und dem Vorgebirge von Hillsbrad.\n\nViele Jahrhunderte später steht sie noch, aber schwer beschädigt, ihre Steine zerbrochen und weit klaffend.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "Der Turm von Arathor",
			short = "Der Turm von Arathor steht im ehemaligen Magierviertel von Burg Stromgarde und ist nach dem Imperium von Arathor benannt.",
			full = "Der Turm von Arathor steht im ehemaligen Magierviertel von Burg Stromgarde und ist nach dem Imperium von Arathor benannt.\n\nErzmagier Trelane studierte einst in diesem Turm und baute eine Verteidigung hinein, die nur auf einen verzauberten Edelstein reagiert. Als das Syndikat und die Oger der Felsfäuste Stromgarde belagerten, versuchte er, den Turm zu halten, und scheiterte, und er floh aus der Stadt. Die Oger nahmen den Turm und das Viertel ringsum, und der Ogermagier Ruul Zweistein lebt nun darin. Trelane ließ sein Phylakterium, seine Kugel und einen Glutachat zurück. Er hat seinen früheren Lehrling, Erzmagier Malin, gebeten, dafür zu sorgen, dass sie zurückgeholt werden.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "Witherbark",
			short = "Um einen kleinen See im Südosten des Arathihochlands liegt das Dorf der Bleichborke-Trolle. Dahinter liegt eine große Höhle, in der oft die Anführer des Stammes zu finden sind.",
			full = "Um einen kleinen See im Südosten des Arathihochlands liegt das Dorf der Bleichborke-Trolle. Dahinter liegt eine große Höhle, in der oft die Anführer des Stammes zu finden sind.\n\nDie Bleichborke haben ein loses Bündnis mit den benachbarten Ogern der Felsfäuste gegen Stromgarde und Hammerfall geschlossen. Gemeinsam halten sie einen Teil von Stromgarde selbst.",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
	-- Ödland: 17 subzones
	[1418] = {
		["agmonds end"] = {
			name = "Agmondkuppe",
			short = "Prospektor Agmond leitete die Zwergengrabungen im Ödland, und diese kleine Grabungsstätte im südlichen Mittelteil des Gebiets war die südlichste von ihnen.",
			full = "Prospektor Agmond leitete die Zwergengrabungen im Ödland, und diese kleine Grabungsstätte im südlichen Mittelteil des Gebiets war die südlichste von ihnen. Troggs hatten die Stätte befallen, und Agmond fand hier sein Ende. Die Grabung liegt verlassen da und trägt seinen Namen.",
			source = "https://warcraft.wiki.gg/wiki/Agmond's_End",
		},
		["angor fortress"] = {
			name = "Festung Angor",
			short = "Festung Angor ist der Ort, von dem aus die Dunkeleisenzwerge ihre Arbeit im Ödland lenken. Von hier aus organisieren sie die Erforschung von Uldaman und wollen sie ausbeuten.",
			full = "Festung Angor ist der Ort, von dem aus die Dunkeleisenzwerge ihre Arbeit im Ödland lenken. Von hier aus organisieren sie die Erforschung von Uldaman und wollen sie ausbeuten. Botschafter Infernus, ein Feuerelementar im Dienst von Ragnaros, lebt ebenfalls in der Feste und beaufsichtigt die Grabungen des Schattenschmiede-Klans.",
			source = "https://warcraft.wiki.gg/wiki/Angor_Fortress",
		},
		["apocryphans rest"] = {
			name = "Apocryphans Ruheplatz",
			short = "Die Knochen von Apocryphans Ruheplatz erstrecken sich über das Ödland südlich von Kargath, ein gewaltiges Drachenskelett, gefallen und in der trockenen Hitze zum Bleichen liegen gelassen.",
			full = "Die Knochen von Apocryphans Ruheplatz erstrecken sich über das Ödland südlich von Kargath, ein gewaltiges Drachenskelett, gefallen und in der trockenen Hitze zum Bleichen liegen gelassen. Ein Schwarm hungriger Bussarde hat die Knochen in Besitz genommen und nistet zwischen den Rippen.",
			source = "https://warcraft.wiki.gg/wiki/Apocryphan's_Rest",
		},
		["camp boff"] = {
			name = "Camp Boff",
			short = "Nur drei Oger bewachen Camp Boff, das südöstliche der vier Lager, die die Staubspeier-Oger im Ödland unterhalten.",
			full = "Nur drei Oger bewachen Camp Boff, das südöstliche der vier Lager, die die Staubspeier-Oger im Ödland unterhalten.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Boff",
		},
		["camp cagg"] = {
			name = "Camp Cagg",
			short = "Boss Tho'grun, ein Söldnerführer der Staubspeier-Oger, geht mit seinen Leibwächtern eine Runde zwischen den Lagern des Stammes ab, und Camp Cagg ist eine seiner Stationen.",
			full = "Boss Tho'grun, ein Söldnerführer der Staubspeier-Oger, geht mit seinen Leibwächtern eine Runde zwischen den Lagern des Stammes ab, und Camp Cagg ist eine seiner Stationen. Einige der Staubspeier leben hier.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Cagg",
		},
		["camp kosh"] = {
			name = "Camp Kosh",
			short = "Die Oger von Camp Kosh jagen die Versorgungskarawanen, die das kahle Ödland durchqueren müssen. Es ist das nördlichste der Lager der Staubspeier.",
			full = "Die Oger von Camp Kosh jagen die Versorgungskarawanen, die das kahle Ödland durchqueren müssen. Es ist das nördlichste der Lager der Staubspeier.\n\nSigrun Eisenhieb und seine Zwerge mussten die Grabung bei Uldaman verlassen und Wagen und Kisten am Wegesrand zurücklassen. Die Oger von Kosh plünderten sie und nahmen jede Waffe und alle Nahrung.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Kosh",
		},
		["camp wurg"] = {
			name = "Camp Wurg",
			short = "Einige der Staubspeier-Oger leben in Camp Wurg im Nordwesten des Ödlands, und die Söldnerbande von Boss Tho'grun hält hier auf ihren Runden an.",
			full = "Einige der Staubspeier-Oger leben in Camp Wurg im Nordwesten des Ödlands, und die Söldnerbande von Boss Tho'grun hält hier auf ihren Runden an.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Wurg",
		},
		["dustbelch grotto"] = {
			name = "Die Staubspeiergrotte",
			short = "Im südwestlichen Ödland erhebt sich ein großer Hügel aus Erde und Stein, die Hauptheimat der Staubspeier-Oger.",
			full = "Im südwestlichen Ödland erhebt sich ein großer Hügel aus Erde und Stein, die Hauptheimat der Staubspeier-Oger. Der größte Teil des Stammes lebt hier oder in den Lagern, die über das rissige, sonnenverbrannte Land ringsum verstreut sind.",
			source = "https://warcraft.wiki.gg/wiki/Dustbelch_Grotto",
		},
		["dustbowl"] = {
			name = "Die Staubschüssel",
			short = "Rissiger, trockener Boden breitet sich über die Staubschüssel aus, eine weite Ebene im Nordwesten des Ödlands. Kojoten streifen darüber, Bussarde kreisen darüber, und Felselementare regen sich zwischen den Steinen.",
			full = "Rissiger, trockener Boden breitet sich über die Staubschüssel aus, eine weite Ebene im Nordwesten des Ödlands. Kojoten streifen darüber, Bussarde kreisen darüber, und Felselementare regen sich zwischen den Steinen. Nur Kakteen und ein paar Bäume haben einen Weg gefunden, hier zu wachsen.\n\nCamp Wurg liegt in der Einöde, eine der Heimstätten der Staubspeier-Oger.",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
		},
		["dustwind gulch"] = {
			name = "Staubwindschlucht",
			short = "Die Staubwindschlucht schneidet durch den trockenen, rissigen Boden des Ödlands, westlich der Lethlorklamm. Der Wind scheuert sie, und der Staub legt sich nie für lange.",
			full = "Die Staubwindschlucht schneidet durch den trockenen, rissigen Boden des Ödlands, westlich der Lethlorklamm. Der Wind scheuert sie, und der Staub legt sich nie für lange.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["hammertoes digsite"] = {
			name = "Hammertoes Grabungsstätte",
			short = "Der Zwerg Hammertoe Grez legte diese Grabung im nördlichen Ödland an, während er mit dem Historiker Karnik nach verlorenen Artefakten der Titanen suchte.",
			full = "Der Zwerg Hammertoe Grez legte diese Grabung im nördlichen Ödland an, während er mit dem Historiker Karnik nach verlorenen Artefakten der Titanen suchte. Er hat sie aufgegeben. Eine Bande von Dunkeleisenzwergen hat sie übernommen, höchstwahrscheinlich Teil derselben Truppe, die in Uldaman eingezogen ist.",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "Kargath",
			short = "Kargath ist der einzige Außenposten, den die Horde in Khaz Modan hält. Er ist nach Kargath Messerfaust benannt, dem Häuptling des Klans der Shattered-Hand.",
			full = "Kargath ist der einzige Außenposten, den die Horde in Khaz Modan hält. Er ist nach Kargath Messerfaust benannt, dem Häuptling des Klans der Shattered-Hand.\n\nKriegshäuptling Thrall schickte die Kargath-Expeditionstruppe hierher, um das Ödland zu erkunden. Ihre Späher fanden Uldaman, eine Grabung, die die Zwerge hoch schätzen. Das Hauptziel der Truppe ist eine Straße durch die Sengende Schlucht zum Blackrock, damit die Horde Rend Schwarzfaust, den Kriegshäuptling der Dunklen Horde, treffen kann. Unterwegs stieß sie auf die Dunkeleisenzwerge, und die beiden Seiten liegen wieder im Krieg.",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "Die Lethlorklamm",
			short = "Ein weites, zerklüftetes Tal zieht sich durch das östliche Ödland, und Welpen und Drachkin des schwarzen Drachenschwarms streifen darin umher.",
			full = "Ein weites, zerklüftetes Tal zieht sich durch das östliche Ödland, und Welpen und Drachkin des schwarzen Drachenschwarms streifen darin umher. Kristalline Obelisken stehen zwischen den Felsen.",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "Terrasse des Schöpfers",
			short = "Dunkeleisenzwerge patrouillieren auf der weiten Grabungsfläche der Terrasse des Schöpfers, gleich vor dem Eingang nach Uldaman. Die Erde wurde in breiten Streifen abgetragen und liegt offen unter dem Himmel.",
			full = "Dunkeleisenzwerge patrouillieren auf der weiten Grabungsfläche der Terrasse des Schöpfers, gleich vor dem Eingang nach Uldaman. Die Erde wurde in breiten Streifen abgetragen und liegt offen unter dem Himmel.",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "Illusionenebene",
			short = "Riesenbussarde, Patriarchen der Felsgratpirscher und tollwütige Klippenkojoten leben auf der Illusionenebene, östlich der Staubspeiergrotte.",
			full = "Riesenbussarde, Patriarchen der Felsgratpirscher und tollwütige Klippenkojoten leben auf der Illusionenebene, östlich der Staubspeiergrotte.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "Uldaman",
			short = "Legenden sagen, die Titanen schufen die Troggs aus Stein, hielten sie für einen Fehlschlag und sperrten sie in ein Gewölbe unter der Erde.",
			full = "Legenden sagen, die Titanen schufen die Troggs aus Stein, hielten sie für einen Fehlschlag und sperrten sie in ein Gewölbe unter der Erde. Dann versuchten sie es erneut, und die Zwerge waren das Ergebnis. Dieses Gewölbe ist Uldaman.\n\nZwerge aus Ironforge gruben sich vor dem Dritten Krieg hinein und weckten die Troggs. Nun dringen die Dunkeleisenzwerge ein, in der Hoffnung, die Scheiben von Norgannon zu erbeuten, die aufzeichnen, wie die Zwerge erschaffen wurden, für ihren Meister Ragnaros.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "Fangzahntal",
			short = "Ein kleines Tal verläuft zwischen zwei gewaltigen Felsformationen im zentralen Ödland. Wölfe und Pumas jagen dort, und der Weg hindurch ist gefährlich.",
			full = "Ein kleines Tal verläuft zwischen zwei gewaltigen Felsformationen im zentralen Ödland. Wölfe und Pumas jagen dort, und der Weg hindurch ist gefährlich. Martek der Verbannte, Riggelfuzz und Jazzrik unterhalten ein Lager im Tal.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- Verwüstete Lande: 7 subzones
	[1419] = {
		["dark portal"] = {
			name = "Das Dunkle Portal",
			short = "Medivh, ein Menschenmagier in der Gewalt von Sargeras, und der Orc-Hexenmeister Gul'dan rissen im Schwarzen Morast einen Spalt zwischen Draenor und Azeroth auf.",
			full = "Medivh, ein Menschenmagier in der Gewalt von Sargeras, und der Orc-Hexenmeister Gul'dan rissen im Schwarzen Morast einen Spalt zwischen Draenor und Azeroth auf. Durch ihn kam die Horde. Am Ende des Zweiten Krieges zerstörten Erzmagier Khadgar und seine Magier das Tor, um die Rückkehr der Orcs zu verhindern.\n\nDer steinerne Bogen, der heute hier steht, wurde errichtet, als Ner'zhul den Spalt wieder öffnete. Vermummte Wächter halten zu beiden Seiten Schwerter, und eine steinerne Schlange bleckt darüber die Fangzähne. Der Blitz schlägt in den Krater. Das Tor selbst ist still.",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul post"] = {
			name = "Schreckensfelsposten",
			short = "Die Schreckensfels-Oger kamen von Draenor nach Azeroth und entfernten sich nie weit vom Dunklen Portal. Dieser Hügel gehört ihnen, und sie halten ihn stark besetzt.",
			full = "Die Schreckensfels-Oger kamen von Draenor nach Azeroth und entfernten sich nie weit vom Dunklen Portal. Dieser Hügel gehört ihnen, und sie halten ihn stark besetzt. Die Magier von Burg Nethergarde sagen, sie dienten Lord Kazzak.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "Garnison-Waffenkammer",
			short = "Im vernarbten Boden der Verwüsteten Lande bauen Bergleute der Allianz in der Garnison-Waffenkammer Erze ab und entreißen sie der Erde für Burg Nethergarde.",
			full = "Im vernarbten Boden der Verwüsteten Lande bauen Bergleute der Allianz in der Garnison-Waffenkammer Erze ab und entreißen sie der Erde für Burg Nethergarde. Was sie fördern, wird weiter nach Stormwind verschifft, und im Gegenzug erhält die Burg die übrigen Vorräte, die sie braucht, um an diesem verseuchten Ort auszuharren.",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "Burg Nethergarde",
			short = "Burg Nethergarde steht auf einer hohen Felsklippe über der einzigen Straße in die Verwüsteten Lande, ihre Mauern errichtet, um die Ruine eines Tores zu bewachen, das niemand je wieder geöffnet sehen wollte.",
			full = "Burg Nethergarde steht auf einer hohen Felsklippe über der einzigen Straße in die Verwüsteten Lande, ihre Mauern errichtet, um die Ruine eines Tores zu bewachen, das niemand je wieder geöffnet sehen wollte. Erzmagier Khadgar ließ sie nach dem Zweiten Krieg bauen, damit keine zweite Invasion durch das Dunkle Portal käme. Magier aus Dalaran bemannten sie und erforschten, was die Energie des Portals mit dem Boden und den Tieren angerichtet hatte.\n\nDalaran wurde im Dritten Krieg zerstört, und die Burg lebt von den Karawanen aus Stormwind. Ihre Magier und Krieger kämpfen jeden Tag gegen Oger und Dämonen, und sie haben nicht mehr viel Frohsinn übrig.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "Anhöhe des Entweihers",
			short = "Zerklüftete Berge erheben sich nahe der Mitte der Verwüsteten Lande, und ein großer Dämon lebt unter ihnen.",
			full = "Zerklüftete Berge erheben sich nahe der Mitte der Verwüsteten Lande, und ein großer Dämon lebt unter ihnen. Razelikh der Entweiher ist ein Schreckenslord, der furchterregendste Leutnant von Lord Kazzak, der ihn beauftragte, das Land zu sichern.",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "Schlangenschlinge",
			short = "Ausgebrannte Orc-Gebäude aus dem Zweiten Krieg stehen am Eingang dieses gewundenen Höhlensystems im Osten. Kultisten beten dahinter in den Höhlen einen Teufelsjäger namens Kirith der Verdammte an.",
			full = "Ausgebrannte Orc-Gebäude aus dem Zweiten Krieg stehen am Eingang dieses gewundenen Höhlensystems im Osten. Kultisten beten dahinter in den Höhlen einen Teufelsjäger namens Kirith der Verdammte an. Erzmagier Allistarj führt den Kult, die Schattenanbeter, von innen an. Er war einst ein Menschenmagier, doch er hat sich dem Schreckenslord Razelikh verschworen und ist zu einem Dämon geworden. Der Schwur hält ihn am Leben, solange er in den Verwüsteten Landen bleibt und seinen Geist in den Dienst des Schreckenslords stellt.",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "Die faulende Narbe",
			short = "Dieser Abschnitt der westlichen Verwüsteten Lande war einst Teil des Schwarzen Morasts.",
			full = "Dieser Abschnitt der westlichen Verwüsteten Lande war einst Teil des Schwarzen Morasts. Die Verderbnis des Dunklen Portals hat ihn wasserlos und baumlos zurückgelassen, den Boden blutfarben, und dämonische Bestien streifen darüber.\n\nNach der Niederlage der Brennenden Legion am Berg Hyjal führte Lord Kazzak einen großen Teil ihrer verbliebenen Streitmacht auf Azeroth in die Narbe und machte sie zu seiner eigenen. Er ist noch immer dort, und der Schreckenslord Razelikh der Entweiher dient ihm. Ein betagter menschlicher Hexenmeister, Daio der Klapprige, hat sich an ihrem Altar niedergelassen. Er vollzieht Rituale mit den Dämonen und bildet Rekruten in den höllischen Künsten aus.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- Tirisfal: 30 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "Gruft der Familie Agamand",
			short = "Gleich nördlich von Agamands Mühlen liegt die Gruft, in der die Familie Agamand ihre Toten begrub. Hauptmann Dargol, ein Kommandant der Geißel, hat sie zu seinem Hauptquartier gemacht, dem stärksten Punkt der Mühlen.",
			full = "Gleich nördlich von Agamands Mühlen liegt die Gruft, in der die Familie Agamand ihre Toten begrub. Hauptmann Dargol, ein Kommandant der Geißel, hat sie zu seinem Hauptquartier gemacht, dem stärksten Punkt der Mühlen. Mit Nekromantie hat er die Ahnen der Familie erweckt, jeden Leichnam und jeden Geist darin, um sie gegen die Verlassenen einzusetzen. Die Gruft ist dunkel und staubig, und die rachsüchtigen Toten greifen jeden an, der ungebeten eintritt.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Agamands Mühlen",
			short = "Die Windmühlen von Agamand stehen im Hochland des nördlichen Tirisfal, und sie drehten sich einst für eine wohlhabende Familie. Als die Geißel zum ersten Mal nach Tirisfal kam, wollte Gregor Agamand nicht gehen.",
			full = "Die Windmühlen von Agamand stehen im Hochland des nördlichen Tirisfal, und sie drehten sich einst für eine wohlhabende Familie. Als die Geißel zum ersten Mal nach Tirisfal kam, wollte Gregor Agamand nicht gehen. Seine Familie befestigte die Mühlen, versorgte sie gut und überzeugte ihre Arbeiter, zu bleiben und zu kämpfen.\n\nDie Verteidigung scheiterte von innen. Devlin, der jüngste Sohn, schlug sich auf die Seite der Geißel, tötete zwei Wächter und führte Untote durch die Bresche dorthin, wo die Männer schliefen. Ein Drittel der Verteidiger starb, und zu wenige blieben, um zu halten. Dann raffte die Seuche die ganze Familie dahin, und die Agamands wandeln als willenlose Tote durch ihre eigenen Mühlen. Die Geißel hält den Ort nun als Außenposten.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Balnirs Bauernhof",
			short = "Nordöstlich der gefallenen Hauptstadt Lordaeron steht der zerstörte Hof der Familie Balnir, die die großen weißen Pferde züchtete, auf denen das Königshaus von Lordaeron ritt.",
			full = "Nordöstlich der gefallenen Hauptstadt Lordaeron steht der zerstörte Hof der Familie Balnir, die die großen weißen Pferde züchtete, auf denen das Königshaus von Lordaeron ritt. Diener der Geißel aus den Pestländern, die über die Grenze schlüpfen, suchen nun Unterschlupf in den Ruinen. Löwenmäulchen, die einst im Garten gepflegt wurden, wachsen hier noch, und die Apotheker der Verlassenen wollen wissen, ob die Verderbnis der Pestländer in sie eingedrungen ist.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["bandarion keep"] = {
			name = "Die Bandarionfestung",
			short = "Die Bandarionfestung entstand als Außenposten der Armee von Lordaeron auf einem Hügel, an einem Ort namens Nordhangfels im westlichen Tirisfal.",
			full = "Die Bandarionfestung entstand als Außenposten der Armee von Lordaeron auf einem Hügel, an einem Ort namens Nordhangfels im westlichen Tirisfal. In den frühen Tagen der Verlassenen besetzte die Argentumdämmerung sie unter Lord Maxwell Tyrosus, und Crushridge-Oger belagerten sie in der Hoffnung, die Burg zu plündern und die Verteidiger zu fressen. Die Argentumdämmerung hat sich inzwischen in die Östlichen Pestländer zurückgezogen. Paladine von Tyrs Wacht unter Danitha Morr halten die Burg jetzt, und sie ist nach Garek Bandarion benannt, dem ersten Paladin der Verlassenen.",
			source = "",
		},
		["brightwater lake"] = {
			name = "Blendwassersee",
			short = "Der größte See in Tirisfal liegt nordöstlich von Brill. Ein Lich mit freiem Willen namens Gunther Arkanus lebt auf der großen Insel in seiner Mitte.",
			full = "Der größte See in Tirisfal liegt nordöstlich von Brill. Ein Lich mit freiem Willen namens Gunther Arkanus lebt auf der großen Insel in seiner Mitte.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Brill",
			short = "Brill war eine gewöhnliche Stadt in Lordaeron, im Besitz der Familie Barov, wobei die Agamands innerhalb ihrer Grenzen ein eigenes Herrenhaus unterhielten.",
			full = "Brill war eine gewöhnliche Stadt in Lordaeron, im Besitz der Familie Barov, wobei die Agamands innerhalb ihrer Grenzen ein eigenes Herrenhaus unterhielten. Dann wählte Kel'Thuzad, noch ein lebender Mann, sie aus, um seine Experimente mit der Seuche des Untodes zu beginnen. Sie verliefen so gut, dass er den Lichkönig überzeugte, die Invasion früher zu starten als geplant. Der Friedhof gleich vor der Stadt wurde angelegt, um die vielen Toten zu fassen. Brills Verteidiger konnten die Dorfbewohner nicht retten und wurden aus der Stadt vertrieben. Sie schlossen sich Prinz Arthas Menethil bei seiner Jagd nach der Quelle der Seuche an. Die Verlassenen haben die Stadt seither wieder aufgebaut, und Magistrat Sevren regiert sie.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Rathaus von Brill",
			short = "Das Rathaus ist das auffälligste Gebäude in Brill. Von seinem Podium aus führt Magistrat Sevren die Stadt und erteilt den Verlassenen, die ihm dienen, Befehle und Aufgaben.",
			full = "Das Rathaus ist das auffälligste Gebäude in Brill. Von seinem Podium aus führt Magistrat Sevren die Stadt und erteilt den Verlassenen, die ihm dienen, Befehle und Aufgaben. Nur wenige Rathäuser irgendwo werden von Verlassenen geführt, und dies ist eines davon.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "Das Bollwerk",
			short = "Hochexekutor Derrington befehligt das Bollwerk, die letzte Bastion, die die Verlassenen gegen die Geißel im Osten halten, wo Tirisfal auf die Westlichen Pestländer trifft.",
			full = "Hochexekutor Derrington befehligt das Bollwerk, die letzte Bastion, die die Verlassenen gegen die Geißel im Osten halten, wo Tirisfal auf die Westlichen Pestländer trifft. Verteidiger der Verlassenen und die Argentumdämmerung haben sich zusammengetan, um die Grenze zu halten, und Derrington will den Stützpunkt ausmerzen, den die Geißel jenseits davon errichtet hat. Ein Seuchennebel hängt über dem Lager und färbt den Himmel gelbgrau, wie er es in den Westlichen Pestländern tut und nirgends sonst in Tirisfal.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "Coldhearth-Anwesen",
			short = "Das Coldhearth-Anwesen war für seine warme Atmosphäre und seine reiche Ernte bekannt. Die Seuche des Untodes tötete alle, die hier lebten oder arbeiteten, und die Felder wurden unfruchtbar.",
			full = "Das Coldhearth-Anwesen war für seine warme Atmosphäre und seine reiche Ernte bekannt. Die Seuche des Untodes tötete alle, die hier lebten oder arbeiteten, und die Felder wurden unfruchtbar. Willenlose Zombies der Geißel suchen sie nun heim. Die Verlassenen halten das Bauernhaus an der Hauptstraße.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Außenposten der Kreuzzügler",
			short = "Ein Wachturm steht in den östlichen Hügeln von Tirisfal, gehalten vom Scharlachroten Kreuzzug. Von dort beobachten die Kreuzzügler die Hauptstraße, die südlich durch Tirisfal führt.",
			full = "Ein Wachturm steht in den östlichen Hügeln von Tirisfal, gehalten vom Scharlachroten Kreuzzug. Von dort beobachten die Kreuzzügler die Hauptstraße, die südlich durch Tirisfal führt. Sie nutzen ihn auch, um jede Truppe zu flankieren, die versucht, das Scharlachrote Kloster zu stürmen. Hauptmann Vachon befehligt den Turm.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "Deathknell",
			short = "Jede andere Siedlung der Verlassenen behielt den Namen, den sie als Menschenstadt trug. Deathknell wurde umbenannt, und niemand weiß, warum.",
			full = "Jede andere Siedlung der Verlassenen behielt den Namen, den sie als Menschenstadt trug. Deathknell wurde umbenannt, und niemand weiß, warum. Es liegt in einem gut bewachten Tal, und die frisch erwachten Verlassenen kommen aus der Gruft zu ihm herab, in der sie zum ersten Mal die Augen öffnen.\n\nDie Geißel, die die Dorfbewohner die Willenlosen nennen, hält das nördliche Ende des Tals und seine Schmiede, sodass die Verlassenen sich um die Kirche eingegraben haben. Das Überleben ist ein Kampf, und Gold ist das Knappste von allem. Eine Goldmine im Nordwesten ist von Spinnen überrannt, und die Dorfbewohner versuchen immer wieder, sie zu säubern. Elite-Todeswachen beobachten das Tal.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "Faols Ruheplatz",
			short = "Erzbischof Alonsus Faol, das hochverehrte Oberhaupt der Kirche des Heiligen Lichts, wurde hier im Osten von Tirisfal begraben. Er starb einige Zeit, bevor die Geißel kam.",
			full = "Erzbischof Alonsus Faol, das hochverehrte Oberhaupt der Kirche des Heiligen Lichts, wurde hier im Osten von Tirisfal begraben. Er starb einige Zeit, bevor die Geißel kam.\n\nIn den Tagen vor der Seuche des Untodes besuchten Trauernde das Grab oft. Nun liegt es ungepflegt und größtenteils vergessen.",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "Taverne Zur Galgenschlinge",
			short = "In Brill betreiben die Verlassenen die einzige voll funktionierende Taverne, die ihr Volk bekanntermaßen unterhält.",
			full = "In Brill betreiben die Verlassenen die einzige voll funktionierende Taverne, die ihr Volk bekanntermaßen unterhält. In ihrem Keller werden ein gefangener Scharlachroter Zelot und ein zwergischer Bergsteiger gefangen gehalten.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Garrens Schlupfwinkel",
			short = "Garrens Schlupfwinkel war einst ein ertragreicher Hof im Norden von Tirisfal, mit einem Bauernhaus, einer Scheune, ein paar Silos und einem weiten Feld.",
			full = "Garrens Schlupfwinkel war einst ein ertragreicher Hof im Norden von Tirisfal, mit einem Bauernhaus, einer Scheune, ein paar Silos und einem weiten Feld. Als die Geißel durch Lordaeron fegte, ermordete sie Garren und seine Familie. Die Seuche machte das Land grau und leblos.\n\nFäulnisfell-Gnolle halten nun das Bauernhaus und die Scheune unter ihrem Anführer Madenauge. Sie greifen jeden an, der nahe kommt.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "Gunthers Zufluchtsort",
			short = "Auf einer Insel im Blendwassersee lebt Gunther Arkanus, ein Lich, der einst bei den Kirin Tor von Dalaran studierte. Er war ein geschickter Nekromant, obwohl die Kirin Tor diese Kunst verbieten.",
			full = "Auf einer Insel im Blendwassersee lebt Gunther Arkanus, ein Lich, der einst bei den Kirin Tor von Dalaran studierte. Er war ein geschickter Nekromant, obwohl die Kirin Tor diese Kunst verbieten. Die Seuche tötete und erweckte ihn im Dritten Krieg, und er brach den Griff des Lichkönigs über sich aus eigener Kraft.\n\nEr glaubt, jeder andere Untote sei noch immer ein Sklave der Geißel, und so bleibt er auf der Insel, und seine Zombies greifen jeden an, der sich nähert. Die Verlassenen haben nicht erfahren, wer er war, und sie wollen sein Können.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "Nachtwebergrund",
			short = "Spinnen halten dieses kleine Tal und die Goldmine, die in es hineingetrieben wurde. Junge Nachtweberspinnen streifen durch die offene Senke, und ausgewachsene huschen durch die Mine und lauern in ihren verwebten Ecken.",
			full = "Spinnen halten dieses kleine Tal und die Goldmine, die in es hineingetrieben wurde. Junge Nachtweberspinnen streifen durch die offene Senke, und ausgewachsene huschen durch die Mine und lauern in ihren verwebten Ecken.\n\nJunge Verlassene kommen, um sich an den Spinnen draußen zu erproben, ehe sie tiefer vordringen. In der tiefsten Nische der Mine sitzt die Nachtwebermatriarchin, die kleinste der Spinnen und die am schwersten zu erreichende.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Alptraumtal",
			short = "Dieses weite Tal war einst grün und voller Waldtiere. Nun sind die Bäume verdorrt, und hungrige Schattenhunde und riesige Vampirfledermäuse haben die Tierwelt aufgefressen.",
			full = "Dieses weite Tal war einst grün und voller Waldtiere. Nun sind die Bäume verdorrt, und hungrige Schattenhunde und riesige Vampirfledermäuse haben die Tierwelt aufgefressen. Eine seltene weiße Fledermaus namens Ressan der Aufstachler jagt unter ihnen.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "Die Nordküste",
			short = "Der Strand am Nordrand von Tirisfal blickt auf das Große Meer. Gefräßige Murlocs und andere Meerestiere halten ihn.",
			full = "Der Strand am Nordrand von Tirisfal blickt auf das Große Meer. Gefräßige Murlocs und andere Meerestiere halten ihn.\n\nSeit der Seuche des Untodes ist die Küste dunkel und kalt geworden. Tote Meeresgeschöpfe verrotten am Wasserrand.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "Ruinen von Lordaeron",
			short = "Prinz Arthas Menethil wandte sich gegen sein eigenes Volk.",
			full = "Prinz Arthas Menethil wandte sich gegen sein eigenes Volk. Er kehrte an der Spitze eines Heeres nach Lordaeron heim und fand seinen Vater, König Terenas, im Thronsaal wartend, und er tötete ihn dort. Über der Leiche stehend, verkündete er, dass das Königreich fallen werde und dass aus seiner Asche eine neue Ordnung erstehe, die die Welt erschüttern werde. Auf sein Geheiß marschierte die Geißel dann ein und schlachtete die Menschen der Stadt ab.\n\nDer Palast von Lordaeron steht noch über Undercity, und die Stunde des Todes des Königs ist dort noch immer zu hören. Stimmen flüstern im Hof, Glocken schlagen im Eingang, ein Jubel begrüßt den Prinzen, und ein Murmeln steigt aus dem Thronsaal auf. Die Bürger von Lordaeron spuken noch immer im Hof, und wer die Toten sehen kann, findet sie dort.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "Das Scharlachrote Kloster",
			short = "Das Kloster in der Nordostecke von Tirisfal war einst eine Kathedrale der Kirche des Heiligen Lichts. Es besaß große Bibliotheken und diente als Seminar, in dem Paladine ausgebildet wurden.",
			full = "Das Kloster in der Nordostecke von Tirisfal war einst eine Kathedrale der Kirche des Heiligen Lichts. Es besaß große Bibliotheken und diente als Seminar, in dem Paladine ausgebildet wurden. Alexandros Mograine verbrachte in seiner Jugend hier Monate mit Beten und Studieren.\n\nNach dem Dritten Krieg nahm der Scharlachrote Kreuzzug es als seine Festung im Krieg gegen die Geißel und die Verlassenen. Sie machten es zu einem Militärlager und einem Ort, um ihre Gefangenen festzuhalten. Sie sind Fanatiker, die jedes Volk außer den Menschen hassen und glauben, dass jeder Fremde die Seuche tragen könnte. Hochinquisitorin Whitemane ist die wahre Herrin des Klosters.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "Scharlachroter Wachposten",
			short = "Hauptmann Melrache befehligt den Wachturm nördlich des Scharlachroten Klosters.",
			full = "Hauptmann Melrache befehligt den Wachturm nördlich des Scharlachroten Klosters. Er steht an einem abgelegenen Ort, und der Scharlachrote Kreuzzug unterhält ihn, damit seine Feinde das Kloster nicht an seiner schwerer zu verteidigenden Nordseite angreifen können.\n\nEr ist einer von vier Außenposten der Kreuzzügler in Tirisfal.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "Schattengrab",
			short = "Frisch erhobene Verlassene erwachen in dieser Gruft, die oben an einem Hang in den Bergen von Tirisfal steht. Todeswache Balteus und Todeswache Hansel stehen hier Wache.",
			full = "Frisch erhobene Verlassene erwachen in dieser Gruft, die oben an einem Hang in den Bergen von Tirisfal steht. Todeswache Balteus und Todeswache Hansel stehen hier Wache. Ein ausgetretener Pfad führt vom Eingang hinab nach Deathknell.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["shadowvale"] = {
			name = "Schattental",
			short = "Zerstörte Häuser stehen im Dorf Schattental, und die Befleckten sind in sie eingezogen. Es sind Paladine der Verlassenen, die sich nicht in den Untod fügen konnten.",
			full = "Zerstörte Häuser stehen im Dorf Schattental, und die Befleckten sind in sie eingezogen. Es sind Paladine der Verlassenen, die sich nicht in den Untod fügen konnten. Sie behielten den Hass, den sie im Leben trugen, und richten ihn gegen ihre eigene Art.\n\nIhr Anführer, Rudolph Gelhardt, hält sich in einem Zimmer im Obergeschoss eines der Bauernhäuser auf. Unter dem Dorf, im alten Wurzelkeller, wandeln noch immer Skelette und Zombies.",
			source = "",
		},
		["solliden farmstead"] = {
			name = "Sollidens Bauernhof",
			short = "Bauer Solliden besitzt diesen Kürbishof, und er ist sowohl der Horde als auch der Allianz feindlich gesinnt.",
			full = "Bauer Solliden besitzt diesen Kürbishof, und er ist sowohl der Horde als auch der Allianz feindlich gesinnt. Seine Leute gehören zu den wenigen im nördlichen Lordaeron, die die Seuche des Untodes nicht berührt hat, und sie bestellen noch immer ihre Reihen, während das Land ringsum gefallen ist.\n\nSiedler aus Arathor begannen, Tirisfal zu bewirtschaften, als ihr Königreich wuchs. Später kauften Adelsfamilien aus Strom große Flächen auf, die die ersten Siedler gerodet hatten, Solliden unter ihnen. Todeswache Simmer fürchtet, dass diese friedlichen Bauern von der Allianz angeworben und gegen die Verlassenen gewendet werden könnten.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Stillwater-Tümpel",
			short = "Vor der Seuche war der Stillwater-Tümpel ein Ort, an dem die Lebenden jung sein durften.",
			full = "Vor der Seuche war der Stillwater-Tümpel ein Ort, an dem die Lebenden jung sein durften. Familien aus Tirisfal kamen zum Picknick an seine Ufer, und Kinder, die zu klein waren, um sich in die tieferen Gewässer des Blendwassersees zu wagen, lernten stattdessen hier schwimmen.\n\nDieses Wasser ist heute grau. Die Fische unter der Oberfläche sind nur noch Knochen, die weiterschwimmen, als hätte ihnen niemand gesagt, dass sie aufhören sollen. Umherziehende Untote und wilde Tiere gehen am Ufer entlang, und der Schattenhund Bayne streift am Wasserrand umher und frisst, was unvorsichtig genug ist, dort zu verweilen.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Terrasse der Erholung",
			short = "Nördlich des Eingangs zum Scharlachroten Kloster liegt ein kleines Stück Land, das die Seuche des Untodes nie erreicht hat.",
			full = "Nördlich des Eingangs zum Scharlachroten Kloster liegt ein kleines Stück Land, das die Seuche des Untodes nie erreicht hat. Der Scharlachrote Kreuzzug zieht hier grüne Hecken und hält einen Springbrunnen mit frischem Wasser am Laufen, während das Wasser anderswo in Tirisfal abgestanden ist.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["venomweb vale"] = {
			name = "Giftwebertal",
			short = "Eine Brut giftiger Spinnen unter der tödlichen Sri'skulk hält nun das Giftwebertal, und sie haben dem Tal seinen Namen gegeben.",
			full = "Eine Brut giftiger Spinnen unter der tödlichen Sri'skulk hält nun das Giftwebertal, und sie haben dem Tal seinen Namen gegeben. Bevor sie kamen, war das Gras grün und die Bäume gesund, und Jäger fanden hier Hirsche und Kaninchen. Schattenhunde streifen durch das nördliche Ende.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering forest"] = {
			name = "Der Flüsternde Wald",
			short = "Kranke Hirsche, Hirschkühe und Kitze grasen zwischen den Bäumen des Flüsternden Waldes, hoch in den Bergen im Westen von Tirisfal. Ratten und ein einzelner kranker Bär teilen sich den Wald mit ihnen.",
			full = "Kranke Hirsche, Hirschkühe und Kitze grasen zwischen den Bäumen des Flüsternden Waldes, hoch in den Bergen im Westen von Tirisfal. Ratten und ein einzelner kranker Bär teilen sich den Wald mit ihnen.\n\nPaladine der Verlassenen von Tyrs Wacht bewachen den Wald von der Bandarionfestung auf dem Nordhangfels aus, der steilen Klippe, die ihn vom Rest von Tirisfal abschneidet. Finsterflossen-Murlocs, aus der Burg vertrieben, haben die Felsen und den See in der Nähe überrannt.",
			source = "",
		},
		["whispering gardens"] = {
			name = "Flüstergärten",
			short = "Auf diesem Hügel südlich des Eingangs zum Scharlachroten Kloster wurde eine große Schlacht geschlagen. Auf der einen Seite standen die Männer, die zum Scharlachroten Kreuzzug wurden, auf der anderen ein Heer der Geißel.",
			full = "Auf diesem Hügel südlich des Eingangs zum Scharlachroten Kloster wurde eine große Schlacht geschlagen. Auf der einen Seite standen die Männer, die zum Scharlachroten Kreuzzug wurden, auf der anderen ein Heer der Geißel. In der Dämmerung kann man hier noch die Geister der Gefallenen als leises Flüstern hören. Scharlachrote Magier, Bewahrer und Späher halten nun den Boden.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Die stille Küste",
			short = "Das Wasser vor der stillen Küste ist kalt und dunkel, und die Fülle, die einst Fischer an diesen Küstenstreifen lockte, ist verschwunden.",
			full = "Das Wasser vor der stillen Küste ist kalt und dunkel, und die Fülle, die einst Fischer an diesen Küstenstreifen lockte, ist verschwunden. Eine Bande Murlocs unter dem grimmigen Muad hat sie überrannt und fällt über jeden her, der sich in ihre Nähe verirrt.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Silberwald: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "Ambermill",
			short = "Ambermill war eine unbedeutende Holzfällerstadt, bis der Dritte Krieg kam.",
			full = "Ambermill war eine unbedeutende Holzfällerstadt, bis der Dritte Krieg kam. Dann fegten die Geißel und die Brennende Legion durch den Norden, und die Kirin Tor von Dalaran, die ihre eigene Stadt wieder aufbauten, fanden Verwendung für den Ort. Die Stadt liegt auf einer schlafenden Leylinie, die die Magier wecken wollen. Durch ihre Unterstützung ist Ambermill die einzige echte Quelle menschlichen Widerstands im Wald, und die Sägewerke, die Ställe und das Rathaus sind in der Hand der Kirin Tor. Die Verlassenen fürchten, ihren Halt im Silberwald zu verlieren. Ein Gefangener hat ihren Todespirschern erzählt, dass die Magier hier Unterlagen über den Zustand von Dalaran aufbewahren.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "Beren's Peril",
			short = "Kundschafter der Verlassenen kehrten aus den Hügeln südwestlich von Ambermill mit einer Warnung zurück. Eine Gruppe Untoter versteckt sich in Beren's Peril und bereitet einen Angriff auf das Grabmal vor.",
			full = "Kundschafter der Verlassenen kehrten aus den Hügeln südwestlich von Ambermill mit einer Warnung zurück. Eine Gruppe Untoter versteckt sich in Beren's Peril und bereitet einen Angriff auf das Grabmal vor. Mehr konnten die Kundschafter nicht sagen. Schattenpriester Allister hat nur erfahren, dass die Untoten Diener des Nekromanten Thule Rabenklaue sind.",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "Die Morgeninseln",
			short = "Die Morgeninseln waren einst eine idyllische Gruppe flacher Inselchen, die aus dem klaren Wasser des Lordameresees ragten. Die Seuche des Untodes erreichte sie, und ihre Bäume wurden kränklich.",
			full = "Die Morgeninseln waren einst eine idyllische Gruppe flacher Inselchen, die aus dem klaren Wasser des Lordameresees ragten. Die Seuche des Untodes erreichte sie, und ihre Bäume wurden kränklich. Murlocs streiften an den Ufern umher, und heute halten die Finsterflossen-Murlocs, inzwischen sehr zahlreich, die Inseln vollständig.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "Das Todesfeld",
			short = "Niemand weiß, wer das Todesfeld bestellt hat. Die Farm im Norden des Silberwalds ist verlassen und verrottet, und die Fäulnisfell-Gnolle, Diener der Geißel, haben sie zu ihrem Stützpunkt gemacht.",
			full = "Niemand weiß, wer das Todesfeld bestellt hat. Die Farm im Norden des Silberwalds ist verlassen und verrottet, und die Fäulnisfell-Gnolle, Diener der Geißel, haben sie zu ihrem Stützpunkt gemacht. Ihre Zahl wächst stetig, was auf einen bevorstehenden Angriff hindeutet. Thule Rabenklaue schickt Erscheinungen hierher, die sie antreiben. Die Verlassenen haben das Feld wieder und wieder angegriffen und sind jedes Mal gescheitert, denn die Banshee Nachtseele taucht auf, sobald ihre Gnolle angegriffen werden.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "Die verfallene Fähre",
			short = "Eine Fähre fuhr einst von diesem Ufer zur Insel Fenris und beförderte für ein kleines Entgelt Waren und Reisende.",
			full = "Eine Fähre fuhr einst von diesem Ufer zur Insel Fenris und beförderte für ein kleines Entgelt Waren und Reisende. Die Höfe in der Nähe verkauften einen Teil ihrer Ernte an den reichen Lord auf der Insel und seine Familie. Dann fiel die Geißel in Lordaeron ein. Der Fährmann wurde ermordet und die Fähre zerstört. Ghule, Skelette und Fäulnisfell-Gnolle drängen sich jetzt an den Anlegern, und der Boden ist gefährlich.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "Tiefenfelsmine",
			short = "Arugals Magie hat die Tiefenfelsmine erreicht, und Worgen haben sie zu ihrer Heimat gemacht. Sie folgen Grimson dem Blassen, dem listigen Vorarbeiter, der die Mine einst leitete.",
			full = "Arugals Magie hat die Tiefenfelsmine erreicht, und Worgen haben sie zu ihrer Heimat gemacht. Sie folgen Grimson dem Blassen, dem listigen Vorarbeiter, der die Mine einst leitete. Dalar Morgenweber von den Verlassenen will Grimson tot sehen, damit die Verlassenen die Mine als Rohstoffquelle für sich beanspruchen können.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Insel Fenris",
			short = "Zusammen mit den Morgeninseln bildet die Insel Fenris einen zerbrochenen Ring aus festem Land in der Mitte des Lordameresees.",
			full = "Zusammen mit den Morgeninseln bildet die Insel Fenris einen zerbrochenen Ring aus festem Land in der Mitte des Lordameresees. Sie ist groß, und vor dem Dritten Krieg stand dort Burg Fenris, ein blühender Militärposten von Lordaeron. Als die Geißel das Land einnahm, floh jeder auf der Insel oder wurde ermordet. Die Fäulnisfell-Gnolle machten die Burg dann zu ihrem Stützpunkt, und ihr verräterischer Meister Thule Rabenklaue hält die ganze Insel.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Burg Fenris",
			short = "Thule Rabenklaue war ein junger, vielversprechender Magier der Kirin Tor, bis er dem Lichkönig seine Seele verkaufte. In Burg Fenris hatte einst ein beträchtlicher Teil der Armee von Lordaeron gelegen.",
			full = "Thule Rabenklaue war ein junger, vielversprechender Magier der Kirin Tor, bis er dem Lichkönig seine Seele verkaufte. In Burg Fenris hatte einst ein beträchtlicher Teil der Armee von Lordaeron gelegen. Als die Geißel über das Land hereinbrach, entkam auch die Burg nicht. Thule band die Gnolle der Gegend mit Nekromantie an sich, und ein Ichor, den er selbst gebraut hat, hält die Fäulnisfell-Gnolle nun am Leben. Er ist der Herr der Burg, und seine Gnolle fallen über jeden her, der sich nähert.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "Der Greymane-Wall",
			short = "König Genn Greymane ließ diese Mauer bauen, um Gilneas von der Welt abzuschneiden.",
			full = "König Genn Greymane ließ diese Mauer bauen, um Gilneas von der Welt abzuschneiden. Er hatte es satt, gilneanische Steuern für die Internierungslager der Orcs zu zahlen, und er hatte die Streitereien unter den Königen der Allianz von Lordaeron satt. Die Mauer ist gewaltig und hat ein einziges großes Tor, und sie hielt die Geißel von seinem Königreich fern. Flüchtlinge, die von Lordaeron nach Süden fliehen, lagern in ihrem Schatten. Sie sind ausgezehrt und krank, und das Tor bleibt ihnen verschlossen.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "Das Ivar-Feld",
			short = "Ivars Hof war ein angenehmer, wohlhabender Ort, und er beschäftigte viele Knechte und Diener. Dann kam die Seuche des Untodes.",
			full = "Ivars Hof war ein angenehmer, wohlhabender Ort, und er beschäftigte viele Knechte und Diener. Dann kam die Seuche des Untodes. Ivar, seine Familie und jeder Knecht verwandelten sich in verwesende Ghule, und sie fallen über jeden her, der sich nähert. Ivar selbst ist als Ivar der Verfaulte bekannt. Ein Spähtrupp der Verlassenen geriet hier in einen Hinterhalt, und Ivar verwundete den Todespirscher Quinn Yorick. Quinn und Rane Yorick halten in Ivars altem Haus aus.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Der Lordameresee",
			short = "Viele menschliche Königreiche gediehen rund um den Lordameresee in den Tagen der Allianz von Lordaeron. Lordaeron baute seine Hauptstadt am Nordufer, und der See hat seinen Namen sehr wahrscheinlich von ihr.",
			full = "Viele menschliche Königreiche gediehen rund um den Lordameresee in den Tagen der Allianz von Lordaeron. Lordaeron baute seine Hauptstadt am Nordufer, und der See hat seinen Namen sehr wahrscheinlich von ihr. Dalaran und Alterac lagen in der Nähe. Dieses Zeitalter ist vorbei, und der See ist heute eine Grenze. Er liegt zwischen den Ländern der Verlassenen in Tirisfal und im Silberwald und dem umkämpften Alteracgebirge.\n\nIn seiner Mitte liegt die Insel Fenris, wo Fäulnisfell-Gnolle eine alte Burg der Armee von Lordaeron halten. Östlich davon haben die Finsterflossen-Murlocs die kleinen Morgeninseln überrannt.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Maldens Obsthain",
			short = "Die Bäume in Maldens Obsthain sind dunkel und immergrün geworden, und ihre Früchte wurden seit Jahren nicht gepflückt.",
			full = "Die Bäume in Maldens Obsthain sind dunkel und immergrün geworden, und ihre Früchte wurden seit Jahren nicht gepflückt. Der Obsthain hat seinen Namen von seinem Besitzer, der aus seinem Heim floh, als die Geißel in Lordaeron einfiel.\n\nSchwarze Worge hausen jetzt zwischen den Bäumen und rund um das einzige kleine Häuschen des Obsthains.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "North Tide's Hollow",
			short = "North Tide's Hollow liegt gleich nördlich des Grabmals im Silberwald. Es ist eines der vielen Verstecke der Mondzorn-Worgen, Diener von Erzmagier Arugal.",
			full = "North Tide's Hollow liegt gleich nördlich des Grabmals im Silberwald. Es ist eines der vielen Verstecke der Mondzorn-Worgen, Diener von Erzmagier Arugal. Hier errichten sie grobe Lager mit nur dem Nötigsten zum Überleben, Unterschlupf genug für Geschöpfe, die von Zahn und Kraft leben.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "North Tide's Run",
			short = "Die nordwestliche Küste des Silberwalds, wo der Strand auf das kalte Große Meer trifft, trägt den Namen North Tide's Run.",
			full = "Die nordwestliche Küste des Silberwalds, wo der Strand auf das kalte Große Meer trifft, trägt den Namen North Tide's Run. Halb im Flachwasser versunken liegt ein zerbrochenes Schiff der Horde, sein Rumpf in die Brandung gesackt, das auffälligste Zeichen an diesem Küstenstreifen.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Olsen's Farthing",
			short = "Olsen's Farthing war einst ein belebter Hof an der großen Handelsstraße durch den Silberwald. Jetzt liegt er in Trümmern. Untote unter dem Befehl von Thule Rabenklaue halten den Hof und greifen jeden an, der sich nähert.",
			full = "Olsen's Farthing war einst ein belebter Hof an der großen Handelsstraße durch den Silberwald. Jetzt liegt er in Trümmern. Untote unter dem Befehl von Thule Rabenklaue halten den Hof und greifen jeden an, der sich nähert.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "Pyrewood",
			short = "Bei Tag ist Pyrewood eine menschliche Siedlung mit einem Rathaus, einer Schmiede und einer Kapelle.",
			full = "Bei Tag ist Pyrewood eine menschliche Siedlung mit einem Rathaus, einer Schmiede und einer Kapelle. Die Bewohner haben das Kommen der Geißel überlebt, und sie verkaufen Reisenden noch immer Stoff, Leder und Kettenrüstung.\n\nDann bricht die Nacht herein. Von Burg Shadowfang auf der Klippe darüber hat Erzmagier Arugal das Dorf verflucht. Jeden Abend verwandeln sich seine Bewohner in Mondzorn-Worgen und greifen jeden in ihrer Nähe an, gleich auf welcher Seite er steht. Im Morgengrauen erwachen sie wieder als Menschen. Ein Rat der Dorfvorsteher herrscht hier, und jedes Mitglied dient Arugal.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "Das Grabmal",
			short = "Das Grabmal liegt in den westlichen Hügeln über der Küste von Lordaeron. Einst war es nur ein großer Friedhof neben der Straße, die den Silberwald durchquert, und seine Krypten waren eine Ruhestätte für die Toten.",
			full = "Das Grabmal liegt in den westlichen Hügeln über der Küste von Lordaeron. Einst war es nur ein großer Friedhof neben der Straße, die den Silberwald durchquert, und seine Krypten waren eine Ruhestätte für die Toten. Seit dem Dritten Krieg haben die Verlassenen den alten Friedhof zu ihrem Stützpunkt in der Gegend gemacht, ein Ort, der für die Toten gebaut wurde und nun denen dient, die nicht sterben.\n\nIm Süden sind die Worgen, im Osten die Geißel und im Südosten die Streitkräfte der Kirin Tor. Fast von allen Seiten umzingelt, halten die Verlassenen einen der wenigen Orte im Wald, an denen die Horde sicher stehen kann.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Burg Shadowfang",
			short = "Baron Silverlaine hielt diese Burg einst auf einer hohen Klippe über Pyrewood. Als die Geißel über Lordaeron hinwegfegte, beschwor Erzmagier Arugal die Worgen gegen den Rat der Kirin Tor.",
			full = "Baron Silverlaine hielt diese Burg einst auf einer hohen Klippe über Pyrewood. Als die Geißel über Lordaeron hinwegfegte, beschwor Erzmagier Arugal die Worgen gegen den Rat der Kirin Tor.\n\nDie Worgen schlugen die Geißel nieder, belagerten dann die Burg und töteten den Baron. Arugal, wahnsinnig vor Schuld, nahm die Worgen als seine Kinder an und zog sich ins Innere zurück. Er nannte den Ort Burg Shadowfang. Er soll noch immer dort sein, bewacht von seinem großen Haustier Fenrus und heimgesucht vom Geist des Barons.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "Der leuchtende Strand",
			short = "Ein langes Ufer des Lordameresees zieht sich von der Hauptstadt Lordaeron im Norden bis zu den rauen Hügeln, die den Silberwald vom Alteracgebirge trennen.",
			full = "Ein langes Ufer des Lordameresees zieht sich von der Hauptstadt Lordaeron im Norden bis zu den rauen Hügeln, die den Silberwald vom Alteracgebirge trennen. Das ist der leuchtende Strand.\n\nDie Finsterflossen-Murlocs haben mehrere Siedlungen entlang des Ufers, und Reisende, die es nicht kennen, finden es gefährlich.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "Das Huschdunkel",
			short = "Netzhuscherspinnen haben diese verlassene Mine übernommen. Die Netzhuschermatriarchin, eine gigantische Spinne, versteckt sich tief in ihrem Inneren.",
			full = "Netzhuscherspinnen haben diese verlassene Mine übernommen. Die Netzhuschermatriarchin, eine gigantische Spinne, versteckt sich tief in ihrem Inneren. Draußen liegen Kokons auf dem Boden, jeder mit einem gefangenen Worgen, Worg oder Bären darin oder mit einem Orc von dem Schiff, das im Westen am Ufer zerschellt ist. Eine seltene Spinne, Krethis der Schattenspinner, streift manchmal vor der Mine umher.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "South Tide's Run",
			short = "Die südwestliche Küste des Silberwalds, wo das Land auf das Große Meer trifft, heißt South Tide's Run.",
			full = "Die südwestliche Küste des Silberwalds, wo das Land auf das Große Meer trifft, heißt South Tide's Run.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Valgans Feld",
			short = "Valgans Feld war eine Weizenfarm und hat seinen Namen von dem Mann, dem sie gehörte. Als die Geißel im Silberwald eintraf, wurde er getötet oder musste fliehen.",
			full = "Valgans Feld war eine Weizenfarm und hat seinen Namen von dem Mann, dem sie gehörte. Als die Geißel im Silberwald eintraf, wurde er getötet oder musste fliehen. Von den Feldern hatte man einen herrlichen Blick auf den Lordameresee.\n\nJetzt steht die Farm leer, einer der verlassenen Höfe im Norden des Waldes, westlich des leuchtenden Strandes.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- Westliche Pestländer: 17 subzones
	[1422] = {
		["bulwark"] = {
			name = "Das Bollwerk",
			short = "Nach dem Fall von Lordaeron errichtete Uther der Lichtbringer hier ein Lager für die Überlebenden, an der Grenze, wo Tirisfal auf die Westlichen Pestländer trifft.",
			full = "Nach dem Fall von Lordaeron errichtete Uther der Lichtbringer hier ein Lager für die Überlebenden, an der Grenze, wo Tirisfal auf die Westlichen Pestländer trifft. Jetzt halten die Verlassenen den Boden gegen die Geißel, und Soldaten der Argentumdämmerung stehen an ihrer Seite.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "Caer Darrow",
			short = "Menschen bauten die Festung Caer Darrow vor langer Zeit, und ein uralter hochelfischer Runenstein wurde in ihr aufgestellt.",
			full = "Menschen bauten die Festung Caer Darrow vor langer Zeit, und ein uralter hochelfischer Runenstein wurde in ihr aufgestellt. Im Zweiten Krieg fiel die Horde auf der Insel ein, plünderte die Burg und hieb den Runenstein in die Stücke, aus denen die Altäre der Stürme gefertigt wurden. Gul'dan nutzte sie, um seinen Ogerverbündeten Magie einzuflößen.\n\nNach dem Krieg wurde die Burg wiederhergestellt und zum Landsitz des Hauses Barov. In den Jahren vor dem Dritten Krieg wurden die Barovs gierig und verbittert und wollten ihr Vermögen und ihr Land über die eigene Lebensspanne hinaus behalten. Kel'Thuzad, der Anführer des Kults der Verdammten, bot einen Weg an. Unter dem Landsitz wurden die Katakomben zu Scholomance, einer Schule der Nekromantie, und die Diener der Familie dienten dazu, die Seuche des Untodes zu erproben. Binnen sechs Monaten brach eine Krankheit aus und tötete alle auf der Insel. Ihre Geister bleiben, jeder dazu gebunden, noch einmal zu durchleben, was er zuletzt erfuhr.",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "Chillwind-Lager",
			short = "Kommandant Ashlam Valorfist hält das Chillwind-Lager für die Argentumdämmerung.",
			full = "Kommandant Ashlam Valorfist hält das Chillwind-Lager für die Argentumdämmerung. Es liegt am südlichen Eingang der Westlichen Pestländer, wo die Straße aus dem Alteracgebirge herabkommt, und es ist der letzte sichere Boden für Reisende der Allianz. Die Argentumdämmerung hat hier nur wenige Truppen und Spezialisten, also stützt sie sich auf Söldner und führt bei Andorhal und an den Seuchenkesseln einen Guerillakrieg gegen die Geißel.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "Dalsons Tränenfeld",
			short = "Dalsons Obstgarten trug einst Früchte für die Familie, die ihm ihren Namen gab. Jetzt hält die Geißel den Hof.",
			full = "Dalsons Obstgarten trug einst Früchte für die Familie, die ihm ihren Namen gab. Jetzt hält die Geißel den Hof. Ein Seuchenkessel hockt auf dem Feld und atmet Krankheit aus, und Kessellord Malvinius bewacht ihn mit verseuchten Zombies und skelettierten Schrecken.\n\nDie Dalsons sind nie gegangen. Frau Dalson wandelt noch immer über den Hof ihrer Familie, jetzt ein Skelett. Ihr Mann ist im Abort eingesperrt. Er ist zum Ghul geworden.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "Darrowmeresee",
			short = "Der Darrowmeresee ist einer der größten Seen der Östlichen Königreiche und einer der symbolträchtigsten Orte des gefallenen Königreichs Lordaeron.",
			full = "Der Darrowmeresee ist einer der größten Seen der Östlichen Königreiche und einer der symbolträchtigsten Orte des gefallenen Königreichs Lordaeron. Im Norden ist der Thondroril mit ihm verbunden und im Süden der Fluss Darrowmere. In der Mitte liegt die Inselstadt Caer Darrow, wo einst das Haus Barov lebte. Jetzt ist sie verlassen. Darunter liegt Scholomance, wo der Kult der Verdammten unter seinen Untoten wirkt.",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "Teufelssteinfeld",
			short = "Das Teufelssteinfeld nährte einst die Lebenden. Die Geißel überrannte es und stellte mitten auf das Feld einen Kessel, und seither strömt dichter, krankheitsschwerer Dunst aus ihm.",
			full = "Das Teufelssteinfeld nährte einst die Lebenden. Die Geißel überrannte es und stellte mitten auf das Feld einen Kessel, und seither strömt dichter, krankheitsschwerer Dunst aus ihm. Kessellord Gallenschlund bewacht ihn mit skelettierten Zauberern und geifernden Ghulen. Eine Gruppe des Scharlachroten Kreuzzugs ist auch hier und übt Rache an Lebenden und Toten gleichermaßen. In dem Haus an der nordöstlichen Ecke des Feldes ist Janice Teufelsstein noch immer zu Hause.",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "Gahrrons Trauerfeld",
			short = "Der Hof am östlichen Rand der Westlichen Pestländer gehörte einst Del Gahrron, und in besseren Zeiten hieß er Gahrrons Erwachen. Heute wächst dort nichts mehr.",
			full = "Der Hof am östlichen Rand der Westlichen Pestländer gehörte einst Del Gahrron, und in besseren Zeiten hieß er Gahrrons Erwachen. Heute wächst dort nichts mehr. Die Geißel nahm das Feld und errichtete einen Kessel in seiner Mitte, und Kessellord Rachseele bewacht ihn mit anderen Offizieren der Geißel. Heimsuchende Visionen, klagende Tote und hungernde Gespenster treiben über die zerstörten Reihen.",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "Hearthglen",
			short = "Die Horde nahm Hearthglen im Zweiten Krieg nie ein, und die Geißel nahm es ebenso wenig, obwohl seine Bewohner gerade Brot aus verseuchtem Getreide von Andorhal gebacken hatten, als die Toten kamen.",
			full = "Die Horde nahm Hearthglen im Zweiten Krieg nie ein, und die Geißel nahm es ebenso wenig, obwohl seine Bewohner gerade Brot aus verseuchtem Getreide von Andorhal gebacken hatten, als die Toten kamen. Seine Mauern umschließen ein Rathaus, einen Magierturm, ein Sägewerk, Ställe, eine Mine und Burg Mardenholde, von der aus die Region regiert wurde. Jetzt hält der Scharlachrote Kreuzzug die Stadt und die Burg, und seine Soldaten schlagen hinter den Mauern hervor gegen die Geißel zu.",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "Burg Mardenholde",
			short = "Tirion Fordring war Herr von Burg Mardenholde, bis er exkommuniziert wurde, und sein Sohn Taelan übernahm die Burg nach ihm.",
			full = "Tirion Fordring war Herr von Burg Mardenholde, bis er exkommuniziert wurde, und sein Sohn Taelan übernahm die Burg nach ihm. Taelan ist jetzt Hochlord des Scharlachroten Kreuzzugs, und die Burg ist das Hauptquartier des Kreuzzugs in den Westlichen Pestländern.",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "Holzlager Northridge",
			short = "Der Scharlachrote Kreuzzug betreibt hier das Sägewerk, im Norden der Westlichen Pestländer nahe Hearthglen.",
			full = "Der Scharlachrote Kreuzzug betreibt hier das Sägewerk, im Norden der Westlichen Pestländer nahe Hearthglen. Das Holz, das er schlägt, ist ein Vorrat, den der Kreuzzug braucht, und sowohl die Allianz als auch die Horde würden ihn gern verderben sehen. Vor dem Dritten Krieg wurde das Sägewerk von der Familie von Nathaniel Dumah geführt.",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["ruins of andorhal"] = {
			name = "Die Ruinen von Andorhal",
			short = "Andorhal war die Kornkammer des nördlichen Lordaeron.",
			full = "Andorhal war die Kornkammer des nördlichen Lordaeron. Sein Getreide ging an die Städte des Nordens, und der Nekromant Kel'Thuzad und sein Kult der Verdammten verseuchten es mit der Seuche des Untodes, bevor es die Stadt verließ.\n\nAls die Geißel auf die Stadt zukam, steckten ihre verzweifelten Verteidiger sie in Brand, damit die Geißel keine weiteren Krieger aus den Toten erheben konnte. Jetzt liegt sie in Trümmern. Ghule schleppen sich zwischen den gefallenen Steinen dahin, Skelette stehen Wache, wo einst Wächter standen, Banshees klagen über den Ruinen, und Monstrositäten stapfen durch die Trümmer der Häuser. Der Lich Araj der Beschwörer hält die Stadt als seinen Stützpunkt und überwacht die Seuchenkessel in den gesamten Westlichen Pestländern.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "Scholomance",
			short = "Das Haus Barov hatte seinen Landsitz auf dieser Anhöhe über Caer Darrow, und sein Reich reichte von Caer Darrow bis nach Brill, Southshore und Tarrens Mühle.",
			full = "Das Haus Barov hatte seinen Landsitz auf dieser Anhöhe über Caer Darrow, und sein Reich reichte von Caer Darrow bis nach Brill, Southshore und Tarrens Mühle. Um sein Vermögen über den Tod hinaus zu bewahren, übergab die Familie den Landsitz und seine Krypten an Kel'Thuzad und seinen Kult der Verdammten, im Tausch gegen den Segen der Unsterblichkeit durch den Lichkönig.\n\nDer Kult machte die Krypten zu einer Schule der Nekromantie, und die Barovs bleiben als untote Ungeheuer. Der Lich Ras Frostraunen herrscht über den Ort und bewacht ihn für die Geißel, während der sterbliche Nekromant Dunkelmeister Gandling als sein Schulleiter dient.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "Sorrow Hill",
			short = "In friedlichen Jahren war Sorrow Hill der Ort, an dem Andorhal seine Toten begrub, Reiche und Arme gleichermaßen.",
			full = "In friedlichen Jahren war Sorrow Hill der Ort, an dem Andorhal seine Toten begrub, Reiche und Arme gleichermaßen. Als die Seuche kam und die Geißel ohne Ende plünderte, vermehrten sich die Gräber schneller, als irgendjemand sie kennzeichnen konnte. Eilig aufgeworfene Hügel bedecken noch immer den Boden, wo Verteidiger fielen. Schließlich hörten die Überlebenden auf zu begraben und verbrannten ihre Toten in einem Massengrab südlich des Friedhofs, aus Angst, was die Seuche aus ihnen machen würde. Als Prinz Arthas Menethil Uther den Lichtbringer niederstreckte, wurde auf dem Hügel ein großes Grabmal errichtet und der zerschundene Körper des Paladins darin beigesetzt.\n\nTrotzdem ließen die Seuchenkessel die Toten des Hügels auferstehen. Soldaten und Stadtbewohner stehen Wache über ihren eigenen Gräbern.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "Thondroril",
			short = "Der Thondroril bildet die Grenze zwischen den Westlichen und den Östlichen Pestländern. Er fließt nach Süden in den Darrowmeresee und setzt sich darunter als Fluss Darrowmere fort.",
			full = "Der Thondroril bildet die Grenze zwischen den Westlichen und den Östlichen Pestländern. Er fließt nach Süden in den Darrowmeresee und setzt sich darunter als Fluss Darrowmere fort. Maden, Vampirfledermäuse, Seuchenbären und Spinnen drängen sich an seinen Ufern.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "Uthers Grabmal",
			short = "Uthers Grabmal steht auf Sorrow Hill, dem einen Ort in den Westlichen Pestländern, an dem das Licht noch gegen das Sterben des Landes besteht.",
			full = "Uthers Grabmal steht auf Sorrow Hill, dem einen Ort in den Westlichen Pestländern, an dem das Licht noch gegen das Sterben des Landes besteht.\n\nUther der Lichtbringer hielt einst Andorhal gegen die Geißel und stand neben dem Weisen Wahrheitsträger und Ballador dem Strahlenden, die Ritter der Silbernen Hand im Rücken. Arthas Menethil beendete diesen Widerstand. Er führte sein untotes Heer gegen die Stadt und erschlug Wahrheitsträger, Ballador und Uther selbst.\n\nUthers eigene Soldaten bargen seinen Leichnam, trugen ihn südlich der Ruinen von Andorhal und errichteten ein großes Grabmal über ihm. Sein Grabstein zeigt ihn, wie er im Leben war, ein Buch des Lichts in der einen Hand und seinen Kriegshammer in der anderen.\n\nHohepriester Thel'danis hütet das Grabmal als Verwalter und Wächter. Das Grab ist denen heilig, die dem Licht folgen.",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "Die weinende Höhle",
			short = "Die weinende Höhle öffnet sich im nordöstlichen Teil der Westlichen Pestländer, gleich westlich des Thondroril.",
			full = "Die weinende Höhle öffnet sich im nordöstlichen Teil der Westlichen Pestländer, gleich westlich des Thondroril. Sumpfbestien und Schleime füllen ihre Hohlräume, und im Dunkeln schlurfen verwesende Behemoths und faulende Schrecken umher. Ein seltenes Elementar namens Hülle lauert unter ihnen.",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "Das trostlose Feld",
			short = "In den Furchen des trostlosen Feldes wuchsen einst Feldfrüchte, gepflegt zur Nahrung der Lebenden.",
			full = "In den Furchen des trostlosen Feldes wuchsen einst Feldfrüchte, gepflegt zur Nahrung der Lebenden. Die Geißel nahm die Felder ein und stellte in ihre Mitte einen großen Kessel, der seither nicht aufgehört hat zu arbeiten. Ein ständiger Strom krankheitsschweren Dunstes wälzt sich über die Reihen.\n\nKessellord Razarch hält Wache darüber, und um ihn bewegen sich verrottende Ghule, frierende Ghule und stinkende Zombies, an den Ort gebunden als seine Wächter.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- Östliche Pestländer: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "Blackwoodsee",
			short = "Am Ufer dieses Sees stand einst eine Stadt namens Blackwood, Heimat von Großmarschall Othmar Garithos, der sie als Baron regierte. Von ihr ist nichts geblieben außer dem Namen.",
			full = "Am Ufer dieses Sees stand einst eine Stadt namens Blackwood, Heimat von Großmarschall Othmar Garithos, der sie als Baron regierte. Von ihr ist nichts geblieben außer dem Namen.\n\nDas Wasser ist jetzt faul, und verderbte Wasserelementare winden sich darin. Die Annalen von Darroheim berichten, dass der Schädel des Ghulfürsten Horgus der Verheerer auf dem Grund des Sees liegt. Paladine der Silbernen Hand warfen ihn dorthin, nachdem sie die Schar der Geißel besiegt hatten, die ihn davongetragen hatte.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "Braumanns Mühle",
			short = "Skelette, Banshees und Monstrositäten drängen sich in Braumanns Mühle, einem heimgesuchten Sägewerk nördlich der Kapelle des hoffnungsvollen Lichts.",
			full = "Skelette, Banshees und Monstrositäten drängen sich in Braumanns Mühle, einem heimgesuchten Sägewerk nördlich der Kapelle des hoffnungsvollen Lichts. Sein Besitzer, Stephan Braumann, wurde getötet und im Dienst der Geißel als Ghul erweckt, und er hält in seiner alten Mühle Wache.",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "Corins Kreuzung",
			short = "Corins Kreuzung liegt dort, wo die Straßen nach Andorhal, Darrowshire, Stratholme und Tyrs Hand zusammentreffen, zwischen der Infektnarbe und dem Mereldarsee.",
			full = "Corins Kreuzung liegt dort, wo die Straßen nach Andorhal, Darrowshire, Stratholme und Tyrs Hand zusammentreffen, zwischen der Infektnarbe und dem Mereldarsee. Sein Rathaus und seine Schmiede stehen noch zwischen den Ruinen, doch die Geißel füllt die Straßen bis zum Rand.\n\nUnter den Toten bewegen sich Wesen, die man überhaupt nicht sehen kann, die Unsichtbaren Diener, und nichts schleicht unbemerkt an ihnen vorbei.",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "Turm der Kronenwache",
			short = "Lordaeron errichtete Spähtürme wie diesen, um seine Grenzen zu beobachten und Feinde schon von Weitem zu erkennen. Als die Geißel durch das Königreich fegte, wurde der Turm der Kronenwache zerstört.",
			full = "Lordaeron errichtete Spähtürme wie diesen, um seine Grenzen zu beobachten und Feinde schon von Weitem zu erkennen. Als die Geißel durch das Königreich fegte, wurde der Turm der Kronenwache zerstört. Jetzt steht er in Trümmern.\n\nDie Horde und die Allianz streiten beide um den zerbrochenen Turm, jede in der Hoffnung, sich von hier aus in Lordaeron festzusetzen.",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["darrowshire"] = {
			name = "Darrowshire",
			short = "Im Dritten Krieg führten der Ghulfürst Horgus der Verheerer und der Todesritter Marduk der Schwarze ein Heer der Geißel gegen Darrowshire.",
			full = "Im Dritten Krieg führten der Ghulfürst Horgus der Verheerer und der Todesritter Marduk der Schwarze ein Heer der Geißel gegen Darrowshire. Paladine unter Davil Lichterschein und die Miliz unter Hauptmann Joseph Rotpfad kämpften hart dagegen. Davil tötete Horgus, doch die Wunden, die er davontrug, töteten auch ihn. Die endlosen Legionen zermürbten den Rest, und jeder Verteidiger wurde abgeschlachtet.\n\nSie erhoben sich wieder als Ghule, ihre Geister gefangen in verwesendem Fleisch, und dienen der Geißel. Darrowshire liegt still und in Trümmern. Sehr selten führen Geister die Schlacht noch einmal auf.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["eastwall gate"] = {
			name = "Ostwalltor",
			short = "Das Ostwalltor ist ein Seiteneingang nach Stratholme. Es öffnet sich direkt auf den Platz der Ältesten, neben der Alonsus-Kapelle, in der die ersten Paladine der Silbernen Hand vor dem Zweiten Krieg geweiht wurden.",
			full = "Das Ostwalltor ist ein Seiteneingang nach Stratholme. Es öffnet sich direkt auf den Platz der Ältesten, neben der Alonsus-Kapelle, in der die ersten Paladine der Silbernen Hand vor dem Zweiten Krieg geweiht wurden.\n\nHinter dem Tor kämpfen der Scharlachrote Kreuzzug und die Geißel um die Stadt.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Gate",
		},
		["eastwall tower"] = {
			name = "Ostwallturm",
			short = "Der Ostwallturm steht nahe der Kapelle des hoffnungsvollen Lichts, ein Späherturm von Lordaeron. Die Invasion der Geißel zerstörte ihn, und nur Ruinen sind übrig, die über das tote Land wachen.",
			full = "Der Ostwallturm steht nahe der Kapelle des hoffnungsvollen Lichts, ein Späherturm von Lordaeron. Die Invasion der Geißel zerstörte ihn, und nur Ruinen sind übrig, die über das tote Land wachen.\n\nDie Horde und die Allianz kämpfen beide um die Ruine, und jede will von ihr aus Boden in Lordaeron halten.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Tower",
		},
		["fungal vale"] = {
			name = "Das Fungustal",
			short = "Nördlich von Marris' Siedlung und dem Turm der Kronenwache liegt das Fungustal, ein Boden, der unter trübem Dunst dunkelviolett geworden ist.",
			full = "Nördlich von Marris' Siedlung und dem Turm der Kronenwache liegt das Fungustal, ein Boden, der unter trübem Dunst dunkelviolett geworden ist. Die Seuche des Untodes hat hier einen ihrer tiefsten Stützpunkte eingenommen, und die Geißel und der Kult der Verdammten bewegen sich frei durch die Verderbnis.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
		},
		["infectis scar"] = {
			name = "Die Infektnarbe",
			short = "Nahe Corins Kreuzung kämpfte der Todesritter Marduk der Schwarze gegen einen Zwergenhauptmann. Der verzauberte Schild des Hauptmanns zerschmetterte Marduks runenbeladenes Schwert, und Marduk floh mit nur dem Heft.",
			full = "Nahe Corins Kreuzung kämpfte der Todesritter Marduk der Schwarze gegen einen Zwergenhauptmann. Der verzauberte Schild des Hauptmanns zerschmetterte Marduks runenbeladenes Schwert, und Marduk floh mit nur dem Heft. Die Klinge sank in die Erde und fraß eine Schlucht in das Land.\n\nDiese Schlucht ist die Infektnarbe. Dunkle Magie schuf sie, anders als die Pestilenznarbe, die eine natürliche Schlucht ist.",
			source = "https://warcraft.wiki.gg/wiki/Infectis_Scar",
		},
		["lake mereldar"] = {
			name = "Mereldarsee",
			short = "Verderbte Wasserelementare ziehen durch den Mereldarsee, einen großen See südlich von Corins Kreuzung, dessen Wasser die Seuche verschmutzt hat.",
			full = "Verderbte Wasserelementare ziehen durch den Mereldarsee, einen großen See südlich von Corins Kreuzung, dessen Wasser die Seuche verschmutzt hat. Am Ufer stehen die Ruinen eines alten Hauses und eine Hütte samt Fähre, die zu einem Hof gehörten.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["lights hope chapel"] = {
			name = "Kapelle des hoffnungsvollen Lichts",
			short = "Als eine der ältesten und am meisten verehrten heiligen Stätten der Kirche des Heiligen Lichts steht die Kapelle des hoffnungsvollen Lichts an den Hängen der Berge im Osten der Region.",
			full = "Als eine der ältesten und am meisten verehrten heiligen Stätten der Kirche des Heiligen Lichts steht die Kapelle des hoffnungsvollen Lichts an den Hängen der Berge im Osten der Region. Sie ist jetzt die Hauptfestung der Argentumdämmerung, die Kämpfer jeder Rasse aufnimmt und sowohl die Allianz als auch die Horde zu ihren Verbündeten zählt.\n\nDrinnen wahrt Kommandant Eligor Dawnbringer von der Bruderschaft des Lichts den Frieden zwischen der Dämmerung und dem Scharlachroten Kreuzzug. Er hat sich hier mit scharlachroten Gesandten getroffen, um gegen Kel'Thuzad und die Geißel zu planen.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["marris stead"] = {
			name = "Marris' Siedlung",
			short = "Marris' Siedlung steht auf einer kleinen Anhöhe neben der Hauptstraße, seit langer Zeit das Gehöft von Nathanos Marris. Sein Vetter Stephon lebte eine Weile hier, und Fürstin Sylvanas Windrunner kam manchmal zu Besuch.",
			full = "Marris' Siedlung steht auf einer kleinen Anhöhe neben der Hauptstraße, seit langer Zeit das Gehöft von Nathanos Marris. Sein Vetter Stephon lebte eine Weile hier, und Fürstin Sylvanas Windrunner kam manchmal zu Besuch.\n\nNathanos wurde getötet, als die Geißel über Lordaeron hinwegfegte, und dann von Sylvanas befreit. Jetzt ist er einer der Verlassenen und auf ihren Befehl heimgekehrt, mit seinen Seuchenhunden. Er wirbt Soldaten der Horde an, um gegen die Geißel und den Scharlachroten Kreuzzug zu kämpfen, und er bewahrt im Haus Relikte aus der Schlacht von Darrowshire auf, aus Gründen, die er nicht preisgegeben hat.",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "Mazra'Alor",
			short = "Waldtroll-Schattenjäger vom Stamm der Moosschinder halten Mazra'Alor, die große Zikkurat im Herzen von Zul'Mashar. Kriegsherr Thresh'jin und Zul'Brin Wirbelstab haben darin ihr Heim.",
			full = "Waldtroll-Schattenjäger vom Stamm der Moosschinder halten Mazra'Alor, die große Zikkurat im Herzen von Zul'Mashar. Kriegsherr Thresh'jin und Zul'Brin Wirbelstab haben darin ihr Heim.",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
		},
		["northdale"] = {
			name = "Northdale",
			short = "Banshees und unsichtbare, augenlose Wächter spuken in den zerstörten Häusern von Northdale, einer vernichteten Stadt nördlich der Kapelle des hoffnungsvollen Lichts und südöstlich des Eingangs nach Quel'Thalas.",
			full = "Banshees und unsichtbare, augenlose Wächter spuken in den zerstörten Häusern von Northdale, einer vernichteten Stadt nördlich der Kapelle des hoffnungsvollen Lichts und südöstlich des Eingangs nach Quel'Thalas. Hier sagte sich Taelan Fordring vom Orden der Silbernen Hand los und schloss sich dem Scharlachroten Kreuzzug an. Der See in der Nähe ist voller verderbter Wasserelementare.",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "Nordpassturm",
			short = "Der Nordpassturm ist der nördlichste der Wachtürme in den Östlichen Pestländern und markiert die Straße nach Quel'Thalas.",
			full = "Der Nordpassturm ist der nördlichste der Wachtürme in den Östlichen Pestländern und markiert die Straße nach Quel'Thalas. Die Geißel fegte durch Lordaeron, und der Turm trägt ihre Narben noch immer.",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "Das giftige Tal",
			short = "Die Luft im giftigen Tal hängt dick und kränklich grün, und der Boden ist dunkelviolett gefärbt.",
			full = "Die Luft im giftigen Tal hängt dick und kränklich grün, und der Boden ist dunkelviolett gefärbt. Das Tal liegt einen Hügel hinauf nördlich der Kapelle des hoffnungsvollen Lichts, und die Verseuchung hat es schlimmer verdorben als den Rest der Pestländer. Die Geißel hat hier einen Seuchenkessel und ein Schlachthaus gebaut, und ihre Geschöpfe bewegen sich über den vergifteten Boden.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "Pestilenznarbe",
			short = "Eine tiefe Schlucht zeichnet die verseuchte Erde der Östlichen Pestländer. Sie wirkt natürlich, vielleicht ein See, der austrocknete, als die Seuche des Untodes zuschlug.",
			full = "Eine tiefe Schlucht zeichnet die verseuchte Erde der Östlichen Pestländer. Sie wirkt natürlich, vielleicht ein See, der austrocknete, als die Seuche des Untodes zuschlug. Schleime leben noch in ihrer Tiefe.",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "Der Pestwald",
			short = "Südlich von Stratholme hieß dieser Wald vor der Seuche Grünwald. Er stand grün und ungestört da, ein Waldland ganz ähnlich dem Wald von Elwynn, mit einem kleinen Dorf nahe dem Torbogen an seinem Eingang.",
			full = "Südlich von Stratholme hieß dieser Wald vor der Seuche Grünwald. Er stand grün und ungestört da, ein Waldland ganz ähnlich dem Wald von Elwynn, mit einem kleinen Dorf nahe dem Torbogen an seinem Eingang. Als Kel'Thuzad sein Werk begann, erreichte vergiftetes Getreide aus Andorhal das Dorf. Unteroffizier Morigan, ein Soldat aus Lordaeron, der von dort stammte, bemerkte als Erster, dass etwas nicht stimmte. Prinz Arthas durchquerte das Waldland auf seinem Weg nach Stratholme.\n\nWas danach blieb, war kein Wald mehr. Der Boden wurde schwammig unter den Füßen, und Pilze und Giftpilze schwollen auf die Größe von Bäumen an und überragten, was vom alten Waldland übrig war. Sie atmen ein dunkelbraunes Gas aus, nicht unähnlich den Dämpfen der Seuchenkessel der Geißel. Niemand kann sagen, ob der Pilz einfach in vergiftetem Boden wächst oder ob die Geißel ihn züchtet, um ihre Krankheit zu verbreiten. Der Wald erhielt durch diese Wandlung den Namen Pestwald.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "Quel'Lithien-Lodge",
			short = "Die Quel'Lithien-Lodge war ein Lager der Weitschreiter nahe Quel'Thalas, ein Ort der Wärme und Gastfreundschaft.",
			full = "Die Quel'Lithien-Lodge war ein Lager der Weitschreiter nahe Quel'Thalas, ein Ort der Wärme und Gastfreundschaft. Die Lodge beherbergte einst eine Reihe elfischer Dokumente, manche davon über die Königsfamilie und den Waldläufergeneral von Silbermond. Zur Zeit des Zweiten Krieges führte Renthar Hawkspear die Jäger dort an.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "Scharlachroter Stützpunkt",
			short = "Der Scharlachrote Stützpunkt ist eine kleine Befestigung aus Barrikaden am Ostufer des Mereldarsees, nicht weit von Tyrs Hand.",
			full = "Der Scharlachrote Stützpunkt ist eine kleine Befestigung aus Barrikaden am Ostufer des Mereldarsees, nicht weit von Tyrs Hand.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "Die Scharlachrote Basilika",
			short = "Der Hauptsitz der religiösen Macht des Scharlachroten Kreuzzugs ist die Scharlachrote Basilika, eine große Kathedrale in Tyrs Hand, wo Kreuzzüglerlord Valdelmar zu finden ist.",
			full = "Der Hauptsitz der religiösen Macht des Scharlachroten Kreuzzugs ist die Scharlachrote Basilika, eine große Kathedrale in Tyrs Hand, wo Kreuzzüglerlord Valdelmar zu finden ist. Sie steht nahe der Abtei von Tyrs Hand und hat Verbindungen zum weit entfernten Scharlachroten Kloster in Tirisfal. Das Gebäude ähnelt stark der Kathedrale des Lichts in Stormwind.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "Stratholme",
			short = "Der Untergang von Stratholme begann mit Getreide. Lieferungen aus Andorhal, vom Kult der Verdammten verseucht, wurden zu Brot gebacken und von einer Bevölkerung gegessen, die nie erfuhr, dass sie starb.",
			full = "Der Untergang von Stratholme begann mit Getreide. Lieferungen aus Andorhal, vom Kult der Verdammten verseucht, wurden zu Brot gebacken und von einer Bevölkerung gegessen, die nie erfuhr, dass sie starb. Prinz Arthas Menethil traf mit Uther dem Lichtbringer und Jaina Proudmoore ein und fand die Seuche bereits in Ausbreitung. Arthas glaubte, der einzige Weg, die Stadt daran zu hindern, eine Festung der Geißel zu werden, sei, sie zu säubern, und er befahl, die verseuchten Bürger zu töten. Uther und Jaina hielten es für Wahnsinn und weigerten sich. Arthas machte mit seinen eigenen Soldaten weiter. Feuer fegte durch die Straßen, und fast jede Seele in Stratholme wurde niedergemetzelt. Der Schreckenslord Mal'Ganis, den Arthas zu töten gekommen war, entkam dem Gemetzel.\n\nDie Untoten zogen ein, und die Stadt wurde die Hauptstadt der Geißel in Lordaeron. Stratholme brennt noch immer. Der Scharlachrote Kreuzzug unter dem Obersten Kreuzzügler Dathrohan hält die eine Hälfte der Ruine, die Geißel unter Baron Rivendare die andere, und die beiden Seiten kämpfen ohne Pause.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "Schreckenstal",
			short = "Geister spuken in den Straßen von Schreckenstal, einer kleinen Stadt in der Nordwestecke der Östlichen Pestländer.",
			full = "Geister spuken in den Straßen von Schreckenstal, einer kleinen Stadt in der Nordwestecke der Östlichen Pestländer. Sie liegt am Rand des Pestwaldes, und außer dem Händler Augustus dem Meschuggenen und dem Geisterjäger Egan streifen nur noch die Geißel und verseuchte Tiere hindurch. An manchen Stellen scheint die Stadt einzuknicken, als gäbe die Welt unter der Qual der Geisterwelt nach.",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "Terrorweb-Tunnel",
			short = "Gruftunholde füllen den Terrorweb-Tunnel, einen langen, gewundenen Gang durch den Berg, der von Schreckenstal im Norden bis zum Thondroril im Süden verläuft.",
			full = "Gruftunholde füllen den Terrorweb-Tunnel, einen langen, gewundenen Gang durch den Berg, der von Schreckenstal im Norden bis zum Thondroril im Süden verläuft. Hin und wieder streift ein Nerubischer Aufseher, weit mächtiger als die übrigen, durch seine ganze Länge. Tirion Fordring steht an der Mündung des Tunnels beim Fluss.",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "Thondroril",
			short = "Tirion Fordring, einer der ersten Paladine der Silbernen Hand, hält sich auf der Ostseite des Thondroril auf, nahe einem zerstörten Bauernhaus.",
			full = "Tirion Fordring, einer der ersten Paladine der Silbernen Hand, hält sich auf der Ostseite des Thondroril auf, nahe einem zerstörten Bauernhaus. Der Fluss bildet die Grenze zwischen den Westlichen und den Östlichen Pestländern. Er entspringt im Norden und fließt nach Süden in den Darrowmeresee, und unterhalb des Sees setzt er sich als Fluss Darrowmere fort.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "Tyrs Hand",
			short = "Tyrs Hand ist eine befestigte Stadt der Menschen, eine der letzten Bastionen der Lebenden gegen die Geißel in der Region.",
			full = "Tyrs Hand ist eine befestigte Stadt der Menschen, eine der letzten Bastionen der Lebenden gegen die Geißel in der Region. Ihre Umgebung ist in weit besserem Zustand als der Rest der Pestländer, auch wenn die Bäume und Pflanzen noch immer verfallen.\n\nDie Stadt gehört zu den ältesten und meistverehrten heiligen Stätten der Kirche des Lichts und besteht fast ausschließlich aus Kirchen, gekrönt von der Scharlachroten Basilika und der befestigten Abtei.\n\nAls die Geißel kam und die Östlichen Lande zu den Pestländern wurden, fiel Tyrs Hand nicht. Unter Lord Valdelmar hielt sie täglichen Angriffen stand, geschützt zuerst von den Rittern der Silbernen Hand und später vom Scharlachroten Kreuzzug, und schickte Vorräte und Verstärkung weiter zu anderen Stützpunkten des Kreuzzugs, während Kuriere, die sich durch die seuchenverpesteten Straßen kämpfen mussten, täglich Berichte aus Stratholme brachten.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "Das Tiefgewölbe",
			short = "Untote Trolle haben eine Gruft im Südwesten der Östlichen Pestländer zu ihrem Bau gemacht. Zaeldarr der Ausgestoßene, ein von den Toten auferstandener Schreckenstroll, führt sie an.",
			full = "Untote Trolle haben eine Gruft im Südwesten der Östlichen Pestländer zu ihrem Bau gemacht. Zaeldarr der Ausgestoßene, ein von den Toten auferstandener Schreckenstroll, führt sie an. Von Zeit zu Zeit überfällt seine Bande die Grabgrube der Argentumdämmerung bei der Kapelle des hoffnungsvollen Lichts und trägt die Leichen zurück in das Tiefgewölbe.",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "Zul'Mashar",
			short = "Die Moosschinder, ein kleiner Stamm von Waldtrollen, herrschten einst von Zul'Mashar aus.",
			full = "Die Moosschinder, ein kleiner Stamm von Waldtrollen, herrschten einst von Zul'Mashar aus. Lange Kämpfe mit den Menschen von Lordaeron stürzten ihr Land in Unordnung, und die Trolle eroberten Teile davon zurück, ehe die Seuche des Untodes kam und noch mehr Schaden anrichtete. Die Stadt ist ein Schatten ihrer früheren Pracht. Einige vom Stamm werden heimlich in Untote verwandelt, und die Stadt läuft Gefahr, eine Bastion der Toten zu werden.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- Vorgebirge von Hillsbrad: 24 subzones
	[1424] = {
		["azurelode mine"] = {
			name = "Der Azurschacht",
			short = "Aus dieser Mine kommt Eisen für die Waffenkammern der Allianz. Bergleute von den Feldern von Hillsbrad bauen es unter Großknecht Bonds ab, und Wachen sichern die Mine zu ihrem Schutz.",
			full = "Aus dieser Mine kommt Eisen für die Waffenkammern der Allianz. Bergleute von den Feldern von Hillsbrad bauen es unter Großknecht Bonds ab, und Wachen sichern die Mine zu ihrem Schutz. Sie liegt im Südwesten des Vorgebirges, südlich der Felder.",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
		},
		["chillwind point"] = {
			name = "Chillwindspitze",
			short = "Kalter Wind strömt hier aus den Pestländern die Schlucht herab, und die Anhöhe hat ihren Namen von ihm. Der Pass gehörte einst zum Königreich Lordaeron.",
			full = "Kalter Wind strömt hier aus den Pestländern die Schlucht herab, und die Anhöhe hat ihren Namen von ihm. Der Pass gehörte einst zum Königreich Lordaeron. Eine uralte Trollruine krönt den Hügel. Ein Dschungeltroll-Schamane, Bath'rah der Windbehüter, hat die Ruine zu seinem Heim gemacht und lebt dort als Einsiedler. Er ist Waffenbauer, und er will das Herz des Cyclonian, eines mächtigen Elementars, das in den Ruinen haust, um daraus eine Waffe zu schmieden.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Point",
		},
		["corrahns dagger"] = {
			name = "Corrahns Dolch",
			short = "Gesetzlose des Syndikats halten diesen Hügel. Es sind menschliche Verbrecher, angeführt von Adligen des gefallenen Königreichs Alterac, und sie sind Feinde der Allianz und der Horde gleichermaßen.",
			full = "Gesetzlose des Syndikats halten diesen Hügel. Es sind menschliche Verbrecher, angeführt von Adligen des gefallenen Königreichs Alterac, und sie sind Feinde der Allianz und der Horde gleichermaßen.",
			source = "https://warcraft.wiki.gg/wiki/Corrahn's_Dagger",
		},
		["crushridge hold"] = {
			name = "Crushridgehöhle",
			short = "Nahe den Ruinen von Alterac beherbergt eine Höhle in einem Erdhügel eine große Zahl von Crushridge-Ogern, und weitere lagern rundherum.",
			full = "Nahe den Ruinen von Alterac beherbergt eine Höhle in einem Erdhügel eine große Zahl von Crushridge-Ogern, und weitere lagern rundherum. Das Königreich Alterac hatte im Zweiten Krieg einen Pakt mit der Horde geschlossen, und die anderen menschlichen Königreiche schlugen wegen des Verrats gegen seine Hauptstadt los. Die meisten Bewohner flohen. Jetzt halten die Oger die leeren Ruinen.",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["darrow hill"] = {
			name = "Darrow Hill",
			short = "Darrow Hill liegt im nördlichen Vorgebirge von Hillsbrad, unterhalb der Landzunge.",
			full = "Darrow Hill liegt im nördlichen Vorgebirge von Hillsbrad, unterhalb der Landzunge. Berglöwen und Hirsche streifen über seine offenen Felder, und in den Vorgebirgshöhlen haben Yetis ihren Bau, zwischen Adern von Alterac-Granit, die den Fels durchziehen.",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "Dun Garok",
			short = "Dun Garok steht in den Hügeln des Vorgebirges von Hillsbrad, eine Zwergenfeste unter dem Befehl von Captain Eisenberg.",
			full = "Dun Garok steht in den Hügeln des Vorgebirges von Hillsbrad, eine Zwergenfeste unter dem Befehl von Captain Eisenberg. Seine Garnison schützt die Menschen von Hillsbrad und wacht über den Azurschacht, eine Gegenwart, die die Verlassenen nicht dulden können, die jedem Gold geboten haben, der sich in die Feste schleicht und ihre Zwerge niedermacht.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "Burg Durnholde",
			short = "Im Zweiten Krieg überfiel Orgrim Schicksalshammer persönlich Burg Durnholde, um den Trollkriegsherrn Zul'jin aus ihren Zellen zu befreien.",
			full = "Im Zweiten Krieg überfiel Orgrim Schicksalshammer persönlich Burg Durnholde, um den Trollkriegsherrn Zul'jin aus ihren Zellen zu befreien. Danach wurde sie zur Kommandozentrale der Internierungslager der Orcs, geleitet von Generalleutnant Aedelas Schwarzmoor, einem selbstverliebten Trunkenbold. Schwarzmoor fand ein verlorenes Orc-Kind in der Wildnis, nannte es Thrall und zog es hier als Sklaven und Gladiator auf.\n\nDie Burg liegt jetzt in Trümmern, östlich von Tarrens Mühle. Einst enthielt sie innere Kasernen, einen Magierturm und eine Arena. Das Syndikat hält sie als seinen Stützpunkt im Vorgebirge, und von hier stehlen seine Gesetzlosen Pferde und Lieferungen aus Southshore.",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "Oststrand",
			short = "Der Oststrand zieht sich an der südöstlichen Küste des Vorgebirges von Hillsbrad entlang, sein Gegenstück liegt weiter westlich an derselben Küste.",
			full = "Der Oststrand zieht sich an der südöstlichen Küste des Vorgebirges von Hillsbrad entlang, sein Gegenstück liegt weiter westlich an derselben Küste. Dieser Sandstreifen gehört den Säbelflossen-Naga, die die Strände und das flache Wasser dahinter halten.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["gallows corner"] = {
			name = "Galgeneck",
			short = "Bei Galgeneck, wo die Straßen im Alteracgebirge nahe den Ruinen von Alterac zusammentreffen, steht ein Späherturm zerbrochen und leer.",
			full = "Bei Galgeneck, wo die Straßen im Alteracgebirge nahe den Ruinen von Alterac zusammentreffen, steht ein Späherturm zerbrochen und leer. Crushridge-Oger halten nun die Kreuzung und streifen über die Steine rings um die Reste des Turms, und sonst regt sich dort nichts.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "Gavins Landspitze",
			short = "Berglöwen streifen über diesen Hügel, und manchmal ist die seltene Araga unter ihnen.",
			full = "Berglöwen streifen über diesen Hügel, und manchmal ist die seltene Araga unter ihnen.",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "Growlesshöhle",
			short = "Tief in dieser Höhle im Alteracgebirge steht die Flamme von Uzel, ein Scheiterhaufen, den ein Mensch namens Helcular für das Ritual errichtet hat, durch das er zum Lich werden will.",
			full = "Tief in dieser Höhle im Alteracgebirge steht die Flamme von Uzel, ein Scheiterhaufen, den ein Mensch namens Helcular für das Ritual errichtet hat, durch das er zum Lich werden will. Bergyetis suchen in der Höhle um sie herum Zuflucht, und ein Yeti namens Skhowl findet sich oft gleich vor ihrem Eingang.",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "Die Landzunge",
			short = "Ein Berglöwe mit einer schwachen Mähne und einem gestreiften Schwanz ruht an der Klippenseite der Landzunge. Sie ist Araga, und keine andere Katze in den Hügeln sieht aus wie sie.",
			full = "Ein Berglöwe mit einer schwachen Mähne und einem gestreiften Schwanz ruht an der Klippenseite der Landzunge. Sie ist Araga, und keine andere Katze in den Hügeln sieht aus wie sie.",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "Die Felder von Hillsbrad",
			short = "Apfelgärten und Kürbisfelder bedecken die Felder von Hillsbrad, dazwischen weiden Rinder, und die Ernte ernährt das ganze Vorgebirge von Hillsbrad.",
			full = "Apfelgärten und Kürbisfelder bedecken die Felder von Hillsbrad, dazwischen weiden Rinder, und die Ernte ernährt das ganze Vorgebirge von Hillsbrad. Orgrim Schicksalshammer ließ die Stadt im Zweiten Krieg als grausiges Exempel zerstören, und die Nachricht verbreitete sich durch die menschlichen Königreiche. Nach dem Krieg wurde sie wieder aufgebaut.\n\nHillsbrad und Southshore sind die einzigen Teile des einstigen Lordaeron, die der Dritte Krieg nicht völlig verwüstet zurückließ, und keines von beiden schloss sich dem Scharlachroten Kreuzzug an. Ihre Wachen tragen noch immer den Wappenrock von Lordaeron. Magistrat Uferbach regiert vom Rathaus aus, unterstützt vom Rat von Hillsbrad und dem Schreiber Horrace Whitesteed.\n\nDie Verlassenen von Tarrens Mühle unter Hochexekutorin Darthalia bedrohen die Höfe. Die Bauern antworten mit Hinterhalten, bewaffnet vom Schmied Verringtan und seinen Gehilfen.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["misty shore"] = {
			name = "Nebelufer",
			short = "Das Nebelufer zieht sich am Lordameresee entlang, zwischen Dandreds Senke und dem Dalaran-Krater. Schildkröten bewegen sich langsam durch seine Untiefen.",
			full = "Das Nebelufer zieht sich am Lordameresee entlang, zwischen Dandreds Senke und dem Dalaran-Krater. Schildkröten bewegen sich langsam durch seine Untiefen.\n\nZwei Menschen, die mit dem Scharlachroten Kreuzzug verbündet sind, halten dieses Ufer und fallen über jeden her, der ihnen zu nahe kommt.\n\nÜber das Wasser hinweg sieht man die Morgeninseln, mit der unheimlichen Burg Fenris in der Ferne.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "Nethander-Siedlung",
			short = "Die Nethander-Siedlung liegt gleich östlich von Southshore, ihre Felder verlassen und von Morastschnauzen-Gnollen überrannt, dem einzigen Ort, an dem ihr Stamm zu finden ist.",
			full = "Die Nethander-Siedlung liegt gleich östlich von Southshore, ihre Felder verlassen und von Morastschnauzen-Gnollen überrannt, dem einzigen Ort, an dem ihr Stamm zu finden ist. Riesige weiße Pilze, die Morastschnauzenblüten genannt werden, wachsen dort wild.",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "Fegefeuer-Insel",
			short = "Eine hoch aufragende Felsspirale erhebt sich südlich der Küste von Hillsbrad aus dem Wasser, mit einem Friedhof auf ihrer Spitze und den Ruinen eines Spähturms.",
			full = "Eine hoch aufragende Felsspirale erhebt sich südlich der Küste von Hillsbrad aus dem Wasser, mit einem Friedhof auf ihrer Spitze und den Ruinen eines Spähturms. Vor dem Ersten Krieg gehörte die Insel zu Kul Tiras.\n\nDutzende verdammter Geister von Menschen und Zwergen spuken dort, Paladine und Priester, Mönche und Magier, die keine Ruhe finden. Der Ogernekromant Kormok soll Freude daran gehabt haben, sie zu beschwören, damit sie seinen Willen tun.",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "Ravenholdt-Anwesen",
			short = "Lord Jorach Ravenholdt führt seine Assassinenliga von diesem verborgenen Anwesen im Alteracgebirge aus. Ein schmaler Pfad führt von einer Hochebene hinauf, windet sich durch die Berge und eine kleine Höhle.",
			full = "Lord Jorach Ravenholdt führt seine Assassinenliga von diesem verborgenen Anwesen im Alteracgebirge aus. Ein schmaler Pfad führt von einer Hochebene hinauf, windet sich durch die Berge und eine kleine Höhle. Die Liga nimmt nur Menschen von außergewöhnlichem Können auf, und ein Fremder, der ohne Klinge im Rücken oder Gift in den Adern wieder geht, hat sich gut geschlagen.\n\nSeit Jahren bekämpft die Liga das Syndikat. Ihre Agenten stehlen Embleme des Syndikats, denn ein Mitglied, das sein Emblem verliert, wird von den eigenen Leuten erledigt.",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["slaughter hollow"] = {
			name = "Slaughter Hollow",
			short = "Die Crushridge-Oger haben ihr Heim in Slaughter Hollow, einem Ogerhügel tief im Alteracgebirge.",
			full = "Die Crushridge-Oger haben ihr Heim in Slaughter Hollow, einem Ogerhügel tief im Alteracgebirge.",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["soferas naze"] = {
			name = "Soferas Landspitze",
			short = "Das Syndikat hält diesen Hügel über Hillsbrad.",
			full = "Das Syndikat hält diesen Hügel über Hillsbrad.",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
		},
		["southpoint tower"] = {
			name = "Southpoint-Turm",
			short = "Der Southpoint-Turm steht am äußersten Westrand des Vorgebirges von Hillsbrad, gleich südlich der Straße, die weiter in den Silberwald führt.",
			full = "Der Southpoint-Turm steht am äußersten Westrand des Vorgebirges von Hillsbrad, gleich südlich der Straße, die weiter in den Silberwald führt. Das Mauerwerk ist alt und rissig, ein dem Verfall überlassener Späherposten, doch der Turm selbst wurde in den Kämpfen, die hier tobten, nie zu Fall gebracht.",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["strahnbrad"] = {
			name = "Strahnbrad",
			short = "Strahnbrad liegt auf den nordöstlichen Ausläufern des Alteracgebirges, eine Geisterstadt mit einem verlassenen Rathaus und einer verlassenen Schmiede.",
			full = "Strahnbrad liegt auf den nordöstlichen Ausläufern des Alteracgebirges, eine Geisterstadt mit einem verlassenen Rathaus und einer verlassenen Schmiede. Sie gehörte einst zum Königreich Alterac und fiel nach dem Zweiten Krieg an Lordaeron.\n\nKurz vor dem Dritten Krieg überfielen Blackrockorcs sie und nahmen Sklaven mit, um sie der Brennenden Legion zu opfern. Nur eine Handvoll Fußsoldaten bewachte die Stadt, doch sie ließ die Ritter der Silbernen Hand benachrichtigen. Uther der Lichtbringer jagte dem Orc-Lager nach, und Prinz Arthas Menethil ritt los, um die Stadt zu halten. Der Überfall hatte begonnen, als er eintraf, und viele Dorfbewohner starben, doch Arthas und die überlebenden Verteidiger schlugen die Orcs in die Flucht und töteten den Sklavenmeister, der sie anführte.\n\nJetzt hält das Syndikat die Stadt als seinen Hauptstützpunkt. Es hält den Orc Gol'dir hier in einer Zelle und lässt ihn als Sklaven arbeiten.",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "Tarrens Mühle",
			short = "Zu Beginn des Zweiten Krieges kamen hochelfische Bogenschützen aus Silbermond nach Süden, um die Bedrohung durch die Orcs zu erkunden.",
			full = "Zu Beginn des Zweiten Krieges kamen hochelfische Bogenschützen aus Silbermond nach Süden, um die Bedrohung durch die Orcs zu erkunden. Sie gerieten im Grasland nahe Tarrens Mühle in einen Hinterhalt und wurden in ein nahes Gefangenenlager gebracht. König Terenas schickte Soldaten der Allianz, die sie befreiten. Der Rat von Silbermond verpflichtete daraufhin die Armeen von Quel'Thalas der Allianz von Lordaeron.\n\nDie Verlassenen halten die Stadt jetzt. Eine Kirche, ein paar Häuser und verdorrte Obstgärten stehen verfallen da. Von hier aus führen sie Krieg gegen die Städte der Allianz, Southshore und Dun Garok. Der Boden zwischen Tarrens Mühle und Southshore ist berüchtigt für ständige Kämpfe.",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "Thoradinswall",
			short = "Bald nachdem das Königreich Arathor gegründet und Strom seine Hauptstadt geworden war, ließ König Thoradin eine große Mauer bauen, um die Menschheit vor den Amani-Trollen zu schützen.",
			full = "Bald nachdem das Königreich Arathor gegründet und Strom seine Hauptstadt geworden war, ließ König Thoradin eine große Mauer bauen, um die Menschheit vor den Amani-Trollen zu schützen. Sie verläuft zwischen dem Vorgebirge von Hillsbrad und dem Arathihochland.\n\nNach vielen Jahrhunderten ist die Mauer schwer beschädigt und liegt in Trümmern.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["western strand"] = {
			name = "Weststrand",
			short = "Der Weststrand liegt an der Südwestküste des Vorgebirges von Hillsbrad. Fetzenflossen-Murlocs haben an seinem Ufer kleine Lager errichtet, und Andy Murgole patrouilliert in der Gegend.",
			full = "Der Weststrand liegt an der Südwestküste des Vorgebirges von Hillsbrad. Fetzenflossen-Murlocs haben an seinem Ufer kleine Lager errichtet, und Andy Murgole patrouilliert in der Gegend.",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- Hinterland: 20 subzones
	[1425] = {
		["aerie peak"] = {
			name = "Aerie Peak",
			short = "Die Wildhammer kehrten nach dem Krieg der Drei Hämmer nach Grim Batol heim und fanden die Festung durch den Tod von Modgud befleckt.",
			full = "Die Wildhammer kehrten nach dem Krieg der Drei Hämmer nach Grim Batol heim und fanden die Festung durch den Tod von Modgud befleckt. Sie konnten dort nicht leben. Da sie in den Tunneln gegen die Dunkeleisenzwerge gekämpft hatten, wollten sie sich nicht noch einmal in den Stein graben und bauten Aerie Peak stattdessen an der Außenseite eines Berges.\n\nEine große Greifenvoliere krönt seine Mitte, und die Burg der Wildhammer steht am fernen Ende.",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "Agol'watha",
			short = "Agol'watha wurde als Tempel des Imperiums der Amani errichtet, und das Imperium ist vergangen.",
			full = "Agol'watha wurde als Tempel des Imperiums der Amani errichtet, und das Imperium ist vergangen. Die Blutfratzen-Trolle, die danach kamen, nahmen die Ruine in Besitz, und ihre Brutwächter gehen noch immer durch ihre Hallen. Grüne Schlämme und Jadeschleime haben sie überrannt und kriechen durch ihre zerfallenen Höfe.",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
		},
		["altar of zul"] = {
			name = "Der Altar von Zul",
			short = "Der Altar von Zul erhebt sich im Hinterland, errichtet von den Waldtrollen der Vilebranch für ihre alten Riten. Qiaga die Bewahrerin hält oben auf den Steinen Wacht, Wächterin über welche Macht auch immer der Altar noch birgt.",
			full = "Der Altar von Zul erhebt sich im Hinterland, errichtet von den Waldtrollen der Vilebranch für ihre alten Riten. Qiaga die Bewahrerin hält oben auf den Steinen Wacht, Wächterin über welche Macht auch immer der Altar noch birgt.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Zul",
		},
		["bogens ledge"] = {
			name = "Bogens Kante",
			short = "Hexendoktor Mai'jin hat sein Heim in einer Höhle im südwestlichen Hinterland, und seine Spinne Tcha'kaz bewacht sie mit ihm.",
			full = "Hexendoktor Mai'jin hat sein Heim in einer Höhle im südwestlichen Hinterland, und seine Spinne Tcha'kaz bewacht sie mit ihm.",
			source = "https://warcraft.wiki.gg/wiki/Bogen's_Ledge",
		},
		["creeping ruin"] = {
			name = "Die Gruselruinen",
			short = "Waldtrolle bauten die Gruselruinen, und feindliche Schleime haben überrannt, was sie zurückließen. Sie kriechen durch den zerbrochenen Stein.",
			full = "Waldtrolle bauten die Gruselruinen, und feindliche Schleime haben überrannt, was sie zurückließen. Sie kriechen durch den zerbrochenen Stein.",
			source = "https://warcraft.wiki.gg/wiki/Creeping_Ruin",
		},
		["featherbeards hovel"] = {
			name = "Federbarts Hütte",
			short = "Ein kleines Haus steht neben Aerie Peak, das Heim von Federbart.",
			full = "Ein kleines Haus steht neben Aerie Peak, das Heim von Federbart.",
			source = "https://warcraft.wiki.gg/wiki/Featherbeard's_Hovel",
		},
		["hiriwatha"] = {
			name = "Hiri'watha",
			short = "Bleichborke-Waldtrolle leben zwischen den alten Ruinen von Hiri'watha, südlich der Quel'Danil-Hütte. Als Gesandte der Horde ins Hinterland kamen, wiesen die Bleichborke sie rundheraus ab.",
			full = "Bleichborke-Waldtrolle leben zwischen den alten Ruinen von Hiri'watha, südlich der Quel'Danil-Hütte. Als Gesandte der Horde ins Hinterland kamen, wiesen die Bleichborke sie rundheraus ab.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["jinthaalor"] = {
			name = "Jintha'Alor",
			short = "Trolle des Imperiums der Amani errichteten Jintha'Alor und benannten es nach Jintha, einem ihrer uralten Anführer. Unter den Städten der Waldtrolle ist nur Zul'Aman größer.",
			full = "Trolle des Imperiums der Amani errichteten Jintha'Alor und benannten es nach Jintha, einem ihrer uralten Anführer. Unter den Städten der Waldtrolle ist nur Zul'Aman größer. Die Blutfratzen halten es jetzt und nutzen seine Terrassen als Festung für Opferungen.\n\nÜble Priesterin Hexx herrscht hier im Namen von Hakkar dem Seelenschinder. Die Blutfratzen jagen die schwächeren Revantusk, um ihn zu nähren. Älterer Torntusk wurde bei einem Überfall gefangen genommen und wird noch immer in der Stadt gehalten, und sein Wachhauptmann, Jäger Markhor, wurde getötet, seine Überreste den Wölfen und Schleimen innerhalb der Mauern vorgeworfen.",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["overlook cliffs"] = {
			name = "Die Aussichtsklippen",
			short = "Der große Fluss, der durch das Hinterland fließt, endet an den Aussichtsklippen und stürzt in einem gewaltigen Wasserfall über die Kante, wo die Berge der östlichen Küste weichen.",
			full = "Der große Fluss, der durch das Hinterland fließt, endet an den Aussichtsklippen und stürzt in einem gewaltigen Wasserfall über die Kante, wo die Berge der östlichen Küste weichen. Die Klippen sind steil und trügerisch hoch, und viele Reisende haben den Abgrund falsch eingeschätzt und sind in den Tod gestürzt.",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "Seuchennebelklamm",
			short = "Ein Nebel hängt über der Seuchennebelklamm, einem schmalen Pfad, der nach Norden durch die Berge in Richtung Caer Darrow in den Westlichen Pestländern führt.",
			full = "Ein Nebel hängt über der Seuchennebelklamm, einem schmalen Pfad, der nach Norden durch die Berge in Richtung Caer Darrow in den Westlichen Pestländern führt. Der Eingang liegt in den Wäldern westlich der Quel'Danil-Hütte. Die Klamm wurde erst vor Kurzem benannt, nach dem kränklichen Nebel, der diesen einen Pfad verdirbt und scharf mit der sauberen Frische des übrigen Hinterlands kontrastiert. Niemand lebt darin.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "Die Quel'Danil-Hütte",
			short = "Die Elfen von Hochtal halten diese Hütte als ihren Stützpunkt nahe Aerie Peak.",
			full = "Die Elfen von Hochtal halten diese Hütte als ihren Stützpunkt nahe Aerie Peak. Sie ist die größere der beiden großen Versammlungen der Hochelfen, die in Lordaeron geblieben sind, und eine der letzten hochelfischen Siedlungen.\n\nNach dem Dritten Krieg wurde die Hütte zu einem Zentrum des Austauschs. Gesandte von Hochtal suchten den Kontakt zu den anderen Völkern der Allianz und teilten, was sie über die Bleichborke-Trolle wussten. Die Elfen verbündeten sich später mit den Wildhammer-Zwergen, was die Revantusktrolle erzürnte. Die Hütte führt Aufzeichnungen über Geburten, Todesfälle und Jahreszeiten.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "Revantusk",
			short = "Als der Zweite Krieg die Alte Horde zerbrach, ließen viele Waldtrolle ihre Orc-Verbündeten ohne einen Augenblick des Zögerns im Stich.",
			full = "Als der Zweite Krieg die Alte Horde zerbrach, ließen viele Waldtrolle ihre Orc-Verbündeten ohne einen Augenblick des Zögerns im Stich. Die Revantusk bewahrten der Horde eine gewisse Treue. Sie waren zu wenige, um die gefangenen Orcs zu befreien, die ohnehin an Freiheit nicht interessiert schienen, und andere Waldtrolle griffen sie dafür an. Der Stamm zog an die Küste des Hinterlands, in der Hoffnung, unbemerkt zu bleiben, und baute dieses Dorf.\n\nMit der Zeit erfuhren sie, dass Thrall eine neue Horde gesammelt und sein Volk zu seinen schamanistischen Überlieferungen zurückgeführt hatte. Sie schickten ihre schnellsten Läufer zu ihm, und die beiden schlossen einen Freundschaftspakt. Andere Waldtrolle nennen die Revantusk Schwächlinge und Feinde, und die Revantusk nennen sie Verräter an der neuen Horde.",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "Seradane",
			short = "Ein großes kreisförmiges Portal steht im nordöstlichen Hinterland, einer von vier Eingängen in den Smaragdgrünen Traum. Grüne Drachen machten diesen Wald zu ihrer Heimat, unter ihnen die Drachkin Rothos und Traumsucher.",
			full = "Ein großes kreisförmiges Portal steht im nordöstlichen Hinterland, einer von vier Eingängen in den Smaragdgrünen Traum. Grüne Drachen machten diesen Wald zu ihrer Heimat, unter ihnen die Drachkin Rothos und Traumsucher.\n\nDie grüne Drachenbrut hält den größten Teil der Wälder. Ein Tiefgrünes Orakel führt jede Gruppe an, mit Tiefgrünen Astwächtern und Baumwärtern an seiner Seite. Der Schädel eines unbekannten Drachen ruht auf einem Hügel nördlich des Portals.",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "Shadra'Alor",
			short = "Der Stamm der Bleichborke hat seine Hauptsiedlung in Shadra'Alor, zwischen alten Tempeln, die die Waldtrolle des Imperiums der Amani errichteten.",
			full = "Der Stamm der Bleichborke hat seine Hauptsiedlung in Shadra'Alor, zwischen alten Tempeln, die die Waldtrolle des Imperiums der Amani errichteten. Die Bleichborke verehren hier die Loa Shadra, und sie kann beschworen werden.",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "Shaol'watha",
			short = "Wenig ist von Shaol'watha übrig, einem Tempel der Blutfratzen-Waldtrolle im nordöstlichen Hinterland.",
			full = "Wenig ist von Shaol'watha übrig, einem Tempel der Blutfratzen-Waldtrolle im nordöstlichen Hinterland.",
			source = "https://warcraft.wiki.gg/wiki/Shaol'watha",
		},
		["shindiggers camp"] = {
			name = "Shindiggers Lager",
			short = "Rhapsodie Shindigger, ein trinkfreudiger Zwerg, unterhält sein kleines Lager im Hinterland neben dem Hochelfen Gilveradin Sunchaser, ein seltsames Paar.",
			full = "Rhapsodie Shindigger, ein trinkfreudiger Zwerg, unterhält sein kleines Lager im Hinterland neben dem Hochelfen Gilveradin Sunchaser, ein seltsames Paar.",
			source = "https://warcraft.wiki.gg/wiki/Shindigger's_Camp",
		},
		["skulk rock"] = {
			name = "Skulk Rock",
			short = "Im Zweiten Krieg errichtete die Alte Horde in dieser Waldtroll-Ruine einen Stützpunkt. Die Allianz von Lordaeron vertrieb sie, und sie ließen mehrere Kisten Hinterland-Honigwelle zurück.",
			full = "Im Zweiten Krieg errichtete die Alte Horde in dieser Waldtroll-Ruine einen Stützpunkt. Die Allianz von Lordaeron vertrieb sie, und sie ließen mehrere Kisten Hinterland-Honigwelle zurück.\n\nSeither haben Schleime die Ruine überrannt. Eine Höhle hier ist einer der wenigen Orte, an denen noch Geisterpilze wachsen.",
			source = "https://warcraft.wiki.gg/wiki/Skulk_Rock",
		},
		["valorwind lake"] = {
			name = "Valorwindsee",
			short = "Nordöstlich von Shadra'Alor liegt der Valorwindsee, ein kleines, stilles Gewässer. Sein Wasser wirkt unauffällig, und doch ist er der einzige bekannte Ort, an dem der Violette Tragan, ein geheimnisvoller Pilz, wächst.",
			full = "Nordöstlich von Shadra'Alor liegt der Valorwindsee, ein kleines, stilles Gewässer. Sein Wasser wirkt unauffällig, und doch ist er der einzige bekannte Ort, an dem der Violette Tragan, ein geheimnisvoller Pilz, wächst.",
			source = "https://warcraft.wiki.gg/wiki/Valorwind_Lake",
		},
		["wildhammer keep"] = {
			name = "Burg Wildhammer",
			short = "An einem Ende von Aerie Peak, gegenüber der großen Greifenvoliere, steht die Burg der Wildhammer-Zwerge. Falstad Wildhammer, ihr Hochthan, herrscht vom Gipfel des Berges aus.",
			full = "An einem Ende von Aerie Peak, gegenüber der großen Greifenvoliere, steht die Burg der Wildhammer-Zwerge. Falstad Wildhammer, ihr Hochthan, herrscht vom Gipfel des Berges aus.\n\nDie meisten Zwerge treiben ihre Hallen in den Berg. Die Wildhammer bauen unter freiem Himmel, eine Gewohnheit, die sie aus dem Grauen der unterirdischen Schlachten gegen die Dunkeleisenzwerge mitbrachten.",
			source = "https://warcraft.wiki.gg/wiki/Wildhammer_Keep",
		},
		["zunwatha"] = {
			name = "Zun'watha",
			short = "Zwischen den alten Ruinen von Zun'watha haben sich die Bleichborke-Trolle niedergelassen. Man sieht Zul'arek Faulhass dort von Zeit zu Zeit umhergehen.",
			full = "Zwischen den alten Ruinen von Zun'watha haben sich die Bleichborke-Trolle niedergelassen. Man sieht Zul'arek Faulhass dort von Zeit zu Zeit umhergehen.",
			source = "https://warcraft.wiki.gg/wiki/Zun'watha",
		},
	},
	-- Dun Morogh: 24 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "Amberstill-Ranch",
			short = "Die Zwerge der Familie Amberstill halten Bergwidder, die Sorte, die Zwerge reiten, auf ihrer Ranch an der Straße nach Loch Modan, nördlich des Gol'bolar Steinbruchs.",
			full = "Die Zwerge der Familie Amberstill halten Bergwidder, die Sorte, die Zwerge reiten, auf ihrer Ranch an der Straße nach Loch Modan, nördlich des Gol'bolar Steinbruchs. Der junge Yarlyn Amberstill kümmert sich um ein Gehege mit Schneehasen. Ein Wendigo namens Vagash pirscht um die Herde, und Rudra Amberstill will ihn vertrieben sehen.",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "Anvilmar",
			short = "Im Coldridgetal liegt Anvilmar, die erste Ortschaft von einiger Größe im Norden des Tals. Eine Halle, um eine große Schmiede herum gebaut, liegt in seiner Mitte.",
			full = "Im Coldridgetal liegt Anvilmar, die erste Ortschaft von einiger Größe im Norden des Tals. Eine Halle, um eine große Schmiede herum gebaut, liegt in seiner Mitte.",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "Brewnall",
			short = "Die Familie Gerstenbräu hat ihr Heim in Brewnall, im Chillbreezetal nahe Gnomeregan.",
			full = "Die Familie Gerstenbräu hat ihr Heim in Brewnall, im Chillbreezetal nahe Gnomeregan. Rejold Gerstenbräu führt ihre Suche nach dem besten Bierrezept an, und die Familie arbeitet daran, die alte zwergische Braukunst zu verbessern. Sie schicken ihre Jungen aus, um das Dorf vor wilden Tieren zu schützen und nach seltenen Zutaten für das ultimative Bier zu jagen.\n\nDas Dorf ist eher ein Lager als eine Siedlung. Es untersteht Ironforge, obwohl es in gnomischem Land liegt.",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "Chillbreezetal",
			short = "Blut zeigt sich auf dem Schnee in den nördlichen und südlichen Armen des Chillbreezetals. Große Flecken breiten sich über das Weiß aus, und zerfetzte Tierkadaver liegen dort, wo sie fallen gelassen wurden.",
			full = "Blut zeigt sich auf dem Schnee in den nördlichen und südlichen Armen des Chillbreezetals. Große Flecken breiten sich über das Weiß aus, und zerfetzte Tierkadaver liegen dort, wo sie fallen gelassen wurden. Wenige Menschen betreten diese Arme. Jäger gehen den Bestien nach, die dafür verantwortlich sind, in der Hoffnung, ihre Bedrohung für die Zwergenländer zu beenden, und viele kehren nicht zurück. Ein gefährlicher Wendigo haust in einer der Höhlen.\n\nDer Arm, der von Osten nach Westen verläuft, ist leichter zu begehen. Er führt zwischen Gnomeregan und Kharanos entlang, und junge Zwerge und Gnome nutzen ihn oft.",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "Coldridgepass",
			short = "Troggs haben den Coldridgepass überrannt, den Tunnel, der das Coldridgetal mit dem übrigen Dun Morogh verbindet.",
			full = "Troggs haben den Coldridgepass überrannt, den Tunnel, der das Coldridgetal mit dem übrigen Dun Morogh verbindet. Zwergische Rekruten kommen nur tröpfchenweise durch, auf ihrem Weg in die Grenzstadt Kharanos, und sie müssen sich einen Weg durch die Troggs schlagen oder an ihnen vorbeirennen.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "Das Coldridgetal",
			short = "Abgeschnitten in der südwestlichen Ecke von Dun Morogh liegt das Coldridgetal unter dichtem Schnee. Sein einziger Ausgang ist der Tunnel des Coldridgepasses im Nordosten.",
			full = "Abgeschnitten in der südwestlichen Ecke von Dun Morogh liegt das Coldridgetal unter dichtem Schnee. Sein einziger Ausgang ist der Tunnel des Coldridgepasses im Nordosten. Zwergische Gebirgsjäger halten hier Wache, obwohl Troggs und Frostmanetrolle das Tal heimsuchen.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "Höhle der Frostmane",
			short = "Die Höhle der Frostmane liegt am westlichen Rand der kalten Berge von Dun Morogh, südlich von Gnomeregan, eine Ansammlung von Gebäuden, verwoben mit einem Höhlensystem, das in die Bergflanke getrieben wurde.",
			full = "Die Höhle der Frostmane liegt am westlichen Rand der kalten Berge von Dun Morogh, südlich von Gnomeregan, eine Ansammlung von Gebäuden, verwoben mit einem Höhlensystem, das in die Bergflanke getrieben wurde. Sie ist das Basislager der Frostmane-Eistrolle, die den Boden halten und jeden Zugang mit Kopfjägern und Fellhäutern bewachen.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "Tore von Ironforge",
			short = "Die Tore von Ironforge sind ein großartiger Anblick, von weit über Dun Morogh sichtbar. Sie stehen am Kopf der großen Rampe, die nach Norden zum Berg hinaufführt, und öffnen sich in Ironforge selbst.",
			full = "Die Tore von Ironforge sind ein großartiger Anblick, von weit über Dun Morogh sichtbar. Sie stehen am Kopf der großen Rampe, die nach Norden zum Berg hinaufführt, und öffnen sich in Ironforge selbst. Gleich dahinter hält eine riesige Statue von Hochkönig Modimus Ambossar Wache.\n\nEr war der letzte König der vereinten Zwerge, ein Herrscher der Gerechtigkeit und Weisheit, bekannt für seine Diplomatie gegenüber den drei großen Zwergenclans. Als er an Altersschwäche starb, bevor sein ältester Sohn gekrönt werden konnte, zogen diese Klans gegeneinander in den Krieg.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "Gnomeregan",
			short = "Die Gnome bauten Gnomeregan unter der Erde, in den Ausläufern von Dun Morogh, und füllten es mit Eisen und Erfindungen. Im Dritten Krieg verseuchten mutierte Troggs die Stadt.",
			full = "Die Gnome bauten Gnomeregan unter der Erde, in den Ausläufern von Dun Morogh, und füllten es mit Eisen und Erfindungen. Im Dritten Krieg verseuchten mutierte Troggs die Stadt. In einem verzweifelten Versuch, sie zu vernichten, ordnete Hochtüftler Gelbin Mekkatorque an, die Abfalltanks zu entlüften, und füllte die Hallen mit Strahlung. Die Gnome suchten vor den Dämpfen Schutz und warteten, dass die Troggs starben oder flohen. Die Troggs wurden krank, aber sie kamen weiter. Fast vier von fünf Gnomen starben binnen Tagen, und die Überlebenden flohen nach Ironforge. Andere wurden zu Leprosengnomen entstellt, ohne Verstand und grausam.\n\nSicco Thermastecker, einst Mekkatorques vertrauter Berater, wurde vom Gift in den Wahnsinn getrieben. Er herrscht nun als Technoherrscher über die zerstörten Hallen, über Troggs und Leprosengnome.",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "Der Gol'bolar Steinbruch",
			short = "Im Südosten von Dun Morogh unterhalten Zwerge ein kleines Bergbaulager neben dem Gol'bolar Steinbruch, einer großen Grabungsstätte.",
			full = "Im Südosten von Dun Morogh unterhalten Zwerge ein kleines Bergbaulager neben dem Gol'bolar Steinbruch, einer großen Grabungsstätte. Troggs haben die Ausgrabung und die Mine darunter überrannt, und die Bergleute halten nur das Lager.",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "Der altgediente Bau",
			short = "Die Wendigos des altgedienten Baus zerstreuen sich nicht, wenn Fremde kommen. Sie rotten sich zusammen, atmen Frost und treiben Eindringlinge aus diesem großen Höhlensystem gleich südwestlich von Kharanos zurück.",
			full = "Die Wendigos des altgedienten Baus zerstreuen sich nicht, wenn Fremde kommen. Sie rotten sich zusammen, atmen Frost und treiben Eindringlinge aus diesem großen Höhlensystem gleich südwestlich von Kharanos zurück. Jäger gehen hinein, um an ihre Mähnen zu kommen, die für Sitzbezüge begehrt sind. Kupferadern durchziehen den Fels, und ein zäherer Wendigo haust im hinteren Teil.",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "Helmsbedsee",
			short = "Eis bedeckt den größten Teil des Helmsbedsees, doch ein Loch wird offen gehalten, damit frisches Wasser geschöpft werden kann. Das Eis ist sicher zu überqueren.",
			full = "Eis bedeckt den größten Teil des Helmsbedsees, doch ein Loch wird offen gehalten, damit frisches Wasser geschöpft werden kann. Das Eis ist sicher zu überqueren. Das Ufer ist es nicht, denn wilde Tiere und verirrte Troggs streifen dort umher.\n\nSüdlich des Sees haben Dunkeleisenzwerge ein verlassenes Gebäude besetzt, und sie schlagen gegen jeden zu, der ihnen zu nahe kommt.",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "Iceflowsee",
			short = "Der Iceflowsee friert in der Kälte von Dun Morogh hart zu, doch die Zwerge von Brewnall halten ein Loch durch das Eis offen und holen frisches Wasser und Fische unter der gefrorenen Oberfläche hervor.",
			full = "Der Iceflowsee friert in der Kälte von Dun Morogh hart zu, doch die Zwerge von Brewnall halten ein Loch durch das Eis offen und holen frisches Wasser und Fische unter der gefrorenen Oberfläche hervor.\n\nZur Mitte des Sees hin erheben sich zwei Inseln, die man besser in Ruhe lässt. Ein Rudel ausgehungerter Wölfe hat sie in Besitz genommen, angeführt von einem Worg namens Timber, und ihre Anwesenheit hält die Inseln frei von allem außer den Bestien, die sie halten.",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "Ironbands Truppenlager",
			short = "Südlich des Helmsbedsees steht Ironbands Truppenlager als Stützpunkt der Dunkeleisenzwerge, die gegen jeden zuschlagen, der sich zu nahe heranwagt.",
			full = "Südlich des Helmsbedsees steht Ironbands Truppenlager als Stützpunkt der Dunkeleisenzwerge, die gegen jeden zuschlagen, der sich zu nahe heranwagt. Der Ort gehörte einst Sturgy Ironband, ehe er in die Hände der Dunkeleisenzwerge fiel.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["kharanos"] = {
			name = "Kharanos",
			short = "Kharanos liegt zwischen den Berggipfeln von Dun Morogh, ein geschäftiges kleines Städtchen, umringt von winterlicher Wildnis.",
			full = "Kharanos liegt zwischen den Berggipfeln von Dun Morogh, ein geschäftiges kleines Städtchen, umringt von winterlicher Wildnis. Hier glüht eine große Schmiede, eine gnomische Werkstatt klappert vor sich hin, und die Brauerei Donnerbräu schenkt eines der besten Biere der Welt aus. Hinter dem Charme ist Kharanos ein Zentrum militärischer Tätigkeit und verteidigt sich gegen jede Gefahr, die die Wildnis schickt.\n\nEine große Höhle voller wilder Wendigos liegt direkt im Westen. Im Nordwesten haben sich Frostmanetrolle oben auf dem Schimmergrat eingenistet und beobachten die Stadt unter sich, und Senir Weißbart ist entschlossen, sie zu vertreiben.",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["misty pine refuge"] = {
			name = "Nebelfichtenzuflucht",
			short = "Die Nebelfichtenzuflucht liegt ruhig im mittleren Dun Morogh, eine geschützte Lichtung zwischen schneebeladenen Kiefern.",
			full = "Die Nebelfichtenzuflucht liegt ruhig im mittleren Dun Morogh, eine geschützte Lichtung zwischen schneebeladenen Kiefern.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["north gate outpost"] = {
			name = "Nordtoraußenposten",
			short = "Die nordöstlichste Siedlung, die die Zwerge in Dun Morogh gebaut haben, steht mitten im Nordtorpass, der Dun Morogh mit Loch Modan verbindet.",
			full = "Die nordöstlichste Siedlung, die die Zwerge in Dun Morogh gebaut haben, steht mitten im Nordtorpass, der Dun Morogh mit Loch Modan verbindet. Hier sind Gebirgsjäger stationiert, und sie haben alle Hände voll zu tun, das Getier abzuwehren, das aus den Bergen heranströmt. Einige von ihnen gingen auf die Jagd nach den wilderen Bestien und sind verschwunden.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Outpost",
		},
		["north gate pass"] = {
			name = "Nordtorpass",
			short = "Der Nordtorpass trägt die Straße von den hohen Bergen von Dun Morogh hinab in die niedrigeren Berge von Loch Modan. Reisende von und nach dem Sumpfland nutzen ihn am meisten, da er dem Abstieg vom Loch am nächsten liegt.",
			full = "Der Nordtorpass trägt die Straße von den hohen Bergen von Dun Morogh hinab in die niedrigeren Berge von Loch Modan. Reisende von und nach dem Sumpfland nutzen ihn am meisten, da er dem Abstieg vom Loch am nächsten liegt. Die Wachstation des Nordtoraußenpostens steht hier.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["shimmer ridge"] = {
			name = "Schimmergrat",
			short = "Frostmanetrolle halten die Höhen des Schimmergrats, westlich der Tore von Ironforge. Sie leben in zwei Lagern, die eine Brücke verbindet, und sie zähmen Eber und bauen Schimmerkraut an.",
			full = "Frostmanetrolle halten die Höhen des Schimmergrats, westlich der Tore von Ironforge. Sie leben in zwei Lagern, die eine Brücke verbindet, und sie zähmen Eber und bauen Schimmerkraut an. Die Zwerge verwenden das Kraut in ihrem Bier, doch es sind die Trolle, die es pflegen.",
			source = "https://warcraft.wiki.gg/wiki/Shimmer_Ridge",
		},
		["south gate outpost"] = {
			name = "Südtoraußenposten",
			short = "Zwerge halten den Südtoraußenposten mitten im Pass, der hinab nach Loch Modan führt, mit Schnee auf dem Boden ringsum.",
			full = "Zwerge halten den Südtoraußenposten mitten im Pass, der hinab nach Loch Modan führt, mit Schnee auf dem Boden ringsum. Die hier stationierten Gebirgsjäger haben den größten Teil des Getiers vertrieben, das auf sie eindrang, und so haben sie weniger Ärger als die meisten Garnisonen in diesen Bergen. Viele Reisende kommen hier auf ihrem Weg von oder nach Thelsamar durch.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "Südtorpass",
			short = "Reisende nach Thelsamar nehmen den Südtorpass, der die hohen Berge von Dun Morogh mit den niedrigeren Bergen von Loch Modan verbindet.",
			full = "Reisende nach Thelsamar nehmen den Südtorpass, der die hohen Berge von Dun Morogh mit den niedrigeren Bergen von Loch Modan verbindet. Er ist der Pass, der der Zwergenstadt am nächsten liegt. Die Wachstation des Südtoraußenpostens steht hier.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["steelgrills depot"] = {
			name = "Steelgrills Depot",
			short = "Steelgrills Depot liegt östlich von Kharanos, ein kleines Lager aus Bergleuten und Ingenieuren, die den gefrorenen Boden von Dun Morogh bearbeiten.",
			full = "Steelgrills Depot liegt östlich von Kharanos, ein kleines Lager aus Bergleuten und Ingenieuren, die den gefrorenen Boden von Dun Morogh bearbeiten.",
			source = "https://warcraft.wiki.gg/wiki/Steelgrill's_Depot",
		},
		["thunderbrew distillery"] = {
			name = "Brauerei Donnerbräu",
			short = "Das Bier der Brauerei Donnerbräu ist weit und breit bekannt. Die zwergische Taverne in Kharanos wurde, so sagt Ragnar Donnerbräu, von seinem Vater Arkilus Donnerbräu gegründet.",
			full = "Das Bier der Brauerei Donnerbräu ist weit und breit bekannt. Die zwergische Taverne in Kharanos wurde, so sagt Ragnar Donnerbräu, von seinem Vater Arkilus Donnerbräu gegründet. Gastwirt Belm führt das Gasthaus.",
			source = "https://warcraft.wiki.gg/wiki/Thunderbrew_Distillery",
		},
		["tundrid hills"] = {
			name = "Die Tundrid-Hügel",
			short = "Wenige Reisende durchqueren die Tundrid-Hügel ohne eine Waffe in der Hand. Mehrere Arten feindlichen Getiers streifen durch diese Hügel im Süden des mittleren Dun Morogh, westlich des Gol'bolar Steinbruchs.",
			full = "Wenige Reisende durchqueren die Tundrid-Hügel ohne eine Waffe in der Hand. Mehrere Arten feindlichen Getiers streifen durch diese Hügel im Süden des mittleren Dun Morogh, westlich des Gol'bolar Steinbruchs. Einige nehmen sie noch immer als Abkürzung zwischen dem Coldridgetal und dem östlichen Dun Morogh, obwohl die Straße durch Kharanos weitaus sicherer ist.",
			source = "https://warcraft.wiki.gg/wiki/Tundrid_Hills",
		},
	},
	-- Sengende Schlucht: 11 subzones
	[1427] = {
		["blackchar cave"] = {
			name = "Blackcharhöhle",
			short = "Die Blackcharhöhle im Südwesten der Schlucht nahe dem Blackrock ist versiegelt. Was sie birgt, ist ein Geheimnis.",
			full = "Die Blackcharhöhle im Südwesten der Schlucht nahe dem Blackrock ist versiegelt. Was sie birgt, ist ein Geheimnis.",
			source = "https://warcraft.wiki.gg/wiki/Blackchar_Cave",
		},
		["blackrock mountain"] = {
			name = "Der Blackrock",
			short = "Die Heere der Bronzebeard und der Wildhammer marschierten, um den Klan der Dunkeleisenzwerge auszulöschen, als sich der Kamm zum Blackrock auftürmte.",
			full = "Die Heere der Bronzebeard und der Wildhammer marschierten, um den Klan der Dunkeleisenzwerge auszulöschen, als sich der Kamm zum Blackrock auftürmte. König Madoran und König Khardros wandten ihre Armeen zurück, statt sich dem Feuerlord zu stellen, der mit ihm gekommen war. Wo das Königreich der Dunkeleisenzwerge gestanden hatte, erhob sich ein Vulkan, und Ragnaros zog sich in seinen Kern zurück und ließ die überlebenden Zwerge darunter eine neue Stadt aushauen.\n\nZwei Mächte teilen sich nun den Berg. Ragnaros herrscht vom geschmolzenen Kern aus mit seinen Dunkeleisenzwergen, Golems und Elementaren. Nefarian wacht vom Pechschwingenhort oben, mit der Dunklen Horde der Blackrockorcs unter seinem Befehl. Jeder will ein Heer aufstellen und Azeroth nehmen.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "Der Kessel",
			short = "Die Dunkeleisenzwerge gruben den Kessel in die Mitte der Schlucht, eine gewaltige Ausgrabung, gesäumt von ihren großen Grabmaschinen, und sie befestigten ihn, nachdem Ragnaros beschworen worden war.",
			full = "Die Dunkeleisenzwerge gruben den Kessel in die Mitte der Schlucht, eine gewaltige Ausgrabung, gesäumt von ihren großen Grabmaschinen, und sie befestigten ihn, nachdem Ragnaros beschworen worden war. Feuer- und Magmaelementare ziehen durch die glühenden Spalten unten. Sklaven, meist gefangene Feinde, schuften dort ohne Rast. Die Arbeit, die Hitze und ihre Herren haben sie in den Wahnsinn getrieben, und sie greifen jeden an, der sich einmischt, selbst jene, die kommen, um sie zu befreien.",
			source = "https://warcraft.wiki.gg/wiki/Cauldron",
		},
		["dustfire valley"] = {
			name = "Staubfeuertal",
			short = "Wind fegt durch das Staubfeuertal, wo es nach Norden durch die Schlucht verläuft. An seinem Ende stehen die Tore des Stonewroughtpasses, und dahinter liegt das Tal der Könige in Loch Modan.",
			full = "Wind fegt durch das Staubfeuertal, wo es nach Norden durch die Schlucht verläuft. An seinem Ende stehen die Tore des Stonewroughtpasses, und dahinter liegt das Tal der Könige in Loch Modan.",
			source = "https://warcraft.wiki.gg/wiki/Dustfire_Valley",
		},
		["firewatch ridge"] = {
			name = "Firewatchgrat",
			short = "Der Firewatchgrat ist das Hauptlager der Dunkeleisenzwerge in der Sengenden Schlucht und überblickt die große Ausgrabung des Kessels.",
			full = "Der Firewatchgrat ist das Hauptlager der Dunkeleisenzwerge in der Sengenden Schlucht und überblickt die große Ausgrabung des Kessels. Dunkeleisenzwerge halten die Hänge mit mechanischen Golems und riesigen Flammenspinnen, was den Grat zu einem gefährlichen Ort macht.",
			source = "https://warcraft.wiki.gg/wiki/Firewatch_Ridge",
		},
		["grimesilt dig site"] = {
			name = "Grimesilt-Grabungsstätte",
			short = "Zwerge aus Ironforge gruben einst an der Grimesilt-Grabungsstätte. Die Dunkeleisenzwerge übernahmen sie und halten sie noch immer. Dorius Steinhüter, einer der ursprünglichen Arbeiter, liegt verletzt am Grund der Grube.",
			full = "Zwerge aus Ironforge gruben einst an der Grimesilt-Grabungsstätte. Die Dunkeleisenzwerge übernahmen sie und halten sie noch immer. Dorius Steinhüter, einer der ursprünglichen Arbeiter, liegt verletzt am Grund der Grube.",
			source = "https://warcraft.wiki.gg/wiki/Grimesilt_Dig_Site",
		},
		["sea of cinders"] = {
			name = "Das Meer der Asche",
			short = "Das Meer der Asche liegt flach und offen im südlichen Teil der Sengenden Schlucht, gleich nördlich des Blackrock. Nichts wächst dort.",
			full = "Das Meer der Asche liegt flach und offen im südlichen Teil der Sengenden Schlucht, gleich nördlich des Blackrock. Nichts wächst dort. Der Boden schwelt noch immer, und ständig steigt Asche im Wind auf und treibt über die kahlen Flächen. Feuer und Wind ließen nichts zurück als Ödnis, und das Brennen hat nie aufgehört.",
			source = "https://warcraft.wiki.gg/wiki/Sea_of_Cinders",
		},
		["slag pit"] = {
			name = "Die Schlackengrube",
			short = "Tief im Inneren des Kessels liegt die Schlackengrube, eine unterirdische Mine reich an Erz. Grausame Dunkeleisenzwerge betreiben sie, und Sklavenarbeiter graben, während Sklavenhändler und Zuchtmeister sie antreiben.",
			full = "Tief im Inneren des Kessels liegt die Schlackengrube, eine unterirdische Mine reich an Erz. Grausame Dunkeleisenzwerge betreiben sie, und Sklavenarbeiter graben, während Sklavenhändler und Zuchtmeister sie antreiben. Die Dunkeleisenzwerge begegnen jedem, der ihren Bergbau stört, mit offener Feindseligkeit, und ausgehungerte Incendosaurier streifen durch die Tiefen.",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "Stonewroughtpass",
			short = "Franclorn Forgewright, der Baumeister der Dunkeleisenzwerge, der auch den Stonewroughtdamm beaufsichtigte, entwarf diesen Tunnel durch die Berge.",
			full = "Franclorn Forgewright, der Baumeister der Dunkeleisenzwerge, der auch den Stonewroughtdamm beaufsichtigte, entwarf diesen Tunnel durch die Berge. Er verläuft nordöstlich vom Kopf des Staubfeuertals zum Tal der Könige in Loch Modan.\n\nAls die Dunkeleisenzwerge die Garnisonen der Zwerge in der Schlucht überrannten, zogen sich die Zwerge nach Loch Modan zurück und versiegelten den Pass. Seine Tore sind noch immer verschlossen, und Gebirgsjägerin Pebblebitty bewacht das auf der Seite von Loch Modan und weist Reisende ab.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "Tanners Lager",
			short = "Sarah Tanner, eine Meisterin der Elementarlederverarbeitung, hat ein einsames Zelt in diesem kleinen Lager.",
			full = "Sarah Tanner, eine Meisterin der Elementarlederverarbeitung, hat ein einsames Zelt in diesem kleinen Lager. Dahinter windet sich ein langer Gang zum Bau von Margol die Wütende, einer Donnerechse und dem Schrecken jedes Archäologen, der die Schlucht betreten hat. Der Legende nach hat sie Barnabas gefressen, den Bruder von Burrian Kohlenstaub, und der Kopf der Axt von Gebirgsjägerin Pebblebitty steckt noch in ihrem Horn.",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
		},
		["thorium point"] = {
			name = "Thoriumspitze",
			short = "Aufseher Schlickfaust führt die Thoriumbruderschaft an, Dunkeleisenzwerge, die ihren Klan verlassen haben.",
			full = "Aufseher Schlickfaust führt die Thoriumbruderschaft an, Dunkeleisenzwerge, die ihren Klan verlassen haben. Sie bauten die Thoriumspitze auf den Klippen im äußersten Norden der Schlucht, über dem Kessel, und von dort behalten sie genau im Auge, was ihre früheren Verwandten tun. Die Stadt ist neutral, mit einer Schmiede und einem Amboss, bereit zur Arbeit. Die Schmiede der Bruderschaft gehören angeblich zu den besten, die Azeroth gesehen hat, und das Gerücht sagt, sie wüssten, wie man die Waffen von Ragnaros selbst herstellt, doch es fehle ihnen an Händen, um zu beschaffen, was die Arbeit braucht.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Point",
		},
	},
	-- Brennende Steppe: 11 subzones
	[1428] = {
		["blackrock mountain"] = {
			name = "Der Blackrock",
			short = "Der Blackrock trug seinen Namen Jahrhunderte, bevor die Blackrockorcs zu ihm kamen. Er erhob sich aus dem zerstörten Königreich der Dunkeleisenzwerge, als Ragnaros in die Welt einbrach.",
			full = "Der Blackrock trug seinen Namen Jahrhunderte, bevor die Blackrockorcs zu ihm kamen. Er erhob sich aus dem zerstörten Königreich der Dunkeleisenzwerge, als Ragnaros in die Welt einbrach. Die Heere der Bronzebeard und der Wildhammer waren marschiert, um die Dunkeleisenzwerge zu vernichten. Ihre Könige, Madoran und Khardros, sahen Feuerstürme das Land verschlingen und wandten die Armeen zurück zu ihren Königreichen. Ragnaros zog sich in das sengende Herz des Berges zurück und ließ die überlebenden Dunkeleisenzwerge darunter eine Festung aushauen, Schattenschmiede.\n\nIm Zweiten Krieg nahm die Horde die Blackrockspitze, die Festung im Berg, und machte sie zum Stützpunkt für ihren Feldzug gegen Lordaeron. Jetzt streiten Ragnaros und Nefarian um den ganzen Berg. Der Feuerlord herrscht vom Kern des Vulkans aus mit seinen Dunkeleisenzwergen und seinen Elementaren. Nefarian hält die Höhen mit den Blackrockorcs und seinen schwarzen Drachen.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "Blackrockpass",
			short = "Der Blackrockpass ist die Schwelle zwischen zwei Welten. Auf der einen Seite liegen die stillen grünen Hügel des Rotkammgebirges.",
			full = "Der Blackrockpass ist die Schwelle zwischen zwei Welten. Auf der einen Seite liegen die stillen grünen Hügel des Rotkammgebirges. Auf der anderen wartet die Brennende Steppe, versengt und bis zur Unkenntlichkeit verdreht. Ein Tor steht an der Grenze und markiert die Linie deutlich. Es ist der Hauptzugang in die Steppe von Süden.\n\nDie Wesen jenseits des Tors sind weit grausamer als alles, was sich in den Bergen dahinter regt.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "Festung der Blackrock",
			short = "Dicht im Schatten der Blackrockspitze, einer Festung aus schwarzem Stein, hält der Blackrockklan eine massive Festung im Norden der Brennenden Steppe.",
			full = "Dicht im Schatten der Blackrockspitze, einer Festung aus schwarzem Stein, hält der Blackrockklan eine massive Festung im Norden der Brennenden Steppe. Diese Orcs bleiben außer Sichtweite der Straße und spähen stets nach einem Angriff der Allianz aus. Sie folgen den alten, brutalen Wegen und schürfen in den Bergen rings um die Spitze das Metall für ihre Waffen und Rüstungen.\n\nVor den Mauern, auf den Feldern der Ehre, versammeln sich die Krieger des Klans und ihre Verbündeten und üben, im Zaum gehalten von den Blackrock-Unteroffizieren. General Thorg'izog überwacht die Festung und gibt den Truppen ihre Befehle.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
		},
		["dracodar"] = {
			name = "Draco'dar",
			short = "Versengte Hügel füllen den Südwesten der Brennenden Steppe, geschwärzt und dem schwarzen Drachenschwarm überlassen. Seine Diener kriechen in großer Zahl über den Boden.",
			full = "Versengte Hügel füllen den Südwesten der Brennenden Steppe, geschwärzt und dem schwarzen Drachenschwarm überlassen. Seine Diener kriechen in großer Zahl über den Boden.",
			source = "https://warcraft.wiki.gg/wiki/Draco'dar",
		},
		["dreadmaul rock"] = {
			name = "Schreckensfels",
			short = "Die Oger der Feuermägen machen den Schreckensfels, auch Schreckensfelsgipfel genannt, zu ihrem Stützpunkt. Pfade führen zur Spitze des Felsens, und ein verwickeltes Höhlensystem aus Ogerhügeln verläuft in seinem Inneren.",
			full = "Die Oger der Feuermägen machen den Schreckensfels, auch Schreckensfelsgipfel genannt, zu ihrem Stützpunkt. Pfade führen zur Spitze des Felsens, und ein verwickeltes Höhlensystem aus Ogerhügeln verläuft in seinem Inneren.\n\nDie Feuermägen sind Zurückgelassene des Zweiten Krieges. Einige studieren arkane Magie, auch wenn ihre riesigen Körper sie weiterhin zu besseren Kämpfern als Zauberern machen. Sie wollen die Brennende Steppe allein für Oger beanspruchen, und die Allianz, die Blackrockorcs, die Dunkeleisenzwerge und die schwarzen Drachen lassen es nicht zu.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Rock",
		},
		["flame crest"] = {
			name = "Flammenkamm",
			short = "Nur eine grobe Brücke führt auf den kahlen Felsvorsprung, auf dem der Flammenkamm steht. Der Außenposten gehört weder der Horde noch der Allianz.",
			full = "Nur eine grobe Brücke führt auf den kahlen Felsvorsprung, auf dem der Flammenkamm steht. Der Außenposten gehört weder der Horde noch der Allianz. In einer kleinen Höhle im hinteren Teil lebt Kibler, der einen geschwätzigen Papagei namens Opus hält. Mathredis Feuerstern, hungrig nach Magie, feilscht um mächtige arkane Komponenten.",
			source = "https://warcraft.wiki.gg/wiki/Flame_Crest",
		},
		["morgans vigil"] = {
			name = "Morgans Wacht",
			short = "Feuer ist durch Morgans Wacht gegangen, in der südöstlichen Ecke der Brennenden Steppe. Seine Häuser sind bis auf die Grundmauern niedergebrannt, und sein einziger Magierturm ist zerfallen.",
			full = "Feuer ist durch Morgans Wacht gegangen, in der südöstlichen Ecke der Brennenden Steppe. Seine Häuser sind bis auf die Grundmauern niedergebrannt, und sein einziger Magierturm ist zerfallen. Die Allianz hält, was übrig ist, und ihre Leute leben in Zelten zwischen den Trümmern. Marschall Maxwell ist hier und sucht Nachricht von einem hochrangigen Offizier aus Stormwind.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Vigil",
		},
		["pillar of ash"] = {
			name = "Die Aschensäule",
			short = "Ein hoher Turm aus verbranntem Stein erhebt sich am östlichen Ende dieses Lagers, das Blackrockorcs, Oger der Feuermägen und Gluthauer-Trolle untereinander halten.",
			full = "Ein hoher Turm aus verbranntem Stein erhebt sich am östlichen Ende dieses Lagers, das Blackrockorcs, Oger der Feuermägen und Gluthauer-Trolle untereinander halten.",
			source = "https://warcraft.wiki.gg/wiki/Pillar_of_Ash",
		},
		["ruins of thaurissan"] = {
			name = "Die Ruinen von Thaurissan",
			short = "Diese aschigen Flächen in der Brennenden Steppe waren einst grün, als hier die Stadt Thaurissan stand. Der Klan der Dunkeleisenzwerge, aus Ironforge verbannt, gründete sie, und Zaubererthan Thaurissan herrschte über sie.",
			full = "Diese aschigen Flächen in der Brennenden Steppe waren einst grün, als hier die Stadt Thaurissan stand. Der Klan der Dunkeleisenzwerge, aus Ironforge verbannt, gründete sie, und Zaubererthan Thaurissan herrschte über sie.\n\nDer Klan verlor den Krieg der Drei Hämmer. Seine Armee war gerade an den Festungen der beiden anderen Klans zerbrochen, als Thaurissan sieben seiner vertrautesten Zwerge versammelte. Verzweifelt, das Blatt zu wenden, rief er die Mächte an, die unter der Welt schliefen, um einen Diener, der den Krieg zurückgewinnen sollte. Ragnaros, Elementarlord des Feuers, antwortete. Ein Vulkan spaltete die Berge und brannte das Tal zu Asche, und die Stadt wurde zerstört. Die überlebenden Dunkeleisenzwerge, als Sklaven des Feuerlords, verließen die Ruinen für eine neue Heimat unter dem Berg, der dort aufgestiegen war.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
		},
		["slither rock"] = {
			name = "Schlitterfels",
			short = "Versteckt hinter dem Schreckenspfad, in der äußersten nordöstlichen Ecke der Brennenden Steppe, birgt eine kleine Höhle einen einzigen Bewohner.",
			full = "Versteckt hinter dem Schreckenspfad, in der äußersten nordöstlichen Ecke der Brennenden Steppe, birgt eine kleine Höhle einen einzigen Bewohner. Cyrus Therepentous, ein Spross der schwarzen Drachenbrut, lebt hier allein. Er hilft anderen gegen einen gemeinsamen Feind, aber niemals ohne grobe und spöttische Bemerkungen.",
			source = "https://warcraft.wiki.gg/wiki/Slither_Rock",
		},
		["terror wing path"] = {
			name = "Schreckenspfad",
			short = "Schwarze Drachkin patrouillieren in dem Tal, das Schreckenspfad heißt, in der östlichen Brennenden Steppe. Welpen und Drachkin des schwarzen Drachenschwarms nisten zwischen seinen Felsen und der Asche.",
			full = "Schwarze Drachkin patrouillieren in dem Tal, das Schreckenspfad heißt, in der östlichen Brennenden Steppe. Welpen und Drachkin des schwarzen Drachenschwarms nisten zwischen seinen Felsen und der Asche.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Wing_Path",
		},
	},
	-- Wald von Elwynn: 22 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "Brackwells Kürbisbeet",
			short = "Im Südosten des Waldes von Elwynn steht ein Gehöft, das einst der Familie Brackwell gehörte. Heute hält die Bruderschaft der Defias es, und niemand kann sagen, was aus den Brackwells geworden ist.",
			full = "Im Südosten des Waldes von Elwynn steht ein Gehöft, das einst der Familie Brackwell gehörte. Heute hält die Bruderschaft der Defias es, und niemand kann sagen, was aus den Brackwells geworden ist. Sie sind einfach von ihren Feldern und Zäunen verschwunden.\n\nEines wird noch über sie erzählt. Ihre preisgekrönte Sau Prinzessin wurde riesig von dem Gemüse, das sie stahl, wenn sie sich zum benachbarten Hof der Stonefields hinüberschlich.",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "Kristallsee",
			short = "Östlich von Goldhain kriechen Murlocs über die Ufer des Kristallsees und waten in großer Zahl durch seine Untiefen. Das Wasser ist gefährlich für jeden, der unvorbereitet herkommt.",
			full = "Östlich von Goldhain kriechen Murlocs über die Ufer des Kristallsees und waten in großer Zahl durch seine Untiefen. Das Wasser ist gefährlich für jeden, der unvorbereitet herkommt.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "Holzfällerlager des Osttals",
			short = "Über den Osten des Waldes von Elwynn verteilen sich Sägewerkslager, dazwischen die Unterkünfte. Zusammen bilden sie das Holzfällerlager des Osttals.",
			full = "Über den Osten des Waldes von Elwynn verteilen sich Sägewerkslager, dazwischen die Unterkünfte. Zusammen bilden sie das Holzfällerlager des Osttals. Käufer schicken ohne Pause Aufträge für Bauholz, und die Holzfäller arbeiten unter strengen Fristen.\n\nDer Wald drängt nah heran. Wölfe und Bären greifen die Lager so oft an, dass Arbeiter vertrieben und Lieferungen gefährdet werden, und die Wache von Stormwind musste Hilfe von außen anfordern, um ihre Zahl zu verringern.",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "Echokammmine",
			short = "Marschall McBride schickt immer wieder Männer in die Echokammmine im Nordwesten des Nordhaintals, um die Kobolde zu dezimieren, die ihre Stollen besetzt haben.",
			full = "Marschall McBride schickt immer wieder Männer in die Echokammmine im Nordwesten des Nordhaintals, um die Kobolde zu dezimieren, die ihre Stollen besetzt haben. Die Menschen, die in der Nähe wohnen, sind ihretwegen verärgert.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "Tiefenschachtmine",
			short = "Stormwind hat einst Gold aus der Tiefenschachtmine geholt. Die Schächte liegen jetzt verlassen da, und eine Sippe von Kobolden hält sie besetzt.",
			full = "Stormwind hat einst Gold aus der Tiefenschachtmine geholt. Die Schächte liegen jetzt verlassen da, und eine Sippe von Kobolden hält sie besetzt. Als sich die Berichte über Kobolde bestätigten, verstärkte Marschall Dughan die Patrouillen rund um die Mine.\n\nUnter den Kobolden ist einer namens Goldzahn, der eine Halskette hält, die Tantchen Bernice Stonefield gestohlen wurde.",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "Der Waldrand",
			short = "Ein Waldstreifen südwestlich von Stormwind ragt wie eine Halbinsel zwischen dem Nazferitisee und einem kleineren Bach, der nach Westfall fließt.",
			full = "Ein Waldstreifen südwestlich von Stormwind ragt wie eine Halbinsel zwischen dem Nazferitisee und einem kleineren Bach, der nach Westfall fließt. Eber wühlen im Unterholz, und an den Flussufern zeigen sich Kupferadern.\n\nEine Bande von Flusspfoten-Gnollen hält den Wald unter ihrem Häuptling Hogger, der Farmen und Dörfer im ganzen Wald von Elwynn überfällt. Die Armee von Stormwind hat ein Kopfgeld auf ihn ausgesetzt. Gerüchten zufolge steckt die Meute mit der Bruderschaft der Defias unter einer Decke, die sie angeblich mit Waffen versorgt.",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "Goldhain",
			short = "Goldhain liegt mitten im Wald von Elwynn, eine der kleinen Städte, die rund um Stormwind entstanden. Im Ersten Krieg waren Goldhain und Moonbrook die letzten beiden Städte zwischen den Orcs und der Hauptstadt.",
			full = "Goldhain liegt mitten im Wald von Elwynn, eine der kleinen Städte, die rund um Stormwind entstanden. Im Ersten Krieg waren Goldhain und Moonbrook die letzten beiden Städte zwischen den Orcs und der Hauptstadt. Kriegshäuptling Schwarzfaust nahm beide ein, um König Llane Wrynn vor der Plünderung der Burg Stormwind von seinem Volk abzuschneiden. Nach dem Zweiten Krieg baute die Allianz von Lordaeron die Stadt wieder auf, und Oberbefehlshaber Turalyon überwachte die Rückkehr der verstreuten Bürger des Königreichs.\n\nMarschall Dughan von der Wache von Stormwind hält hier jetzt die Ordnung. Herd und Bier des Gasthauses Zur Höhle des Löwen, einer der angesehensten Schenken in Azeroth, ziehen Reisende von allen Straßen an, die sich hier treffen. Murlocs vom Steinhügelsee haben Stadtbewohner getötet, darunter zwei Wachen, und die Wachen fürchten, dass die Kämpfe die Stadt erreichen.",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "Heldenwache",
			short = "Auf einer Insel im Steinhügelsee umgibt ein Ring aufrecht stehender Steine den Stein der Erinnerung. Er ehrt die Toten des Ersten Krieges, als die Orcs Goldhain und das Land ringsum plünderten.",
			full = "Auf einer Insel im Steinhügelsee umgibt ein Ring aufrecht stehender Steine den Stein der Erinnerung. Er ehrt die Toten des Ersten Krieges, als die Orcs Goldhain und das Land ringsum plünderten. Abtrünnige Magier halten die Insel jetzt.",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["jasperlode mine"] = {
			name = "Jaspismine",
			short = "Kobolde haben die Stollen der Jaspismine überrannt, die Stormwind einst das Roherz lieferte, das es für seine Kriege brauchte. Die Armee, von anderen Bedrohungen überdehnt, hat keine Männer übrig, um sie zu vertreiben.",
			full = "Kobolde haben die Stollen der Jaspismine überrannt, die Stormwind einst das Roherz lieferte, das es für seine Kriege brauchte. Die Armee, von anderen Bedrohungen überdehnt, hat keine Männer übrig, um sie zu vertreiben.\n\nDie Kobolde sind dort unten nicht allein. Eine Kolonie von Minenspinnen hat sich im tiefsten Teil niedergelassen, und für sie sind die Kobolde eine Mahlzeit. Ihre Königin, die Giftzahnbrutmutter, heißt ungebetene Gäste nicht willkommen.",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
		},
		["jerods landing"] = {
			name = "Jerods Anlegestelle",
			short = "Die Bruderschaft der Defias hält Jerods Anlegestelle, einen Bootsanleger am Ufer des Nazferitisees auf der Seite des Waldes von Elwynn.",
			full = "Die Bruderschaft der Defias hält Jerods Anlegestelle, einen Bootsanleger am Ufer des Nazferitisees auf der Seite des Waldes von Elwynn. Ihr Dockmeister und seine Männer schmuggeln darüber gestohlene Waren aus dem Rotkammgebirge zu Klavens Turm in Westfall.",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["maclure vineyards"] = {
			name = "Weinberge der Maclures",
			short = "Die Maclures pflegen lange Rebreihen im Süden des Waldes von Elwynn. Sie liegen in bitterer Rivalität mit den Stonefields nebenan, und keine Seite verbirgt ihre Abneigung.",
			full = "Die Maclures pflegen lange Rebreihen im Süden des Waldes von Elwynn. Sie liegen in bitterer Rivalität mit den Stonefields nebenan, und keine Seite verbirgt ihre Abneigung. Doch ein Kind jeder Familie hat sich in das Kind der anderen verliebt.",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
		},
		["mirror lake"] = {
			name = "Spiegelsee",
			short = "Der Spiegelsee liegt klein und still im Westen des Waldes von Elwynn, sein Wasserfall stürzt hell neben einem nahen Obsthain herab, ein Ort, der wie zum Schwimmen oder Angeln gemacht aussieht.",
			full = "Der Spiegelsee liegt klein und still im Westen des Waldes von Elwynn, sein Wasserfall stürzt hell neben einem nahen Obsthain herab, ein Ort, der wie zum Schwimmen oder Angeln gemacht aussieht. Banditen der Defias haben sich jetzt in den Wäldern ringsum eingenistet, und was ein Ort der Ruhe sein sollte, ist zu einem geworden, den man nur vorsichtig durchquert.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
		},
		["mirror lake orchard"] = {
			name = "Obsthain am Spiegelsee",
			short = "Am Südufer des Spiegelsees steht ein Obsthain mit einem Häuschen daneben. Banditen der Defias haben sich beides genommen.",
			full = "Am Südufer des Spiegelsees steht ein Obsthain mit einem Häuschen daneben. Banditen der Defias haben sich beides genommen.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "Abtei von Nordhain",
			short = "Vor Jahrhunderten kamen Kleriker der Kirche des Heiligen Lichts aus Lordaeron nach Süden und gründeten in dieser Abtei den Heiligen Orden der Kleriker von Nordhain.",
			full = "Vor Jahrhunderten kamen Kleriker der Kirche des Heiligen Lichts aus Lordaeron nach Süden und gründeten in dieser Abtei den Heiligen Orden der Kleriker von Nordhain. Sie spendeten Stormwind in schweren Zeiten Trost, und Medivh, der Wächter von Tirisfal, lag jahrelang in ihrer Obhut im Koma.\n\nIm Ersten Krieg standen die Kleriker an der Seite der Armeen von Stormwind. Als der Ogerlord Turok und seine Bande den Folianten der Göttlichkeit stahlen, führte Sir Anduin Lothar eine Expedition in ihr Versteck, um ihn zurückzuholen. Der Verteidiger der Krone, vom Abt und König Llane Wrynn entsandt, rettete Lothar und die Überlebenden, und der Foliant kehrte in die Abtei zurück. Einmal belagerten Räuber, von den Orcs überredet, gegen die Krone zu kämpfen, die Abtei, und der Verteidiger kam wieder, mit Truppen aus Stormwind, und rettete sie.\n\nKurz nachdem Garona die Halborcin als Gefangene dorthin gebracht worden war, überrannten die Orcs die Abtei und zerstörten sie. Flüchtlinge flohen mit heiligen Folianten, die sie aus den Trümmern gezogen hatten, nach Lordaeron, und Magier von Dalaran lernten von ihnen den Zauber Unsichtbarkeit.\n\nIm Zweiten Krieg machte Cho'galls Schattenhammerklan die Ruinen zu seinem Hauptquartier. Nachdem die Allianz von Lordaeron den Wald von Elwynn zurückerobert hatte, half Erzbischof Alonsus Faol beim Wiederaufbau der Abtei und gründete die Bruderschaft von Nordhain, die sie heute hält. Ihre Haupthalle, die Waffenhalle und der Bibliotheksflügel stehen wieder in dem Tal, das den Namen der Abtei trägt.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "Nordhaintal",
			short = "Undurchdringliche Berge schließen das Nordhaintal auf allen Seiten bis auf eine ein. Ein Pass führt nach Süden hinaus, geschützt von dicken Steinmauern und einem bewachten Tor.",
			full = "Undurchdringliche Berge schließen das Nordhaintal auf allen Seiten bis auf eine ein. Ein Pass führt nach Süden hinaus, geschützt von dicken Steinmauern und einem bewachten Tor. Ein Fluss durchzieht das Tal und mündet in den Kristallsee.\n\nMarschall Douglas McBride von der Wache von Stormwind befehligt die Garnison der Abtei und verantwortet die Verteidigung des Tals. Seine Wachen haben immer noch Mühe, den Frieden zu halten. Wölfe, die aus dem Dämmerwald geflohen sind, haben sich in den Wäldern vermehrt, Kobolde wimmeln in der Echokammmine, und Schläger der Defias haben die Weinberge besetzt.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire vineyards"] = {
			name = "Weinberge von Nordhain",
			short = "Banditen der Defias haben die Bauern aus den Weinbergen von Nordhain vertrieben, einst der Stolz von Stormwind. Die Reben liegen östlich der Abtei.",
			full = "Banditen der Defias haben die Bauern aus den Weinbergen von Nordhain vertrieben, einst der Stolz von Stormwind. Die Reben liegen östlich der Abtei. Garrick Schleichfuß führt die Agenten, die die Reihen jetzt halten, und seine Handlanger haben Eigentum von Milly Geltmark an sich genommen, die um ihren eigenen Weinberg fürchtet.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "Kammwacht",
			short = "Die Kammwacht überblickt die Grenze des Waldes von Elwynn, einer der Spähtürme der Wache von Stormwind.",
			full = "Die Kammwacht überblickt die Grenze des Waldes von Elwynn, einer der Spähtürme der Wache von Stormwind. Ihre Wachposten richten den Blick auf das Rotkammgebirge, wo sich Gnolle und Orcs sammeln, auf den Dämmerwald, wo die Toten nicht begraben bleiben, und auf die nahen Lager der Defias. Die Garnison ist gegen alle drei gut gewappnet.",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "Der Steinhügelsee",
			short = "Der Steinhügelsee liegt im Nordosten des Waldes von Elwynn, und auf der großen Insel in seiner Mitte steht die Heldenwache, ein Ring aus Steinen und ein Denkmal namens Stein der Erinnerung.",
			full = "Der Steinhügelsee liegt im Nordosten des Waldes von Elwynn, und auf der großen Insel in seiner Mitte steht die Heldenwache, ein Ring aus Steinen und ein Denkmal namens Stein der Erinnerung.\n\nPilger kamen einst sicher hierher. Jetzt hat ein Murlocstamm grobe Behausungen am Südufer errichtet, gleichgültig gegenüber dem Denkmal auf der anderen Seite des Wassers.",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "Hof der Stonefields",
			short = "Der Hof der Stonefields liegt im Süden des Waldes von Elwynn und wird von den Stonefields bewirtschaftet, die mit den benachbarten Maclures in bitterer Rivalität leben.",
			full = "Der Hof der Stonefields liegt im Süden des Waldes von Elwynn und wird von den Stonefields bewirtschaftet, die mit den benachbarten Maclures in bitterer Rivalität leben. Doch ein Kind jedes Hauses hat sich verliebt und trotzt damit dem alten Groll zwischen den Familien. Manche hoffen, dass die Liebe gelingen könnte, wo jahrelanger Streit nie etwas ausrichtete, und heilen, was die Fehde zerbrochen hat.",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["thunder falls"] = {
			name = "Donnerfälle",
			short = "Wasser fällt an beiden Enden der Donnerfälle, einer schmalen Schlucht in den Bergen im Nordwesten des Waldes von Elwynn, und keine andere Schlucht im Wald kann das von sich sagen.",
			full = "Wasser fällt an beiden Enden der Donnerfälle, einer schmalen Schlucht in den Bergen im Nordwesten des Waldes von Elwynn, und keine andere Schlucht im Wald kann das von sich sagen. Ein dritter Wasserfall stürzt von den nördlichen Klippen herab und speist sie von oben.\n\nDer Pfad vom Wasserfall am Spiegelsee hinauf führt steil und schmal zu einem kleinen Landhaus, wo man Amboss und Feuer in Gang hält. Ein kleiner Steg und ein Boot liegen am Fluss neben dem Haus. Ein paar Banditen halten sich in der Nähe des Häuschens auf. Der Fluss fließt weiter zu einem weiteren Wasserfall nahe der Grenze zu Westfall.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "Turm von Azora",
			short = "Der Turm von Azora erhebt sich zwischen den Feldern im Zentrum des Waldes von Elwynn, ein kleiner Magierturm, den Diener unterhalten, die alle Gnome zu sein scheinen und dem Erzmagier Theocritus gehorchen.",
			full = "Der Turm von Azora erhebt sich zwischen den Feldern im Zentrum des Waldes von Elwynn, ein kleiner Magierturm, den Diener unterhalten, die alle Gnome zu sein scheinen und dem Erzmagier Theocritus gehorchen. Weit entfernt im Rotkammgebirge herrscht der böse Großmagus Doane über den Turm von Ilgalar. Die beiden Türme liegen in ständiger Fehde, und jeder spioniert den anderen mit Magie aus.\n\nDie Aura des Turms wirkt auf alles, was ihm zu nahe kommt, und verwandelt es in etwas Seltsameres. Die Diener müssen gegen lebende Eimer und mutierte Schmetterlinge kämpfen.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "Weststromgarnison",
			short = "Die Wache von Stormwind unterhält eine Kaserne in der Weststromgarnison, am Westende des Waldes von Elwynn nahe der Grenze zu Westfall.",
			full = "Die Wache von Stormwind unterhält eine Kaserne in der Weststromgarnison, am Westende des Waldes von Elwynn nahe der Grenze zu Westfall. Korruption und politische Instabilität haben das Königreich geschwächt. Da der Großteil der Armee von Stormwind in der Ferne steht, hat die Garnison kaum genug Männer, um die Straßen gegen wachsende Zahlen von Gnollen und Dieben aus Westfall sicher zu halten.\n\nStellvertreter Rainer befehligt den Posten. Steckbriefe dort nennen Hogger, den Häuptling der Flusspfoten-Gnolle, der jeden Versuch seiner Festnahme niedergeschlagen hat. Seine Meute wimmelt in den Wäldern südlich des Wachturms.",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- Gebirgspass der Totenwinde: 9 subzones
	[1430] = {
		["aridens camp"] = {
			name = "Aridens Lager",
			short = "Ein verlassener Lagerplatz liegt direkt nördlich der Hauptstraße durch den Pass. Er ist als Aridens Lager bekannt, und heute ist niemand dort.",
			full = "Ein verlassener Lagerplatz liegt direkt nördlich der Hauptstraße durch den Pass. Er ist als Aridens Lager bekannt, und heute ist niemand dort.",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
		},
		["deadmans crossing"] = {
			name = "Totmannsfurt",
			short = "An der östlichen Kreuzung des Passes steht ein Galgenbaum, und zwei Leichen hängen noch an seinen Ästen. Daneben steht ein Wegweiser mit den Worten „Kehrt um!“ und „Lasst alle Hoffnung fahren, die ihr hier eintretet.“",
			full = "An der östlichen Kreuzung des Passes steht ein Galgenbaum, und zwei Leichen hängen noch an seinen Ästen. Daneben steht ein Wegweiser mit den Worten „Kehrt um!“ und „Lasst alle Hoffnung fahren, die ihr hier eintretet.“\n\nVon der Kreuzung führt eine Straße nach Westen in den Dämmerwald, eine andere nach Osten in die Sümpfe des Elends und eine dritte nach Süden Richtung Karazhan.",
			source = "https://warcraft.wiki.gg/wiki/Deadman's_Crossing",
		},
		["deadwind ravine"] = {
			name = "Schlucht der Totenwinde",
			short = "Eine zerklüftete Spalte zieht sich nach Süden durch die Berge Richtung Karazhan. Die westliche Straße folgt ihrer oberen Ebene.",
			full = "Eine zerklüftete Spalte zieht sich nach Süden durch die Berge Richtung Karazhan. Die westliche Straße folgt ihrer oberen Ebene. Am fernen Ende führt eine Brücke nach Süden, und der unheilvolle Turm steht ganz in der Nähe.",
			source = "https://warcraft.wiki.gg/wiki/Deadwind_Ravine",
		},
		["groshgok compound"] = {
			name = "Das Grosh'gok Lager",
			short = "Von allen Höhlen der Totenwindoger im Laster liegt das Grosh'gok Lager am weitesten im Süden, und es ist die größte. Die Totenwindoger leben darin.",
			full = "Von allen Höhlen der Totenwindoger im Laster liegt das Grosh'gok Lager am weitesten im Süden, und es ist die größte. Die Totenwindoger leben darin.",
			source = "https://warcraft.wiki.gg/wiki/Grosh'gok_Compound",
		},
		["karazhan"] = {
			name = "Karazhan",
			short = "Die Erbauer des Elfenbeinturms von Karazhan sind in der Zeit verloren. Er steht auf einem Knotenpunkt von Leylinien im Süden des Gebirgspasses der Totenwinde und wurde zum Sitz Medivhs, des letzten Wächters von Tirisfal.",
			full = "Die Erbauer des Elfenbeinturms von Karazhan sind in der Zeit verloren. Er steht auf einem Knotenpunkt von Leylinien im Süden des Gebirgspasses der Totenwinde und wurde zum Sitz Medivhs, des letzten Wächters von Tirisfal. Wie es seinem Titel entsprach, hatte Medivh eine gewaltige Sammlung von Schriften und Artefakten angehäuft, größer noch als die der Kirin Tor. Er wurde im Ersten Krieg im Turm von Khadgar, Anduin Lothar und Garona getötet.\n\nSeither steht der Turm verlassen, und ein Fluch lastet auf ihm und dem Land ringsum. Geister erfüllen seine Hallen, und Dämonen sollen unter ihnen umgehen.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan",
		},
		["masters cellar"] = {
			name = "Der Keller des Meisters",
			short = "Unter den Ruinen eines kleinen Dorfes südlich von Karazhan öffnet sich der Boden zu Kellern voller Geister. Die Dorfbewohner waren wohl Diener des Turms.",
			full = "Unter den Ruinen eines kleinen Dorfes südlich von Karazhan öffnet sich der Boden zu Kellern voller Geister. Die Dorfbewohner waren wohl Diener des Turms. Niemand weiß, wer sie getötet hat. Manche geben Medivh die Schuld oder etwas, das er beschworen hat, andere den Dunklen Reitern.\n\nZwei Eingänge führen hinab. Einer öffnet sich in einen riesigen Weinkeller, dessen Regale und Fässer längst den Toten überlassen sind. Der andere führt zu einem Keller, dessen Boden in ein Höhlensystem eingebrochen ist, das tief unter die Erde reicht. Untote Bewohner und Verwalter, verdammte Seelen, ruhelose Schemen und wehklagende Gespenster erfüllen beide. Manche der Verwalter scheinen noch ein Haus ohne Herrn zu betreuen.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "Morgans Plot",
			short = "Hinter Karazhan steht eine kleine, verfallene Kirche, deren Friedhof und Gruft in die Düsternis des Gebirgspasses der Totenwinde eingesunken sind.",
			full = "Hinter Karazhan steht eine kleine, verfallene Kirche, deren Friedhof und Gruft in die Düsternis des Gebirgspasses der Totenwinde eingesunken sind. Untote Bewohner suchen die Kapelle heim, und ein weiterer geht auf dem Hügel unmittelbar darunter auf Streife.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Plot",
		},
		["sleeping gorge"] = {
			name = "Die schlummernde Schlucht",
			short = "Eine kleine Schlucht schneidet durch den östlichen Gebirgspass der Totenwinde. Einer der Pfade nach Süden Richtung Karazhan führt ein Stück durch sie hindurch, bevor er nach Osten ins Laster abbiegt.",
			full = "Eine kleine Schlucht schneidet durch den östlichen Gebirgspass der Totenwinde. Einer der Pfade nach Süden Richtung Karazhan führt ein Stück durch sie hindurch, bevor er nach Osten ins Laster abbiegt.",
			source = "https://warcraft.wiki.gg/wiki/Sleeping_Gorge",
		},
		["vice"] = {
			name = "Das Laster",
			short = "Entlang der Straße nach Karazhan, im Süden des Passes, liegt ein trostloser Streifen aus Felsen, das Laster genannt. Die Totenwindoger leben hier in Hügeln und Lagern, die entlang der Straße verstreut liegen.",
			full = "Entlang der Straße nach Karazhan, im Süden des Passes, liegt ein trostloser Streifen aus Felsen, das Laster genannt. Die Totenwindoger leben hier in Hügeln und Lagern, die entlang der Straße verstreut liegen.\n\nNiemand weiß, warum sie sich dort niedergelassen haben, wo ihnen nur ruhelose Geister und die darüber kreisenden Geier Gesellschaft leisten.",
			source = "https://warcraft.wiki.gg/wiki/Vice",
		},
	},
	-- Dämmerwald: 17 subzones
	[1431] = {
		["addles stead"] = {
			name = "Addles Siedlung",
			short = "Die Bruderschaft der Defias hat Addles Siedlung besetzt, eines der vielen Gehöfte, die im Südwesten des Dämmerwalds aufgegeben wurden, als die Dunkelheit hereinkroch.",
			full = "Die Bruderschaft der Defias hat Addles Siedlung besetzt, eines der vielen Gehöfte, die im Südwesten des Dämmerwalds aufgegeben wurden, als die Dunkelheit hereinkroch. Ihre Agenten ziehen über das Feld, verstecken sich in der Scheune und pirschen durch die Zimmer des kleinen Bauernhauses.",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "Bettlerschlupfwinkel",
			short = "Bettlerschlupfwinkel, ein verlassener Spähturm der Wache von Stormwind, steht im Nordosten des Dämmerwalds, östlich des Anwesens der Mistmantles und nördlich der Straße in den Gebirgspass der Totenwinde.",
			full = "Bettlerschlupfwinkel, ein verlassener Spähturm der Wache von Stormwind, steht im Nordosten des Dämmerwalds, östlich des Anwesens der Mistmantles und nördlich der Straße in den Gebirgspass der Totenwinde. Die Verlassenen halten ihn jetzt, und Todespirscher Zraedus und Apotheker Faustin führen in seinen Mauern Experimente durch.\n\nEin Pfad windet sich hinab zu einem kleinen Teich, der von einem Wasserfall gespeist wird, wo ein unmarkiertes Grab unter zwei großen Statuen ruht, die wie die am Dunklen Portal gemeißelt sind. Nahe dem Turm liegt ein weiterer kleiner Friedhof mit dem Grab eines Unbekannten Soldaten.",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "Schattenhain",
			short = "Die wenigen Gebäude am Rand des Schattenhains liegen in Trümmern, und Worgen der Nachtheuler streifen über seine dunklen Felder.",
			full = "Die wenigen Gebäude am Rand des Schattenhains liegen in Trümmern, und Worgen der Nachtheuler streifen über seine dunklen Felder. Sie errichten grobe Lager zwischen den Trümmern und greifen jeden an, der ihnen zu nahe kommt. Der Hain liegt direkt westlich von Dunkelhain. Er trägt den alten Namen des ganzen Waldes, der vor der Dunkelheit Schattenwald hieß.",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "Das dunkle Ufer",
			short = "Das dunkle Ufer zieht sich am Nordufer des Dämmerwalds entlang, vom äußersten Westrand nach Osten bis zur Brücke, die den Wald mit dem Rotkammgebirge verbindet.",
			full = "Das dunkle Ufer zieht sich am Nordufer des Dämmerwalds entlang, vom äußersten Westrand nach Osten bis zur Brücke, die den Wald mit dem Rotkammgebirge verbindet. An seinem westlichen Ende haben Flüchtlinge ein kleines Lager errichtet. Sven Yorgen lebt dort mit Lars, und Sven hat seine Frau und seine Kinder an die Dunklen Reiter des Gebirgspasses der Totenwinde verloren.",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "Dunkelhain",
			short = "Dunkelhain war einst ein malerisches kleines Walddorf namens Großweiler, im Schattenwald gelegen. Dann kam die Dunkelheit, und die Wälder wurden zu einer gefährlichen, dornigen Verseuchung.",
			full = "Dunkelhain war einst ein malerisches kleines Walddorf namens Großweiler, im Schattenwald gelegen. Dann kam die Dunkelheit, und die Wälder wurden zu einer gefährlichen, dornigen Verseuchung. Aus dem Schattenwald wurde der Dämmerwald, aus Großweiler wurde Dunkelhain. Auf den Friedhöfen drängen sich jetzt die wandelnden Toten, und Worgen haben viele der Gehöfte rund um die Stadt überrannt.\n\nStormwind zog alle Truppen aus dem Dämmerwald ab, nachdem König Varian Wrynn verschwunden war. Die Bürger bewaffneten sich stattdessen selbst. Ihre Miliz, die Nachtwache, wurde ganz von den Menschen des Waldes aufgestellt und ausgebildet, und Kommandantin Althea Ebonlocke führt sie. Ihre Wächter halten die Hauptstraße und die Stadt gegen Wölfe und wandelnde Leichen.\n\nDie Menschen von Dunkelhain sind schreckhaft und misstrauisch, und sie brauchen jede Hilfe, die sie bekommen können.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "Katakomben des Morgenwaldes",
			short = "Unter dem Friedhof von Rabenflucht liegen verwinkelte Katakomben, in denen die mächtigsten Untoten der Gegend hausen. Es gibt zwei Eingänge.",
			full = "Unter dem Friedhof von Rabenflucht liegen verwinkelte Katakomben, in denen die mächtigsten Untoten der Gegend hausen. Es gibt zwei Eingänge. Der östliche führt in eine Höhle voller Ghule, krank und wild. Der westliche führt in eine Halle voller Skelette, die die Gräber ihrer früheren Brüder bewachen.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "Das verlassene Gut",
			short = "Das verlassene Gut ist ein Hügel am Nordrand des Friedhofs von Rabenflucht, in eine Dunkelheit gehüllt, die schwerer ist als der Schatten des Waldes ringsum.",
			full = "Das verlassene Gut ist ein Hügel am Nordrand des Friedhofs von Rabenflucht, in eine Dunkelheit gehüllt, die schwerer ist als der Schatten des Waldes ringsum. Der Nekromant Morbent Teufel hat sein Zuhause auf seiner Kuppe. Er beherrscht die Untoten des Dämmerwalds durch böse arkane Magie, und ein magischer Schild wehrt Angriffe auf ihn ab.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "Das stille Ufer",
			short = "Das stille Ufer folgt dem westlichen Fluss des Dämmerwalds nach Süden, ab dem Punkt, an dem Westfall, der Wald von Elwynn und der Dämmerwald zusammentreffen, hinunter Richtung Schlingendorntal.",
			full = "Das stille Ufer folgt dem westlichen Fluss des Dämmerwalds nach Süden, ab dem Punkt, an dem Westfall, der Wald von Elwynn und der Dämmerwald zusammentreffen, hinunter Richtung Schlingendorntal. Eine überdachte Brücke führt hier über den Fluss und verbindet den Dämmerwald mit Westfall. Spinnen und Wölfe streifen zwischen den Bäumen, und Sven Yorgen und Lars haben an seinem nördlichen Ende ein Lager.",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "Anwesen der Mistmantles",
			short = "Stalvan Mistmantle war einst Lehrer und Hauslehrer.",
			full = "Stalvan Mistmantle war einst Lehrer und Hauslehrer. Er zog sich auf sein Anwesen im Nordosten des Dämmerwalds zurück und blieb dort, bis die Dunkelheit in ihn kroch, einsam und wahnsinnig, hungrig nach Rache an jedem, der sich näherte. Jetzt wandelt er als Untoter, und seine Ghule schlurfen über das verrottete Gelände. Der Garten ist verfallen. Eine einzelne Blume wächst noch darin, die Träne von Tilloa, das einzige Lebenszeichen auf dem Anwesen.",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "Rabenflucht",
			short = "Die Häuser von Rabenflucht stehen leer im Westen des Dämmerwalds, der Fäulnis und der Dunkelheit überlassen. Fast niemand ist mehr da.",
			full = "Die Häuser von Rabenflucht stehen leer im Westen des Dämmerwalds, der Fäulnis und der Dunkelheit überlassen. Fast niemand ist mehr da. Bibbers, ein verängstigter Mann, versteckt sich hier vor seiner dunklen Vergangenheit, und ein Goblin namens Bliztik hält sich im obersten Stock eines der Gebäude verborgen. Die Unsichtbaren suchen den Rest der Stadt heim und ziehen durch ihre leeren Räume.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "Friedhof von Rabenflucht",
			short = "Der Friedhof wuchs erst weit über seine alten Grenzen hinaus, nachdem die Dunkelheit über den Dämmerwald gekommen war.",
			full = "Der Friedhof wuchs erst weit über seine alten Grenzen hinaus, nachdem die Dunkelheit über den Dämmerwald gekommen war. Untote gehen zwischen seinen Steinen um, dazu riesige Spinnen und Banden von Grabräubern, die jeden angreifen, der sie bei ihrer Arbeit stört.\n\nMorgan Ladimore zog in den Dritten Krieg und kam heim, um zu finden, dass seine Frau Lys und zwei seiner Kinder bereits in ihren Gräbern lagen. Der Kummer nahm ihm den Verstand. Er erschlug mehrere der Friedhofswärter und nahm sich, als er wieder zu sich kam, das Leben. Er wurde in aller Stille begraben, und einige Tage später lag das Grab offen und leer. Als Mor'Ladim geht er noch immer über das Gelände, und den Unvorsichtigen, die ihm begegnen, droht der Tod.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "Rolands Verdammnis",
			short = "Die Nachtelfenpriesterin Velinde Sternensang trug die Sense von Elune in den Dämmerwald. Sie starb in dieser Mine, und die Sense blieb hier liegen.",
			full = "Die Nachtelfenpriesterin Velinde Sternensang trug die Sense von Elune in den Dämmerwald. Sie starb in dieser Mine, und die Sense blieb hier liegen. Später ging ein Trupp Männer in die Schächte, um die Quelle der Dunkelheit zu finden. Einer von ihnen, ein Mann namens Bibbers, nahm die Sense auf. Sofort füllten Worgen die Mine und rissen die anderen Männer in Stücke, und Bibbers floh mit der Waffe.\n\nDie Mine wird jetzt von Bauchreißer und Nefaru vom Rudel der Nachtheuler gehalten, die die Worgen der Wälder anführen.",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "Der verlassene Obstgarten",
			short = "Worgen vom Rudel der Nachtheuler haben den verlassenen Obstgarten im Süden des Dämmerwalds besetzt. Sie errichten Lager zwischen den baufälligen Gebäuden.",
			full = "Worgen vom Rudel der Nachtheuler haben den verlassenen Obstgarten im Süden des Dämmerwalds besetzt. Sie errichten Lager zwischen den baufälligen Gebäuden. Schattenwirker der Nachtheuler üben dort ihre Magie aus, und Schleicher der Nachtheuler halten in den Schatten Wache.",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "Der Friedhof \"Stille Gärten\"",
			short = "Nichts am Friedhof „Stille Gärten“ ist noch still. Er liegt südöstlich von Dunkelhain, und seine Toten ruhen nicht, obwohl sie schwächer sind als die Untoten anderswo im Dämmerwald.",
			full = "Nichts am Friedhof „Stille Gärten“ ist noch still. Er liegt südöstlich von Dunkelhain, und seine Toten ruhen nicht, obwohl sie schwächer sind als die Untoten anderswo im Dämmerwald. Sie wandern zwischen den Grabsteinen und der ruinierten Kirche umher. Der Irrsinnige Ghul geht auf dem Gelände um, mal in der Kirche, mal draußen. Das Haus der blinden Mary steht direkt nördlich.",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "Der Zwielichtshain",
			short = "Ein uralter, längst erloschener Vulkankrater liegt im Zentrum des Dämmerwalds und wimmelt von Leben. Das Zwielicht hier ist anders als die Dunkelheit im übrigen Wald.",
			full = "Ein uralter, längst erloschener Vulkankrater liegt im Zentrum des Dämmerwalds und wimmelt von Leben. Das Zwielicht hier ist anders als die Dunkelheit im übrigen Wald. Ein großer namenloser Baum steht in seinem Herzen neben einem Mondbrunnen und einem alten Pavillon der Nachtelfen. Unter seinen Zweigen liegt eines von nur vier Portalen in den Smaragdgrünen Traum, und der Einfluss der schlafenden Druiden zeigt sich im Land ringsum.\n\nVier große Drachen bewachen das Portal. Sie waren einst stolze Leutnants von Ysera, Aspekt der Träume, und Beschützer des Traums. Der Smaragdgrüne Alptraum hat sie verderbt, und nun suchen sie nur noch Zerstörung und Tod.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "Ogerhort Vul'Gol",
			short = "Oger der Splitterfäuste haben ein kleines Becken im Süden des Dämmerwalds überrannt, südwestlich der Gabelung der Hauptstraße. Der Ogerhort trägt den Namen ihres Anführers Zzarc'Vul.",
			full = "Oger der Splitterfäuste haben ein kleines Becken im Süden des Dämmerwalds überrannt, südwestlich der Gabelung der Hauptstraße. Der Ogerhort trägt den Namen ihres Anführers Zzarc'Vul. Hier lebten einst Menschen, wie die zerfallenen Bauernhäuser zeigen. In der Höhle fressen die Oger die Kadaver von Schwarzbären, und sie schleppten eine Kiste mit kostbaren Werkzeugen und Kräutern fort, nachdem sie den Nekromanten Calvinius angegriffen hatten.",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "Yorgens Bauernhof",
			short = "Sven Yorgen bewirtschaftete einst dieses Land im Süden des Dämmerwalds.",
			full = "Sven Yorgen bewirtschaftete einst dieses Land im Süden des Dämmerwalds. Dunkle Reiter aus dem Gebirgspass der Totenwinde, von der Sense von Elune angezogen, töteten seine Familie, während ein verängstigter Mann namens Bibbers aus seinem Versteck zusah. Der Hof ist jetzt verlassen, seine Felder verrottet, und Sven hält sich in einem kleinen Lager am dunklen Ufer auf.\n\nDie Bruderschaft der Defias hält das Gehöft. Ihre Assassinen ziehen ungesehen über die Felder.",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- Loch Modan: 15 subzones
	[1432] = {
		["algaz station"] = {
			name = "Station Algaz",
			short = "Viele zwergische Gebirgsjäger sind an diesem Außenposten stationiert, direkt östlich des Nordtorpasses. Er liegt südlich von Dun Algaz, der Festung im Pass, und ist nach ihr benannt.",
			full = "Viele zwergische Gebirgsjäger sind an diesem Außenposten stationiert, direkt östlich des Nordtorpasses. Er liegt südlich von Dun Algaz, der Festung im Pass, und ist nach ihr benannt.",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "Der Tunnel durch Dun Algaz ist älter als der Krieg der Drei Hämmer. Als dieser Krieg die Wildhammer-Zwerge aus Ironforge vertrieb, zogen sie hier hindurch.",
			full = "Der Tunnel durch Dun Algaz ist älter als der Krieg der Drei Hämmer. Als dieser Krieg die Wildhammer-Zwerge aus Ironforge vertrieb, zogen sie hier hindurch.\n\nAuch die Horde zog sich auf diesem Weg zurück. Im Zweiten Krieg bei Dun Modr zurückgeschlagen, zogen sich die Orcs nach Süden über das Thandoltal zurück und verschanzten sich im Außenposten hier. Anduin Lothar, der sie ganz aus Khaz Modan vertreiben wollte, schickte seine Truppen, um die Festung niederzureißen. Der Angriff scheiterte. Die Orcs hielten durch, und Dun Algaz wurde zum letzten Boden, den die Horde in der Gegend behielt.\n\nDie zwergischen Gebirgsjäger, die diesen Pass bewachen, hielten sich meist in den Hügeln darüber auf, doch der Dragonmawklan hat ihren Posten überrannt und sie in den oberen Tunnel zurückgedrängt. Mit dem verlorenen unteren Pass ist die Straße zwischen den Heimatländern der Zwerge und dem Hafen von Menethil weit gefährlicher geworden.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "Die Weitschreiter-Lodge",
			short = "Die Weitschreiter-Lodge steht in den südöstlichen Hügeln von Loch Modan, ein Jagdhaus, dessen Mauerwerk eindeutig hochelfisch ist. Man kennt nur einen einzigen Hochelfen, der dort heute lebt.",
			full = "Die Weitschreiter-Lodge steht in den südöstlichen Hügeln von Loch Modan, ein Jagdhaus, dessen Mauerwerk eindeutig hochelfisch ist. Man kennt nur einen einzigen Hochelfen, der dort heute lebt. Menschen und Zwerge, darunter Jäger, sind inzwischen in seine elfischen Mauern gezogen.",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
		},
		["grizzlepaw ridge"] = {
			name = "Grizzlepaw-Grat",
			short = "Der Grizzlepaw-Grat erhebt sich südlich von Thelsamar, voller Bären, die die Höhen zu ihrem Revier gemacht haben.",
			full = "Der Grizzlepaw-Grat erhebt sich südlich von Thelsamar, voller Bären, die die Höhen zu ihrem Revier gemacht haben. Allen voran steht Alte Rußtatze, ein schwarzer Bär von furchterregender Größe und Laune, der an den Hängen einen Bau hat. Hin und wieder streift er hinunter zum Grund des Tals und fällt jeden an, der Pech genug hat, ihn zu reizen.",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "Ironbands Ausgrabungsstätte",
			short = "Ausgrabungsleiter Ironband leitet hier, im südöstlichen Winkel von Loch Modan, eine Ausgrabung uralter Ruinen. Wie die anderen Grabungen der Zwerge wurde sie überfallen, und die Schürfer und Bergleute wurden vertrieben.",
			full = "Ausgrabungsleiter Ironband leitet hier, im südöstlichen Winkel von Loch Modan, eine Ausgrabung uralter Ruinen. Wie die anderen Grabungen der Zwerge wurde sie überfallen, und die Schürfer und Bergleute wurden vertrieben. Die Eindringlinge sind Troggs einer besonders großen und unberechenbaren Art.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
		},
		["loch"] = {
			name = "Der Loch",
			short = "Kein anderer See auf Khaz Modan reicht an den Loch heran. Nur der Lordameresee und der Darrowmeresee sind irgendwo in der bekannten Welt größer.",
			full = "Kein anderer See auf Khaz Modan reicht an den Loch heran. Nur der Lordameresee und der Darrowmeresee sind irgendwo in der bekannten Welt größer.",
			source = "https://warcraft.wiki.gg/wiki/The_Loch",
		},
		["mogrosh stronghold"] = {
			name = "Festung Mo'grosh",
			short = "Ein Ogerstamm, die Mo'grosh, hält die Höhlen der nordöstlichen Hügel. Chok'sul, der als ihr Anführer gilt, hat Angriffe auf Thelsamar, den Stonewroughtdamm und die Grabungen der Zwerge koordiniert.",
			full = "Ein Ogerstamm, die Mo'grosh, hält die Höhlen der nordöstlichen Hügel. Chok'sul, der als ihr Anführer gilt, hat Angriffe auf Thelsamar, den Stonewroughtdamm und die Grabungen der Zwerge koordiniert. Eine Bande überfiel eine zwergische Karawane aus dem Sumpfland und ließ niemanden am Leben außer einer tödlich verwundeten Wache.",
			source = "https://warcraft.wiki.gg/wiki/Mo'grosh_Stronghold",
		},
		["north gate pass"] = {
			name = "Nordtorpass",
			short = "Der Pass verläuft zwischen den hohen Bergen von Dun Morogh im Westen und den niedrigeren Bergen von Loch Modan im Osten.",
			full = "Der Pass verläuft zwischen den hohen Bergen von Dun Morogh im Westen und den niedrigeren Bergen von Loch Modan im Osten. In seiner Mitte steht der Nordtoraußenposten, die nordöstlichste Siedlung, die die Zwerge in Dun Morogh errichtet haben.\n\nDie Gebirgsjäger hier haben alle Hände voll zu tun, das Wild von den Mauern zurückzudrängen. Einige Zwerge sind in den Bergen verschwunden, als sie nach den wilderen Bestien suchten.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "Silberbachmine",
			short = "Aus dieser Mine kam einst reichlich Silber, das an die Zwerge von Ironforge ging. Die Ader versiegte vor langer Zeit, und die Minenarbeiterliga machte aus den Stollen ein Lagerdepot.",
			full = "Aus dieser Mine kam einst reichlich Silber, das an die Zwerge von Ironforge ging. Die Ader versiegte vor langer Zeit, und die Minenarbeiterliga machte aus den Stollen ein Lagerdepot.\n\nDann zogen Kobolde der Tunnelratten ein, gierig nach dem, was die Mine noch birgt, und die Bergleute konnten ihre Ausrüstung nicht rechtzeitig herausholen. Die Gebirgsjäger wollen die Kobolde vertreiben, doch die Minenarbeiterliga fürchtet, dass die Ausrüstung im Kampf zerstört wird. Kisten mit aufgeladenen Rissedelsteinen, wie man sie zur Herstellung von Magierroben verwendet, lagern noch im Inneren. Hinter der Mine liegen die zerstörten Wagen und Katapulte der Orcs.",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate pass"] = {
			name = "Südtorpass",
			short = "Auf halbem Weg durch den Pass steht ein zwergischer Außenposten, und seine Gebirgsjäger haben die meisten Wildtiere vertrieben, die ihn früher bedrängten.",
			full = "Auf halbem Weg durch den Pass steht ein zwergischer Außenposten, und seine Gebirgsjäger haben die meisten Wildtiere vertrieben, die ihn früher bedrängten. Hier liegt Schnee auf dem Boden, wie in den Bergen im Westen.\n\nDer Pass ist der nächste Weg hinab zur Zwergenstadt Thelsamar.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "Splittersteintal",
			short = "Das Splittersteintal war einst ein unberührter Ort, eingebettet in die Berge im Südwesten von Loch Modan. Jetzt wimmelt es von feindlichen Splittersteintroggs.",
			full = "Das Splittersteintal war einst ein unberührter Ort, eingebettet in die Berge im Südwesten von Loch Modan. Jetzt wimmelt es von feindlichen Splittersteintroggs.\n\nDie Zwerge sind überzeugt, dass der Vorstoß des Stammes in ihre Länder von einem Trogg namens Grawmug angeführt wird, der in der innersten Höhle lebt. Zwei Elitewachen, Knirscher und Muskelprotz, weichen nie von seiner Seite. Hauptmann Rugelfuß will ihn tot sehen.",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "Der Stonewroughtdamm",
			short = "Wenige, die den Stonewroughtdamm überqueren, wissen, dass ihn ein Dunkeleisenzwerg gebaut hat.",
			full = "Wenige, die den Stonewroughtdamm überqueren, wissen, dass ihn ein Dunkeleisenzwerg gebaut hat. Franclorn Forgewright, der große Architekt dieses Klans, leitete die Arbeiten und erfand die Stonewrought-Methode, nach der der Damm benannt ist.\n\nDer Damm erhebt sich östlich von Dun Algaz am Nordrand von Loch Modan, und das Wasser, das er zurückhält, hat die Größe des Sees mehr als verdoppelt. Der Klan der Dunkeleisenzwerge hat ihn zuletzt angegriffen, und die Zwerge von Ironforge haben ihre Wache verstärkt. Chefingenieur Hinderweir VII. beaufsichtigt ihn jetzt.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "Gasthof Zum Starkbier-Lager",
			short = "Der Gasthof Zum Starkbier-Lager steht in Thelsamar, sein Herd selten kalt.",
			full = "Der Gasthof Zum Starkbier-Lager steht in Thelsamar, sein Herd selten kalt. Zwerge und Reisende kommen hier gleichermaßen zusammen, um zu trinken und Neuigkeiten über den Loch auszutauschen, und wenige Orte in der Gegend ziehen so stetig Gäste durch die Tür.",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "Thelsamar",
			short = "Eine Zwergenstadt liegt am Westufer von Loch Modan, nördlich des Grizzlepaw-Grats und nordöstlich des Splittersteintals. Gebirgsjäger bewachen ihre Häuser.",
			full = "Eine Zwergenstadt liegt am Westufer von Loch Modan, nördlich des Grizzlepaw-Grats und nordöstlich des Splittersteintals. Gebirgsjäger bewachen ihre Häuser. Sie hat ein Gasthaus und eine Schmiede mit Amboss nahe ihrem südwestlichsten Haus.\n\nEine Nord-Süd-Straße verläuft direkt westlich der Stadt und führt zu den Pässen nach Dun Morogh und ins Sumpfland.",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["valley of kings"] = {
			name = "Tal der Könige",
			short = "Das Tal der Könige liegt im südwestlichen Ausläufer von Loch Modan, wo sich das grüne Land zum Tor hin verengt, das hinab in die geschwärzte Sengende Schlucht führt.",
			full = "Das Tal der Könige liegt im südwestlichen Ausläufer von Loch Modan, wo sich das grüne Land zum Tor hin verengt, das hinab in die geschwärzte Sengende Schlucht führt. Das Tor bleibt verschlossen und bewacht, und Gebirgsjägerin Pebblebitty hält es.\n\nZwei große Statuen ragen über dem Pass auf, König Madoran Bronzebeard und König Khardros Wildhammer. Als die beiden Könige starben, gaben ihre Söhne die Statuen gemeinsam zu Ehren ihrer Väter in Auftrag. Das Land im Süden war im Gefolge von Ragnaros vulkanisch geworden, und die Statuen halten Wache über die Straße dorthin. Sie sind eine Warnung an jeden, der die Zwergenreiche angreifen wollte, und eine Erinnerung an den Preis, den die Dunkeleisenzwerge für ihre Verbrechen zahlten.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- Rotkammgebirge: 16 subzones
	[1433] = {
		["althers mill"] = {
			name = "Althers Mühle",
			short = "Das Sägewerk nordöstlich von Seenhain ist verlassen. Es war immer ein Hinterland, ein Ort, durch den man auf dem Weg zur Burg Steinwacht kam.",
			full = "Das Sägewerk nordöstlich von Seenhain ist verlassen. Es war immer ein Hinterland, ein Ort, durch den man auf dem Weg zur Burg Steinwacht kam. Spinnen und Bussarde überrannten es, und jetzt halten es die Blackrockorcs und unterhalten hier einen großen Zwinger voller Worge unter Homurk und Murdunk.",
			source = "https://warcraft.wiki.gg/wiki/Alther's_Mill",
		},
		["galardell valley"] = {
			name = "Galardelltal",
			short = "Der Turm von Ilgalar steht im Galardelltal, im Nordosten des Rotkammgebirges. Großmagus Doane, ein dunkler Magier, der aus Stormwind verstoßen wurde, lebt dort.",
			full = "Der Turm von Ilgalar steht im Galardelltal, im Nordosten des Rotkammgebirges. Großmagus Doane, ein dunkler Magier, der aus Stormwind verstoßen wurde, lebt dort.\n\nDas Tal darunter wimmelt von den Schattenfell-Gnollen, die ihm dienen. Der stärkste ist General Fangor, der die Gnolle in der Nähe beim ersten Anzeichen von Eindringlingen an seine Seite ruft.",
			source = "https://warcraft.wiki.gg/wiki/Galardell_Valley",
		},
		["lake everstill"] = {
			name = "Der Immerruhsee",
			short = "Weit, klar und azurblau füllt der Immerruhsee die Mitte des Rotkammgebirges und bildet die Kulisse für die verschlafene Stadt Seenhain.",
			full = "Weit, klar und azurblau füllt der Immerruhsee die Mitte des Rotkammgebirges und bildet die Kulisse für die verschlafene Stadt Seenhain. Sein östlicher Fluss fließt an den dunklen Mauern der Burg Steinwacht vorbei.\n\nDer See war einst für seinen Fischfang bekannt. Murlocstämme haben ihn seither überrannt, und ein gewaltiger Drescher, der Seedrescher, patrouilliert in der Tiefe. Die Immerruhbrücke trägt die Straße über das Wasser.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Everstill",
		},
		["lakeridge highway"] = {
			name = "Uferpfad",
			short = "Auf dem Uferpfad am Südrand des Immerruhsees herrschte einst steter Verkehr, in den Tagen vor dem Ersten Krieg. Seit die Orcs die Burg Steinwacht nahmen, ist die alte Straße verwaist.",
			full = "Auf dem Uferpfad am Südrand des Immerruhsees herrschte einst steter Verkehr, in den Tagen vor dem Ersten Krieg. Seit die Orcs die Burg Steinwacht nahmen, ist die alte Straße verwaist. Gnolle patrouillieren auf dem größten Teil ihrer Länge, und nur wenige Reisende wagen sie.",
			source = "https://warcraft.wiki.gg/wiki/Lakeridge_Highway",
		},
		["lakeshire"] = {
			name = "Seenhain",
			short = "Seenhain liegt am Nordufer des Immerruhsees, und die Stadt hat für diesen Boden mehr als einmal geblutet.",
			full = "Seenhain liegt am Nordufer des Immerruhsees, und die Stadt hat für diesen Boden mehr als einmal geblutet. Im Ersten Krieg führte Kriegshäuptling Schwarzfaust einen Plünderertrupp in diese Berge, um die Stadt für die Horde zu nehmen. Anduin Lothar und die Ritter von Stormwind überfielen die Orcs von den Hängen und schlugen sie beinahe. Zwei Hexenmeister des Schattenrats wendeten den Kampf und trieben Lothar zurück. Schwarzfaust kehrte Wochen später mit einer größeren Streitmacht zurück und nahm die Stadt. Nach dem Zweiten Krieg eroberte die Allianz von Lordaeron sie zurück und baute sie wieder auf, und Oberbefehlshaber Turalyon überwachte die Rückkehr ihrer Bewohner.\n\nMagistrat Solomon führt Seenhain jetzt durch sein eigenes Gericht, und Marschall Marris befehligt die Wache. Gnolle und Blackrockorcs bedrängen die Stadt, und aus Stormwind kommt wenig Hilfe.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire",
		},
		["redridge canyons"] = {
			name = "Rotkammschlucht",
			short = "Die Schluchten schneiden sich durch den Nordwesten des Rotkammgebirges, und ihre Wände verbergen den Bau von Jauler, der die Gnolle anführt, die dieses Gebiet halten.",
			full = "Die Schluchten schneiden sich durch den Nordwesten des Rotkammgebirges, und ihre Wände verbergen den Bau von Jauler, der die Gnolle anführt, die dieses Gebiet halten.",
			source = "https://warcraft.wiki.gg/wiki/Redridge_Canyons",
		},
		["renders camp"] = {
			name = "Renders Lager",
			short = "Blackrockorcs halten einen Außenposten im Nordwesten des Rotkammgebirges, nahe dem Eingang zur Brennenden Steppe.",
			full = "Blackrockorcs halten einen Außenposten im Nordwesten des Rotkammgebirges, nahe dem Eingang zur Brennenden Steppe.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Camp",
		},
		["renders rock"] = {
			name = "Renders Fels",
			short = "Mächtige Blackrockorcs halten hier eine große Höhle, nahe der Brennenden Steppe, und Korporal Keeshan von der Armee von Stormwind liegt verwundet darin.",
			full = "Mächtige Blackrockorcs halten hier eine große Höhle, nahe der Brennenden Steppe, und Korporal Keeshan von der Armee von Stormwind liegt verwundet darin.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Rock",
		},
		["renders valley"] = {
			name = "Renders Tal",
			short = "Die Orcs dieses Tals im Südosten des Rotkammgebirges sind nicht so stark wie ihre Verwandten weiter im Nordwesten. Das Lager gehört trotzdem ihnen, ein Außenposten des Blackrockklans.",
			full = "Die Orcs dieses Tals im Südosten des Rotkammgebirges sind nicht so stark wie ihre Verwandten weiter im Nordwesten. Das Lager gehört trotzdem ihnen, ein Außenposten des Blackrockklans.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Valley",
		},
		["rethban caverns"] = {
			name = "Rethbanhöhlen",
			short = "Gnolle halten die tiefen Tunnel der Rethbanhöhlen im Nordwesten des Rotkammgebirges. Ihr Anführer, Ardo Schmutzpranke, ist ein gerissener Kerl.",
			full = "Gnolle halten die tiefen Tunnel der Rethbanhöhlen im Nordwesten des Rotkammgebirges. Ihr Anführer, Ardo Schmutzpranke, ist ein gerissener Kerl. Die Gnolle tragen Rethbanerz, das seinen Namen von Bart Rethban hat, dem ersten Menschen, der es fand. Die Höhlen wurden wohl auch nach ihm benannt.",
			source = "https://warcraft.wiki.gg/wiki/Rethban_Caverns",
		},
		["stonewatch"] = {
			name = "Steinwacht",
			short = "Die Menschen von Seenhain hielten Steinwacht als Festung gegen die Überfälle der Orcs, die aus der Brennenden Steppe herabkommen.",
			full = "Die Menschen von Seenhain hielten Steinwacht als Festung gegen die Überfälle der Orcs, die aus der Brennenden Steppe herabkommen. Sie hat eine leicht zu verteidigende Burg, daneben einen gepanzerten Turm und darunter Fälle, die die Felswand hinabstürzen.\n\nGroßmagus Doane schloss einen Handel mit dem Kriegsherrn Gath'Ilzogg vom Blackrockklan. Mit Doanes dunkler Magie im Rücken fielen die Orcs mit entsetzlicher Wildheit über die Burg her, schlugen das 12. Säbelregiment und nahmen die Festung.\n\nDas Bündnis hielt nicht. Doane wandte sich gegen die Orcs und errichtete einen eigenen Turm, in dem er ein Heer von Schattenfell-Gnollen aufbaute. Auf sich selbst gestellt, halten die Blackrockorcs Steinwacht noch immer.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "Steinwachtfälle",
			short = "Der östliche Fluss des Immerruhsees endet hier und stürzt den Hang unterhalb von Steinwacht hinab in einen tiefen See in der Nische der östlichen Berge.",
			full = "Der östliche Fluss des Immerruhsees endet hier und stürzt den Hang unterhalb von Steinwacht hinab in einen tiefen See in der Nische der östlichen Berge. Ein kleiner Stamm von Murlocs lebt an seinen Ufern. Sie fangen Fische im Wasser und bauen grobe Unterkünfte zum Schlafen.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "Burg Steinwacht",
			short = "Gath'Ilzogg, ein Kriegsherr des Blackrockklans, hält die Burg Steinwacht mit seinem vertrauten Leutnant Tharil'zun.",
			full = "Gath'Ilzogg, ein Kriegsherr des Blackrockklans, hält die Burg Steinwacht mit seinem vertrauten Leutnant Tharil'zun. Die Orcs nahmen die Burg den Menschen von Seenhain ab, und Gath'Ilzogg führt von dort Überfälle gegen die Stadt.\n\nBei den Kämpfen nahmen die Orcs Korporal Keeshan von der Armee von Stormwind gefangen und schleppten ihn in ihre Lager weiter im Norden. Magistrat Solomon hat ein Kopfgeld auf Gath'Ilzogg ausgesetzt, und Marschall Marris von Seenhain will, dass Tharil'zun für seine Untaten geradesteht.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "Turm der Steinwacht",
			short = "Neben der Burg steht der gepanzerte Spähturm von Steinwacht. Er gehörte einst den Menschen von Seenhain, wie die Burg.",
			full = "Neben der Burg steht der gepanzerte Spähturm von Steinwacht. Er gehörte einst den Menschen von Seenhain, wie die Burg. Jetzt wird er von Untergebenen Gath'Ilzoggs gehalten, Blackrockorcs, die von ihm aus die Festung bewachen, die ihr Klan eingenommen hat.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
		},
		["three corners"] = {
			name = "Drei Ecken",
			short = "Bei Drei Ecken teilt sich die Straße dreifach, Richtung der Drei Grafschaften. Eine Straße führt nach Goldhain im Wald von Elwynn, eine nach Seenhain und eine nach Dunkelhain im Dämmerwald.",
			full = "Bei Drei Ecken teilt sich die Straße dreifach, Richtung der Drei Grafschaften. Eine Straße führt nach Goldhain im Wald von Elwynn, eine nach Seenhain und eine nach Dunkelhain im Dämmerwald. Nur die Kreuzung markiert die Naht zwischen den drei Ländern. Ein einzelner Wachmann aus Stormwind, Wache Parker, bewacht sie, und Gnolle streifen auf den Straßen in der Nähe.",
			source = "https://warcraft.wiki.gg/wiki/Three_Corners",
		},
		["tower of ilgalar"] = {
			name = "Der Turm von Ilgalar",
			short = "Großmagus Doane studierte einst im Magierturm von Stormwind mit zwei anderen Magiern, bis er den dunklen Künsten verfiel.",
			full = "Großmagus Doane studierte einst im Magierturm von Stormwind mit zwei anderen Magiern, bis er den dunklen Künsten verfiel. Man drängte ihn, sich von dieser Magie abzuwenden, und er konnte es nicht, und er wurde aus dem Magierviertel verbannt. Er nahm ein mächtiges Buch mit, Urs Abhandlung über Schattenmagie, und es ist ihm nicht gelungen, die Siegel zu brechen, die die Magier von Stormwind darauf gelegt haben.\n\nJetzt lebt er im Turm von Ilgalar, im Nordosten des Rotkammgebirges, und setzt seine dunklen Studien fort. Drachenknochen hängen zur Schau im ganzen Turm, und ein Drachenschädel und ein Menschenschädel liegen oben auf dem Alchemietisch. Durch magische Anhänger befehligt er die Schattenfell-Gnolle, die Orcs und Menschen gleichermaßen niedergestreckt haben.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Ilgalar",
		},
	},
	-- Schlingendorntal: 38 subzones
	[1434] = {
		["baliamah ruins"] = {
			name = "Ruinen von Balia'mah",
			short = "Uraltes Trollmauerwerk steht hier am Ostufer des Flusses, und die Schädelspalter-Trolle haben sich darin niedergelassen. Der Ogerhügel der Mosh'Ogg liegt im Nordosten.",
			full = "Uraltes Trollmauerwerk steht hier am Ostufer des Flusses, und die Schädelspalter-Trolle haben sich darin niedergelassen. Der Ogerhügel der Mosh'Ogg liegt im Nordosten.",
			source = "https://warcraft.wiki.gg/wiki/Balia'mah_Ruins",
		},
		["ballal ruins"] = {
			name = "Ruinen von Bal'lal",
			short = "Von Bal'lal ist nur eine Reihe zerbrochener Säulen an der Nordwestküste übrig, dem finsteren Riff gegenüber.",
			full = "Von Bal'lal ist nur eine Reihe zerbrochener Säulen an der Nordwestküste übrig, dem finsteren Riff gegenüber. Die Trolle, die es errichteten, sind längst fort, und Blutskalp-Trolle leben jetzt zwischen den gefallenen Steinen.",
			source = "https://warcraft.wiki.gg/wiki/Bal'lal_Ruins",
		},
		["bloodsail compound"] = {
			name = "Truppenlager der Blutsegelbukaniere",
			short = "Die Blutsegelbukaniere, eine abtrünnige Bande von Seeleuten, unterhalten ein loses Lager an der Westküste des Schlingendorntals, in der Mitte der Küste.",
			full = "Die Blutsegelbukaniere, eine abtrünnige Bande von Seeleuten, unterhalten ein loses Lager an der Westküste des Schlingendorntals, in der Mitte der Küste. Hier wehen keine Banner der Ordnung, und es gibt keine Disziplin eines richtigen Hafens. Haudegen und Hexenmeister sammeln sich unter den Piraten.",
			source = "https://warcraft.wiki.gg/wiki/Bloodsail_Compound",
		},
		["booty bay"] = {
			name = "Booty Bay",
			short = "Besucher zu Fuß betreten Booty Bay durch die gebleichten Kiefer eines riesigen Hais. Dahinter klettert eine Hafenstadt die Klippen rund um eine blaue Lagune an der Südspitze des Schlingendorntals hinauf.",
			full = "Besucher zu Fuß betreten Booty Bay durch die gebleichten Kiefer eines riesigen Hais. Dahinter klettert eine Hafenstadt die Klippen rund um eine blaue Lagune an der Südspitze des Schlingendorntals hinauf. Das Leben ist hier billig, und niemandem ist zu trauen. Es ist ein Paradies für Gauner, voller Informanten.\n\nDer Ort war einst die Schwarzmeerbucht, ein kleiner menschlicher Hafen, bis Dschungeltrolle ihn überrannten. Goblins des Steamwheedle-Kartells vertrieben die Trolle von der Küste und machten die Bucht zu ihrem Einsatzzentrum in den Östlichen Königreichen. Das war vor dem Ersten Krieg.\n\nDie Schwarzmeerräuber führen den Hafen jetzt, in enger Gemeinschaft mit dem Kartell, und er dient jedem Reisenden, welchem Banner er auch folgt. Baron Revilgaz herrscht oben im Gasthaus, neben Flottenmeister Seehorn von den Räubern, und heuert jedes Schwert an, das er bekommen kann, gegen die Blutsegelbukaniere, die die Bucht bedrohen.",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
			name = "Kap des Schlingendorntals",
			short = "Der Süden des Schlingendorntals ist dicht von Trollruinen überzogen, halb vom Dschungel verschluckt, und von langen sandigen Küstenstreifen, wo die Bäume dem Meer weichen.",
			full = "Der Süden des Schlingendorntals ist dicht von Trollruinen überzogen, halb vom Dschungel verschluckt, und von langen sandigen Küstenstreifen, wo die Bäume dem Meer weichen. Dies ist der Boden eines langen Streits zwischen den Goblin-Piraten von Booty Bay und den Blutsegelbukanieren, ihren Rivalen. Die Goblins mühen sich, die Küste zu halten, und die Blutsegelbukaniere mühen sich, sie zu nehmen, und der Kampf wird mit der Zeit schlimmer.",
			source = "https://warcraft.wiki.gg/wiki/Cape_of_Stranglethorn",
		},
		["crystal shore"] = {
			name = "Das Kristallufer",
			short = "Die südlichen Meere brechen sich hier an einem langen Sandstrand, gegenüber den Ostküsten der Insel Jaguero.",
			full = "Die südlichen Meere brechen sich hier an einem langen Sandstrand, gegenüber den Ostküsten der Insel Jaguero. Ein steiler Grat riegelt den Strand vom Land dahinter ab, und nur zwei Pfade führen hindurch, einer davon hinauf Richtung Nebeltal. Am Nordende des Strandes stehen die Ruinen von Aboraz.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Shore",
		},
		["crystalvein mine"] = {
			name = "Kristalladermine",
			short = "Das Gestein der Kristalladermine bei Zul'Mamwe birgt seltsame Kristalle, die Crank Zischelbub Singende Kristalle nannte. Man findet sie nirgends außer im Schlingendorntal, und sie sind einiges wert.",
			full = "Das Gestein der Kristalladermine bei Zul'Mamwe birgt seltsame Kristalle, die Crank Zischelbub Singende Kristalle nannte. Man findet sie nirgends außer im Schlingendorntal, und sie sind einiges wert. Die Basilisken, die hier nisten, fressen sie, und davon wird ihre Haut hart. Die Venture Co. kam in der Hoffnung, die Mine auszubeuten, doch die Basilisken haben sie bisher aufgehalten. Vor dem Eingang stehen Trolle und Menschen kristallisiert da, wo sie erwischt wurden.",
			source = "https://warcraft.wiki.gg/wiki/Crystalvein_Mine",
		},
		["gromgol base camp"] = {
			name = "Das Basislager von Grom'gol",
			short = "Kommandant Aggro'gosh hält das Basislager von Grom'gol, ein Orcfort an der Südwestküste. Es ist stark befestigt gegen Dschungeltrolle, Naga aus der Brandung und die Männer der Allianz, die an der Küste entlangkommen.",
			full = "Kommandant Aggro'gosh hält das Basislager von Grom'gol, ein Orcfort an der Südwestküste. Es ist stark befestigt gegen Dschungeltrolle, Naga aus der Brandung und die Männer der Allianz, die an der Küste entlangkommen. Das Lager hält eine sichere Nachschubkette nach Stonard in den Sümpfen des Elends offen.",
			source = "https://warcraft.wiki.gg/wiki/Grom'gol_Base_Camp",
		},
		["gurubashi arena"] = {
			name = "Die Arena der Gurubashi",
			short = "In alter Zeit gingen die Kämpfe in der Arena der Gurubashi auf Leben und Tod, und der Sand wurde vom Trollblut zu Schlamm.",
			full = "In alter Zeit gingen die Kämpfe in der Arena der Gurubashi auf Leben und Tod, und der Sand wurde vom Trollblut zu Schlamm. Das Imperium der Gurubashi errichtete sie, als es über weite Teile des Südens der Östlichen Königreiche herrschte. Sie steht im Nordwesten des Kaps des Schlingendorntals, nördlich von Booty Bay, und hat das Imperium überdauert.\n\nStörtebrecher leitet jetzt Kämpfe, die weniger tödlich sind, mit Ruhm und Schätzen als Preis. Alle drei Stunden wirft ein Piratenkapitän zur Unterhaltung seiner Mannschaft eine Beutetruhe in die Mitte der Arena, und wer sie als Erster erreicht, behält, was darin ist. Alte Geschichten sagen, dass jeder, der um Mitternacht ein blutrotes Amulett findet, vor Tagesanbruch von einem Dämon seine Seele verschlingen lassen muss.",
			source = "https://warcraft.wiki.gg/wiki/Gurubashi_Arena",
		},
		["jaguero isle"] = {
			name = "Die Insel Jaguero",
			short = "Die Insel Jaguero liegt vor der Küste des Schlingendorntals, eine Dschungelinsel voller Panther und Gorillas. König Mukla, ein riesiger Affe, herrscht dort und hält Prinzessin Poobah, eine Tauren, gefangen.",
			full = "Die Insel Jaguero liegt vor der Küste des Schlingendorntals, eine Dschungelinsel voller Panther und Gorillas. König Mukla, ein riesiger Affe, herrscht dort und hält Prinzessin Poobah, eine Tauren, gefangen.",
			source = "https://warcraft.wiki.gg/wiki/Jaguero_Isle",
		},
		["janeiros point"] = {
			name = "Janeirospitze",
			short = "Auf dieser kleinen Insel vor Booty Bay steht eine riesige Statue eines Goblins, die Arme weit ausgebreitet. Niemand weiß, wessen Abbild sie ist.",
			full = "Auf dieser kleinen Insel vor Booty Bay steht eine riesige Statue eines Goblins, die Arme weit ausgebreitet. Niemand weiß, wessen Abbild sie ist. Sie wurde als Leuchtfeuer gebaut, um Schiffe im Hafen willkommen zu heißen. Der Meeresriese Mok'rash der Spalter hat die Insel zu seiner Heimat gemacht.",
			source = "https://warcraft.wiki.gg/wiki/Janeiro's_Point",
		},
		["kalai ruins"] = {
			name = "Ruinen von Kal'ai",
			short = "Die Ruinen von Kal'ai liegen halb vom Meer verschluckt im Schlingendorntal, uraltes Trollmauerwerk, von Gezeiten und Alter abgetragen.",
			full = "Die Ruinen von Kal'ai liegen halb vom Meer verschluckt im Schlingendorntal, uraltes Trollmauerwerk, von Gezeiten und Alter abgetragen. Der Stamm der Düsterkiemen, Murlocs, nistet jetzt zwischen den gefallenen Säulen und hat die versunkenen Hallen für sich beansprucht.",
			source = "https://warcraft.wiki.gg/wiki/Kal'ai_Ruins",
		},
		["kurzens compound"] = {
			name = "Kurzens Truppenlager",
			short = "Die Expedition von Oberst Conrad Kurzen errichtete diese ungewöhnliche menschliche Siedlung, östlich des Rebellenlagers, und sie hat ein Sägewerk.",
			full = "Die Expedition von Oberst Conrad Kurzen errichtete diese ungewöhnliche menschliche Siedlung, östlich des Rebellenlagers, und sie hat ein Sägewerk. Der Wahnsinn hat Kurzen ergriffen. Die Männer, die ihm nicht folgen wollten, trennten sich ab und gründeten das Rebellenlager, und die beiden Seiten stecken in einem tödlichen Kampf, Männer, die einst unter einem Befehl standen und sich zwischen den Bäumen töten.\n\nIn der Nähe der Ställe sitzen Panther und Schlingendorntiger in Käfigen, während die Männer sie zu Kriegsbestien abrichten.",
			source = "https://warcraft.wiki.gg/wiki/Kurzen's_Compound",
		},
		["lake nazferiti"] = {
			name = "Der Nazferitisee",
			short = "Ein großer Stützpunkt der Goblins der Venture Co. steht am Ufer des Nazferitisees. Frenzys und Krokilisken füllen das Wasser.",
			full = "Ein großer Stützpunkt der Goblins der Venture Co. steht am Ufer des Nazferitisees. Frenzys und Krokilisken füllen das Wasser.\n\nDer Nazferiti fließt durch den See, und er ist vielleicht der längste Fluss im südlichen Teil der Östlichen Königreiche. Seine Quelle ist ein Wasserfall im Rotkammgebirge, obwohl manche seinen Ursprung weiter entfernt im Gebirgspass der Totenwinde sehen.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Nazferiti",
		},
		["mistvale valley"] = {
			name = "Nebeltal",
			short = "Nebel legt sich tief über das Nebeltal, dicht genug, um die Linie der Baumkronen zu verwischen, im Süden des Schlingendorntals.",
			full = "Nebel legt sich tief über das Nebeltal, dicht genug, um die Linie der Baumkronen zu verwischen, im Süden des Schlingendorntals. Die großen Nebeltalgorillas leben hier, ziehen durch den Dunst zwischen den Bäumen, ungestörte Herrscher dieser stillen, feuchten Senke.",
			source = "https://warcraft.wiki.gg/wiki/Mistvale_Valley",
		},
		["mizjah ruins"] = {
			name = "Ruinen von Mizjah",
			short = "Die Ruinen von Mizjah liegen südöstlich des Basislagers von Grom'gol, gehalten von Schlägern der Mosh'Ogg und ihren Hexendoktoren.",
			full = "Die Ruinen von Mizjah liegen südöstlich des Basislagers von Grom'gol, gehalten von Schlägern der Mosh'Ogg und ihren Hexendoktoren. Von diesen zerbrochenen Steinen aus überfallen die Oger die Nachschubkarawanen nach Stonard.",
			source = "https://warcraft.wiki.gg/wiki/Mizjah_Ruins",
		},
		["moshogg ogre mound"] = {
			name = "Ogerhügel der Mosh'Ogg",
			short = "Der Ogerhügel der Mosh'Ogg liegt südlich von Zul'Gurub, seine dunklen Höhlungen die Heimat des Ogerstammes der Mosh'Ogg.",
			full = "Der Ogerhügel der Mosh'Ogg liegt südlich von Zul'Gurub, seine dunklen Höhlungen die Heimat des Ogerstammes der Mosh'Ogg. Tief darin hält ihr Anführer, der Ogermagier Mai'Zoth, ein mächtiges Relikt namens Geistiges Auge, und aus diesen Tiefen herrscht er heute über den Hügel.",
			source = "https://warcraft.wiki.gg/wiki/Mosh'Ogg_Ogre_Mound",
		},
		["nekmani wellspring"] = {
			name = "Nek'maniquellbrunnen",
			short = "Am Westrand des Schlingendorntals, hoch in den Klippen über der Südlichen ungezähmten Küste, entspringt eine heilige Quelle. Ihr Wasser ist das einzige saubere Süßwasser südlich des Dämmerwalds.",
			full = "Am Westrand des Schlingendorntals, hoch in den Klippen über der Südlichen ungezähmten Küste, entspringt eine heilige Quelle. Ihr Wasser ist das einzige saubere Süßwasser südlich des Dämmerwalds.\n\nGelehrte streiten darüber, denn jedes Volk behauptet, das Wasser sei für die eigenen Leute göttlich geworden, und keines hat die Streitfrage entschieden.",
			source = "https://warcraft.wiki.gg/wiki/Nek'mani_Wellspring",
		},
		["nesingwarys expedition"] = {
			name = "Nesingwarys Expedition",
			short = "Der Zwerg Hemet Nesingwary, ein Meisterjäger, führte eine Expedition ins Schlingendorntal, um das Wild zu jagen, das den Dschungel durchstreift.",
			full = "Der Zwerg Hemet Nesingwary, ein Meisterjäger, führte eine Expedition ins Schlingendorntal, um das Wild zu jagen, das den Dschungel durchstreift. Sein Lager liegt knapp unterhalb des Flusses, nördlich des Nazferitisees.\n\nAngeheuerte Söldner halten Wache. Sein Diener Barnil Steinkrug nennt ihn einen Kriegshelden der Allianz.",
			source = "https://warcraft.wiki.gg/wiki/Nesingwary's_Expedition",
		},
		["rebel camp"] = {
			name = "Rebellenlager",
			short = "Soldaten von Stormwind, die mit ihrem eigenen Oberst brachen, bauten dieses Lager. Es liegt im nördlichsten Teil des Schlingendorntals, westlich der Straße, die vom Dämmerwald nach Süden führt.",
			full = "Soldaten von Stormwind, die mit ihrem eigenen Oberst brachen, bauten dieses Lager. Es liegt im nördlichsten Teil des Schlingendorntals, westlich der Straße, die vom Dämmerwald nach Süden führt.\n\nOberst Conrad Kurzen führte eine Expedition aus Stormwind, und der Wahnsinn fiel über sie. Die meisten seiner Männer folgen ihm noch. Leutnant Doren und eine kleine Schar entkamen aus Kurzens Truppenlager, flohen nach Westen und richteten sich hier ein. Ihre Treue gilt weiter Stormwind, und Doren will Kurzens Kopf, um den Wahnsinn zu beenden. Krazek aus Booty Bay schickt ihnen Nachschub, darunter Landminen, zur Verteidigung gegen den Oberst und seine Männer.",
			source = "https://warcraft.wiki.gg/wiki/Rebel_Camp",
		},
		["ruins of aboraz"] = {
			name = "Ruinen von Aboraz",
			short = "Zanzil der Ausgestoßene hält diese uralten Trollruinen an der Südostküste des Schlingendorntals. Der Stamm der Schädelspalter verbannte ihn, weil er sein eigenes Volk vergiftet hatte.",
			full = "Zanzil der Ausgestoßene hält diese uralten Trollruinen an der Südostküste des Schlingendorntals. Der Stamm der Schädelspalter verbannte ihn, weil er sein eigenes Volk vergiftet hatte.\n\nHier braut er eine Mischung, die jeden, der sie trinkt, stark und geistesschwach macht. Sie hat Ghule, Naga und Trollhandlanger seinem Willen gebeugt. Unter seinen Sklaven ist Yenniku, ein Troll der Darkspear, den er gefangen nahm und dessen Körper und Geist Zanzil nun beherrscht.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Aboraz",
		},
		["ruins of jubuwal"] = {
			name = "Ruinen von Jubuwal",
			short = "Alte Trollruinen stehen direkt östlich der Arena der Gurubashi, neben der Hauptstraße, die der Länge nach durch das Schlingendorntal verläuft.",
			full = "Alte Trollruinen stehen direkt östlich der Arena der Gurubashi, neben der Hauptstraße, die der Länge nach durch das Schlingendorntal verläuft. Ghule, Naga und Trolle im Dienst von Zanzil dem Ausgestoßenen haben sie übernommen.\n\nZwei Männer sind unter ihnen, Jon-Jon die Krähe und Maury „Klumpfuß“ Wilkins, die dem skrupellosen Seewolf MacKinley Geld schulden.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Jubuwal",
		},
		["ruins of zulkunda"] = {
			name = "Ruinen von Zul'Kunda",
			short = "Der Stamm der Blutskalpe hält die weiten Dschungeltrollruinen von Zul'Kunda im Nordwesten des Schlingendorntals. Nezzliok der Düstere und Gan'zulah befehligen hier.",
			full = "Der Stamm der Blutskalpe hält die weiten Dschungeltrollruinen von Zul'Kunda im Nordwesten des Schlingendorntals. Nezzliok der Düstere und Gan'zulah befehligen hier.\n\nDie Blutskalpe lösten sich im Bürgerkrieg vom Imperium der Gurubashi. Sie wehren jeden Eindringling ab, auch die Schädelspalter, um das Land zu halten, das sie sich genommen haben. Sie haben nur Verachtung für den Stamm der Darkspear, die ersten Dschungeltrolle, die sich der Horde anschlossen.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Kunda",
		},
		["ruins of zulmamwe"] = {
			name = "Ruinen von Zul'Mamwe",
			short = "Berge schließen die Ruinen von Zul'Mamwe auf allen Seiten ein, außer im Norden.",
			full = "Berge schließen die Ruinen von Zul'Mamwe auf allen Seiten ein, außer im Norden. Hier lebt der Stamm der Schädelspalter, der zweite große Trollstamm des Schlingendorntals, unter seinem bösartigen Häuptling Ana'thek dem Grausamen.\n\nWie die Blutskalpe lösten sich die Schädelspalter im Bürgerkrieg vom Imperium der Gurubashi. Sie verachten den Stamm der Darkspear und wehren jeden Eindringling ab, die nahen Blutskalpe vor allem. Ihr Hexendoktor Mogh der Tote hat mehrere Männer aus der Expedition von Oberst Conrad Kurzen seinem Willen unterworfen und hält sie an seiner Seite.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Mamwe",
		},
		["savage coast"] = {
			name = "Die ungezähmte Küste",
			short = "Krokilisken füllen die Untiefen der ungezähmten Küste, und Basilisken leben an ihrem Ufer. Mehrere Trollsiedlungen stehen daneben.",
			full = "Krokilisken füllen die Untiefen der ungezähmten Küste, und Basilisken leben an ihrem Ufer. Mehrere Trollsiedlungen stehen daneben.\n\nSie nimmt die Nordküste des Schlingendorntals ein, von der Grenze zu Westfall nach Süden am finsteren Riff vorbei bis zum Basislager von Grom'gol.",
			source = "https://warcraft.wiki.gg/wiki/Savage_Coast",
		},
		["south seas"] = {
			name = "Die südlichen Meere",
			short = "Die südlichen Meere füllen das Wasser zwischen den bekannten Kontinenten, ein Teil des Großen Meeres. Zandalar erhebt sich aus diesen Wassern, die uralte Heimat des Trollreichs.",
			full = "Die südlichen Meere füllen das Wasser zwischen den bekannten Kontinenten, ein Teil des Großen Meeres. Zandalar erhebt sich aus diesen Wassern, die uralte Heimat des Trollreichs. Auch Kezan liegt in ihnen, eine Vulkaninsel, deren Volk sich von den Mächten des Festlands fernhält. Näher am Schlingendorntal wird das Meer tückisch mit Riffen und kleinen Inseln, manche nicht mehr als eine Sandbank, andere mit Ruinen, deren Erbauer verschwunden sind. Die südlichen Meere erstrecken sich entlang der Grenzen des Schlingendorntals und von Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southern savage coast"] = {
			name = "Südliche ungezähmte Küste",
			short = "Strände und flaches Wasser säumen die Westseite des Kaps des Schlingendorntals, wo die südlichen Meere auf die Küste treffen.",
			full = "Strände und flaches Wasser säumen die Westseite des Kaps des Schlingendorntals, wo die südlichen Meere auf die Küste treffen. Die Küste verläuft nach Süden an Booty Bay und der Janeirospitze vorbei bis zu den wilden Ufern.\n\nDas finstere Riff trennt sie von der ungezähmten Küste im Norden. Dort weicht das Große Meer den südlichen Meeren.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Savage_Coast",
		},
		["spirit den"] = {
			name = "Geisterhöhlenbau",
			short = "Ein Dschungeltroll, Hexendoktor Unbagwa, hält sich in einer versteckten Höhle am Nordende des Nebeltals auf. Das Tal rund um den Geisterhöhlenbau ist das Revier der großen Nebeltalgorillas.",
			full = "Ein Dschungeltroll, Hexendoktor Unbagwa, hält sich in einer versteckten Höhle am Nordende des Nebeltals auf. Das Tal rund um den Geisterhöhlenbau ist das Revier der großen Nebeltalgorillas.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Den",
		},
		["stockpile"] = {
			name = "Das Vorratslager",
			short = "Eine Höhle im hinteren Teil von Kurzens Truppenlager dient als Arsenal der Dschungelkämpfer von Oberst Conrad Kurzen, die hier ihre Waffen und Ausrüstung aufbewahren.",
			full = "Eine Höhle im hinteren Teil von Kurzens Truppenlager dient als Arsenal der Dschungelkämpfer von Oberst Conrad Kurzen, die hier ihre Waffen und Ausrüstung aufbewahren. Was auch immer im Kopf des Obersts schiefgelaufen ist, die meisten seiner Männer folgen ihm noch.",
			source = "https://warcraft.wiki.gg/wiki/Stockpile",
		},
		["tkashi ruins"] = {
			name = "Ruinen von Tkashi",
			short = "Zerbrochene Trollmauern stehen im Dschungel südwestlich von Nesingwarys Expedition. Eine große Schar von Blutskalp-Trollen lebt zwischen ihnen, und ihre Schamanen halten die alten Riten aufrecht.",
			full = "Zerbrochene Trollmauern stehen im Dschungel südwestlich von Nesingwarys Expedition. Eine große Schar von Blutskalp-Trollen lebt zwischen ihnen, und ihre Schamanen halten die alten Riten aufrecht. Artefakte dieses Schamanismus liegen über die Ruinen verstreut. Der Jäger Hemet Nesingwary schrieb, dass er und seine Gefolgsleute die Ruinen ohne Zwischenfall durchquert hätten.",
			source = "https://warcraft.wiki.gg/wiki/Tkashi_Ruins",
		},
		["venture co base camp"] = {
			name = "Stützpunkt der Venture Co.",
			short = "Goblins der Venture Co. haben am Nazferitisee ein Lager angelegt.",
			full = "Goblins der Venture Co. haben am Nazferitisee ein Lager angelegt. Holzfäller und Schredder bearbeiten das Dschungelholz, während Geologen die Hügel nach Kristallen durchgraben, die es nur im Schlingendorntal gibt und die bestimmte Käufer hoch schätzen.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Base_Camp",
		},
		["venture co operations center"] = {
			name = "Arbeitszentrale der Venture Co.",
			short = "Eine Ölplattform steht auf einem See im nördlichen Dschungel, errichtet von Goblins der Venture Co.",
			full = "Eine Ölplattform steht auf einem See im nördlichen Dschungel, errichtet von Goblins der Venture Co. Mechaniker und Geologen drängen sich auf der Bohrinsel, und die Mannschaften dringen von hier tiefer in den Dschungel vor. Ihr Halt an diesen abgelegenen Anlagen ist dünn. Die Dschungeltrolle sind darauf aus, ihre alten Länder von jedem fremden Eindringling zu säubern.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Operations_Center",
		},
		["vile reef"] = {
			name = "Das finstere Riff",
			short = "Vor der Westküste des Schlingendorntals, nahe dem Basislager von Grom'gol, bricht sich das Meer hell über Korallen.",
			full = "Vor der Westküste des Schlingendorntals, nahe dem Basislager von Grom'gol, bricht sich das Meer hell über Korallen. Darunter liegen versunkene Trollruinen, und zwischen diesem ertrunkenen Stein haben die Murlocs ihr Zuhause, ziehen durch Hallen, die einst jemand anderem gehörten. Der Altar der Gezeiten steht dort noch. Riesenmuscheln liegen auf dem Riffboden verstreut, und Gerüchten zufolge bergen sie blaue Perlen. Wrackteile von Schiffen spülen am Ufer an.",
			source = "https://warcraft.wiki.gg/wiki/Vile_Reef",
		},
		["wild shore"] = {
			name = "Die wilden Ufer",
			short = "An der südlichsten Küste der Östlichen Königreiche gibt das Land den südlichen Meeren nach.",
			full = "An der südlichsten Küste der Östlichen Königreiche gibt das Land den südlichen Meeren nach. Die Blutsegelbukaniere haben drei Schiffe vor dem Strand ankern lassen und westlich von Booty Bay einen Spähtrupp an Land gesetzt. Sie wollen Booty Bay plündern. Gorlash, ein Meeresriese, wandert über den Sand, und er bewahrt Schnupftabak in der Truhe von Kapitän Hecklebury Smotts auf, dessen Schiff die Riesen des Tals versenkt haben.\n\nDas Land endet in einer felsigen Landspitze an seinem Westrand, mit Booty Bay auf der Nordseite.",
			source = "https://warcraft.wiki.gg/wiki/Wild_Shore",
		},
		["yojamba isle"] = {
			name = "Die Insel Yojamba",
			short = "Kleine Inseln liegen vor der Nordwestküste des Schlingendorntals, nahe der Grenze zu Westfall, und der Stamm der Zandalari hat dort sein Lager aufgeschlagen.",
			full = "Kleine Inseln liegen vor der Nordwestküste des Schlingendorntals, nahe der Grenze zu Westfall, und der Stamm der Zandalari hat dort sein Lager aufgeschlagen. Hakkar der Seelenschinder, ein uralter Blutgott, hält Zul'Gurub und hat es zu einem Ort von Blut und Wahnsinn gemacht. Der Stamm kann ihn nicht allein niederringen, und die Trollstämme sind zersplittert. Also senden sie Nachricht an die Allianz und die Horde und bitten Champions aller Völker, ihren Krieg lange genug beiseitezulegen, um zu helfen.",
			source = "https://warcraft.wiki.gg/wiki/Yojamba_Isle",
		},
		["ziatajai ruins"] = {
			name = "Ruinen von Ziata'jai",
			short = "Trollruinen liegen hier im Dschungel, und der Stamm der Schädelspalter hält sie gegen jeden Eindringling, der sich nähert.",
			full = "Trollruinen liegen hier im Dschungel, und der Stamm der Schädelspalter hält sie gegen jeden Eindringling, der sich nähert.",
			source = "https://warcraft.wiki.gg/wiki/Ziata'jai_Ruins",
		},
		["zulgurub"] = {
			name = "Zul'Gurub",
			short = "Zul'Gurub erhebt sich aus dem Dschungel im Nordosten des Schlingendorntals, eine Tempelstadt aus von Ranken überwucherten Zikkurats und zugewachsenen Götzenbildern.",
			full = "Zul'Gurub erhebt sich aus dem Dschungel im Nordosten des Schlingendorntals, eine Tempelstadt aus von Ranken überwucherten Zikkurats und zugewachsenen Götzenbildern. Es war die Hauptstadt des Imperiums der Gurubashi, und jeder Dschungeltrollstamm unterstand ihr. Jetzt hält nur noch der Stamm der Gurubashi sie.\n\nLange bevor sich das Dunkle Portal öffnete, riss der Bürgerkrieg das Imperium auseinander. Ein Kreis von Priestern, die Atal'ai genannt wurden, beschwor den Avatar von Hakkar dem Seelenschinder, einem uralten Blutgott, und wurde ins Exil getrieben. Die Verbannten hatten erfahren, dass Hakkar nur in der alten Hauptstadt körperliche Gestalt annehmen konnte.\n\nJetzt weilt Hakkar in ihrem tiefsten Teil. Jin'do der Verhexer hat mehrere Hohepriester der Gurubashi versklavt, damit sie ihm dienen. Champions der Urgötter gingen hinein, um den Blutgott zu bezwingen, und fielen unter seinen Bann, und ihre Macht nährt ihn.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Gurub",
		},
		["zuuldaia ruins"] = {
			name = "Ruinen von Zuuldaia",
			short = "Blutskalp-Trolle leben in großer Zahl zwischen den uralten Ruinen am nördlichen Abschnitt der Westküste des Schlingendorntals. Sie vertreiben jeden Eindringling.",
			full = "Blutskalp-Trolle leben in großer Zahl zwischen den uralten Ruinen am nördlichen Abschnitt der Westküste des Schlingendorntals. Sie vertreiben jeden Eindringling.",
			source = "https://warcraft.wiki.gg/wiki/Zuuldaia_Ruins",
		},
	},
	-- Sümpfe des Elends: 14 subzones
	[1435] = {
		["fallow sanctuary"] = {
			name = "Das Fallow Heiligtum",
			short = "In diesem Dorf lebt ein Stamm, der einfach die Verirrten genannt wird. Es sind Draenei, die durch das Dunkle Portal kamen, und Heimweh hat sie wahnsinnig und wild gemacht.",
			full = "In diesem Dorf lebt ein Stamm, der einfach die Verirrten genannt wird. Es sind Draenei, die durch das Dunkle Portal kamen, und Heimweh hat sie wahnsinnig und wild gemacht. Sie greifen auf Sicht an, und sie schicken Assassinen und Saboteure gegen die Orcs.",
			source = "https://warcraft.wiki.gg/wiki/Fallow_Sanctuary",
		},
		["harborage"] = {
			name = "Der sichere Hafen",
			short = "Magtoor führt hier, im nördlichen Teil des Sumpfes, eine Handvoll Draenei an.",
			full = "Magtoor führt hier, im nördlichen Teil des Sumpfes, eine Handvoll Draenei an. Anders als die meisten ihrer Art bewahrten sie ihren Verstand, und sie erinnern sich an ihre edle Herkunft und leben abseits ihrer wahnsinnigen Verwandten. Magtoor hatte die grimmige Aufgabe, jene zu töten, die einst seine eigenen Brüder waren.\n\nDas Dorf verkehrt mit der Horde und der Allianz. Die Verirrten im Fallow Heiligtum liegen mit ihm im offenen Krieg, und Noboru und seine Bande ziehen durch den Sumpf und töten jeden, der ihren Weg kreuzt.",
			source = "https://warcraft.wiki.gg/wiki/Harborage",
		},
		["ithariuss cave"] = {
			name = "Itharius' Höhle",
			short = "Ein geheimnisvoller Hochelf namens Itharius lebt in dieser Höhle, im äußersten Südwesten des Sumpfes. Draußen auf dem Boden raufen und stolpern ungebärdige grüne Welpen, zu jung, um Flügel oder Feuer zu meistern.",
			full = "Ein geheimnisvoller Hochelf namens Itharius lebt in dieser Höhle, im äußersten Südwesten des Sumpfes. Draußen auf dem Boden raufen und stolpern ungebärdige grüne Welpen, zu jung, um Flügel oder Feuer zu meistern. Itharius hat es sich zur Aufgabe gemacht, über sie zu wachen, solange sie wachsen.",
			source = "https://warcraft.wiki.gg/wiki/Itharius's_Cave",
		},
		["misty reed post"] = {
			name = "Nebelschilfposten",
			short = "Tok'Kar hält diesen kleinen Außenposten für Stonard, mit Katar, ein paar Jägern und einem Schamanen aus der Stadt. Er liegt zwischen dem Stagalbog und dem Nebelschilfstrand.",
			full = "Tok'Kar hält diesen kleinen Außenposten für Stonard, mit Katar, ein paar Jägern und einem Schamanen aus der Stadt. Er liegt zwischen dem Stagalbog und dem Nebelschilfstrand. Es ist ein Lager ohne Erdbau und ohne Turm, und Tok'Kar träumt hier von einem Erdbau, oder wenigstens einem Turm.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Post",
		},
		["misty reed strand"] = {
			name = "Nebelschilfstrand",
			short = "Treibholz und Trümmer säumen diesen düsteren Küstenstreifen, mit wenig anderem entlang des weiten Strandes. Krokilisken und Krabben teilen sich das Ufer mit Murlocs.",
			full = "Treibholz und Trümmer säumen diesen düsteren Küstenstreifen, mit wenig anderem entlang des weiten Strandes. Krokilisken und Krabben teilen sich das Ufer mit Murlocs.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Strand",
		},
		["misty valley"] = {
			name = "Das neblige Tal",
			short = "Nebel hängt tief in diesem Tal im Nordwesten des Sumpfes, nördlich des Wegs in den Gebirgspass der Totenwinde, und Sumpfwandler und Wuchernde Schrecken drängen sich darin.",
			full = "Nebel hängt tief in diesem Tal im Nordwesten des Sumpfes, nördlich des Wegs in den Gebirgspass der Totenwinde, und Sumpfwandler und Wuchernde Schrecken drängen sich darin. Tief in einer Höhle im hinteren Teil lebt der Morastlord, eine Sumpfbestie.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Valley",
		},
		["pool of tears"] = {
			name = "Tränenteich",
			short = "Der Tränenteich liegt breit und still am Ostrand der Sümpfe des Elends.",
			full = "Der Tränenteich liegt breit und still am Ostrand der Sümpfe des Elends. Unter seiner ruhigen Oberfläche liegt der versunkene Trolltempel von Atal'Hakkar, und Mitglieder des grünen Drachenschwarms halten Wache über das Gelände in der Nähe und über die Ruine darunter.\n\nBlutrünstige Frenzys schwimmen im Wasser. Zerbrochenes Mauerwerk der Atal'ai liegt am Ufer und unter der Oberfläche.",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
		},
		["shifting mire"] = {
			name = "Der Wabersumpf",
			short = "Der feine Schlick des Wabersumpfes liegt nie still. Eine geheimnisvolle Kraft sammelt ihn zu Wehen und zieht ihn über den Boden, kräuselt und staut ihn, als wäre er lebendig.",
			full = "Der feine Schlick des Wabersumpfes liegt nie still. Eine geheimnisvolle Kraft sammelt ihn zu Wehen und zieht ihn über den Boden, kräuselt und staut ihn, als wäre er lebendig. Der Wabersumpf macht den zentralen Hauptteil des Sumpfgebiets aus, westlich des Tränenteichs. Krokilisken und Sumpfjaguare jagen darin, und Verirrte wandern hindurch.",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "Sorrowmurk",
			short = "Die grüne Drachenbrut kriecht hier durch den Morast, direkt östlich des Tränenteichs und des Tempels von Atal'Hakkar. Ein großer grüner Drache patrouilliert die Gegend.",
			full = "Die grüne Drachenbrut kriecht hier durch den Morast, direkt östlich des Tränenteichs und des Tempels von Atal'Hakkar. Ein großer grüner Drache patrouilliert die Gegend. Nur die mutigsten Reisenden gehen hinein.",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "Splitterspeerkreuzung",
			short = "Die Straße in den Sumpf gabelt sich hier. Ein Zweig führt nach Norden, der andere nach Süden Richtung Stonard. An der Gabelung steht ein alter Wachturm der Orcs, und Wachen der Horde patrouillieren an der Kreuzung.",
			full = "Die Straße in den Sumpf gabelt sich hier. Ein Zweig führt nach Norden, der andere nach Süden Richtung Stonard. An der Gabelung steht ein alter Wachturm der Orcs, und Wachen der Horde patrouillieren an der Kreuzung.",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "Stagalbog",
			short = "Dichtes Sumpfland liegt südlich des Tränenteichs, wo der Sumpf an die Berge stößt, die ihn im Süden einschließen. Am Rand der Berge öffnet sich eine Höhle in den Fels.",
			full = "Dichtes Sumpfland liegt südlich des Tränenteichs, wo der Sumpf an die Berge stößt, die ihn im Süden einschließen. Am Rand der Berge öffnet sich eine Höhle in den Fels.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog",
		},
		["stagalbog cave"] = {
			name = "Stagalboghöhle",
			short = "Viele Marschenmurlocs leben in dieser großen Höhle im östlichen Sumpfland, unter ihrem Anführer, dem Sumpfredner.",
			full = "Viele Marschenmurlocs leben in dieser großen Höhle im östlichen Sumpfland, unter ihrem Anführer, dem Sumpfredner.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
		},
		["stonard"] = {
			name = "Stonard",
			short = "Orcs der Alten Horde errichteten Stonard im Schwarzen Morast, kurz nachdem sich das Dunkle Portal zum ersten Mal geöffnet hatte.",
			full = "Orcs der Alten Horde errichteten Stonard im Schwarzen Morast, kurz nachdem sich das Dunkle Portal zum ersten Mal geöffnet hatte. Es ist eine der ältesten Orcsiedlungen auf Azeroth, und der Erste Krieg hat es schwer beschädigt. Nachdem Thrall das Kommando über die Horde übernommen hatte, bauten die Orcs es wieder auf.\n\nEs ist die einzige Stadt der Horde in den Sümpfen des Elends. Eine große Halle steht noch in seiner Mitte, eine Seltenheit unter den Orcsiedlungen, und zwei Erdbauten bewachen den Zugang. Patrouillen streifen von hier aus, und kleine Lager in der Nähe festigen den Halt der Horde in der Region. Der Sumpf ist für die Orcs noch weitgehend unkartiert, und sie schicken von hier Pfadfinder und Kartografen aus, um ihn zu erfassen. Forscher sind gekommen, um seine uralten magischen Artefakte und seine Pflanzen und Tiere zu studieren.",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "Der Tempel von Atal'Hakkar",
			short = "Vor mehr als tausend Jahren wurde das Imperium der Gurubashi von einem Bürgerkrieg zerrissen.",
			full = "Vor mehr als tausend Jahren wurde das Imperium der Gurubashi von einem Bürgerkrieg zerrissen. In seinem Zentrum standen die Atal'ai, Trollpriester, die den Blutgott Hakkar den Seelenschinder zurück in die Welt holen wollten. Sie wurden besiegt und vertrieben, und sie flohen nach Norden in die Sümpfe des Elends. Dort errichteten sie einen großen Tempel, um sein Kommen vorzubereiten.\n\nYsera die Träumerin, Aspekt des grünen Drachenschwarms, erfuhr von ihrem Plan und schmetterte den Tempel unter dem Sumpf nieder. Grüne Drachen bewachen die versunkenen Ruinen und lassen niemanden hinein oder heraus. Man glaubt, dass einige der fanatischen Atal'ai ihren Zorn überlebten und in den dunklen Dienst Hakkars zurückkehrten.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- Westfall: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "Alexstons Bauernhof",
			short = "Die Felder von Alexstons Bauernhof ernährten einst Familien, bevor die Bruderschaft der Defias das Land nahm.",
			full = "Die Felder von Alexstons Bauernhof ernährten einst Familien, bevor die Bruderschaft der Defias das Land nahm. Er ist einer von vielen Höfen im Norden und in der Mitte von Westfall, die die Bruderschaft jetzt hält, und mechanische Erntegolems durchstreifen seine Furchen und bewachen Reihen, die niemand mehr bepflanzt.\n\nBaros Alexston, ein Architekt im Dienst von Stormwind, bearbeitete diese Felder als Junge, bevor das Land, das ihn geprägt hatte, in andere Hände überging.",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["dagger hills"] = {
			name = "Die Dolchhügel",
			short = "Hinter Moonbrook zieht sich ein langer Hügelrücken durch den Süden von Westfall. Wenig lebt dort. Knöchelhauer, Pfadpirscher und Straßenräuber der Defias beobachten das Gelände.",
			full = "Hinter Moonbrook zieht sich ein langer Hügelrücken durch den Süden von Westfall. Wenig lebt dort. Knöchelhauer, Pfadpirscher und Straßenräuber der Defias beobachten das Gelände. Ein leutseliger Zwergenbrauer namens Grimbooze Donnerbräu hält sich in den Hügeln auf und spricht in Reimen, und der Ghul Leprithus steigt bekanntermaßen in der Nähe aus der Erde.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "Der Todesacker",
			short = "Hier stand einst ein Hof im Südosten von Westfall, nahe der Brücke in den Dämmerwald. Die Bruderschaft der Defias brannte ihn und die Felder ringsum nieder.",
			full = "Hier stand einst ein Hof im Südosten von Westfall, nahe der Brücke in den Dämmerwald. Die Bruderschaft der Defias brannte ihn und die Felder ringsum nieder. Kein Bauer geht jetzt über den Boden. Rauchende Ruinen bleiben, und Erntegolems durchstreifen die schwelenden Äcker.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "Die Todesminen",
			short = "Vor dem Ersten Krieg waren die Tunnel unter Moonbrook die größte Goldmine in den Ländern der Menschen. Der Erste Krieg leerte sie von Bergleuten, und danach blieben sie unberührt und galten als verflucht.",
			full = "Vor dem Ersten Krieg waren die Tunnel unter Moonbrook die größte Goldmine in den Ländern der Menschen. Der Erste Krieg leerte sie von Bergleuten, und danach blieben sie unberührt und galten als verflucht. Später arbeitete eine Mannschaft der Minenarbeiterliga unter Großknecht Distelklette in einem Teil der Tunnel. Die Bruderschaft der Defias griff sie bei der Arbeit an, ein Tunnel stürzte ein, und die Bergleute, die dort starben, wandeln als ruhelose Untote durch die Dunkelheit.\n\nDie Bruderschaft hat die Minen zu ihrem Hauptquartier gemacht. Edwin VanCleef baut mit Hilfe von Goblins auf dem Grund der Minen einen Koloss, ein Schiff, das Stormwind vom Meer aus zerstören soll.",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["demonts place"] = {
			name = "Demonts Heim",
			short = "Von Demonts Heim sind nur zerbrochenes Holz und überwucherte Felder übrig, westlich von Moonbrook. Einst ein arbeitendes Gehöft, wird es jetzt von Agenten der Defias besetzt, die es als ihr eigenes halten.",
			full = "Von Demonts Heim sind nur zerbrochenes Holz und überwucherte Felder übrig, westlich von Moonbrook. Einst ein arbeitendes Gehöft, wird es jetzt von Agenten der Defias besetzt, die es als ihr eigenes halten.",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "Die Staubebenen",
			short = "Das südliche Ende von Westfall ist trockener, offener Boden. Gnolle halten dort einige Lager und bedrohen jeden, der ihn durchquert.",
			full = "Das südliche Ende von Westfall ist trockener, offener Boden. Gnolle halten dort einige Lager und bedrohen jeden, der ihn durchquert. Am Ostrand steht ein alter Magierturm, jetzt eine Hochburg der Defias namens Klavens Turm, nach dem unberechenbaren Klaven Jagdruf, der ihn beherrscht. Die Bruderschaft nutzt ihn als Ausgangspunkt für ihre Überfälle.",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "Furlbrows Kürbishof",
			short = "Bauer Furlbrow und seine Frau Verna hatten hier einen Kürbishof, bis die Bruderschaft der Defias mit ihren mechanischen Erntegolems durch Westfall fegte und ihn nahm.",
			full = "Bauer Furlbrow und seine Frau Verna hatten hier einen Kürbishof, bis die Bruderschaft der Defias mit ihren mechanischen Erntegolems durch Westfall fegte und ihn nahm. Die Defias halten jetzt die Hofgebäude. Das Paar floh auf die Straße im Norden von Westfall und ließ seine Kürbisse zurück.",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "Der Goldküstensteinbruch",
			short = "Lange Zeit lieferten die Gruben des Goldküstensteinbruchs Stormwind Gold und Erz, bevor Westfall in Ruin fiel.",
			full = "Lange Zeit lieferten die Gruben des Goldküstensteinbruchs Stormwind Gold und Erz, bevor Westfall in Ruin fiel. Die Bruderschaft der Defias besitzt ihn jetzt, bearbeitet die Gruben unter ihrem eigenen Banner und patrouilliert im Gestein.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "Der Jangoschacht",
			short = "Kobolde besetzen jetzt die Schächte des Jangoschachts, und es heißt, dass die Bruderschaft der Defias Geschäfte mit ihnen macht. Die Mine war eine der wichtigsten Erzquellen in Westfall, und ihr Erz ging nach Stormwind.",
			full = "Kobolde besetzen jetzt die Schächte des Jangoschachts, und es heißt, dass die Bruderschaft der Defias Geschäfte mit ihnen macht. Die Mine war eine der wichtigsten Erzquellen in Westfall, und ihr Erz ging nach Stormwind.",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
		},
		["jansen stead"] = {
			name = "Jansens Siedlung",
			short = "Das nördlichste Gehöft in Westfall, Jansens Siedlung, steht nahe der Brücke in den Wald von Elwynn. Seine Besitzer wurden von der Bruderschaft der Defias vertrieben, deren Agenten und Erntegolems es jetzt kontrollieren.",
			full = "Das nördlichste Gehöft in Westfall, Jansens Siedlung, steht nahe der Brücke in den Wald von Elwynn. Seine Besitzer wurden von der Bruderschaft der Defias vertrieben, deren Agenten und Erntegolems es jetzt kontrollieren.",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "Longshore",
			short = "Die Küste von Westfall zieht sich lang und leer hin, einer der breitesten Strände in Azeroth.",
			full = "Die Küste von Westfall zieht sich lang und leer hin, einer der breitesten Strände in Azeroth. Murlocs ziehen in Schwärmen darüber, und unter ihnen schwimmt Old Murk-Eye, ein Wesen, das die Fischersleute der Küste fürchten gelernt haben. Draußen hinter der Brandung liegen die Wracks von Schiffen, darunter Zerstörer der Elfen, der Flut überlassen.\n\nAn der fernen Südwestküste steht der Hof von Daphne Stillbrunn. Die Bruderschaft der Defias hat ihn mehr als einmal angegriffen.",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "Molsens Hof",
			short = "Molsens Hof liegt unter den vielen Gehöften von Westfall, die die Bruderschaft der Defias hält.",
			full = "Molsens Hof liegt unter den vielen Gehöften von Westfall, die die Bruderschaft der Defias hält. Seine Reihen sind Rost und Maschinen überlassen, und die Erntegolems der Bruderschaft patrouillieren auf den Feldern und schlagen jeden nieder, der zu nah heranwandert.",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "Moonbrook",
			short = "Moonbrook war eine Bergbaustadt und der Mittelpunkt des Ackerlandes von Westfall, der Kornkammer des Königreichs. Bevor die Orcs kamen, machten die Goldvorkommen unter ihr ein Drittel der Schatzkammer von Stormwind aus.",
			full = "Moonbrook war eine Bergbaustadt und der Mittelpunkt des Ackerlandes von Westfall, der Kornkammer des Königreichs. Bevor die Orcs kamen, machten die Goldvorkommen unter ihr ein Drittel der Schatzkammer von Stormwind aus. Die Orcs machten sie im Ersten Krieg dem Erdboden gleich, eine der letzten Städte, die fielen, bevor sie die Burg Stormwind zerstörten, und sie wurde nach dem Zweiten Krieg wieder aufgebaut.\n\nDie Bruderschaft der Defias hält sie jetzt. Sie vertrieben die Einwohner, und nur wenige Defias bleiben über der Erde als Wachposten. Die übrigen leben unten, in den alten Bergwerkstunneln unter der Stadt.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "Saldeans Farm",
			short = "Bauer Saldean und seine Frau Salma haben sich geweigert zu gehen. Dies ist die einzige Farm in Westfall, die die Bruderschaft der Defias nie überrannte, obwohl Erntegolems der Bruderschaft über ihre Felder streifen.",
			full = "Bauer Saldean und seine Frau Salma haben sich geweigert zu gehen. Dies ist die einzige Farm in Westfall, die die Bruderschaft der Defias nie überrannte, obwohl Erntegolems der Bruderschaft über ihre Felder streifen. Das Bauernhaus ist seit Jahren eine Zwischenstation, und das Paar tut, was es kann, um seine Gäste am Leben zu halten.",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "Späherkuppe",
			short = "Die Späherkuppe liegt auf einer Anhöhe im Osten von Westfall. Ein Turm wacht auf der Spitze, und darunter am Hang liegen Häuschen, eine Schmiede, ein Gasthaus und ein Sägewerk.",
			full = "Die Späherkuppe liegt auf einer Anhöhe im Osten von Westfall. Ein Turm wacht auf der Spitze, und darunter am Hang liegen Häuschen, eine Schmiede, ein Gasthaus und ein Sägewerk. Die Volksmiliz von Gryan Stoutmantle hält den Hügel als letzte militärische Bastion der Region und ruft jeden zu sich, der bereit ist, gegen die Defias zu kämpfen. Stormwind gibt ihr wenig Hilfe.\n\nFlusspfoten-Gnolle und die Bruderschaft der Defias greifen beide den Hügel an.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "Stendels Tümpel",
			short = "Ein kleiner Teich liegt südwestlich der Späherkuppe. Gnolle umringen ihn, und ein paar alte Knochen und zwei Gräber liegen an seinem Rand, was darauf hindeutet, dass das Wasser nicht mehr trinkbar ist.",
			full = "Ein kleiner Teich liegt südwestlich der Späherkuppe. Gnolle umringen ihn, und ein paar alte Knochen und zwei Gräber liegen an seinem Rand, was darauf hindeutet, dass das Wasser nicht mehr trinkbar ist.",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "Der Leuchtturm von Westfall",
			short = "Der Leuchtturm steht vor der fernen Südküste von Westfall, und nachts kreist sein Strahl noch immer über das Wasser, obwohl die Hand, die ihn bedient, einem Toten gehört.",
			full = "Der Leuchtturm steht vor der fernen Südküste von Westfall, und nachts kreist sein Strahl noch immer über das Wasser, obwohl die Hand, die ihn bedient, einem Toten gehört. Der Geist von Kapitän Grayson hält das Licht. Zu Lebzeiten war er ein Piratenkapitän, dessen Schiff eines Nachts an den Felsen zerbrach, als der Leuchtturm dunkel war. Nach seinem Tod kam er zum Turm und sah, wie Old Murk-Eye die Familie des Leuchtturmwärters vertrieb.\n\nDie Familie kehrte zurück und entzündete die Flamme neu. Old Murk-Eye kam mit den Murlocs der Küste zurück, und diesmal starb die Familie vor Graysons Augen. Niemand ist mehr übrig, das Licht zu pflegen, außer ihm, und er hält draußen vor dem Turm Wache, damit kein anderes Schiff sein Ende findet.",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- Sumpfland: 26 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "Angerfang-Lager",
			short = "Das Angerfang-Lager breitet sich über das mittlere Sumpfland aus. Es ist das größte Lager, das der Dragonmawklan in der Region hält, und die Angerfang-Orcs leben darin.",
			full = "Das Angerfang-Lager breitet sich über das mittlere Sumpfland aus. Es ist das größte Lager, das der Dragonmawklan in der Region hält, und die Angerfang-Orcs leben darin. Nek'rosh Schädelbrecher, der Sohn von Nekros Schädelbrecher, befehligt sie und will das Lager zum Sammelplatz für einen Angriff auf den Hafen von Menethil machen. Für den Sturm hat er Katapulte bauen lassen.",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "Baradinbucht",
			short = "Das Wasser der Baradinbucht umspült die Küste, an der Khaz Modan auf Lordaeron trifft. Die Geschichte der Bucht liegt zerbrochen auf ihrem Grund.",
			full = "Das Wasser der Baradinbucht umspült die Küste, an der Khaz Modan auf Lordaeron trifft. Die Geschichte der Bucht liegt zerbrochen auf ihrem Grund. Die Flotte von Kul Tiras patrouillierte hier im und nach dem Zweiten Krieg regelmäßig, und ihre Dritte Flotte wurde in diesem Krieg vernichtet. Einige der Wracks liegen zerschmettert an der Küste des Sumpflands, andere sanken auf den dunklen Meeresgrund.\n\nMurlocs und Krokilisken treiben in den Untiefen. Krabben und Haie beherrschen das tiefere Wasser.",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "Schwarzkanalmarschen",
			short = "Raptoren haben ihre Nester überall in den Schwarzkanalmarschen im südwestlichen Sumpfland.",
			full = "Raptoren haben ihre Nester überall in den Schwarzkanalmarschen im südwestlichen Sumpfland. Die Straße zum Hafen von Menethil führt am Rand der Marschen entlang, und die hungrigeren Raptoren streifen bis dicht an den Straßenrand.",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "Blaukiemenmarschen",
			short = "In den Marschen des westlichen Sumpflands stehen mehrere Lager der Murlocs der Blaukiemen. Die Murlocs hier ziehen in Gruppen von zwei oder drei umher, und Gobbler, der wildeste unter ihnen, führt sie an.",
			full = "In den Marschen des westlichen Sumpflands stehen mehrere Lager der Murlocs der Blaukiemen. Die Murlocs hier ziehen in Gruppen von zwei oder drei umher, und Gobbler, der wildeste unter ihnen, führt sie an.",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "Deepwater Taverne",
			short = "In der Deepwater Taverne brechen oft Schlägereien aus, und Tapoke „Slim“ Jahn fängt viele davon an.",
			full = "In der Deepwater Taverne brechen oft Schlägereien aus, und Tapoke „Slim“ Jahn fängt viele davon an. Sie ist ein belebter Treffpunkt mitten im Hafen von Menethil, und im Schankraum herrscht dichtes Stimmengewirr durchreisender Seeleute. Stühle fliegen ebenso oft durch die Luft, wie Ale eingeschenkt wird.",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "Direforge Hill",
			short = "Dunkeleisenzwerge unterhalten auf Direforge Hill im nordöstlichen Sumpfland ein großes Lager. Der Hexenmeister Balgaras der Niederträchtige führt sie an.",
			full = "Dunkeleisenzwerge unterhalten auf Direforge Hill im nordöstlichen Sumpfland ein großes Lager. Der Hexenmeister Balgaras der Niederträchtige führt sie an.",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "Tore der Dragonmaw",
			short = "Vier gewaltige Tore versperren den gewundenen Pfad, der vom Sumpfland nach Grim Batol hinaufführt. Der rote Drachenschwarm bewacht sie unter dem mächtigen Drachkin Axtroz und hält den Weg gegen jeden, der sich nähert.",
			full = "Vier gewaltige Tore versperren den gewundenen Pfad, der vom Sumpfland nach Grim Batol hinaufführt. Der rote Drachenschwarm bewacht sie unter dem mächtigen Drachkin Axtroz und hält den Weg gegen jeden, der sich nähert. Vor den Toren, an der Straße, liegen die Überreste einer Orckarawane, die aus der Festung zu fliehen versuchte.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dragonmaw retreat"] = {
			name = "Die Zuflucht des Drachenmals",
			short = "Orcs der Dragonmaw halten hier ein Lager an der Straße. Unter ihnen stehen Seelenbinder, Infiltratoren und Rückeroberer, und sie schwören, dass Grim Batol wieder ihnen gehören wird.",
			full = "Orcs der Dragonmaw halten hier ein Lager an der Straße. Unter ihnen stehen Seelenbinder, Infiltratoren und Rückeroberer, und sie schwören, dass Grim Batol wieder ihnen gehören wird.",
			source = "",
		},
		["drunken dwarf"] = {
			name = "Zum Betrunkenen Zwerg",
			short = "Agriel Firebrew und die Zwerge bei ihr haben einen alten Ausguck, den ihr Königreich nicht mehr unterhalten wollte, in eine Taverne verwandelt, die sie seit etwas mehr als einem Jahr betreiben.",
			full = "Agriel Firebrew und die Zwerge bei ihr haben einen alten Ausguck, den ihr Königreich nicht mehr unterhalten wollte, in eine Taverne verwandelt, die sie seit etwas mehr als einem Jahr betreiben. Die Kunde hat sich verbreitet, und Händler und Kaufleute wollen ihre Gebräue in Agriels Regalen und ihr Dörrfleisch auf ihren Tellern sehen. Die Zwerge kümmern sich um ihre eigenen Angelegenheiten und lassen die Leute kommen, wie sie wollen.",
			source = "",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "Der Tunnel durch Dun Algaz ist älter als der Krieg der Drei Hämmer. Als dieser Krieg die Wildhammer-Zwerge aus Ironforge vertrieb, zogen sie hier hindurch.",
			full = "Der Tunnel durch Dun Algaz ist älter als der Krieg der Drei Hämmer. Als dieser Krieg die Wildhammer-Zwerge aus Ironforge vertrieb, zogen sie hier hindurch.\n\nAuch die Horde zog sich auf diesem Weg zurück. Im Zweiten Krieg von Dun Modr zurückgeschlagen, fielen die Orcs nach Süden über das Thandoltal hinweg und gruben sich im Außenposten hier ein. Anduin Lothar, der sie ganz aus Khaz Modan hinausdrängen wollte, schickte seine Truppen, um die Festung niederzureißen. Der Angriff scheiterte. Die Orcs hielten stand, und Dun Algaz wurde der letzte Boden, den die Horde in der Region behielt.\n\nDie Gebirgsjäger der Zwerge, die diesen Pass bewachen, hielten sich meist in den Hügeln darüber auf, doch der Dragonmawklan hat ihren Posten überrannt und sie in den oberen Tunnel zurückgedrängt. Seit der untere Pass verloren ist, ist die Straße zwischen den Heimatländern der Zwerge und dem Hafen von Menethil weit gefährlicher geworden.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "Dun Modr",
			short = "Wer die alte Zwergenstadt Dun Modr hält, gebietet über das Land ringsum, und sie hat oft den Besitzer gewechselt.",
			full = "Wer die alte Zwergenstadt Dun Modr hält, gebietet über das Land ringsum, und sie hat oft den Besitzer gewechselt. Im Zweiten Krieg errichtete die Horde neben ihren Ruinen einen Außenposten und nutzte ihn als Aufmarschgebiet, schlug Truppen der Allianz zurück und überfiel die nahen Bauernhöfe. Krieger aus Stromgarde belagerten den Ort und trieben die Orcs nach Süden, doch die Horde schlug zurück und nahm ihn wieder ein. Als Anduin Lothar die Horde über den Thandol-Übergang zurückdrängte, kam die Stadt wieder in die Hände der Allianz und blieb es auch nach dem Krieg.\n\nJetzt haben die Dunkeleisenzwerge sie. Während die Soldaten von Ironforge in Kriegen weit weg von zu Hause starben, verwüsteten die Dunkeleisenzwerge unter dem Hexenmeister Balgaras dem Niederträchtigen den Übergang, und das südliche Dun Modr fiel bald darauf. Eine Schmiede und ein Gasthaus mit einer Brauerei stehen noch zwischen den Trümmern.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["excavation site wetlands"] = {
			name = "Ausgrabungsstätte: Sumpfland",
			short = "Hier steht eine Zwergengrabungsstätte, und Orcs der Dragonmaw haben ihre Anlagen übernommen.",
			full = "Hier steht eine Zwergengrabungsstätte, und Orcs der Dragonmaw haben ihre Anlagen übernommen. Ihre Thaumaturgen beschwören Feuerelementare, ihre Saboteure tragen Bomben, und in einem Zelt zwischen den Grabungen liegt ein toter Zwerg.",
			source = "",
		},
		["green belt"] = {
			name = "Der grüne Gürtel",
			short = "Krokilisken, Sumpfbestien und Schleime füllen den grünen Gürtel im östlichen Sumpfland. Rethiel der Sumpfhüter, selbst eine Sumpfbestie, wacht hier über das Land.",
			full = "Krokilisken, Sumpfbestien und Schleime füllen den grünen Gürtel im östlichen Sumpfland. Rethiel der Sumpfhüter, selbst eine Sumpfbestie, wacht hier über das Land. Gnolle sind in den Sumpf vorgedrungen, und einige seiner geringeren Verwandten unter den Sumpfbestien wurden verderbt. Beides will er beendet sehen.\n\nIm Gürtel liegt eine zerstörte Karawane der Dragonmaw, in deren Trümmern rote Welpen hausen. Sie scheint zerbrochen zu sein, als die befreiten Drachen sich gegen den Klan wandten.",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "Grim Batol",
			short = "Die Mauern und Türme von Grim Batol ragen im östlichen Sumpfland einem stahlgrauen Himmel entgegen, doch der größte Teil der Festung liegt unter der Erde.",
			full = "Die Mauern und Türme von Grim Batol ragen im östlichen Sumpfland einem stahlgrauen Himmel entgegen, doch der größte Teil der Festung liegt unter der Erde. Die Wildhammer-Zwerge gründeten sie und lebten dort, bis im Krieg der Drei Hämmer ein Fluch auf sie fiel. Sie ließen sie leer zurück.\n\nIm Zweiten Krieg schickte Orgrim Schicksalshammer den Dragonmawklan, um die leere Festung einzunehmen. Sie hielten die Drachenkönigin Alexstrasza in ihren Tiefen gefangen und zwangen die roten Drachen, der Horde zu dienen. Ihre Herrschaft brach, als die Drachen befreit wurden und die Orcs verbrannten, die sie versklavt hatten.\n\nDie meisten glaubten, das Böse der Festung sei mit dem Klan gestorben. Die Zwerge spürten noch eine Dunkelheit im Berg und gingen fort. Nun hat Alexstrasza rote Drachkin um die Festung aufgestellt, und sie lassen niemanden ein.",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "Ironbeards Grabmal",
			short = "Über dem Friedhof von Ironbeards Grabmal steht die Statue eines Zwergs, die offenbar dem Abbild Ironbeards selbst nachempfunden ist.",
			full = "Über dem Friedhof von Ironbeards Grabmal steht die Statue eines Zwergs, die offenbar dem Abbild Ironbeards selbst nachempfunden ist. Die Gruft liegt knapp westlich der Straße nach Dun Modr im nördlichen Zentrum des Sumpflands. Schwarze, karmesinrote und ungeheuerliche Schleime haben sie entweiht, und die Toten ruhen nicht mehr in Frieden. Wer seine Toten bestatten will, kommt nicht mehr hierher.",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "Die verlorene Flotte",
			short = "Die Wellenherrin und die Unerschrockene liegen auf dem Meeresgrund der Baradinbucht, vor der Küste der nördlichen Blaukiemenmarschen.",
			full = "Die Wellenherrin und die Unerschrockene liegen auf dem Meeresgrund der Baradinbucht, vor der Küste der nördlichen Blaukiemenmarschen. Sie gehörten zur Dritten Flotte von Kul Tiras, die im Zweiten Krieg von Derek Proudmoore befehligt wurde, dem älteren Sohn von Großadmiral Daelin Proudmoore. In der Schlacht von Crestfall stürzten sich rote Drachen, die der Dragonmawklan versklavt hatte, auf die Flotte und setzten sie in Brand. Derek kletterte in den Ausguck, um seinen Vater zu warnen, und ein Drache tötete ihn dort. Sein Schiff sank kurz darauf. Nur Erster Maat Fitzsimmons von der Wellenherrin überlebte.\n\nDie Toten fanden keine Ruhe. Kapitän Halyndor von der Unerschrockenen hatte aus Gier tief in seinem Frachtraum eine geschwärzte Kugel versteckt, das Verfluchte Auge von Paleth. Sein Fluch hat die versunkenen Mannschaften an den Untod gebunden. Nur Erster Maat Snellig behielt seinen Verstand, und sein Geist wandert über die nahe Küste.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "Bucht von Menethil",
			short = "Krokilisken jeden Alters und jeder Größe drängen sich in der Bucht von Menethil, und Jäger erlegen sie wegen ihres feinen Leders.",
			full = "Krokilisken jeden Alters und jeder Größe drängen sich in der Bucht von Menethil, und Jäger erlegen sie wegen ihres feinen Leders. Die Bucht ist ein Arm der Baradinbucht zwischen dem Hafen von Menethil und den nördlichen Klippen von Dun Morogh. An ihrer Einfahrt ruht das Wrack des Fliegenden Fischadlers, eines Schiffs der Dritten Flotte von Kul Tiras.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "Der Hafen von Menethil",
			short = "Die Mauer fällt jedem zuerst auf, dicker Stein, aufgeworfen um eine Hafenstadt auf einer kleinen Insel vor der Westküste.",
			full = "Die Mauer fällt jedem zuerst auf, dicker Stein, aufgeworfen um eine Hafenstadt auf einer kleinen Insel vor der Westküste. Vier Türme ragen über ihr auf, und es gibt keinen Weg hinein außer der Brücke, dem Meer oder einem geheimen Pfad, der unterirdisch zum Festland führt. Seeleute, Reisende, Schmuggler und Piraten füllen ihre Straßen.\n\nDie Horde baute hier die erste Werft. Nach dem Ersten Krieg wählte Kriegshäuptling Orgrim Schicksalshammer diese Küste, um die Flotte zu bauen, die sein Heer an den Landverteidigungen Lordaerons vorbeitragen sollte, und die Orcs plünderten dafür Eisen und Holz aus den Zwergenminen von Khaz Modan. Als der Zweite Krieg zu Ende ging, nahm die Allianz den Ort ein und baute ihn als Hafenstadt wieder auf. Großadmiral Daelin Proudmoore nannte ihn Hafen von Menethil, nach König Terenas Menethil II. von Lordaeron. Raptoren aus den Hügeln fallen jetzt hin und wieder über die Stadt her, nie in großer Zahl.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "Burg Menethil",
			short = "Hauptmann Starkfaust befehligt die Miliz von Menethil von der Burg Menethil aus, deren vier Türme wie strenge Wächter über die Hafenstadt darunter wachen.",
			full = "Hauptmann Starkfaust befehligt die Miliz von Menethil von der Burg Menethil aus, deren vier Türme wie strenge Wächter über die Hafenstadt darunter wachen.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "Moosfellmoor",
			short = "Die Gnolle der Moosfelle halten dieses wassergetränkte Moor im östlichen Sumpfland, und ihre Lager sprenkeln den Boden.",
			full = "Die Gnolle der Moosfelle halten dieses wassergetränkte Moor im östlichen Sumpfland, und ihre Lager sprenkeln den Boden. Ihr bösartiger Anführer Knochennager befiehlt dem Stamm, jeden Fremden zu ergreifen, der im Sumpf gesehen wird, und ihn zu fressen.",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
		},
		["raptor ridge"] = {
			name = "Raptorgrat",
			short = "Raptoren hausen in großer Zahl am Raptorgrat im östlichen Sumpfland, knapp nordwestlich der gefährlichen Tore der Dragonmaw. Eine Höhle im Grat beherbergt die wilde Scharfzahnmatriarchin, die über ihre Brut wacht.",
			full = "Raptoren hausen in großer Zahl am Raptorgrat im östlichen Sumpfland, knapp nordwestlich der gefährlichen Tore der Dragonmaw. Eine Höhle im Grat beherbergt die wilde Scharfzahnmatriarchin, die über ihre Brut wacht.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
		},
		["saltspray glen"] = {
			name = "Salzgischtschlucht",
			short = "Wenn ein starker Wind von der Bucht weht, wirft das Meer seine Gischt bei der Salzgischtschlucht weit ins Landesinnere, und der Boden bleibt salzglatt zurück.",
			full = "Wenn ein starker Wind von der Bucht weht, wirft das Meer seine Gischt bei der Salzgischtschlucht weit ins Landesinnere, und der Boden bleibt salzglatt zurück. So kam die Schlucht zu ihrem Namen. Sie ist ein kleiner Streifen im nordwestlichen Sumpfland, im Norden und Westen offen zur Baradinbucht. Raptoren nisten hier dicht an dicht.",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["sundown marsh"] = {
			name = "Sonnenwendmarschen",
			short = "Der tiefste Teil des Sumpflands liegt im Nordwesten, in den Sonnenwendmarschen.",
			full = "Der tiefste Teil des Sumpflands liegt im Nordwesten, in den Sonnenwendmarschen. Hier steht die Schnellschaltstation, ein kleines Steinhaus mit einer Windmühle, in dem ein seltsames Paar namens Fradd Schnellschalt und Wenna Seidenbart wohnt. Sie verkaufen merkwürdige Dinge, die sie im Sumpf finden. Rings um sie ist der Sumpf voll aggressiver Krokilisken, Gnolle, Raptoren, Sumpfbestien und Schleime.",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "Thandol-Übergang",
			short = "Zwei große Steinbögen tragen die Straße über die Kluft zwischen dem Sumpfland und dem Arathihochland, eines der größten Bauwerke, die die Zwerge je vollendet haben.",
			full = "Zwei große Steinbögen tragen die Straße über die Kluft zwischen dem Sumpfland und dem Arathihochland, eines der größten Bauwerke, die die Zwerge je vollendet haben. Zwerge errichteten sie nach dem Krieg der Drei Hämmer, als Ironforge den Handel und die Bande zu seinen Wildhammer-Vettern in Aerie Peak erhalten wollte. Die Brücken dienten als Straße und als Sinnbild zwischen den beiden Zwergenreichen, und der Handel bereicherte beide. Die Familie Anvilmar bewacht den Übergang seit mindestens drei Generationen.\n\nNun sind die Brücken vernarbt. Die Dunkeleisenzwerge schlugen unter Kam Tiefenzorn und Balgaras dem Niederträchtigen zu, und ein Bogen wurde fast zerstört. Zwergentruppen kämpften erbittert, um den anderen zu verteidigen und die nahe Stadt Dun Modr zurückzuerobern, und viele starben, unter ihnen Sully Balloo, Ebenezer Rustlocke und der Bruder von Longbraid dem Grimmigen.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "Thelgenfelsen",
			short = "Eine große Höhle zieht sich tief in die Berge des südlichen Sumpflands, und der Ort hat von ihr seinen Namen, Thelgenfelsen.",
			full = "Eine große Höhle zieht sich tief in die Berge des südlichen Sumpflands, und der Ort hat von ihr seinen Namen, Thelgenfelsen. Giftige Spinnen kriechen durch die Höhlen und spinnen Seide in jede Spalte, und irgendwo in den tieferen Tunneln liegen Adern von Incendicit-Erz.",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "Whelgars Ausgrabungsstätte",
			short = "Zwerge kamen hierher, um in Frieden zu graben, östlich des Hafens von Menethil, und trieben ihre Schächte in Erde, die älter ist als jede Erinnerung.",
			full = "Zwerge kamen hierher, um in Frieden zu graben, östlich des Hafens von Menethil, und trieben ihre Schächte in Erde, die älter ist als jede Erinnerung. Dann überrannten gefleckte Raptoren die Stätte. Eine kleine Gruppe Zwerge, darunter Ausgrabungsleiter Whelgar und seine Mannschaft, sitzt auf einem Grat über ihrer eigenen Ausgrabung fest, während Raptoren unten in den Gruben umherstreifen.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
	},
	-- Teldrassil: 16 subzones
	[1438] = {
		["aldrassil"] = {
			name = "Aldrassil",
			short = "Aldrassil erhebt sich im Herzen von Shadowglen, ein riesiger Baum mit einem Dorf in seinen Ästen.",
			full = "Aldrassil erhebt sich im Herzen von Shadowglen, ein riesiger Baum mit einem Dorf in seinen Ästen. Tenaron Sturmgewalt, der Anführer von Shadowglen, wohnt ganz oben im Wipfel, außerhalb der Reichweite der Siedlung darunter, und wacht von dort über die Lichtung. Von der Krone aus schickt er vielversprechende junge Nachtelfen in die Welt hinaus.",
			source = "https://warcraft.wiki.gg/wiki/Aldrassil",
		},
		["banethil barrow den"] = {
			name = "Grabhügel von Ban'ethil",
			short = "Die Nachtelfen bauten den Grabhügel von Ban'ethil als einen ihrer heiligen Orte, einen Hügel, in dem schlafende Druiden der Kralle ruhen konnten.",
			full = "Die Nachtelfen bauten den Grabhügel von Ban'ethil als einen ihrer heiligen Orte, einen Hügel, in dem schlafende Druiden der Kralle ruhen konnten. Er hat zwei Teile, den Unteren Bau und den Oberen Bau. Die verderbten Furbolgs des Stammes der Knarzklauen haben ihn übernommen, und für einen einzelnen Nachtelfen ist er ein gefährlicher Ort.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Barrow_Den",
		},
		["banethil hollow"] = {
			name = "Ban'ethil Hollow",
			short = "Eine kleine Schlucht schneidet sich südlich der Straße von Dolanaar nach Darnassus ins Land. Feindselige Furbolgs halten ihre Hänge und überfallen hin und wieder Reisende auf der Straße.",
			full = "Eine kleine Schlucht schneidet sich südlich der Straße von Dolanaar nach Darnassus ins Land. Feindselige Furbolgs halten ihre Hänge und überfallen hin und wieder Reisende auf der Straße. Am Ende der Senke liegt der Grabhügel von Ban'ethil, tief in die Erde gesunken.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Hollow",
		},
		["cleft"] = {
			name = "Die Kluft",
			short = "Ursal der Raufer führt die verderbten Furbolgs des Stammes der Knarzklauen, die eine Höhle nordwestlich von Dolanaar halten.",
			full = "Ursal der Raufer führt die verderbten Furbolgs des Stammes der Knarzklauen, die eine Höhle nordwestlich von Dolanaar halten. Sie überfallen Reisende auf der Straße nach Darnassus und halten eine Gruppe schlummernder Druiden gefangen. Nahe dem Eingang bewachen Mondpriesterin Amara und ihre Leibwächter die Straße.",
			source = "https://warcraft.wiki.gg/wiki/Cleft",
		},
		["dolanaar"] = {
			name = "Dolanaar",
			short = "Junge Nachtelfen, die Shadowglen verlassen, kommen zuerst nach Dolanaar.",
			full = "Junge Nachtelfen, die Shadowglen verlassen, kommen zuerst nach Dolanaar. Das Dorf liegt im mittleren Osten von Teldrassil, knapp südwestlich der Lichtung, und seine zentrale Lage zieht es in einen Großteil der Geschäfte der Insel hinein. Tallonkai Flinkwurzel führt hier den Kampf gegen die verderbten Furbolgs und Satyrn des Großen Baums an.",
			source = "https://warcraft.wiki.gg/wiki/Dolanaar",
		},
		["fel rock"] = {
			name = "Teufelsfels",
			short = "Nördlich von Dolanaar liegt eine Höhle, die einst schön war und nun verderbt ist. Grells befallen ihre dunklen Höhlungen, und der bösartige Satyr Lord Melenas hat dort drinnen sein Heim.",
			full = "Nördlich von Dolanaar liegt eine Höhle, die einst schön war und nun verderbt ist. Grells befallen ihre dunklen Höhlungen, und der bösartige Satyr Lord Melenas hat dort drinnen sein Heim. Der Druide Tallonkai Flinkwurzel, der den Kampf gegen die Verderbnis auf der Insel anführt, will den Satyr vernichtet sehen.",
			source = "https://warcraft.wiki.gg/wiki/Fel_Rock",
		},
		["gnarlpine hold"] = {
			name = "Höhle der Knarzklauen",
			short = "Die Höhle der Knarzklauen liegt im äußersten Südwesten von Teldrassil und ist die Heimat der Furbolgs der Knarzklauen.",
			full = "Die Höhle der Knarzklauen liegt im äußersten Südwesten von Teldrassil und ist die Heimat der Furbolgs der Knarzklauen.",
			source = "https://warcraft.wiki.gg/wiki/Gnarlpine_Hold",
		},
		["lake alameth"] = {
			name = "Al'Amethsee",
			short = "Südlich von Dolanaar breitet sich der Al'Amethsee aus, eines der größten Gewässer auf Teldrassil. An seinen Ufern steht wenig außer einem kleinen Steg.",
			full = "Südlich von Dolanaar breitet sich der Al'Amethsee aus, eines der größten Gewässer auf Teldrassil. An seinen Ufern steht wenig außer einem kleinen Steg. In letzter Zeit sah man viele wütende Bäumlinge an den Ufern, und der See ist nicht mehr sicher. Denalan hat in der Nähe des Wassers ein kleines Zelt, wo er versucht, das seltsame Leiden zu begreifen, das in die Insel sickert.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Al'Ameth",
		},
		["oracle glade"] = {
			name = "Die Lichtung des Orakels",
			short = "Der erste und mächtigste der Mondbrunnen Teldrassils liegt auf der Lichtung des Orakels, einem Schrein im Nordwesten der Insel. Daneben steht der Orakelbaum.",
			full = "Der erste und mächtigste der Mondbrunnen Teldrassils liegt auf der Lichtung des Orakels, einem Schrein im Nordwesten der Insel. Daneben steht der Orakelbaum. Sein Stamm ist breit, und seine Äste haben die Gestalt eines großen Adlers, der auf einem mächtigen Bären sitzt. Viele glauben, Naturmagie habe ihn so wachsen lassen. Der Baum wacht gemeinsam mit den Druiden über das Wachstum Teldrassils, und er kann Stücke beschriebener Rinde abwerfen, um Berichte an Erzdruide Fandral Staghelm in Darnassus zu senden.\n\nHarpyien der Blutfedern haben in der Nähe Nester gebaut und bedrohen den Baum. Eine kleine Gruppe Schildwachen wurde entsandt, um sie zurückzudrängen.",
			source = "https://warcraft.wiki.gg/wiki/Oracle_Glade",
		},
		["pools of arlithrien"] = {
			name = "Teiche von Arlithrien",
			short = "Kleine Teiche sammeln sich im Westen von Teldrassil, südlich des Eingangs nach Darnassus. Der Ort war einst friedlich, und ein einsamer Mondbrunnen steht noch zwischen den Teichen.",
			full = "Kleine Teiche sammeln sich im Westen von Teldrassil, südlich des Eingangs nach Darnassus. Der Ort war einst friedlich, und ein einsamer Mondbrunnen steht noch zwischen den Teichen. Die Nachtelfen gaben ihn auf, als die Furbolgs der Knarzklauen zur Gefahr wurden, und feindselige Tiere streifen nun am Wasserrand umher.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "Rut'theran",
			short = "Das Dorf Rut'theran liegt ganz am Fuß des Weltenbaums, als Hafen für die Nachtelfenstadt Darnassus hoch darüber. Ein Portal hier führt direkt hinauf in die Hauptstadt, und im Dorf nisten Hippogryphen.",
			full = "Das Dorf Rut'theran liegt ganz am Fuß des Weltenbaums, als Hafen für die Nachtelfenstadt Darnassus hoch darüber. Ein Portal hier führt direkt hinauf in die Hauptstadt, und im Dorf nisten Hippogryphen. Wenn das Sonnenwendfest kommt, werden die Feuerschalen im Dorf entzündet.",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "Shadowglen",
			short = "Ein ewiges Zwielicht liegt über Shadowglen, einer kleinen Lichtung im Nordosten von Teldrassil, die nie ganz volles Tageslicht sieht.",
			full = "Ein ewiges Zwielicht liegt über Shadowglen, einer kleinen Lichtung im Nordosten von Teldrassil, die nie ganz volles Tageslicht sieht. Berge umgeben sie auf allen Seiten. Die einzige Lücke liegt im Süden, wo ein Pfad das Gebirge teilt und in Richtung Dolanaar führt. In der Mitte der Lichtung steht der große Baum Aldrassil, als wäre die ganze Lichtung um ihn herum angeordnet.",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "Schattenweberhöhle",
			short = "Große Spinnen haben schon immer in der Schattenweberhöhle gelebt, in der Nordwestecke von Shadowglen. In letzter Zeit sind sie feindseliger geworden, und die Höhle ist weit gefährlicher.",
			full = "Große Spinnen haben schon immer in der Schattenweberhöhle gelebt, in der Nordwestecke von Shadowglen. In letzter Zeit sind sie feindseliger geworden, und die Höhle ist weit gefährlicher. Die größte von ihnen, Githyiss die Üble, ist mehr als einem unerfahrenen Nachtelfen zum Verhängnis geworden.",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "Starbreeze",
			short = "Südöstlich von Shadowglen stehen die wenigen kleinen Häuser von Starbreeze, einer früheren Nachtelfensiedlung. Verderbte Furbolgs des Stammes der Knarzklauen haben sie überrannt.",
			full = "Südöstlich von Shadowglen stehen die wenigen kleinen Häuser von Starbreeze, einer früheren Nachtelfensiedlung. Verderbte Furbolgs des Stammes der Knarzklauen haben sie überrannt. Uruson patrouilliert durch das Dorf, und Ferocitas der Traumfresser ist an seinem Rand zu finden.",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring lake"] = {
			name = "Wellspringsee",
			short = "Nachtelfenfischer bevorzugten einst den Wellspringsee, einen kleinen See nordöstlich von Darnassus. Eine natürliche Quelle tief im Land des Weltenbaums speist ihn, und der Wellspring entwässert ihn.",
			full = "Nachtelfenfischer bevorzugten einst den Wellspringsee, einen kleinen See nordöstlich von Darnassus. Eine natürliche Quelle tief im Land des Weltenbaums speist ihn, und der Wellspring entwässert ihn. Verderbte Bäumlinge haben hier jetzt ihr Zuhause, und Nachtsäbler und Spinnen verseuchen das Land ringsum.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "Der Wellspring",
			short = "Der Wellspring entspringt einer Quelle tief im großen Baum. Er fließt vom Wellspringsee nach Norden und stürzt in einem gewaltigen Wasserfall über den Rand von Teldrassil, tief hinunter ins Meer.",
			full = "Der Wellspring entspringt einer Quelle tief im großen Baum. Er fließt vom Wellspringsee nach Norden und stürzt in einem gewaltigen Wasserfall über den Rand von Teldrassil, tief hinunter ins Meer. Wahnsinnige Bäumlinge patrouillieren an seinen Ufern und greifen jeden an, der in ihre Nähe gerät.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- Dunkelküste: 15 subzones
	[1439] = {
		["ametharan"] = {
			name = "Ameth'Aran",
			short = "Die Ruinen von Ameth'Aran liegen südöstlich von Auberdine.",
			full = "Die Ruinen von Ameth'Aran liegen südöstlich von Auberdine. Königin Azshara ließ die Stadt und ihre Zwillingsstadt Bashal'Aran für ihre bevorzugten Hochgeborenen errichten, mit Basaren und Tempeln der Elune, und Athrikus Narassin regierte sie für sie. In den letzten Tagen des alten Reichs lag die Stadt schon in Trümmern, und ihre Bewohner klammerten sich an den Boden, als könnte das sie vor der Zerstörung bewahren. Athrikus trat zu ihnen und sagte, ein Zauber werde sie schützen. Während er sprach, starben die Elfen um ihn herum, und ihre Seelen gingen in seine Seelensteine über, die ihnen, wie er sagte, ewiges Leben schenken würden.\n\nIhre ruhelosen Geister erfüllen die Ruinen noch immer. Zwei große Tafeln stehen zwischen den Steinen, in die die Geschichte der Stadt und ihres Falls gemeißelt ist. Eine Schildwache, die sie zu lesen versuchte, wurde von den Hochgeborenen vertrieben.",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "Auberdine",
			short = "Auberdine liegt an einer Küste, die die Zerschlagung schuf, wo das Meer die großen Städte des alten Nachtelfenreichs zerstörte.",
			full = "Auberdine liegt an einer Küste, die die Zerschlagung schuf, wo das Meer die großen Städte des alten Nachtelfenreichs zerstörte. Die Dunkelküste blieb danach leer, und jeder Versuch, sie zu besiedeln, scheiterte bis auf diese eine Stadt am Verhüllten Meer.\n\nZwerge, Gnome, Menschen und sogar Hochelfen gehen durch ihre Straßen, was für eine Nachtelfenstadt ungewöhnlich ist. Ihr Hafen zieht Händler aus den Östlichen Königreichen an, und um ihnen zu helfen, ist die Stadt heller beleuchtet als die meisten Nachtelfenorte, mit einigen Wegweisern in Darnassisch und Gemeinsprache. Der Älteste Thundris Windwirker führt die täglichen Geschäfte der Stadt, und Schildwachen bewachen sie. Murlocs versenken an dieser Küste Boote, und die Stadtbewohner fertigen Rüstungen aus den Schuppen derer, die sie erschlagen.\n\nBeim Leuchtturm liegt das Wrack eines Schiffes unter dem Befehl einer Elfe namens Elura auf den Felsen. Ihre Ladung Elunit-Erz ging mit ihr unter.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "Bashal'Aran",
			short = "Asterion war ein Magier, der mit der Klinge ebenso geschickt umging wie mit den arkanen Künsten, und er diente Athrikus Narassin in Bashal'Aran als Stellvertreter.",
			full = "Asterion war ein Magier, der mit der Klinge ebenso geschickt umging wie mit den arkanen Künsten, und er diente Athrikus Narassin in Bashal'Aran als Stellvertreter. Er lebte unter seinem Volk und reiste oft nach Ameth'Aran, um sich um die Menschen dort zu kümmern. Dann schuf Athrikus mit seiner Kunst ein Mondsteinsiegel und band Asterion in den Ruinen. Niemand weiß, warum er sich gegen seinen Stellvertreter wandte. Asterion lebte in Schmerzen weiter, und als er starb, musste er feststellen, dass sein Geist ebenso fest gehalten wurde, wie es sein Körper gewesen war.\n\nDie Stadt selbst fiel, als der erste Brunnen der Ewigkeit zerschmettert wurde. Satyrn und Grells haben seither ihr Heim in den Ruinen gefunden und werden stärker durch die Magie, die in den Steinen zurückblieb. Sie nähern sich nie dem Schrein, in dem Asterion gefangen ist.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "Bau der Schwarzfelle",
			short = "Im äußersten Süden der Dunkelküste, nahe der Grenze zu Ashenvale, bilden einige Furbolglager und eine kleine Höhle den Bau der Schwarzfelle, der auch Höhle der Schwarzfelle genannt wird.",
			full = "Im äußersten Süden der Dunkelküste, nahe der Grenze zu Ashenvale, bilden einige Furbolglager und eine kleine Höhle den Bau der Schwarzfelle, der auch Höhle der Schwarzfelle genannt wird. Die Furbolgs der Schwarzfelle, die hier leben, hat das Teufelsmoos verderbt. In der Höhle wird ein einzelner Nachtelf namens Volcor unter ihnen gefangen gehalten.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "Cliffspring Falls",
			short = "Cliffspring Falls speisen den Cliffspring und sind die wichtigste Trinkwasserquelle der Dunkelküste. Das Wasser war einst rein. Nun ist die Höhle, aus der es fließt, verderbt, wie ein großer Teil des Landes ringsum.",
			full = "Cliffspring Falls speisen den Cliffspring und sind die wichtigste Trinkwasserquelle der Dunkelküste. Das Wasser war einst rein. Nun ist die Höhle, aus der es fließt, verderbt, wie ein großer Teil des Landes ringsum.\n\nÜber die Ursache gehen die Meinungen auseinander. Manche sagen, die Verderbnis sickere aus dem Teufelswald herein. Andere geben dem Schattenhammer die Schuld, dessen Kultisten tief in den Höhlen gefunden wurden, wo das Wasser entspringt. Auch Naga kriechen durch die Höhle.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "Cliffspring",
			short = "Der Cliffspring fließt von Cliffspring Falls im Norden der Dunkelküste ins Meer. Die Naga der Sturmschuppen haben ihn verseucht, und die Tiere, die daraus trinken, werden oft krank.",
			full = "Der Cliffspring fließt von Cliffspring Falls im Norden der Dunkelküste ins Meer. Die Naga der Sturmschuppen haben ihn verseucht, und die Tiere, die daraus trinken, werden oft krank.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "Der Hain der Uralten",
			short = "Onu, ein Urtum der Lehren, hat sein Heim zwischen den Steinen des Hains der Uralten, der heiligen Ruine eines alten Nachtelfentempels in den Bergen der südöstlichen Dunkelküste.",
			full = "Onu, ein Urtum der Lehren, hat sein Heim zwischen den Steinen des Hains der Uralten, der heiligen Ruine eines alten Nachtelfentempels in den Bergen der südöstlichen Dunkelküste. Er wurde um den reißenden Wildbend herum gebaut, und hier tagt der Zirkel der Uralten. Onu ist geduldig und weise, hat einen schlafenden Druiden zur Gesellschaft, und die Naga und der Kult des Schattenhammers, der in der Region sein Werk treibt, beunruhigen ihn.",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "Der lange Strand",
			short = "Trotz seines Namens ist der lange Strand der kürzeste Küstenabschnitt der Dunkelküste.",
			full = "Trotz seines Namens ist der lange Strand der kürzeste Küstenabschnitt der Dunkelküste. Grauer Sand zieht sich von Auberdine nach Süden bis zu den Gewässern westlich von Ameth'Aran, unter einem bedeckten Himmel, der sich nie hebt. Treibgut liegt am Strand, und Murlocs zeigen sich dort immer öfter.",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "Die Meistergleve",
			short = "Im Südwesten der Dunkelküste liegt ein gewaltiger Schädel, durch dessen Knochen eine adamantene Gleve getrieben ist.",
			full = "Im Südwesten der Dunkelküste liegt ein gewaltiger Schädel, durch dessen Knochen eine adamantene Gleve getrieben ist. Er ist alles, was von Soggoth dem Glitschigen übrig ist, einem Herold der Alten Götter, und die Klinge ist die Meistergleve. Die Nachtelfen hielten den Ort einst für heilig.\n\nTafeln, die Buddler der Forscherliga fanden, erzählen, was hier geschah. Die Titanen schickten zwanzig Steinriesen gegen Soggoth, und der Kampf war so furchtbar, dass nur der größte, Kronn, sein Ende erlebte. Er ließ sich von Soggoths Fangarmen umschlingen, gerade lange genug, um in die Reichweite des Schädels und seines großen Schwerts gehoben zu werden. Das Schwert blieb dort stecken, wo es getroffen hatte.\n\nDer Schattenhammer beherrscht die Stätte jetzt. Seine Kultisten graben in Soggoths Überresten und wollen ihn wieder zum Leben erwecken.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "Nebelrand",
			short = "Graue Strände und düstere Buchten bilden den Nebelrand, die längste Küstenlinie der Dunkelküste, die von nahe Auberdine bis zur nördlichen Spitze der Region reicht.",
			full = "Graue Strände und düstere Buchten bilden den Nebelrand, die längste Küstenlinie der Dunkelküste, die von nahe Auberdine bis zur nördlichen Spitze der Region reicht. Riesige Kadaver von Meerestieren liegen im Sand, und die Wracks versunkener Schiffe sprenkeln das Wasser. Krabben huschen über die gesamte Küste, und Murlocs in den Buchten sind eine ständige Bedrohung.",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "Remtravels Ausgrabung",
			short = "Ausgrabungsleiter Remtravel von der Forscherliga, ein berühmter Archäologe, gab dieser Grabung ihren Namen. In ihr fand er ein Fossil mit ungewöhnlichen mystischen Eigenschaften und vergaß dann, wohin er es gelegt hatte.",
			full = "Ausgrabungsleiter Remtravel von der Forscherliga, ein berühmter Archäologe, gab dieser Grabung ihren Namen. In ihr fand er ein Fossil mit ungewöhnlichen mystischen Eigenschaften und vergaß dann, wohin er es gelegt hatte. Seither haben Kieselsplittertroggs die Ausgrabung übernommen, und riesige Golems, die bei den Grabungen freigelegt wurden, sind ebenfalls in sie eingedrungen.",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "Die Ruinen von Mathystra",
			short = "Hinter dem Turm von Althalaxx, im Norden der Dunkelküste, liegen die Ruinen von Mathystra. Vor der Großen Zerschlagung stand hier eine Stadt der Nachtelfen, errichtet im Zeitalter der Hochgeborenen.",
			full = "Hinter dem Turm von Althalaxx, im Norden der Dunkelküste, liegen die Ruinen von Mathystra. Vor der Großen Zerschlagung stand hier eine Stadt der Nachtelfen, errichtet im Zeitalter der Hochgeborenen. Als der Brunnen der Ewigkeit sich selbst zerriss und die Welt unter ihm zerbrach, wurde Mathystra zusammen mit so vielem anderen zerstört, und die Nachtelfen, die überlebten, kehrten nicht zurück, um sie wieder aufzubauen. Sie zogen sich stattdessen in kleinere Dörfer an der Küste weiter im Süden zurück und ließen die Ruinen hinter sich.\n\nVerstreute Relikte der alten Hochgeborenen liegen noch zwischen den gefallenen Steinen, und junge Nachtelfen kommen manchmal, um in Mathystra nach ihnen zu suchen, wachsam gegenüber den Geistersäblern, die dort zwischen den Ruinen dessen umherstreifen, was ihr Volk einst erbaut hat.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "Turm von Althalaxx",
			short = "Athrikus Narassin regierte die Zwillingsstädte für Königin Azshara, doch der Posten langweilte ihn, und er verbrachte seine Tage in einem eigenen Turm, Althalaxx, ein Stück von ihnen entfernt.",
			full = "Athrikus Narassin regierte die Zwillingsstädte für Königin Azshara, doch der Posten langweilte ihn, und er verbrachte seine Tage in einem eigenen Turm, Althalaxx, ein Stück von ihnen entfernt. Die Explosion des Brunnens der Ewigkeit schleuderte ihn weit fort und machte ihn unsterblich, mit der Kraft, andere Magier auszusaugen, um seine eigene zu nähren.\n\nJetzt beherbergt der Turm einen Kult, der sich Kult des Dunklen Strangs nennt. Hexenmeister versammeln sich dort, unter ihnen ein Satyr, und Athrikus führt sie an.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight vale"] = {
			name = "Das Zwielichttal",
			short = "Das Zwielichttal umfasst die Wälder südlich von Ameth'Aran bis zur Grenze von Ashenvale.",
			full = "Das Zwielichttal umfasst die Wälder südlich von Ameth'Aran bis zur Grenze von Ashenvale. Verderbte Furbolgs, wilde Nachtsäbler und tollwütige Bären suchen diese Wälder heim, und Reisenden wird geraten, auf den Straßen zu bleiben, statt unter den Bäumen umherzuwandern.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "Der Wildbend",
			short = "Der Wildbend trägt seine Krankheit von den Bergen herab, eine Fortsetzung des Blutgiftbachs, der sich aus dem Teufelswald in die südliche Dunkelküste ergießt, nahe dem Hain der Uralten.",
			full = "Der Wildbend trägt seine Krankheit von den Bergen herab, eine Fortsetzung des Blutgiftbachs, der sich aus dem Teufelswald in die südliche Dunkelküste ergießt, nahe dem Hain der Uralten. Sein Wasser ist verseucht, und die Verderbnis des Teufelswalds folgt der Strömung hinab in diese tieferen Länder.",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- Ashenvale: 40 subzones
	[1440] = {
		["astranaar"] = {
			name = "Astranaar",
			short = "Astranaar liegt auf einer Insel mitten in einem See, mit dem Ufer durch zwei Brücken verbunden, und die Hauptstraße führt hindurch. Es ist die größte Siedlung in Ashenvale, und am See liegt ein Friedhof.",
			full = "Astranaar liegt auf einer Insel mitten in einem See, mit dem Ufer durch zwei Brücken verbunden, und die Hauptstraße führt hindurch. Es ist die größte Siedlung in Ashenvale, und am See liegt ein Friedhof.\n\nIm Norden haben die Furbolgs der Distelfelle an Zahl zugenommen. Die Schildwache Raene Wolfsläufer fürchtet, sie könnten den Mut finden, Astranaar selbst anzugreifen.",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "Bathrans Schlupfwinkel",
			short = "Zerbrochene Säulen und gefallener Marmor kennzeichnen eine Nachtelfenruine, die die Elfen vor langer Zeit verlassen haben.",
			full = "Zerbrochene Säulen und gefallener Marmor kennzeichnen eine Nachtelfenruine, die die Elfen vor langer Zeit verlassen haben. Agenten der Verlassenen sind eingezogen, vor allem Kräuterkundige und die Schläger, die sie bewachen. Wo sie arbeiten, ist das Gras braun geworden und sind die Blumen verwelkt. Zwischen den Steinen haben sie ein behelfsmäßiges Labor gebaut und nutzen die einheimischen Kräuter zu bösen Zwecken. Die Verlassenen hier sind der Horde freundlich gesinnt.\n\nEin heilendes Kraut namens Bathrans Haar wächst nur an dieser einen Stelle und nirgendwo sonst.",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "Blackfathom-Tiefe",
			short = "Ein Tempel der Elune, der Mondgöttin der Nachtelfen, stand einst am Zoramstrand.",
			full = "Ein Tempel der Elune, der Mondgöttin der Nachtelfen, stand einst am Zoramstrand. Die Große Zerschlagung zerschmetterte ihn und versenkte ihn unter den Wellen des Verhüllten Meeres, und Tausende von Jahren lag er unberührt. Dann kamen Naga und Satyrn, angelockt von seiner uralten Macht, herauf, um seine Geheimnisse zu erforschen.\n\nDer Schattenhammer folgte, gerufen von Flüstern und üblen Träumen. Der Kult opferte unzählige Unschuldige und wurde mit einer Aufgabe belohnt. Er muss Aku'mai den Verschlinger, eine dreiköpfige Hydra und ein Lieblingsgeschöpf der Alten Götter, bewachen und nähren, bis sie bereit ist, ihre dunkle Macht auf die Welt loszulassen. Zwielichtfürst Kelris führt die Kultisten in den gefluteten Höhlen an, und die Verderbnis eines Alten Gottes hat den Mondbrunnen des Tempels befleckt. Der Ort heißt jetzt Blackfathom-Tiefe, und der Name passt.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "Blutreißers Lager",
			short = "Ran Blutreißer, der König aller Furbolgs in Ashenvale, hält dieses Lager knapp westlich des Falfarren und südwestlich des südlichen Mondbrunnens.",
			full = "Ran Blutreißer, der König aller Furbolgs in Ashenvale, hält dieses Lager knapp westlich des Falfarren und südwestlich des südlichen Mondbrunnens. Das Lager ist nach ihm benannt. Jeder Furbolg darin ist verderbt, und sie greifen jeden Fremden an, der ihnen nahe kommt.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "Bough Shadow",
			short = "Hier wächst ein Großer Baum, und er ist ein Tor in den Smaragdgrünen Traum. Die grünen Drachen Phantim und Traumpirscher bewachen das Portal.",
			full = "Hier wächst ein Großer Baum, und er ist ein Tor in den Smaragdgrünen Traum. Die grünen Drachen Phantim und Traumpirscher bewachen das Portal. Verfluchte grüne Drachenbrut ist daraus in die Wälder geschlüpft, wo sie in Gruppen patrouillieren.",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "Demonfall-Canyon",
			short = "Der Grubenlord Mannoroth kämpfte hier gegen Thrall und Grommash Höllschrei. Er schlug Thrall bewusstlos, doch er war nicht schnell genug, um Grommashs Axt auszuweichen, die ihm in die Brust fuhr.",
			full = "Der Grubenlord Mannoroth kämpfte hier gegen Thrall und Grommash Höllschrei. Er schlug Thrall bewusstlos, doch er war nicht schnell genug, um Grommashs Axt auszuweichen, die ihm in die Brust fuhr. Sein Tod barst in Feuer und Licht und riss auch Grommash das Leben aus dem Leib. Mit Mannoroths Ende war der Fluch der Brennenden Legion auf den Orcs gebrochen. Der Canyon trägt seinen Namen nach diesem Kampf.\n\nEin Denkmal für Grommash steht hier, und viele Orcs pilgern hierher, um den Krieger zu ehren, der sie befreit hat. Der Boden ist noch immer von Teufelsmagie verderbt, und niedere Dämonen füllen jetzt den Canyon.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "Demonfall-Kamm",
			short = "Niedere Dämonen suchen die Hänge dieses Kamms heim, ebenso den verlassenen Grabhügelbau, der in seine Flanke gegraben ist.",
			full = "Niedere Dämonen suchen die Hänge dieses Kamms heim, ebenso den verlassenen Grabhügelbau, der in seine Flanke gegraben ist. Im tiefsten Teil des Baus wartet Diathorus der Sucher, ein Schreckenslord, der das dämonische Konklave in Ashenvale beherrscht.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "Der Dor'danil-Grabhügel",
			short = "Nachtelfendruiden kommen seit Langem zum Dor'danil-Grabhügel, um zu ruhen. Das Vordringen der Horde nach Ashenvale ließ den Bau hinter ihren Linien zurück, und den Orcs waren schlafende Elfen gleichgültig.",
			full = "Nachtelfendruiden kommen seit Langem zum Dor'danil-Grabhügel, um zu ruhen. Das Vordringen der Horde nach Ashenvale ließ den Bau hinter ihren Linien zurück, und den Orcs waren schlafende Elfen gleichgültig. Den Verlassenen, die sich der Horde später anschlossen, waren sie sehr wohl wichtig. Sie experimentierten an den schlafenden Druiden, trennten sie von ihren Geistern und trieben sie in den Wahnsinn.\n\nAssassinen der Verlassenen schleichen nun durch den Bau, zwischen den wütenden Seelen der abgetrennten Druiden. Drei Geister sind stärker als die übrigen. Es sind Uthil Mondweise, Mavoris Wolkenbruch und Taneel Finsterwald.",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "Der Falfarren",
			short = "Der Falfarren zieht sich von Nordosten nach Südwesten durch Ashenvale. Er trennt grob das Nachtelfenland unter Astranaar im Westen vom Orcland unter dem Splintertreeposten im Osten.",
			full = "Der Falfarren zieht sich von Nordosten nach Südwesten durch Ashenvale. Er trennt grob das Nachtelfenland unter Astranaar im Westen vom Orcland unter dem Splintertreeposten im Osten. Der Fluss ist weder tief noch breit, schwillt aber bei starkem Regen an.\n\nEr entspringt an den Hängen des Bergs Hyjal, fällt über eine Reihe von Wasserfällen in einen See und verschwindet schließlich unter den Bergen des nördlichen Brachlands im Untergrund. Aggressive Sumpfbestien streifen unter der Wasseroberfläche nahe Felfire Hill umher.",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "Fallenskysee",
			short = "Südlich des Außenpostens der Silverwing liegt ein kleiner See mit einer einzigen Insel in der Mitte. Ein Schattendickichtorakel, eine Sumpfbestie, lebt auf der Insel, und geringere Schattendickichte säumen das Ufer.",
			full = "Südlich des Außenpostens der Silverwing liegt ein kleiner See mit einer einzigen Insel in der Mitte. Ein Schattendickichtorakel, eine Sumpfbestie, lebt auf der Insel, und geringere Schattendickichte säumen das Ufer.",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "Felfire Hill",
			short = "Felfire Hill trägt noch die Narben des Dritten Krieges, als Höllenbestien brennend vom Himmel fielen und hier in die Erde schlugen. Üble Dämonen leben seither zwischen seinen Steinen.",
			full = "Felfire Hill trägt noch die Narben des Dritten Krieges, als Höllenbestien brennend vom Himmel fielen und hier in die Erde schlugen. Üble Dämonen leben seither zwischen seinen Steinen. Die Horde hat beide Brücken auf den Hügel befestigt, damit Angriffe ihre nahen Siedlungen nicht erreichen.",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "Fire Scar-Schrein",
			short = "Der dämonische Einfluss des Schattenrats hat den Fire Scar-Schrein im südwestlichen Ashenvale verderbt, bis er zu einem Ort großen Übels wurde.",
			full = "Der dämonische Einfluss des Schattenrats hat den Fire Scar-Schrein im südwestlichen Ashenvale verderbt, bis er zu einem Ort großen Übels wurde. Ein orcischer Hexenmeister, Ilkrud Magskluve, lebt hier im Dienst von Athrikus Narassin, dem Anführer des Kults des Dunklen Strangs.\n\nDämonen verseuchen den Schrein nun. Eine seltene Verdammniswache namens Akkrilus erscheint von Zeit zu Zeit in der Gegend.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "Forest Song",
			short = "Der Druide Kayneth Stillwind ist der einzige Bewohner von Forest Song, einer alten Nachtelfenruine im Nordosten von Ashenvale. Von ihren Steinen aus lenkt er den Kampf gegen die Verlassenen in der Region.",
			full = "Der Druide Kayneth Stillwind ist der einzige Bewohner von Forest Song, einer alten Nachtelfenruine im Nordosten von Ashenvale. Von ihren Steinen aus lenkt er den Kampf gegen die Verlassenen in der Region.",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "Laubtatzenlichtung",
			short = "Verderbte Furbolgs des Stammes der Fäulnisklauen haben die Laubtatzenlichtung zu ihrer Heimat gemacht. Häuptling Murgut führt sie an, und der Schamane Knurrtatze ist unter ihnen.",
			full = "Verderbte Furbolgs des Stammes der Fäulnisklauen haben die Laubtatzenlichtung zu ihrer Heimat gemacht. Häuptling Murgut führt sie an, und der Schamane Knurrtatze ist unter ihnen. Der Stamm ist feindselig, und die Horde hält ihn für eine mögliche Bedrohung.",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "Das heulende Tal",
			short = "In einer Höhle nahe der Grenze zum Teufelswald steht der Schrein von Mel'Thandris.",
			full = "In einer Höhle nahe der Grenze zum Teufelswald steht der Schrein von Mel'Thandris. Mel'Thandris Sternenlied gab ihr Leben in der letzten Schlacht des Krieges der Satyrn, nachdem Malfurion Stormrage ihr heimlich die Sense von Elune anvertraut hatte. Der Schrein wurde in ihrem Namen errichtet, und die Sense wurde nach ihrem Tod hier verwahrt. Davor ist eine uralte Inschrift eingemeißelt, die Elune preist, und der Schrein trägt eine weitere, auf Darnassisch, die lautet „Die Wahrheit ist ein leitendes Licht.“\n\nDer Schrein liegt in Ruinen. Ein Rudel Worgen, die Terrowulf genannt werden, hat ihn übernommen, und ihr eisiges Heulen gibt dem Tal seinen Namen.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "Irissee",
			short = "Die Verderbnis des Teufelswalds ist in den Irissee im nördlichen Zentrum von Ashenvale gekrochen, einen von vielen Teilen des Nachtelfenwaldes, die ihr zum Opfer fielen.",
			full = "Die Verderbnis des Teufelswalds ist in den Irissee im nördlichen Zentrum von Ashenvale gekrochen, einen von vielen Teilen des Nachtelfenwaldes, die ihr zum Opfer fielen. Das Wasser hat sich krankhaft gelbgrün gefärbt. Verdrehte Sumpfbestien streifen an seinen Ufern umher und greifen jeden an, der in die Nähe kommt.",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "Burg Kargathia",
			short = "Die Offiziere des Kriegshymnenklans haben ihre Basis in der Burg Kargathia, im östlichen Teil des Holzfällerlagers der Warsong, knapp westlich des Südstroms.",
			full = "Die Offiziere des Kriegshymnenklans haben ihre Basis in der Burg Kargathia, im östlichen Teil des Holzfällerlagers der Warsong, knapp westlich des Südstroms. Stachelbewehrte Barrikaden umgeben die Festung. Ihre Lage erlaubt es, Verstärkung aus Orgrimmar herabzuschicken, falls die Allianz mit großer Macht gegen das Lager vorgeht.\n\nDie Burg ist nach dem legendären Orc-Helden Kargath Messerfaust benannt.",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "Falathimsee",
			short = "Elunes Mondlicht fällt zu jeder Stunde auf den Falathimsee, bei Tag und bei Nacht. Nachtelfen kamen einst zum Schwimmen und Fischen hierher.",
			full = "Elunes Mondlicht fällt zu jeder Stunde auf den Falathimsee, bei Tag und bei Nacht. Nachtelfen kamen einst zum Schwimmen und Fischen hierher. Wilde Murlocs haben den See seither überrannt. Ein Gelehrter namens Teronis wurde zuletzt nahe seinem Ufer gesehen und kehrte nie zurück.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "Maestras Posten",
			short = "Ein Turm und eine große Nachtelfenhalle bilden Maestras Posten, und nur wenige Leute leben hier. Zwei von ihnen sind Menschen, die einzigen in Ashenvale.",
			full = "Ein Turm und eine große Nachtelfenhalle bilden Maestras Posten, und nur wenige Leute leben hier. Zwei von ihnen sind Menschen, die einzigen in Ashenvale. Delgren der Läuterer und Feero Eisenhand kamen von der Argentumdämmerung, um den Nachtelfen zu helfen, ihren Wald von Dämonen und Untoten zu säubern. Sie arbeiten von dem Posten aus daran, den Kult des Dunklen Strangs zu unterwandern.",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["mystral lake"] = {
			name = "Mystralsee",
			short = "Die Wasserelementare im Mystralsee waren einst den Nachtelfen treu. Sarilus Faulmut, ein Magier der Verlassenen, hat sie verderbt.",
			full = "Die Wasserelementare im Mystralsee waren einst den Nachtelfen treu. Sarilus Faulmut, ein Magier der Verlassenen, hat sie verderbt. Es ist der größte See des Waldes, und seine verderbten Elementare machen ihn für jeden gefährlich, der ans Ufer kommt.",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "Night Run",
			short = "Ein paar zerbrochene Säulen und Stücke zerfallenen Mauerwerks beherbergen die Satyrn der Teufelshufe in Night Run, der kleinsten der Satyrsiedlungen in Ashenvale.",
			full = "Ein paar zerbrochene Säulen und Stücke zerfallenen Mauerwerks beherbergen die Satyrn der Teufelshufe in Night Run, der kleinsten der Satyrsiedlungen in Ashenvale. Die Ruinen stehen auf einer Landzunge, die in den Wald hineinragt. Zu steile Klippen, um sie zu erklimmen, sichern ihre Flanken.\n\nDie Teufelshufe sind mit dem Kult des Dunklen Strangs verbündet, und einer der Seelensteine des Kults liegt zwischen den Trümmern.",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "Nightsongwälder",
			short = "Die meisten schweren Kämpfe zwischen Horde und Allianz finden in den Nightsongwäldern statt, im östlichen Teil von Ashenvale, wo der Kriegshymnenklan und die Schildwachen der Silverwing beide Boden halten.",
			full = "Die meisten schweren Kämpfe zwischen Horde und Allianz finden in den Nightsongwäldern statt, im östlichen Teil von Ashenvale, wo der Kriegshymnenklan und die Schildwachen der Silverwing beide Boden halten. Die Schildwachen halten den Westen für die Allianz, und der Kriegshymnenklan hält den Osten für die Horde.\n\nDer äußerste Osten ist das am heftigsten umkämpfte Gebiet von allen. Satyrn, Orcs des Kriegshymnenklans und Dämonen der Brennenden Legion halten jeweils ein Stück davon. Im Süden haben die Orcs des Kriegshymnenklans einen Großteil des uralten Waldes abgeholzt und verwenden das dicke Holz für den Bau ihrer Siedlungen. Sie lassen offenen, verwundeten Boden zurück, wo die alten Bäume einst ungebrochen standen.",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "Raynewood",
			short = "Im Wipfel des Großen Baums Raynewood versteckt sich Ordanus, ein Bewahrer des Hains und einer der ältesten Söhne des Waldgottes Cenarius.",
			full = "Im Wipfel des Großen Baums Raynewood versteckt sich Ordanus, ein Bewahrer des Hains und einer der ältesten Söhne des Waldgottes Cenarius. Der Schattenrat sucht ihn. Braelyn Feuerhand hat sich seinen Tod zum Ziel gesetzt.\n\nUnter ihm halten Cenarische Beschützer, Flimmerdrachen und die Lachenden Schwestern den Außenposten der Allianz und beobachten den Pfad, der nach Norden in den verderbten Teufelswald führt.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "Die Ruinen von Ordil'Aran",
			short = "Von der alten Stadt, die einst bei Ordil'Aran stand, ist nicht viel geblieben.",
			full = "Von der alten Stadt, die einst bei Ordil'Aran stand, ist nicht viel geblieben. Zwischen den zerbrochenen Steinen wächst das Herzholz, ein Baum, der dort Wurzeln schlug, wo zwei Liebende, Anathera und Latherion, im Krieg der Ahnen gemeinsam fielen. Er steht als Sinnbild ihrer unsterblichen Liebe.\n\nDer Kult des Dunklen Strangs hat die Ruinen für sich eingenommen. Seine Mitglieder warten zwischen den Steinen, bereit, jeden anzugreifen, der in die Nähe kommt.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "Die Sternenstaubruinen",
			short = "Die Sternenstaubruinen liegen auf einer Insel in einem See und galten einst als heilig. Die dämonische Fäulnis des Teufelswalds hat sie inzwischen erreicht.",
			full = "Die Sternenstaubruinen liegen auf einer Insel in einem See und galten einst als heilig. Die dämonische Fäulnis des Teufelswalds hat sie inzwischen erreicht. Wasser und Stein tragen denselben Makel, und große Sumpfbestien, vom verseuchten See verderbt, streifen zwischen den Ruinen umher.\n\nNur die verstreuten Sternenstaubsträucher sind dem Makel entgangen. Sie sollen kräftige Heilkräfte besitzen, wenn man sie als Trank zu sich nimmt.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "Satyrnaar",
			short = "Satyrnaar steht zerbrochen zwischen den Bäumen im Nordosten von Eschental, seine Gebäude längst zu Ruinen verfallen, doch nun drängen sich Zelte zwischen den Trümmern, wo die Satyrn der Herzschinder ihr Heim aufgeschlagen haben.",
			full = "Satyrnaar steht zerbrochen zwischen den Bäumen im Nordosten von Eschental, seine Gebäude längst zu Ruinen verfallen, doch nun drängen sich Zelte zwischen den Trümmern, wo die Satyrn der Herzschinder ihr Heim aufgeschlagen haben. Von den drei Satyrfestungen im Wald ist allein Satyrnaar weitgehend erhalten, und seine Lage an der Straße, die von Splintertree nach Azshara führt, hat es zur am leichtesten erreichbaren und am meisten umkämpften der drei gemacht.\n\nDie Herzschinder haben hier mehr als nur Unterschlupf. In Satyrnaar ruht einer der Seelensteine des Kults des Dunklen Strangs, ein Zeichen des Paktes, der die Satyrn an die finsteren Absichten jenes Kults bindet.",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "Der Schattenwinkel",
			short = "Eine Bärenfamilie lebt im Schattenwinkel, einem kleinen Tal in Ashenvale. Eine Höhle öffnet sich im Hang, und die Bären haben dort wahrscheinlich ihren Bau.",
			full = "Eine Bärenfamilie lebt im Schattenwinkel, einem kleinen Tal in Ashenvale. Eine Höhle öffnet sich im Hang, und die Bären haben dort wahrscheinlich ihren Bau.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "Der Schrein von Aessina",
			short = "Ein Schrein für Aessina, den Geist der Wildnis, steht im Wald westlich von Astranaar. Die Nachtelfen haben ihr in ganz Kalimdor Schreine errichtet, doch nur wenige Sterbliche wissen viel über sie.",
			full = "Ein Schrein für Aessina, den Geist der Wildnis, steht im Wald westlich von Astranaar. Die Nachtelfen haben ihr in ganz Kalimdor Schreine errichtet, doch nur wenige Sterbliche wissen viel über sie.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "Silberwindzuflucht",
			short = "Schildwachen bewachen die Silberwindzuflucht, und eine Armee von Wasserelementaren dient an ihrer Seite. Die Nachtelfen zählen sie wie Astranaar zu den wichtigen Außenposten von Ashenvale.",
			full = "Schildwachen bewachen die Silberwindzuflucht, und eine Armee von Wasserelementaren dient an ihrer Seite. Die Nachtelfen zählen sie wie Astranaar zu den wichtigen Außenposten von Ashenvale. Sie liegt knapp nördlich des Mystralsees und ist ein einladender Ort mit einem Gasthaus, das luxuriöser ist als die meisten in diesen Wäldern.",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "Hain der Silverwing",
			short = "Die Schildwachen der Silverwing haben ihre Basis in diesem Hain im südlichen Zentrum von Ashenvale, westlich des Fallenskysees. Schildwache Farsong hält hier Wache.",
			full = "Die Schildwachen der Silverwing haben ihre Basis in diesem Hain im südlichen Zentrum von Ashenvale, westlich des Fallenskysees. Schildwache Farsong hält hier Wache. Vier Jahre nach dem Dritten Krieg begannen die Nachtelfen eine große Offensive, um die Wälder von Ashenvale zurückzugewinnen und ihr Land von der Warsongvorhut zu befreien. Die Schildwachen der Silverwing folgten dem Ruf und schworen, nicht zu ruhen, bis jeder letzte Orc geschlagen und aus der Warsongschlucht vertrieben sei.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "Außenposten der Silverwing",
			short = "Auf der Seite der Horde des Falfarren steht die östlichste Bastion, die die Allianz in Ashenvale hält.",
			full = "Auf der Seite der Horde des Falfarren steht die östlichste Bastion, die die Allianz in Ashenvale hält. Die Schildwachen, die am Außenposten der Silverwing stationiert sind, wehren ständige Angriffe der Orcs in der Nähe ab, die den Wald ein für alle Mal von den Schildwachen der Silverwing befreien wollen. Duriel Mondfeuer führt sie an.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "Der Südstrom",
			short = "Der Südstrom beginnt als See im Berg Hyjal. Von dort stürzt er in einer Folge spektakulärer Wasserfälle hinab und kommt breit und schnell herunter, wahrscheinlich der bedeutendste Fluss in Kalimdor.",
			full = "Der Südstrom beginnt als See im Berg Hyjal. Von dort stürzt er in einer Folge spektakulärer Wasserfälle hinab und kommt breit und schnell herunter, wahrscheinlich der bedeutendste Fluss in Kalimdor. Er bildet die Grenze zwischen Ashenvale und Azshara, und weiter südlich trennt er das Brachland von Durotar.\n\nKnapp nördlich der westlichen Brücke nach Orgrimmar berührt eine Stelle am Wasser vier Länder zugleich. Ashenvale, Azshara, Durotar und das Brachland treffen sich dort. An seiner Mündung ergießt sich der Fluss in einem letzten Wasserfall ins Große Meer, nordöstlich des Goblinhafens Ratchet.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "Splintertreeposten",
			short = "Grommash Höllschrei und sein Kriegshymnenklan errichteten den Splintertreeposten im Dritten Krieg, als die Orcs zum ersten Mal nach Ashenvale vordrangen.",
			full = "Grommash Höllschrei und sein Kriegshymnenklan errichteten den Splintertreeposten im Dritten Krieg, als die Orcs zum ersten Mal nach Ashenvale vordrangen. Er ist eine der ältesten Siedlungen der Horde auf Kalimdor.\n\nDie Nachtelfen haben Grommash nicht vergessen. Von der Brennenden Legion getäuscht, tötete er in diesen Wäldern den Halbgott Cenarius. Dadurch und wegen der Belastung des Friedens zwischen Horde und Allianz zieht der Splintertreeposten sehr viel Vergeltung auf sich, zumal Überfälle auf Astranaar häufig sind.\n\nOrcs und Tauren halten den Posten jetzt, meist Späher und Wachen.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "Der Steinkrallenpfad",
			short = "Ein gewundener Tunnel führt durch den Fels zwischen Ashenvale und dem Steinkrallengebirge. Er öffnet sich auf der einen Seite westlich des Mystralsees und auf der anderen im Nordwesten der Scherwindklippe.",
			full = "Ein gewundener Tunnel führt durch den Fels zwischen Ashenvale und dem Steinkrallengebirge. Er öffnet sich auf der einen Seite westlich des Mystralsees und auf der anderen im Nordwesten der Scherwindklippe. Kleine Sackgassen zweigen von ihm ab, und seltsame Löcher sind in seine Wände gescheuert. Nichts lebt darin, und auf dem Fels darüber finden sich die Überreste einer alten Straße.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "Lager der Distelfelle",
			short = "Furbolgs des Stammes der Distelfelle haben ihr Heim in diesem Dorf nördlich von Astranaar. Sie sind verderbt und feindselig und greifen jeden an, der ihnen zu nahe kommt.",
			full = "Furbolgs des Stammes der Distelfelle haben ihr Heim in diesem Dorf nördlich von Astranaar. Sie sind verderbt und feindselig und greifen jeden an, der ihnen zu nahe kommt. Zwei wilde Krieger, Dal Blutklaue und Grummelkehle, führen sie an.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "Lager der Warsongarbeiter",
			short = "Orc-Wachen beaufsichtigen Holzfäller und Sammler im Lager der Warsongarbeiter im südöstlichen Ashenvale, östlich des Fallenskysees.",
			full = "Orc-Wachen beaufsichtigen Holzfäller und Sammler im Lager der Warsongarbeiter im südöstlichen Ashenvale, östlich des Fallenskysees. Das Lager liegt weit von jeder Hilfe entfernt, sodass Angreifer der Allianz die Wachen hin und wieder ohne Furcht vor Vergeltung überfallen.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "Das Holzfällerlager der Warsong",
			short = "In den Wäldern von Ashenvale hallen Äxte im Holzfällerlager der Warsong, wo der Kriegshymnenklan die uralten Bäume für Bauholz kahlschlägt.",
			full = "In den Wäldern von Ashenvale hallen Äxte im Holzfällerlager der Warsong, wo der Kriegshymnenklan die uralten Bäume für Bauholz kahlschlägt. Holzfäller, Goblin-Waldzerstörer und Schredder besorgen das Fällen, während Grunzer und Schamanen Wache stehen. Das Lager hat einen Zwinger, und seine Festung ist die Burg Kargathia.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "Xavian",
			short = "Satyrn haben ihr Heim in den Ruinen eines uralten Nachtelfentempels im nordöstlichen Ashenvale gefunden.",
			full = "Satyrn haben ihr Heim in den Ruinen eines uralten Nachtelfentempels im nordöstlichen Ashenvale gefunden. Von den drei Satyrsiedlungen im Wald scheint Xavian das Zentrum ihrer Macht zu sein, denn Prinz Schleifer und Geltharis leben beide hier. Sie verwenden Kriegshymnenöl für ihre Rituale.\n\nDryaden haben die Ruinen angegriffen. Eine von ihnen, Anilia, suchte nach einem Zweig des Cenarius, den die Satyrn gestohlen hatten, und liegt hier tödlich verwundet.",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "Der Zoramstrand",
			short = "Vor der Großen Zerschlagung stand bei diesem Strand eine Nachtelfensiedlung namens Zoram. Die Zerschlagung zerstörte sie, und das Verhüllte Meer nahm, was übrig war.",
			full = "Vor der Großen Zerschlagung stand bei diesem Strand eine Nachtelfensiedlung namens Zoram. Die Zerschlagung zerstörte sie, und das Verhüllte Meer nahm, was übrig war.\n\nHeute halten die Naga die Küste. Gestrandete Schiffe und gestrandete Meerestiere liegen am Sand, und die Naga sind zahlreich. Die Horde unterhält hier einen kleinen Außenposten und bekämpft die Naga der Rächerflossen, die ihr die Küste streitig machen. Auch Blackfathom-Tiefe liegt am Zoramstrand.",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "Zoram'gar-Außenposten",
			short = "Stege ragen über das Wasser am Zoram'gar-Außenposten, einem Hafen der Horde am Zoramstrand. Die Horde hat ihn hier errichtet und bekämpft von ihm aus die Naga der Rächerflossen.",
			full = "Stege ragen über das Wasser am Zoram'gar-Außenposten, einem Hafen der Horde am Zoramstrand. Die Horde hat ihn hier errichtet und bekämpft von ihm aus die Naga der Rächerflossen.",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- Tausend Nadeln: 19 subzones
	[1441] = {
		["camp ethok"] = {
			name = "Camp E'thok",
			short = "Zentauren der Galak halten hier im nordwestlichen Tausend Nadeln ein Lager.",
			full = "Zentauren der Galak halten hier im nordwestlichen Tausend Nadeln ein Lager. Sie überfielen eine Karawane, mit der der Goblin Wizlo Lagerputzer reiste, konnten aber das Gerät nicht an sich bringen, das er am meisten schätzte. Es war seinem wilden Panther um den Hals gebunden.",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "Düsterwolkengipfel",
			short = "Drei kleine Mesas hier sind die Heimat der Tauren der Grimmtotem, mit mehreren kleineren leeren Mesas rundherum. Seilbrücken verbinden die Mesas.",
			full = "Drei kleine Mesas hier sind die Heimat der Tauren der Grimmtotem, mit mehreren kleineren leeren Mesas rundherum. Seilbrücken verbinden die Mesas. Nur zwei Wege führen hinauf, eine natürliche Rampe, die auf eine vierte Mesa steigt und in einer Brücke endet, und eine zweite Brücke. Beide sind gut bewacht.\n\nArnak Grimmtotem und Harb Faulberg führen die Grimmtotem hier an. Zwischen ihnen und einer dunklen Macht, deren Name nicht bekannt ist, läuft ein geheimer Briefwechsel.",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "Freiwindposten",
			short = "Der Freiwindposten steht auf einer Mesa, außer Reichweite der Kriegstrupps der Zentauren der Galak, die unten lagern.",
			full = "Der Freiwindposten steht auf einer Mesa, außer Reichweite der Kriegstrupps der Zentauren der Galak, die unten lagern. Seine Bewohner fahren auf hölzernen Aufzügen vom Canyonboden hinauf, und Seilbrücken steigen von Gipfel zu Gipfel, bis sie das Dorf erreichen. Kreischende Harpyien sind eine geringere Gefahr.\n\nDie Tauren von Freiwind wurden den Grimmtotem auf dem Düsterwolkengipfel gegenüber misstrauisch. Tauren wurden entführt, Agenten dunkler und unbekannter Herkunft kamen und gingen, und man legte den Grimmtotem Morde zur Last, vor allem ihrem Häuptling Arnak Grimmtotem. Als Lakota Windweise ihn abwies, ließ er sie entführen. Ihr Bruder wurde getötet, als er sie verteidigte.",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
		["great lift"] = {
			name = "Der große Aufzug",
			short = "Dieser von den Tauren erbaute Aufzug bringt Reisende zwischen dem Brachland und Tausend Nadeln hin und her. Grish Fernläufer und Kriegerheld Moonhorn halten Wache.",
			full = "Dieser von den Tauren erbaute Aufzug bringt Reisende zwischen dem Brachland und Tausend Nadeln hin und her. Grish Fernläufer und Kriegerheld Moonhorn halten Wache.",
			source = "https://warcraft.wiki.gg/wiki/Great_Lift",
		},
		["highperch"] = {
			name = "Der Steilhang",
			short = "Auf diesem erhöhten Gelände im Westen halten die stolzen Wyvern des Steilhangs ihre Nester.",
			full = "Auf diesem erhöhten Gelände im Westen halten die stolzen Wyvern des Steilhangs ihre Nester. Junge Tauren kommen vom Freiwindposten, um sie zu studieren und Eier aus den angestammten Nistplätzen zu nehmen, aus denen Reittiere für die Horde aufgezogen werden. Der Tauren Pao'ka Bergrausch sitzt hier zwischen den Nestern fest.",
			source = "https://warcraft.wiki.gg/wiki/Highperch",
		},
		["ironstone camp"] = {
			name = "Eisensteinlager",
			short = "Eine kleine Gruppe der Horde lagert an der Grenze der schimmernden Ebene.",
			full = "Eine kleine Gruppe der Horde lagert an der Grenze der schimmernden Ebene. Sie wurde ausgesandt, um die Zwergenbuddler von der Rustmaul-Grabungsstätte zu vertreiben, und bekam mehr, als sie erwartet hatte, als Silithiden aus einer nahen Höhle hervorbrachen und sie angriffen. Moktar Krin, der sie anführt, schickt die anderen aus, um die Silithiden zu töten, die die Grabungsstätte befallen.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Camp",
		},
		["mirage raceway"] = {
			name = "Illusionenrennbahn",
			short = "Ein Goblin namens Pozzik und ein Gnom namens Fizzel Kupferbolz behaupteten beide, ihr eigenes Volk habe die besseren Ingenieure.",
			full = "Ein Goblin namens Pozzik und ein Gnom namens Fizzel Kupferbolz behaupteten beide, ihr eigenes Volk habe die besseren Ingenieure. Um das zu beweisen, bauten sie eine Rennbahn und Raketenwagen, die darauf fahren sollten, und warben Teams an, die sie steuern.\n\nHier rasen täglich Dragster der Goblins und der Gnome. Anhänger von Horde und Allianz kommen, um ihre Favoriten anzufeuern, und zwielichtige Gestalten kommen, um auf den Sieger zu wetten. Nach jedem Rennen suchen die beiden Teams hastig nach Verbesserungen, die ihrer Seite einen Vorteil verschaffen.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
		},
		["razorfen downs"] = {
			name = "Die Hügel von Razorfen",
			short = "Der Legende nach ließ das Blut des Halbgotts Agamaggan dort, wo er fiel, große Massen dorniger Ranken wachsen.",
			full = "Der Legende nach ließ das Blut des Halbgotts Agamaggan dort, wo er fiel, große Massen dorniger Ranken wachsen. Die Stacheleber verehren das größte Gewirr von ihnen als seine Ruhestätte, und die Hügel von Razorfen sind ihre angestammte Begräbnisstätte. Der Eingang soll Agamaggans eigener Rachen sein, eine gewölbte Lücke in der äußeren Kuppel, so verborgen, dass ihn nur findet, wer weiß, wo er suchen muss.\n\nDie Hügel sind die traditionelle Hauptstadt der Stacheleber. Die Hohepriester des Totenkopfstamms leben im dornigen Labyrinth unter einer großen Armee treuer Krieger. Nach dem Dritten Krieg übernahmen der Lich Amnennar der Kältebringer und Agenten der Geißel die Herrschaft über die Stacheleber und machten das Labyrinth zu einer Bastion untoter Macht. Die Stacheleber kämpfen darum, ihre Stadt zurückzugewinnen, bevor er seinen Griff über das Brachland ausdehnen kann.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs",
		},
		["roguefeather den"] = {
			name = "Bau der Wildfedern",
			short = "Harpyien drängen sich in dieser kleinen Höhle im südlichen Zentrum von Tausend Nadeln.",
			full = "Harpyien drängen sich in dieser kleinen Höhle im südlichen Zentrum von Tausend Nadeln. Sie kreischen jeden an, der sich nähert, und im hinteren Teil des Baus horten sie die Nahrung, die sie gesammelt haben, und bewachen sie eifersüchtig.",
			source = "https://warcraft.wiki.gg/wiki/Roguefeather_Den",
		},
		["rustmaul dig site"] = {
			name = "Die Rustmaul-Grabungsstätte",
			short = "Zwerge der Forscherliga legten hier alte Ruinen frei, als ein Kriegstrupp der Horde unter Moktar Krin sie angriff und alle tötete. Der Kampf störte ein Nest von Silithiden in einer Höhle der Grabungsstätte auf.",
			full = "Zwerge der Forscherliga legten hier alte Ruinen frei, als ein Kriegstrupp der Horde unter Moktar Krin sie angriff und alle tötete. Der Kampf störte ein Nest von Silithiden in einer Höhle der Grabungsstätte auf. Der Schwarm, der herausquoll, vertrieb den ohnehin geschwächten Kriegstrupp. Die Grabungsstätte ist nun verlassen, und die Silithiden halten das Gelände.",
			source = "https://warcraft.wiki.gg/wiki/Rustmaul_Dig_Site",
		},
		["screeching canyon"] = {
			name = "Der kreischende Canyon",
			short = "Kreischende Harpyien verseuchen diesen Canyon im Süden von Tausend Nadeln, aggressiv und laut. An seinem Ende liegt der Bau der Wildfedern.",
			full = "Kreischende Harpyien verseuchen diesen Canyon im Süden von Tausend Nadeln, aggressiv und laut. An seinem Ende liegt der Bau der Wildfedern.",
			source = "https://warcraft.wiki.gg/wiki/Screeching_Canyon",
		},
		["shimmering flats"] = {
			name = "Die schimmernde Ebene",
			short = "Ein Segelschiff liegt zerschellt im nördlichen Teil der schimmernden Ebene, weit von jedem Wasser entfernt. Es zeigt, was dieser Ort einst war, das Bett eines Sees, der ausgetrocknet ist.",
			full = "Ein Segelschiff liegt zerschellt im nördlichen Teil der schimmernden Ebene, weit von jedem Wasser entfernt. Es zeigt, was dieser Ort einst war, das Bett eines Sees, der ausgetrocknet ist. Auf dem flachen Salz wächst hier, am südöstlichen Ende von Tausend Nadeln, nichts. Nur Basilisken, Skorpide, Schildkröten und Geier leben hier.\n\nDie flache Weite zog Goblins und Gnome an, die hier ihre Maschinen rennen lassen, und ihre Erfindungen sind oft instabil. Krater durchlöchern den Boden, und die Wracks unzähliger gescheiterter Apparate liegen über das Salz verstreut.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Flats",
		},
		["splithoof crag"] = {
			name = "Spalthufklippe",
			short = "Die Zentauren der Galak haben ihr Dorf an der Nordwand von Tausend Nadeln, knapp östlich des Düsterwolkengipfels.",
			full = "Die Zentauren der Galak haben ihr Dorf an der Nordwand von Tausend Nadeln, knapp östlich des Düsterwolkengipfels. In einer Höhle im Berg, in der Mitte des Dorfes, liegt die Spalthufhöhle, wo sie ein uraltes Artefakt namens Gespaltener Huf aufbewahren.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Crag",
		},
		["splithoof hold"] = {
			name = "Spalthufhöhle",
			short = "Diese Höhle in der Spalthufklippe ist die Festung der Zentauren der Galak. Die Uralte Feuerschale steht darin und bewacht den Gespaltenen Huf, und die Heilige Flamme darauf brennt ewig.",
			full = "Diese Höhle in der Spalthufklippe ist die Festung der Zentauren der Galak. Die Uralte Feuerschale steht darin und bewacht den Gespaltenen Huf, und die Heilige Flamme darauf brennt ewig.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Hold",
		},
		["tahonda ruins"] = {
			name = "Ruinen von Tahonda",
			short = "Vor langer Zeit verfiel hier ein Taurendorf und versank unter den Sanden der schimmernden Ebene. Über es ist wenig bekannt.",
			full = "Vor langer Zeit verfiel hier ein Taurendorf und versank unter den Sanden der schimmernden Ebene. Über es ist wenig bekannt. Salzsteinbasilisken leben zwischen den Ruinen, und sie könnten der Grund sein, warum das Dorf aufgegeben wurde.\n\nAndere Hinweise deuten auf einen Angriff feindlicher Kräfte. An einem der Ledergebäude sind zwei Sätze von je drei parallelen Rissen. Die Ruinen liegen in den südlichen Ausläufern der Ebene, nahe dem Pfad durch die Berge nach Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Tahonda_Ruins",
		},
		["weathered nook"] = {
			name = "Der Wetterwinkel",
			short = "Dorn Plainstalker und Prate Wolkendeuter leben in einer kleinen, gut versteckten Höhle in der Nordwand von Tausend Nadeln. Dorn versucht, Angehörigen der Horde etwas über Glauben, Ausdauer und Stärke beizubringen.",
			full = "Dorn Plainstalker und Prate Wolkendeuter leben in einer kleinen, gut versteckten Höhle in der Nordwand von Tausend Nadeln. Dorn versucht, Angehörigen der Horde etwas über Glauben, Ausdauer und Stärke beizubringen.",
			source = "https://warcraft.wiki.gg/wiki/Weathered_Nook",
		},
		["weazels crater"] = {
			name = "Weazels Krater",
			short = "Ein großer, tiefer Krater öffnet sich im nördlichen Teil der schimmernden Ebene. Woher er stammt, ist ein Rätsel. Sein Name deutet entweder darauf hin, wer ihn fand oder wer ihn schuf.",
			full = "Ein großer, tiefer Krater öffnet sich im nördlichen Teil der schimmernden Ebene. Woher er stammt, ist ein Rätsel. Sein Name deutet entweder darauf hin, wer ihn fand oder wer ihn schuf. Geröll und kleinere Krater liegen verstreut umher, und Goblins und Gnome fahren in dieser Gegend gefährliche Wagen in Rennen, sodass er das Werk einer instabilen Erfindung sein könnte. Salzsteinbasilisken leben jetzt darin.",
			source = "https://warcraft.wiki.gg/wiki/Weazel's_Crater",
		},
		["whitereach post"] = {
			name = "Weißgipfelposten",
			short = "Entlang der Straße nahe Camp E'thok steht ein kleines Lager der Horde. Kanati Greycloud und der Goblin Wizlo Lagerputzer gehören zu denen, die hier bleiben.",
			full = "Entlang der Straße nahe Camp E'thok steht ein kleines Lager der Horde. Kanati Greycloud und der Goblin Wizlo Lagerputzer gehören zu denen, die hier bleiben.",
			source = "https://warcraft.wiki.gg/wiki/Whitereach_Post",
		},
		["windbreak canyon"] = {
			name = "Schlucht der heulenden Winde",
			short = "Windnattern füllen diesen Canyon mit ihren Nestern. Er bedeckt den größten Teil des Landes zwischen dem Freiwindposten und der schimmernden Ebene, auf der Nordseite der Straße.",
			full = "Windnattern füllen diesen Canyon mit ihren Nestern. Er bedeckt den größten Teil des Landes zwischen dem Freiwindposten und der schimmernden Ebene, auf der Nordseite der Straße.",
			source = "https://warcraft.wiki.gg/wiki/Windbreak_Canyon",
		},
	},
	-- Steinkrallengebirge: 18 subzones
	[1442] = {
		["blackwolf river"] = {
			name = "Schwarzwolfschnellen",
			short = "Die Schwarzwolfschnellen fließen aus dem Felskesselsee und durch das Tal der Scherwindklippe. Es ist ein kleiner Fluss, und ein verdreckter.",
			full = "Die Schwarzwolfschnellen fließen aus dem Felskesselsee und durch das Tal der Scherwindklippe. Es ist ein kleiner Fluss, und ein verdreckter. Das Abholzen des Tals durch die Venture Co. hat sein Wasser vergiftet.",
			source = "https://warcraft.wiki.gg/wiki/Blackwolf_River",
		},
		["boulderslide cavern"] = {
			name = "Steinschlaghöhle",
			short = "Steinschlagkobolde nisten in dieser Höhle am Ende der Klamm. Sie bauen rastlos Resonit ab, einen seltenen violetten Kristall, der leuchtet und eine Spur irdener Magie trägt, und bewachen ihn mit ihrem Leben.",
			full = "Steinschlagkobolde nisten in dieser Höhle am Ende der Klamm. Sie bauen rastlos Resonit ab, einen seltenen violetten Kristall, der leuchtet und eine Spur irdener Magie trägt, und bewachen ihn mit ihrem Leben.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Cavern",
		},
		["boulderslide ravine"] = {
			name = "Steinschlagklamm",
			short = "Widder weiden an den Hängen dieser kleinen Klamm, und gelegentlich kreist ein Klippenstürmer darüber. Sie führt zur Höhle, in der die Steinschlagkobolde nisten.",
			full = "Widder weiden an den Hängen dieser kleinen Klamm, und gelegentlich kreist ein Klippenstürmer darüber. Sie führt zur Höhle, in der die Steinschlagkobolde nisten.\n\nGegenüber dieser Höhle liegt eine kleine verlassene Höhle. Fässer stehen darin, grobe Fackeln erhellen sie, und die Wände tragen Stammeskunst, die ein Werk der Tauren sein könnte.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Ravine",
		},
		["camp aparaje"] = {
			name = "Camp Aparaje",
			short = "Grimmtotem-Truppen vom Posten der Grimmtotem unter Grundig Düsterwolke fielen über Camp Aparaje her, ein Taurendorf im östlichen Steinkrallengebirge, und ermordeten die meisten, die dort lebten.",
			full = "Grimmtotem-Truppen vom Posten der Grimmtotem unter Grundig Düsterwolke fielen über Camp Aparaje her, ein Taurendorf im östlichen Steinkrallengebirge, und ermordeten die meisten, die dort lebten. Makaba Flachhuf, der hier mit seiner Tochter Kaya sein Heim hatte, gehörte zu den Überlebenden.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Aparaje",
		},
		["charred vale"] = {
			name = "Das verbrannte Tal",
			short = "Das verbrannte Tal war einst ein grünes Tal. Harpyien der Blutfurien nannten es ihre Heimat, und Treants durchschritten seinen Wald als Wächter.",
			full = "Das verbrannte Tal war einst ein grünes Tal. Harpyien der Blutfurien nannten es ihre Heimat, und Treants durchschritten seinen Wald als Wächter.\n\nDann kamen Goblins der Venture Co. und verwüsteten es. Die Geister des Tals gerieten in Zorn, und zahlreiche Elementare brachen los, als die Treants die Goblins zurückschlugen. Die Waffen der Goblins verderbten die Treants wahrscheinlich, als die Goblins abzogen.\n\nDas Tal liegt nun größtenteils in Flammen und Lava, im Südwesten des Steinkrallengebirges. Geschwärzte Urtume und versengte Basilisken leben auf dem brennenden Boden.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Vale",
		},
		["cragpool lake"] = {
			name = "Felskesselsee",
			short = "Ein riesiges Bauwerk der Venture Co. spannt sich über diesen kleinen See. Gerenzo Pfeifzang überwacht von seiner Plattform aus das Abholzen der Scherwindklippe.",
			full = "Ein riesiges Bauwerk der Venture Co. spannt sich über diesen kleinen See. Gerenzo Pfeifzang überwacht von seiner Plattform aus das Abholzen der Scherwindklippe. Der See selbst ist tabu, weil ein gewaltiger Fisch namens Felskiefer darin lebt.",
			source = "https://warcraft.wiki.gg/wiki/Cragpool_Lake",
		},
		["greatwood vale"] = {
			name = "Hochwipfeltal",
			short = "Bewaldete Vorgebirge umschließen dieses Tal, und spärliche Nadelbäume wachsen hier, selbst wo die Berge weiter im Süden weniger bewaldet sind.",
			full = "Bewaldete Vorgebirge umschließen dieses Tal, und spärliche Nadelbäume wachsen hier, selbst wo die Berge weiter im Süden weniger bewaldet sind.\n\nDie Grimmtotem halten das Tal seit ihrem Angriff auf Camp Aparaje, und Makaba Flachhuf, einer der Überlebenden, will, dass sie zur Strecke gebracht werden.",
			source = "https://warcraft.wiki.gg/wiki/Greatwood_Vale",
		},
		["grimtotem post"] = {
			name = "Posten der Grimmtotem",
			short = "Krieger der Grimmtotem aller Art, von Schlägern und Grobianen bis zu Zauberern und Söldnern, patrouillieren am Posten und an den Hängen ringsum.",
			full = "Krieger der Grimmtotem aller Art, von Schlägern und Grobianen bis zu Zauberern und Söldnern, patrouillieren am Posten und an den Hängen ringsum. Er ist die Operationsbasis des Stammes der Grimmtotem im Steinkrallengebirge. Der wilde Häuptling Grundig Düsterwolke führt sie an.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Post",
		},
		["malakajin"] = {
			name = "Malaka'jin",
			short = "Trolle der Darkspear leben in Malaka'jin, einem kleinen Dorf der Horde knapp südlich des Postens der Grimmtotem.",
			full = "Trolle der Darkspear leben in Malaka'jin, einem kleinen Dorf der Horde knapp südlich des Postens der Grimmtotem. Die Jäger verdienen bescheiden, indem sie ihren Fang an Reisende der Horde verkaufen, die hier vorbeikommen. Die Horde will von hier aus gegen den Stamm der Grimmtotem in diesen Bergen losschlagen.",
			source = "https://warcraft.wiki.gg/wiki/Malaka'jin",
		},
		["mirkfallon lake"] = {
			name = "Mirkfallonsee",
			short = "Der Mirkfallonsee füllt ein Becken im Zentrum des Steinkrallengebirges, mit einem Hügel, der mitten im Wasser aufragt.",
			full = "Der Mirkfallonsee füllt ein Becken im Zentrum des Steinkrallengebirges, mit einem Hügel, der mitten im Wasser aufragt. Wyvern nisten rund um den See und oben auf den Scherwindhöhen darüber, und Schleime und Donnerechsen streifen an seinen Ufern.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Lake",
		},
		["sishir canyon"] = {
			name = "Sishircanyon",
			short = "Kluftmoosspinnen haben den Sishircanyon vollständig eingenommen. Ihre Eier und Netze bedecken die Absätze und Mulden im Stein, und tief im Inneren wartet Besseleth, die mächtigste ihrer Brut.",
			full = "Kluftmoosspinnen haben den Sishircanyon vollständig eingenommen. Ihre Eier und Netze bedecken die Absätze und Mulden im Stein, und tief im Inneren wartet Besseleth, die mächtigste ihrer Brut.",
			source = "https://warcraft.wiki.gg/wiki/Sishir_Canyon",
		},
		["stonetalon peak"] = {
			name = "Der Steinkrallengipfel",
			short = "Am äußersten nordwestlichen Ende der Bergkette, in einem grünen Bergtal, steht der Steinkrallengipfel. Der Berg gilt als heilig, und Magie durchströmt seinen Stein.",
			full = "Am äußersten nordwestlichen Ende der Bergkette, in einem grünen Bergtal, steht der Steinkrallengipfel. Der Berg gilt als heilig, und Magie durchströmt seinen Stein.\n\nIm Dritten Krieg gründeten Jaina Proudmoore und ihre Expedition nahe dem Eingang zu den Höhlen unter dem Gipfel eine Basis. Thrall und seine Horde kamen später, auf der Suche nach dem Orakel, und in diesen Höhlen standen die Allianz und die Horde eine Zeit lang gemeinsam gegen die Brennende Legion.\n\nNun halten die Nachtelfen und die Allianz den Gipfel, und die Druiden des Krallenbaus betreuen das Tal.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Peak",
		},
		["sun rock retreat"] = {
			name = "Sonnenfels",
			short = "In vergangenen Zeiten pilgerten Tauren zum Sonnenfels, um die Riten zu vollziehen, die in die Geisterwelt hinüberführen, denn der Ort hat eine starke Bindung an dieses Reich.",
			full = "In vergangenen Zeiten pilgerten Tauren zum Sonnenfels, um die Riten zu vollziehen, die in die Geisterwelt hinüberführen, denn der Ort hat eine starke Bindung an dieses Reich. Es heißt, An'she selbst habe einst den Berg geküsst, auf dem die Zuflucht nun steht.\n\nOrcs und Tauren halten sie jetzt gemeinsam, verborgen zwischen den Gipfeln südlich des Mirkfallonsees. Sie ist die geschäftigste Siedlung im Gebirge, und ihre Bewohner arbeiten daran, wiederherzustellen, was die Venture Co. und andere bösartige Kräfte dem Land entrissen haben.",
			source = "https://warcraft.wiki.gg/wiki/Sun_Rock_Retreat",
		},
		["talon den"] = {
			name = "Der Krallenbau",
			short = "Auf dem Steinkrallengipfel öffnet sich die Erde zum Krallenbau, einem Grabhügelbau. Mirkfallondryaden und Mirkfallonbewahrer haben dort ihr Heim, zusammen mit Cenarischen Verwaltern der Nachtelfen.",
			full = "Auf dem Steinkrallengipfel öffnet sich die Erde zum Krallenbau, einem Grabhügelbau. Mirkfallondryaden und Mirkfallonbewahrer haben dort ihr Heim, zusammen mit Cenarischen Verwaltern der Nachtelfen.",
			source = "https://warcraft.wiki.gg/wiki/Talon_Den",
		},
		["talondeep path"] = {
			name = "Der Steinkrallenpfad",
			short = "Der Steinkrallenpfad windet sich von Ashenvale zur Scherwindklippe durch die Berge. Kleine Sackgassen und seltsame Löcher unterbrechen seine Wände, und nichts lebt darin.",
			full = "Der Steinkrallenpfad windet sich von Ashenvale zur Scherwindklippe durch die Berge. Kleine Sackgassen und seltsame Löcher unterbrechen seine Wände, und nichts lebt darin.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["webwinder path"] = {
			name = "Weberpass",
			short = "Spinnen, Widder und Donnerechsen leben entlang des Weberpasses, der Hauptstraße zwischen Malaka'jin und dem Mirkfallonsee.",
			full = "Spinnen, Widder und Donnerechsen leben entlang des Weberpasses, der Hauptstraße zwischen Malaka'jin und dem Mirkfallonsee.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Path",
		},
		["windshear crag"] = {
			name = "Die Scherwindklippe",
			short = "Die Scherwindklippe war ein gewaltiger Urwald, grün und dicht in ihrem Tal. Jetzt gibt es dort Baumstümpfe, verdrecktes Wasser und Maschinen, die endlos ächzen.",
			full = "Die Scherwindklippe war ein gewaltiger Urwald, grün und dicht in ihrem Tal. Jetzt gibt es dort Baumstümpfe, verdrecktes Wasser und Maschinen, die endlos ächzen. Die von Goblins geführte Venture Co. hat sie abgeholzt, und das ganze Unternehmen untersteht einem Lepragnom, Gerenzo Pfeifzang. Sein Fleisch scheint zu verfaulen, und er hat Metall und Zahnräder auf seinen Körper gepfropft. Er baute den Super-Schnitter 6000, eine Maschine, die die größten Bäume zu Sägemehl machen kann, und er überwacht die Klippe von einer Plattform über dem Felskesselsee.\n\nAndere wollen ihn loswerden. Direktor Riddlevox von der Tüftlerunion von Untermine will Gerenzo tot sehen, und der Goblin Ziz Fizziks, der im Auftrag des Direktors handelt, lauert in der Klippe.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Crag",
		},
		["windshear mine"] = {
			name = "Scherwindmine",
			short = "Scherwindkobolde besetzen die Scherwindmine, eine Zinnmine am Ende der Schwarzwolfschnellen in der südöstlichen Ecke der Scherwindklippe.",
			full = "Scherwindkobolde besetzen die Scherwindmine, eine Zinnmine am Ende der Schwarzwolfschnellen in der südöstlichen Ecke der Scherwindklippe. Sie graben ihr Zinn für die Venture Co.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Mine",
		},
	},
	-- Desolace: 20 subzones
	[1443] = {
		["bolgans hole"] = {
			name = "Bolgans Loch",
			short = "Khan Shaka und die angesehensten Mitglieder des Klans der Gelkis leben in dieser Höhle. Darin wachsen blaue Kristalle, die Tränen der Theradras genannt werden.",
			full = "Khan Shaka und die angesehensten Mitglieder des Klans der Gelkis leben in dieser Höhle. Darin wachsen blaue Kristalle, die Tränen der Theradras genannt werden. Die Schamanen des Klans horten sie und glauben, die Steine trügen den Schutz von Prinzessin Theradras.",
			source = "https://warcraft.wiki.gg/wiki/Bolgan's_Hole",
		},
		["ethel rethor"] = {
			name = "Ethel Rethor",
			short = "Weit im Nordwesten von Desolace liegt eine Nachtelfenruine größtenteils unter Wasser.",
			full = "Weit im Nordwesten von Desolace liegt eine Nachtelfenruine größtenteils unter Wasser. Nur ein einzelner Turm ragt über die Oberfläche, durch eine kleine Brücke mit dem Ufer verbunden, die an einem verschlossenen Eingang endet. Naga, die viele der Elfenruinen an der Küste bewohnen, haben auch diese eingenommen.",
			source = "https://warcraft.wiki.gg/wiki/Ethel_Rethor",
		},
		["gelkis village"] = {
			name = "Gelkis",
			short = "Der Klan der Gelkis hat sein Hauptdorf in einem Ring um eine weite Schlucht im südwestlichen Desolace.",
			full = "Der Klan der Gelkis hat sein Hauptdorf in einem Ring um eine weite Schlucht im südwestlichen Desolace. Brücken verbinden die Klippen und Felsen innerhalb der Schlucht und führen zu einer Höhle in der südlichen Bergwand, wo der Khan der Gelkis lebt.\n\nDas Dorf liegt dicht an der Haupt-Nord-Süd-Straße, was die Straße für jeden gefährlich macht, der sie bereist. In letzter Zeit haben sich die Zentauren ausgebreitet und Hütten auf der Ostseite der Straße gebaut, nahe dem See.",
			source = "https://warcraft.wiki.gg/wiki/Gelkis_Village",
		},
		["ghost walker post"] = {
			name = "Geistwandlerposten",
			short = "Gurda Wildmähne führt die Taurenschamanen, die diesen kleinen Außenposten neben dem Kodofriedhof halten.",
			full = "Gurda Wildmähne führt die Taurenschamanen, die diesen kleinen Außenposten neben dem Kodofriedhof halten. Die Schamanen geleiten die Kodos in der Nähe sanft in ihr nächstes Leben und sprechen manchmal mit den Geistern der Toten. Eine Schar Orcs, von Kriegshäuptling Thrall entsandt, hält den Posten mit ihnen.\n\nDer Außenposten ist schutzlos und kahl. Er hat kein Gasthaus und kaum mehr als das Nötigste. Von hier aus führt die Horde Krieg gegen die Burning Blade, ihre Diener und die Zentaurenstämme.",
			source = "https://warcraft.wiki.gg/wiki/Ghost_Walker_Post",
		},
		["kodo graveyard"] = {
			name = "Der Kodofriedhof",
			short = "Hier liegt die letzte Ruhestätte der Kodos. Ihre Knochen liegen über den Boden verstreut, und viele scheinen von Tieren zu stammen, die weit größer waren als die Kodos, die heute durch das Land ziehen.",
			full = "Hier liegt die letzte Ruhestätte der Kodos. Ihre Knochen liegen über den Boden verstreut, und viele scheinen von Tieren zu stammen, die weit größer waren als die Kodos, die heute durch das Land ziehen. Wer die Knochen nimmt, merkt, dass die Toten nicht still sind, denn die Geister der Kodos erheben sich, um sie zu bewachen.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Graveyard",
		},
		["kolkar village"] = {
			name = "Kolkar",
			short = "Der Klan der Kolkar hält den östlichen Rand von Desolace, wo seine angestammten Gründe am Gebirge entlang liegen. Dieses Dorf ist das Zentrum seiner Macht.",
			full = "Der Klan der Kolkar hält den östlichen Rand von Desolace, wo seine angestammten Gründe am Gebirge entlang liegen. Dieses Dorf ist das Zentrum seiner Macht. Hier sind die Kolkar der kleinste und einflussloseste der Stämme, und doch hat sich kein anderer Zentaurenclan so weit über Kalimdor ausgebreitet. Sie unterhalten Dörfer und Außenposten im Brachland und in Durotar.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Village",
		},
		["kormeks hut"] = {
			name = "Kormeks Hütte",
			short = "Eine ärmliche Hütte steht auf den kargen Ebenen im nördlichen Zentrum von Desolace. Darin lebt Willa, ein freundliches Mitglied des Schattenhammers.",
			full = "Eine ärmliche Hütte steht auf den kargen Ebenen im nördlichen Zentrum von Desolace. Darin lebt Willa, ein freundliches Mitglied des Schattenhammers. Im Gehege draußen liegen Kodoknochen verstreut, und Bibbly F'utzbuckel tanzt zwischen ihnen, begeistert über das Geld, das die Knochen einbringen könnten. Niemand weiß, wohin Kormek, der Namensgeber der Hütte, gegangen ist.",
			source = "https://warcraft.wiki.gg/wiki/Kormek's_Hut",
		},
		["magram village"] = {
			name = "Magram",
			short = "Der Klan der Magram lebt an den Ufern und auf den Inseln einer Kette verschmutzter gelber Teiche im südöstlichen Desolace.",
			full = "Der Klan der Magram lebt an den Ufern und auf den Inseln einer Kette verschmutzter gelber Teiche im südöstlichen Desolace. Grobe Brücken verbinden die Inseln miteinander und mit dem Ufer, und die Jurten und Pavillons des Klans stehen zwischen den Teichen verstreut. Die Magram befinden sich im Krieg mit dem Klan der Gelkis.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Village",
		},
		["mannoroc coven"] = {
			name = "Mannorocs Koven",
			short = "Die Nachtelfenruinen hier tragen ihren Namen nach Mannoroth, dem gefürchteten Grubenlord. Die Erde war schon tot, und die Dämonen, die hier leben, haben sie mit Teufelsmagie noch weiter verwüstet.",
			full = "Die Nachtelfenruinen hier tragen ihren Namen nach Mannoroth, dem gefürchteten Grubenlord. Die Erde war schon tot, und die Dämonen, die hier leben, haben sie mit Teufelsmagie noch weiter verwüstet. Sie hängt dick in der Luft, und ein tödlicher Schleier legt sich über jeden, der den Koven betritt.\n\nKultisten der Burning Blade beschworen diese Dämonen durch eine Reihe magischer Portale. Höllenbestien, Sukkubi, Teufelshunde und Teufelswachen streifen nun durch die Ruinen. Lord Azrethoc befehligt sie, und der orcische Hexenmeister Jugkar Grimm'rod steht hier für die Burning Blade. Es ist die größte Ansammlung von Dämonen im zentralen Kalimdor, und immer wieder öffnen sich neue Portale.",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "Die Nijelspitze",
			short = "Die Allianz und der Zirkel des Cenarius halten einen Außenposten zwischen Nachtelfenruinen in den nördlichen Bergen. Niemand dort kann sagen, wer Nijel war.",
			full = "Die Allianz und der Zirkel des Cenarius halten einen Außenposten zwischen Nachtelfenruinen in den nördlichen Bergen. Niemand dort kann sagen, wer Nijel war.\n\nBewahrer Marandis und seine Dryadenschwestern nutzen den Außenposten als Basis. Sie kamen, um Prinzessin Theradras zu töten und den Leichnam Zaetars aus Maraudon zu holen und ins Steinkrallengebirge heimzubringen. Die Armee von Stormwind unterhält hier eine Wache unter Hauptmann Pentigast, gegen die Zentaurenclans. Er ist sicher, dass derjenige der Gelkis und der Magram, der ihren Krieg gewinnt, kühn genug werden wird, die Besitzungen der Allianz zu bedrohen, und er will herausfinden, wie die Zentauren geschlagen werden können.",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "Die Insel Ranazjar",
			short = "Naga leben auf dieser kleinen, felsigen Insel vor der Nordwestküste von Desolace. Nachtelfenruinen stehen zwischen den Steinen, und sie scheinen zur selben uralten Stadt zu gehören wie Ethel Rethor.",
			full = "Naga leben auf dieser kleinen, felsigen Insel vor der Nordwestküste von Desolace. Nachtelfenruinen stehen zwischen den Steinen, und sie scheinen zur selben uralten Stadt zu gehören wie Ethel Rethor. Auch eine Statue von Königin Azshara steht dort.",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "Sargeron",
			short = "Satyrn der Zornsäer haben die Ruinen einer Nachtelfenstadt übernommen. Die Stadt liegt seit dem Krieg der Ahnen zerbrochen, und ihr erster Name ist verloren.",
			full = "Satyrn der Zornsäer haben die Ruinen einer Nachtelfenstadt übernommen. Die Stadt liegt seit dem Krieg der Ahnen zerbrochen, und ihr erster Name ist verloren. Die Satyrn nannten sie Sargeron um, nach ihrem Dämonenmeister Sargeras.",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "Sar'theris-Strand",
			short = "Die Küste ist der einzige Teil von Desolace mit Farbe. Das Innere ist grau und düster, doch hier ist das Gras grün, und die Sonne kommt heraus.",
			full = "Die Küste ist der einzige Teil von Desolace mit Farbe. Das Innere ist grau und düster, doch hier ist das Gras grün, und die Sonne kommt heraus. Meeresriesen und Naga drängen sich im Wasser, und Makrura teilen sich den Strand. Ein kleines Boot liegt zerschmettert im Sand unterhalb von Ethel Rethor.",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "Scrabblescrews Lager",
			short = "Smeed Schraubenbuddel lebt in einem kleinen Goblinlager unweit des Kodofriedhofs. Er ist ein unternehmungslustiger Goblin, der eine Kodokarawane unterhält.",
			full = "Smeed Schraubenbuddel lebt in einem kleinen Goblinlager unweit des Kodofriedhofs. Er ist ein unternehmungslustiger Goblin, der eine Kodokarawane unterhält.",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "Shadowbreakklamm",
			short = "Die Kultisten der Burning Blade haben aus dieser Klamm in den Bergen einen gut versteckten Zufluchtsort gemacht. Riesige Pilze wachsen zwischen ihren Felsen.",
			full = "Die Kultisten der Burning Blade haben aus dieser Klamm in den Bergen einen gut versteckten Zufluchtsort gemacht. Riesige Pilze wachsen zwischen ihren Felsen. Ein Beschwörungskreis, behängt mit riesigen Ketten, liegt in ihrer Mitte.",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "Shadowprey",
			short = "Trolle der Darkspear bauten dieses Fischerdorf am südlichen Ende der Küste von Desolace, und sie leben von dem, was das Meer ihnen gibt.",
			full = "Trolle der Darkspear bauten dieses Fischerdorf am südlichen Ende der Küste von Desolace, und sie leben von dem, was das Meer ihnen gibt. Ihr Fang ist immer gefragt, und sie versorgen den Außenposten der Tauren im Landesinneren. In letzter Zeit schmaust ein gieriger Orca namens Blubberwampe an den Fischen nahe dem Dorf, und die Trolle können kaum noch etwas fangen.\n\nSelendra, eine Dryade des Zirkels des Cenarius, hält sich in der Nähe auf und sucht nach den Überresten von Zaetar. Das Gasthaus ist luftig, und Gäste wachen mit Blick auf das Wasser auf.",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "Tethris Aran",
			short = "Nördlich der Festung Thunder Axe liegen die Ruinen einer Nachtelfensiedlung, vermutlich in der Großen Zerschlagung zerstört. Nur die wilden Geschöpfe Desolaces leben zwischen den zerbrochenen Steinen.",
			full = "Nördlich der Festung Thunder Axe liegen die Ruinen einer Nachtelfensiedlung, vermutlich in der Großen Zerschlagung zerstört. Nur die wilden Geschöpfe Desolaces leben zwischen den zerbrochenen Steinen.",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "Festung Thunder Axe",
			short = "Kohor führt den Kult der Burning Blade von dieser Festung im nordwestlichen Desolace aus. Ihre Mauern umschließen eine Kaserne, eine Höhle und mehrere Wachtürme.",
			full = "Kohor führt den Kult der Burning Blade von dieser Festung im nordwestlichen Desolace aus. Ihre Mauern umschließen eine Kaserne, eine Höhle und mehrere Wachtürme. Die Kultisten haben einen Weg gefunden, einen sehr mächtigen Dämon namens Nazargen zu beschwören.\n\nDer Kult stahl das Zepter des Lichts von den Naga, ein Artefakt von unermesslicher Macht, und bewahrt es hier auf. Tyranis Malem lebt ebenfalls innerhalb der Mauern, ein Verräter an seinem eigenen Volk und ein Pionier der Dämonenmagie.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "Tal der Knochen",
			short = "Skelette drängen sich auf dieser Klippe am südlichen Rand von Desolace, und Zentaurennekromanten gehen unter ihnen umher. Auch die Geister des Klans der Magram suchen sie heim.",
			full = "Skelette drängen sich auf dieser Klippe am südlichen Rand von Desolace, und Zentaurennekromanten gehen unter ihnen umher. Auch die Geister des Klans der Magram suchen sie heim. Zwei riesige Skelette liegen gegen die Klippenwände gesunken, die Toten Goliaths, und niemand weiß, woher sie kamen.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "Das Tal der Speere",
			short = "Der Zentaurenclan der Maraudine lebt in diesem Tal im westlichen Desolace. Zu Fuß ist es nur durch schmale Bergpässe im Süden und im Osten zu betreten.",
			full = "Der Zentaurenclan der Maraudine lebt in diesem Tal im westlichen Desolace. Zu Fuß ist es nur durch schmale Bergpässe im Süden und im Osten zu betreten. An seinem südwestlichen Ende liegt der Eingang nach Maraudon, dem üblen Ort, an dem die Zentaurenrasse geboren wurde.\n\nUnter den Zentauren, gefangen gehalten, ist Melizza Brummsumms.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
	},
	-- Feralas: 28 subzones
	[1444] = {
		["camp mojache"] = {
			name = "Camp Mojache",
			short = "Die Tauren von Camp Mojache haben ihr Dorf oberhalb des Wildwindsees errichtet, quer über einem schnellen Bach, der in den See hinabfließt.",
			full = "Die Tauren von Camp Mojache haben ihr Dorf oberhalb des Wildwindsees errichtet, quer über einem schnellen Bach, der in den See hinabfließt. Sie sind für ihre dicken Felle bekannt, und ihre Krieger schützen Reisende mit großem Mut vor den Gefahren von Feralas.\n\nGnolle der Waldpfoten überfallen das Lager, und ihre Raserei nimmt zu.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "Düsterbruch",
			short = "Vor zwölftausend Jahren errichtete eine verborgene Sekte nachtelfischer Zauberer Eldre'Thalas, um die kostbarsten arkanen Geheimnisse von Königin Azshara zu hüten.",
			full = "Vor zwölftausend Jahren errichtete eine verborgene Sekte nachtelfischer Zauberer Eldre'Thalas, um die kostbarsten arkanen Geheimnisse von Königin Azshara zu hüten. Unter ihren Hochgeborenen waren die Shen'dralar, ein Zirkel von Arkanisten. Eine von ihnen, Millicent Serene, schuf die Frucht der Fruchtbarkeit, eine Ranke, deren Aura aus Wachstum und Schutz die ganze Stadt aufblühen ließ.\n\nDie Große Zerschlagung schnitt die Hochgeborenen vom Brunnen der Ewigkeit ab. Sie bannten einen Dämon, Immol'thar, und lebten Jahrtausende von seiner Kraft, bis es mehr kostete, ihn zu halten, als er einbrachte. Prinz Tortheldrin tötete viele seines eigenen Volkes, damit die übrigen mehr aus dem Dämon ziehen konnten. Die Hochgeborenen, die davor gewarnt hatten, dass Immol'thar der Brennenden Legion wieder einen Halt in der Welt verschaffen würde, starben in einer einzigen blutigen Nacht. Andere Shen'dralar erhoben sich im Verborgenen unter einem maskierten Anführer, den man den Shal'nan nannte, den Verschleierten, und dessen Name zum Schlachtruf wurde. Nach einem letzten Überfall auf Tortheldrins Sanktum führte der Shal'nan sein Volk nach Westen aus der Stadt, und sie segelten ins Unbekannte. Die, die blieben, zogen sich ins Herz der Stadt zurück und überließen den Rest dem, was auch immer kam.\n\nOger, Satyrn und Geister halten heute die Ruinen, und der Stein steht noch, mit arkaner Energie in seinem Innern gebunden.",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "Traum-Geäst",
			short = "Der größte Baum von Feralas steht auf einer kleinen Insel mitten im Jademirsee. Er ist einer der vier Großen Bäume, und in seinen Wurzeln und Ästen liegt ein Portal in den Smaragdgrünen Traum.",
			full = "Der größte Baum von Feralas steht auf einer kleinen Insel mitten im Jademirsee. Er ist einer der vier Großen Bäume, und in seinen Wurzeln und Ästen liegt ein Portal in den Smaragdgrünen Traum. Der grüne Drachenschwarm bewacht ihn, und Taerar, ein grüner Drache, den der Smaragdgrüne Alptraum verdorben hat, streift über die Insel.",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "Festung Feathermoon",
			short = "General Shandris Feathermoon ließ diese Festung auf der Insel Sardor vor der Westküste von Feralas errichten, und sie trägt ihren Namen.",
			full = "General Shandris Feathermoon ließ diese Festung auf der Insel Sardor vor der Westküste von Feralas errichten, und sie trägt ihren Namen. Seit zehntausend Jahren steht sie unter den Schildwachen an der rechten Seite von Tyrande Whisperwind. Die Festung hält diesen Küstenstreifen Kalimdors weiter für die Nachtelfen.\n\nDie Naga setzen der Insel zu, und Shandris arbeitet daran, das Land von den Hasskämmen und ihrem Anführer, Lord Shalzaru, zu säubern. Nur das Meer verbindet die Insel mit dem Festland, und ein Boot setzt von der Küste zu ihrem Anlegesteg über.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "Wildschrammtal",
			short = "Die Wildschrammyetis halten dieses Tal in der oberen Wildnis im Westen von Feralas, und es trägt ihren Namen.",
			full = "Die Wildschrammyetis halten dieses Tal in der oberen Wildnis im Westen von Feralas, und es trägt ihren Namen.",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "Die vergessene Küste",
			short = "Wasserelementare steigen an der vergessenen Küste aus der Brandung, dem ganzen Westrand von Feralas, wo das Land auf das Verhüllte Meer trifft, und Meeresriesen streifen über den Strand.",
			full = "Wasserelementare steigen an der vergessenen Küste aus der Brandung, dem ganzen Westrand von Feralas, wo das Land auf das Verhüllte Meer trifft, und Meeresriesen streifen über den Strand.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "Fransenfederhochland",
			short = "Die Fransenfederhippogryphen halten dieses Hochland und geben ihm seinen Namen. Tief zwischen den Klippen liegen ihre Nester verborgen, jedes mit seinen Eiern.",
			full = "Die Fransenfederhippogryphen halten dieses Hochland und geben ihm seinen Namen. Tief zwischen den Klippen liegen ihre Nester verborgen, jedes mit seinen Eiern.",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "Außenposten der Gordunni",
			short = "In den Bergen nördlich von Lariss' Pavillon haben die Oger der Gordunni das Land eingenommen, und die Pflanzen, die sonst überall in Feralas grün sind, sind zu Braun verdorrt.",
			full = "In den Bergen nördlich von Lariss' Pavillon haben die Oger der Gordunni das Land eingenommen, und die Pflanzen, die sonst überall in Feralas grün sind, sind zu Braun verdorrt. Zwei Höhlen öffnen sich in den Hügeln, eine kleine nahe dem Eingang und ein Ogerhügel im hinteren Teil. Hügelwächter und Zähmer streifen über die Hänge, und die Oger halten einen gefangenen Sasquatsch namens Großfaust nahe der hinteren Höhle.",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "Truppenlager der Grimmtotem",
			short = "Östlich von Düsterbruch haben die Tauren der Grimmtotem ein großes Dorf in zwei Teilen gebaut.",
			full = "Östlich von Düsterbruch haben die Tauren der Grimmtotem ein großes Dorf in zwei Teilen gebaut. Im südlichen Teil hält ein großer Käfig Grimmlingflitzer gefangen. Östlich des nördlichen Teils haben Gnolle ein paar eigene Lager aufgeschlagen.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "Die obere Wildnis",
			short = "Uralte Bäume füllen die obere Wildnis, einen weiten Wald, der sich über den Westen von Feralas von der vergessenen Küste bis zum Verdantis erstreckt.",
			full = "Uralte Bäume füllen die obere Wildnis, einen weiten Wald, der sich über den Westen von Feralas von der vergessenen Küste bis zum Verdantis erstreckt. Bären, Wölfe und Hippogryphen streifen zwischen ihnen umher, und Treants, Yetis und Oger teilen sich den Wald mit ihnen.",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "Die Insel des Schreckens",
			short = "Die Insel des Schreckens liegt vor der Küste von Feralas, südlich der Insel Sardor. In ihrer Mitte liegt ein Tal, das von unbezwingbaren Klippen umschlossen ist, und der einzige Weg hinein führt von Südosten.",
			full = "Die Insel des Schreckens liegt vor der Küste von Feralas, südlich der Insel Sardor. In ihrer Mitte liegt ein Tal, das von unbezwingbaren Klippen umschlossen ist, und der einzige Weg hinein führt von Südosten. In diesem Tal leben die Chimaerok, darunter vom Arkanen berührte Bestien und Verschlinger, angeführt von Lord Lakmaeran.\n\nAm Nordende der Insel führt eine Höhle tief in den Fels, anders als alles andere dort. Die Naga der Hasskämme halten sie unter Lord Shalzaru.",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "Jademirsee",
			short = "Der Jademirsee liegt im Norden von Feralas, mit einer kleinen Insel in der Mitte. Dort steht ein Portal in den Smaragdgrünen Traum, und Lethlas und eine Reihe grüner Drachenbrut bewachen es.",
			full = "Der Jademirsee liegt im Norden von Feralas, mit einer kleinen Insel in der Mitte. Dort steht ein Portal in den Smaragdgrünen Traum, und Lethlas und eine Reihe grüner Drachenbrut bewachen es. Infizierte grüne Welpen sammeln sich am nordwestlichen Ufer des Sees.",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "Lariss' Pavillon",
			short = "Azj'Tordin, ein Hochgeborener, der mit Prinz Tortheldrin uneins war, verließ Düsterbruch durch einen Hinterausgang, der am Fuß von Lariss' Pavillon herauskommt.",
			full = "Azj'Tordin, ein Hochgeborener, der mit Prinz Tortheldrin uneins war, verließ Düsterbruch durch einen Hinterausgang, der am Fuß von Lariss' Pavillon herauskommt. Er nahm nicht viel mit. Ein Wichtel namens Pusillin hatte zuvor sein Beschwörungsbuch gestohlen.\n\nDer Pavillon ist ein großes offenes Gebäude im nachtelfischen Stil. Die Dryaden ringsum sind gewöhnlich friedlich, doch der Smaragdgrüne Alptraum hat sie verdorben, und sie greifen jeden an, der sich nähert.",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
			name = "Die untere Wildnis",
			short = "Die untere Wildnis ist das östliche Ende von Feralas, wo der Wald in Tausend Nadeln übergeht. Treants gehen zwischen den Bäumen, und verderbte Dryaden bewegen sich durch sie hindurch.",
			full = "Die untere Wildnis ist das östliche Ende von Feralas, wo der Wald in Tausend Nadeln übergeht. Treants gehen zwischen den Bäumen, und verderbte Dryaden bewegen sich durch sie hindurch.",
			source = "https://warcraft.wiki.gg/wiki/Lower_Wilds",
		},
		["oneiros"] = {
			name = "Oneiros",
			short = "Die Ruinen von Oneiros liegen südlich des Jademirsees im Norden von Feralas. Hier stehen viele nachtelfische Ruinen, und grüne Drachenbrut patrouilliert zwischen ihnen.",
			full = "Die Ruinen von Oneiros liegen südlich des Jademirsees im Norden von Feralas. Hier stehen viele nachtelfische Ruinen, und grüne Drachenbrut patrouilliert zwischen ihnen.",
			source = "https://warcraft.wiki.gg/wiki/Oneiros",
		},
		["rage scar hold"] = {
			name = "Wutschrammfeste",
			short = "Die wildesten Yetis der Gegend leben in der Wutschrammfeste, einer in den Boden gegrabenen Höhle. Bücher und fremde Zeichen liegen darin verstreut.",
			full = "Die wildesten Yetis der Gegend leben in der Wutschrammfeste, einer in den Boden gegrabenen Höhle. Bücher und fremde Zeichen liegen darin verstreut. Entweder studieren die Yetis Magie, oder die Bücher gehörten einem unglücklichen Magus, der hier sein Ende fand.",
			source = "https://warcraft.wiki.gg/wiki/Rage_Scar_Hold",
		},
		["ruins of isildien"] = {
			name = "Ruinen von Isildien",
			short = "Vor zehntausend Jahren wurde eine große nachtelfische Stadt im Südwesten von Feralas zerstört.",
			full = "Vor zehntausend Jahren wurde eine große nachtelfische Stadt im Südwesten von Feralas zerstört. Die Oger der Gordunni haben sich in ihren Ruinen niedergelassen und herrschen über Steine, die von weit älteren Händen errichtet wurden als ihren eigenen. Auf der Ostseite öffnet sich eine Höhle, und oben an einer Treppe steht ein großes rundes Gebäude, das einmal ein Tempel der Elune gewesen sein könnte, denn es sieht dem Tempel des Mondes in Darnassus sehr ähnlich.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Isildien",
		},
		["ruins of ravenwind"] = {
			name = "Ruinen von Rabenwind",
			short = "Der Norden von Feralas birgt die zerbrochenen Steine von Rabenwind, vor langer Zeit von den Hochgeborenen der Nachtelfen errichtet, ähnlich wie Düsterbruch an anderer Stelle.",
			full = "Der Norden von Feralas birgt die zerbrochenen Steine von Rabenwind, vor langer Zeit von den Hochgeborenen der Nachtelfen errichtet, ähnlich wie Düsterbruch an anderer Stelle. Von dieser Pracht steht kaum noch etwas. Harpyien der Nordschwingen haben die Ruinen für sich genommen und nisten zwischen den umgestürzten Säulen und leeren Hallen.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ravenwind",
		},
		["ruins of solarsal"] = {
			name = "Ruinen von Solarsal",
			short = "Südwestlich der Festung Feathermoon, auf der Insel Sardor, liegen alte nachtelfische Ruinen, längst verlassen.",
			full = "Südwestlich der Festung Feathermoon, auf der Insel Sardor, liegen alte nachtelfische Ruinen, längst verlassen. Naga der Hasskämme haben sich in solcher Zahl zwischen den zerbrochenen Säulen eingenistet, dass die Nachtelfen der Festung es für den ersten Zug eines Angriffs halten.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Solarsal",
		},
		["sardor isle"] = {
			name = "Insel Sardor",
			short = "Die Insel Sardor liegt vor der Westküste von Feralas, nördlich der Insel des Schreckens. Die Nachtelfen halten sie als kleine Zuflucht, von der Festung Feathermoon aus unter General Shandris Feathermoon.",
			full = "Die Insel Sardor liegt vor der Westküste von Feralas, nördlich der Insel des Schreckens. Die Nachtelfen halten sie als kleine Zuflucht, von der Festung Feathermoon aus unter General Shandris Feathermoon. An ihren Küsten leben Naga, und ein Wolfsrudel streift durch die wilden Orte, die noch übrig sind, sodass die Wache der Festung nie müßig ist.",
			source = "https://warcraft.wiki.gg/wiki/Sardor_Isle",
		},
		["shalzarus lair"] = {
			name = "Shalzarus Unterschlupf",
			short = "Lord Shalzaru, Herr der Hasskämme, lebt tief in dieser gewundenen Höhle am Nordende der Insel des Schreckens.",
			full = "Lord Shalzaru, Herr der Hasskämme, lebt tief in dieser gewundenen Höhle am Nordende der Insel des Schreckens. Sie hat eine Haupthöhle und eine kleinere, die ein Wasserweg verbindet, und ein verborgener Gang unter dem Wasser führt in eine innere Kammer, in der Lady Szallah wohnt. Zauberinnen der Hasskämme und Schlangenwachen füllen sie von einem Ende zum anderen. Späher der Festung Feathermoon berichten, dass Shalzaru bei einer Grabung der Naga ein seltsames Relikt entdeckt hat.",
			source = "https://warcraft.wiki.gg/wiki/Shalzaru's_Lair",
		},
		["thalanaar"] = {
			name = "Thalanaar",
			short = "Wo Feralas auf Tausend Nadeln trifft, steht Thalanaar, ein winziges nachtelfisches Lager in der Hand der Allianz. Falfindel Waywarder ist hier und sucht Hilfe gegen den Kult der Totenköpfe.",
			full = "Wo Feralas auf Tausend Nadeln trifft, steht Thalanaar, ein winziges nachtelfisches Lager in der Hand der Allianz. Falfindel Waywarder ist hier und sucht Hilfe gegen den Kult der Totenköpfe.",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
		},
		["twin colossals"] = {
			name = "Die Zwillingskolosse",
			short = "Zwei steile Berge, die Zwillingskolosse, erheben sich am westlichen Rand von Feralas, höher als alles andere in der Region.",
			full = "Zwei steile Berge, die Zwillingskolosse, erheben sich am westlichen Rand von Feralas, höher als alles andere in der Region. Die Straße nach Desolace führt durch die Lücke zwischen ihnen, und das Paar gehört zu den eindrucksvollsten Anblicken des Landes.\n\nAuf dem östlichen Gipfel liegt ein kleiner, tiefer Teich. Vom Gipfel aus liegt einem die ganze Region zu Füßen.",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "Verdantis",
			short = "Der Verdantis windet sich durch das mittlere Feralas, südöstlich der Ruinen von Düsterbruch, und zieht einen stillen grünen Faden durch den verworrenen Wald.",
			full = "Der Verdantis windet sich durch das mittlere Feralas, südöstlich der Ruinen von Düsterbruch, und zieht einen stillen grünen Faden durch den verworrenen Wald. In seinem Wasser leben Feralas-Ahi, die es nirgendwo sonst auf der Welt gibt.",
			source = "https://warcraft.wiki.gg/wiki/Verdantis_River",
		},
		["wildwind lake"] = {
			name = "Wildwindsee",
			short = "Der Wildwindsee liegt neben Camp Mojache und wird von dem schnellen Bach gespeist, der durch das Taurendorf fließt.",
			full = "Der Wildwindsee liegt neben Camp Mojache und wird von dem schnellen Bach gespeist, der durch das Taurendorf fließt.",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "Waldpfotenbau",
			short = "Die Alphas der Waldpfoten, die Anführer der Gnolle der Waldpfoten, drängen sich in diesem Bau in Feralas. Südlich davon liegen die Ruinen von Graunebel.",
			full = "Die Alphas der Waldpfoten, die Anführer der Gnolle der Waldpfoten, drängen sich in diesem Bau in Feralas. Südlich davon liegen die Ruinen von Graunebel.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "Waldpfotenhügel",
			short = "Die Gnolle des Klans der Waldpfoten haben ihre Heimat in diesen bewaldeten Hügeln im Südosten von Feralas, und sie verlieren sie.",
			full = "Die Gnolle des Klans der Waldpfoten haben ihre Heimat in diesen bewaldeten Hügeln im Südosten von Feralas, und sie verlieren sie. Im äußersten Südosten ist der Boden aufgerissen, an der Stelle, die heute die verwundene Tiefe heißt, und die Silithiden, die daraus hervorbrachen, vertreiben die Gnolle aus ihrem eigenen Gebiet.\n\nAlphas der Waldpfoten führten den Stamm einst aus den Lagern. Heute findet man sie nur noch im Waldpfotenbau.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "Die verwundene Tiefe",
			short = "Der Bau Zukk'ash liegt in der südöstlichen Ecke von Feralas, wo Silithiden aus dem Boden quellen.",
			full = "Der Bau Zukk'ash liegt in der südöstlichen Ecke von Feralas, wo Silithiden aus dem Boden quellen. Sie treiben die benachbarten Gnolle der Waldpfoten in Raserei, und die Gnolle ziehen nach Norden, um Camp Mojache anzugreifen.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- Marschen von Dustwallow: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "Insel Alcaz",
			short = "Tropisches Grün bedeckt die Insel Alcaz vor der Nordostküste der Marschen von Dustwallow, anders als alles auf dem Festland.",
			full = "Tropisches Grün bedeckt die Insel Alcaz vor der Nordostküste der Marschen von Dustwallow, anders als alles auf dem Festland. Die Naga der Strashaz halten ihre Küsten, Myrmidonen und Sirenen dicht unter ihnen, und Hydren streifen durch das Wasser ringsum.\n\nDoktor Weavil ist in seiner Flugmaschine hierhergekommen und hat sich mit seinen Schergen eingerichtet, und die Insel ist ganz seinen technischen Erfindungen überlassen.",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "Beezils Wrack",
			short = "Ein Zeppelin der Goblins, der mit Vorräten nach Süden unterwegs war, ging in den tiefsten Winkeln der Marschen von Dustwallow nieder, östlich von Tabethas Hof.",
			full = "Ein Zeppelin der Goblins, der mit Vorräten nach Süden unterwegs war, ging in den tiefsten Winkeln der Marschen von Dustwallow nieder, östlich von Tabethas Hof. Sein Rumpf liegt zerbrochen im Schlamm, die Ladung ist zwischen den Trümmern verstreut, und die Seaforium-Booster liegen noch dort, wo sie fielen.",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "Blutsumpfbau",
			short = "Blutsumpfraptoren nisten in großer Zahl in einer Höhle im Südwesten der Marschen von Dustwallow. Vor dem Eingang liegen die Überreste irgendeiner Siedlung, von den gefräßigen Raptoren zerrissen.",
			full = "Blutsumpfraptoren nisten in großer Zahl in einer Höhle im Südwesten der Marschen von Dustwallow. Vor dem Eingang liegen die Überreste irgendeiner Siedlung, von den gefräßigen Raptoren zerrissen.",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "Blaumoor",
			short = "Das Blaumoor ist niedriges Marschland im Norden der Marschen von Dustwallow, nahe Brackenwall. Spinnen, Sumpfvögel, Raptoren und Krokilisken überrennen es, und unter ihnen hat man Infiltratoren aus Theramore gesehen.",
			full = "Das Blaumoor ist niedriges Marschland im Norden der Marschen von Dustwallow, nahe Brackenwall. Spinnen, Sumpfvögel, Raptoren und Krokilisken überrennen es, und unter ihnen hat man Infiltratoren aus Theramore gesehen.",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "Brackenwall",
			short = "Die Oger der Stonemaul kamen als Flüchtlinge nach Brackenwall.",
			full = "Die Oger der Stonemaul kamen als Flüchtlinge nach Brackenwall. Schwarze Drachen fielen über ihr altes Dorf im Süden her und zerstörten es, und Oberanführer Mok'Morokk führte die Überlebenden nach Norden zu dieser Ansammlung weniger Hütten und eines Ogerhügels. Hier lebt kein schwarzer Drache, und Mok'Morokk ist es zufrieden, dass es so bleibt.\n\nAndere sind es nicht. Tharg und Draz'Zilb weigern sich, Brackenwall ihre Heimat zu nennen, und wollen das alte Dorf zurück. Draz'Zilb hat erfahren, dass die Angreifer Onyxias Brut waren.",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "Graunebelhöhlen",
			short = "Eine kleine Mine im Nordwesten der Marschen von Dustwallow ist Spinnen überlassen worden, die im Dunkeln zu erschreckender Größe herangewachsen sind.",
			full = "Eine kleine Mine im Nordwesten der Marschen von Dustwallow ist Spinnen überlassen worden, die im Dunkeln zu erschreckender Größe herangewachsen sind. Die Leute der Marschen nennen sie die Graunebelspinnen und die Höhle ihrerseits Graunebel, doch keiner kann sagen, welcher Name zuerst da war.\n\nRuinen kleiner Häuser stehen vor der Mine, halb im nassen Boden versunken. Sie deuten darauf hin, dass hier einmal eine Siedlung lag.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "Der Flammenbau",
			short = "Der Flammenbau begann als Ogerhügel, den die Stonemaul errichteten, und das Mauerwerk trägt noch ihre Handwerkskunst. Er liegt gleich westlich der Stonemaul Ruinen.",
			full = "Der Flammenbau begann als Ogerhügel, den die Stonemaul errichteten, und das Mauerwerk trägt noch ihre Handwerkskunst. Er liegt gleich westlich der Stonemaul Ruinen. Schwarze Drachkin haben ihn überrannt, wahrscheinlich auf Befehl Onyxias, die in der Nähe lebt, und halten ihn als Nest des schwarzen Drachenschwarms. Das Banner der Stonemaul steht noch im Innern.",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "Das Drachendüster",
			short = "Drachenwelpen und Drachenbrut des schwarzen Drachenschwarms brüten dicht gedrängt im Drachendüster, dem fauligen Grund der südlichen Marschen.",
			full = "Drachenwelpen und Drachenbrut des schwarzen Drachenschwarms brüten dicht gedrängt im Drachendüster, dem fauligen Grund der südlichen Marschen. Der Flammenbau und die Stonemaul Ruinen liegen darin, und schwarze Drachenbrut hält beide.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "Dreadmurk Shore",
			short = "Die Murlocs der Schlammflossen beanspruchen diese Küste und die verstreuten Inseln davor, und sie wimmeln dort. Meeresschildkröten und andere Meerestiere teilen sich das Wasser.",
			full = "Die Murlocs der Schlammflossen beanspruchen diese Küste und die verstreuten Inseln davor, und sie wimmeln dort. Meeresschildkröten und andere Meerestiere teilen sich das Wasser.\n\nDie Defias, die vor der Küste Schiffbruch erlitten, haben auf einigen der Inseln und an dem Strand in der Nähe ihr Lager aufgeschlagen.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
		},
		["dustwallow bay"] = {
			name = "Dustwallow Bay",
			short = "Die Dustwallow Bay ist die Stelle, wo das Große Meer auf die Ostküste der Marschen trifft, westlich der Insel Theramore. Salzwasser vermischt sich hier mit Sumpfwasser und macht einen breiten Küstenstreifen brackig.",
			full = "Die Dustwallow Bay ist die Stelle, wo das Große Meer auf die Ostküste der Marschen trifft, westlich der Insel Theramore. Salzwasser vermischt sich hier mit Sumpfwasser und macht einen breiten Küstenstreifen brackig. Die Untiefen sind ein beliebter Brutplatz für Murlocs.",
			source = "https://warcraft.wiki.gg/wiki/Dustwallow_Bay",
		},
		["emberstrifes den"] = {
			name = "Aschenschwingens Bau",
			short = "Eine weite Höhle öffnet sich in den stinkenden Drachensumpf, die Heimat des schwarzen Drachen Aschenschwinge.",
			full = "Eine weite Höhle öffnet sich in den stinkenden Drachensumpf, die Heimat des schwarzen Drachen Aschenschwinge. Er unterzieht junge schwarze Drachenwelpen harten Prüfungen, und nur die, die er für würdig hält, gelangen weiter zu Onyxias Hort.",
			source = "https://warcraft.wiki.gg/wiki/Emberstrife's_Den",
		},
		["foothold citadel"] = {
			name = "Foothold-Zitadelle",
			short = "An den Toren der Foothold-Zitadelle üben die Wachen von Theramore an Übungspuppen, und junge Rekruten messen sich miteinander.",
			full = "An den Toren der Foothold-Zitadelle üben die Wachen von Theramore an Übungspuppen, und junge Rekruten messen sich miteinander. Priester sehen aus der Nähe zu, bereit, das Licht in dem Augenblick anzurufen, in dem jemand verletzt wird. Die Festung ist das Hauptquartier der Wache von Theramore.\n\nGroßadmiral Daelin Proudmoore starb in ihr im Kampf. Er hatte Theramore eingenommen, und Kriegshäuptling Thrall bat Lady Jaina Proudmoore, die Horde hineinzulassen, damit sie ihren Vater töten konnte. Thralls Truppen stürmten die Stadt, angeführt von Rexxar und seinen Gefährten, und Rexxar stellte den Admiral selbst in seiner Festung.",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
		},
		["lost point"] = {
			name = "Die verlassene Wacht",
			short = "Theramore baute die verlassene Wacht als Spähturm im Westen der Marschen. Sie ist heute heruntergekommen und baufällig und dient ihren Erbauern nicht mehr.",
			full = "Theramore baute die verlassene Wacht als Spähturm im Westen der Marschen. Sie ist heute heruntergekommen und baufällig und dient ihren Erbauern nicht mehr. Deserteure aus Theramore leben darin unter ihrem Anführer Balos Jacken.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
		},
		["north point tower"] = {
			name = "Nordwacht",
			short = "Ein beachtlicher Trupp Wachen von Theramore hält die Nordwacht an einem vielbefahrenen Stück Straße im Norden der Marschen.",
			full = "Ein beachtlicher Trupp Wachen von Theramore hält die Nordwacht an einem vielbefahrenen Stück Straße im Norden der Marschen. Seit Deserteure die verlassene Wacht übernommen haben, ist sie der entfernteste Außenposten von Theramore.",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "Onyxias Hort",
			short = "Der Eingang zu Onyxias Hort ist so gehauen, dass er wie der Rachen der Brutmutter selbst aussieht. Im Innern säumt Magma den Weg, und der Boden ist gerissen und glüht von Feuer aus der Tiefe.",
			full = "Der Eingang zu Onyxias Hort ist so gehauen, dass er wie der Rachen der Brutmutter selbst aussieht. Im Innern säumt Magma den Weg, und der Boden ist gerissen und glüht von Feuer aus der Tiefe. Die steinerne Decke ächzt und verschiebt sich, und ohne Ende fällt Gestein herab. Lava quillt aus den Wänden, wo die Hitze sich nicht halten lässt.\n\nOnyxia hat ihn erbaut, und ihre Sippe, der schwarze Drachenschwarm, bewacht sie hier. Sie ist die Tochter von Deathwing und die Schwester von Nefarian, dem Lord der Blackrockspitze. Wo ihr Vater mit Gewalt herrscht und ihr Bruder verdrehte Monstrositäten züchtet, wirkt sie durch Charme. Es macht ihr Freude, sich in die Politik der Sterblichen einzumischen und sie ihren Zielen zu beugen.",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "Der Morast",
			short = "Der Morast füllt das durchweichte Herz der Marschen von Dustwallow und reicht von der verlassenen Wacht im Westen bis zur Dustwallow Bay im Osten.",
			full = "Der Morast füllt das durchweichte Herz der Marschen von Dustwallow und reicht von der verlassenen Wacht im Westen bis zur Dustwallow Bay im Osten. Krokilisken lauern in seinem schwarzen Wasser, Spinnen und Schleime kriechen hindurch, und Tauren der Grimmtotem haben sich hier niedergelassen.",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "Späherwacht",
			short = "Ein Spähturm, den Theramore gebaut hat, steht gleich hinter der Brücke von der Stadt und beobachtet das Kommen und Gehen auf der Straße.",
			full = "Ein Spähturm, den Theramore gebaut hat, steht gleich hinter der Brücke von der Stadt und beobachtet das Kommen und Gehen auf der Straße.",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "Gasthaus Zur süßen Ruh",
			short = "Das Gasthaus Zur süßen Ruh, eine von Menschen erbaute Raststation nahe der Grenze zwischen den Marschen von Dustwallow und dem Brachland, brannte ohne erkennbaren Grund bis auf die Grundmauern nieder.",
			full = "Das Gasthaus Zur süßen Ruh, eine von Menschen erbaute Raststation nahe der Grenze zwischen den Marschen von Dustwallow und dem Brachland, brannte ohne erkennbaren Grund bis auf die Grundmauern nieder. James Hyal führte das Gasthaus, und seine Frau und sein Kind starben in den Flammen.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "Die Stonemaul Ruinen",
			short = "Kor'gall unterwarf den Stonemaulklan mit einer uralten Orcaxt, Serathil, und herrschte grausam über sein Dorf. Crol'ka, dessen Brüder Kor'gall getötet hatte, entkam nur knapp mit dem Leben.",
			full = "Kor'gall unterwarf den Stonemaulklan mit einer uralten Orcaxt, Serathil, und herrschte grausam über sein Dorf. Crol'ka, dessen Brüder Kor'gall getötet hatte, entkam nur knapp mit dem Leben. Eine Patrouille der Darkspear fand ihn, und Vol'jin und Rexxar sagten ihre Hilfe zu, in der Hoffnung, die Stonemaul für den Krieg der Horde gegen Kul Tiras zu gewinnen.\n\nVor den Toren abgewiesen, kämpfte sich Rexxar hinein. Kor'gall ließ ihn dem Klan beitreten, wenn er den Spießrutenlauf überlebte, ein Tal voller tödlicher Bestien, und Rexxar überlebte ihn. Als Kor'gall danach verweigerte, den Klan für den Krieg herzugeben, forderte Rexxar ihn um die Führung heraus und tötete ihn, und die Stonemaul zogen unter Rexxar in den Krieg. Danach überließ er den Klan Mok'Morokk, der sein Volk ausplünderte, statt ihm zu dienen.\n\nOnyxias Brut überfiel das Dorf später und nahm es ein. Mok'Morokk führte die Überlebenden fort, und heute wimmeln die Ruinen von Drachenbrut der Feuermähnen.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "Swamplight-Anwesen",
			short = "„Sumpfauge“ Jarl, ein berühmter Koch, lebt im Swamplight-Anwesen, einem bescheidenen Haus auf dem Hexenhügel.",
			full = "„Sumpfauge“ Jarl, ein berühmter Koch, lebt im Swamplight-Anwesen, einem bescheidenen Haus auf dem Hexenhügel. Im Garten davor verbirgt ein Haufen umgegrabener Erde den Bericht eines Orcspions, dort vergraben, um ihn vor Blicken zu schützen.",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["theramore isle"] = {
			name = "Die Insel Theramore",
			short = "Nach dem Dritten Krieg führte Lady Jaina Proudmoore die Überlebenden von Lordaeron über das Meer nach Kalimdor.",
			full = "Nach dem Dritten Krieg führte Lady Jaina Proudmoore die Überlebenden von Lordaeron über das Meer nach Kalimdor. Auf einer felsigen Insel vor den Marschen von Dustwallow errichteten sie Theramore, einen ummauerten Hafen, der die zerlumpten Reste der zerfallenden Allianz schützen sollte. Eine rechteckige Mauer, besetzt mit Kanonentürmen, umringt den größten Teil der Insel. Nur der Hafen ist offen, und zwei Spähtürme bewachen ihn. In der Mitte, hinter einer inneren Mauer, erhebt sich Jainas Turm, das höchste Gebäude der Stadt. Seine vielen Stockwerke sind durch lange gewundene Treppen verbunden, und seine Wände sind durch Bannzauber gegen Angriffe geschützt. Er birgt ihre privaten Gemächer, ihre Bibliothek und den kleinen Thronsaal.\n\nDie Marschen liefern schlechtes Bauholz, und die Schiffsbauer der Stadt nennen die einheimischen Bäume Sumpfschrott. Sie beneiden die Orcs, die oberhalb von Orgrimmar gute Eichen schlagen. Trotzdem tauschen die Menschen Fisch bei den Orcs gegen überschüssiges Getreide aus Durotar. Die meisten Leute kennen einander, und Verbrechen sind selten.",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "Tidefury-Bucht",
			short = "Tückisches Wasser liegt am Ende der Dustwallow Bay, südlich der Insel Theramore.",
			full = "Tückisches Wasser liegt am Ende der Dustwallow Bay, südlich der Insel Theramore. Kleine Inseln und verborgene Riffe sprenkeln die Bucht, und zwei Schiffe liegen zerbrochen in ihren Untiefen, heute von umherstreifenden Makrura bewohnt. Der berühmte Fischer Nat Pagle hat sein Zuhause auf einem der Eilande, Nat's Landing.\n\nIm Krieg gegen die Kul Tiraner von Großadmiral Daelin Proudmoore wandten sich die Orcs, Tauren und Oger der Horde gegen einen Stützpunkt hier, wo seine Truppen eine gewaltige Burg am Ufer errichtet hatten.",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
		},
		["witch hill"] = {
			name = "Hexenhügel",
			short = "Zombies und Geister suchen den Hexenhügel heim, und Lager der Murlocs der Schlammflossen stehen im Morast ringsum. Das Swamplight-Anwesen liegt nahe seiner Mitte, und „Sumpfauge“ Jarl lebt dort.",
			full = "Zombies und Geister suchen den Hexenhügel heim, und Lager der Murlocs der Schlammflossen stehen im Morast ringsum. Das Swamplight-Anwesen liegt nahe seiner Mitte, und „Sumpfauge“ Jarl lebt dort.",
			source = "https://warcraft.wiki.gg/wiki/Witch_Hill",
		},
		["wyrmbog"] = {
			name = "Der Drachensumpf",
			short = "Südlich des Drachendüsters wird der Boden felsiger. Die Tümpel sind größer und weit tiefer, und halb versunkene Felsen durchbrechen die Oberfläche.",
			full = "Südlich des Drachendüsters wird der Boden felsiger. Die Tümpel sind größer und weit tiefer, und halb versunkene Felsen durchbrechen die Oberfläche. Viele haben Öffnungen in trockene Höhlen. Schwarze Drachen haben hier ihr Zuhause, darunter Onyxia und Aschenschwinge, und die Eingänge zu Aschenschwingens Bau und Onyxias Hort liegen im Sumpf.",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
		},
	},
	-- Tanaris: 23 subzones
	[1446] = {
		["abyssal sands"] = {
			name = "Die ewigen Sande",
			short = "Diese Sande liegen in Tanaris, eine Wüste, die sich in alle Richtungen erstreckt.",
			full = "Diese Sande liegen in Tanaris, eine Wüste, die sich in alle Richtungen erstreckt.",
			source = "https://warcraft.wiki.gg/wiki/Abyssal_Sands",
		},
		["broken pillar"] = {
			name = "Zerbrochene Säule",
			short = "Der Goblin Marvon Rivetseeker, Wissenschaftler und Schatzjäger, hat sein Lager zwischen einer kleinen Gruppe Trollruinen südlich von Gadgetzan aufgeschlagen.",
			full = "Der Goblin Marvon Rivetseeker, Wissenschaftler und Schatzjäger, hat sein Lager zwischen einer kleinen Gruppe Trollruinen südlich von Gadgetzan aufgeschlagen. Er hat uralte Orte auf der ganzen Welt erforscht. Seine Werkstatt überließ er seinem Assistenten, um in die Wüste zu kommen und diese Steine selbst nach Antworten zu durchsuchen.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "Die Höhlen der Zeit",
			short = "Der bronzene Drachenschwarm bewacht die Höhlen der Zeit, seit die Welt jung war. Die Titanen gaben ihm diese Aufgabe, und er erfüllt sie noch heute.",
			full = "Der bronzene Drachenschwarm bewacht die Höhlen der Zeit, seit die Welt jung war. Die Titanen gaben ihm diese Aufgabe, und er erfüllt sie noch heute. Unter dem östlichen Sand winden sich die Höhlen wie ein Labyrinth, und die Pfade hindurch folgen den wandernden Zeitwegen. Sterbliche werden ferngehalten, weil ihr Eingreifen den Fluss der Zeit stören könnte.\n\nNozdormu, der Aspekt der Zeit, hat hier sein Zuhause. Der Drache Anachronos sitzt vor dem Tor. Hier erfuhr er zuerst, wie groß die Bedrohung durch die Silithiden war, deren Baue sich durch die abgelegenen Gegenden der Wüste ausbreiteten.",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["dunemaul compound"] = {
			name = "Truppenlager der Dünenbrecher",
			short = "Die Dünenbrecher sind nomadische Oger, die ein weites Stück von Tanaris übernommen haben, und dieser Hügel ist ihr Lager. Man sagt, sie seien erst vor kurzer Zeit in die Wüste gekommen.",
			full = "Die Dünenbrecher sind nomadische Oger, die ein weites Stück von Tanaris übernommen haben, und dieser Hügel ist ihr Lager. Man sagt, sie seien erst vor kurzer Zeit in die Wüste gekommen. Sie fressen die Überreste der Silithiden der Centipaar.",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["eastmoon ruins"] = {
			name = "Ruinen von Eastmoon",
			short = "Oger der Dünenbrecher haben die Ruinen von Eastmoon übernommen, das bröckelnde Mauerwerk einer uralten Trollsiedlung, gleich westlich der klaffenden Schlucht.",
			full = "Oger der Dünenbrecher haben die Ruinen von Eastmoon übernommen, das bröckelnde Mauerwerk einer uralten Trollsiedlung, gleich westlich der klaffenden Schlucht. Die Trolle sind längst fort.",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "Gadgetzan",
			short = "Gewinn vor Loyalität lautet das Credo von Gadgetzan, der Hauptstadt des Steamwheedle-Kartells, des größten der Goblinkartelle. Das macht die Stadt zu neutralem Boden im Streit zwischen Horde und Allianz.",
			full = "Gewinn vor Loyalität lautet das Credo von Gadgetzan, der Hauptstadt des Steamwheedle-Kartells, des größten der Goblinkartelle. Das macht die Stadt zu neutralem Boden im Streit zwischen Horde und Allianz. Beide Regierungen erkennen das an, und Haudraufs der Goblins patrouillieren durch die Straßen, bereit, jeden zu Brei zu schlagen, der Krieg an einen Ort bringt, der auf Handel gebaut ist. Geldbeutel, nicht Banner, entscheiden, wer willkommen ist.\n\nEinige der besten Goblin-Ingenieure, -Bergleute und -Alchemisten arbeiten hier. Im Auktionshaus handeln Menschen mit der Horde Kätzchen, und Tauren handeln mit der Allianz Präriehunde, und manche sagen, der Haustierhandel könne die beiden Seiten zur Einigung bringen.",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "Die klaffende Schlucht",
			short = "Silithiden der Hazzali wimmeln durch die klaffende Schlucht, und ihre Baukomplexe reichen tief in den Fels. Es ist einer der kleineren Baue im Südosten von Tanaris.",
			full = "Silithiden der Hazzali wimmeln durch die klaffende Schlucht, und ihre Baukomplexe reichen tief in den Fels. Es ist einer der kleineren Baue im Südosten von Tanaris. Leitender Feldmesser Fizzledowser von der Gadgetzan Water Company schickte einst seinen Untergebenen Scrimshank hinab, um ihn zu vermessen. Seitdem hat man nichts mehr von ihm gehört.",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "Landendestrand",
			short = "Der Landendestrand liegt am südlichsten Punkt von Tanaris, in der äußersten südöstlichen Ecke Kalimdors, einem der abgelegensten Orte der Welt.",
			full = "Der Landendestrand liegt am südlichsten Punkt von Tanaris, in der äußersten südöstlichen Ecke Kalimdors, einem der abgelegensten Orte der Welt. Zwei Inseln liegen vor der Küste. Brandungsgleiter und Uferdünenkrebse streifen über den östlichen Abschnitt des Sandes.",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
		},
		["lost rigger cove"] = {
			name = "Lost-Rigger-Bucht",
			short = "Berge schließen die Lost-Rigger-Bucht auf drei Seiten ein, die den Hafen der Südmeerpiraten an der Küste von Tanaris verbirgt. Eine Werft hier ist damit beschäftigt, ein neues Schiff zu bauen.",
			full = "Berge schließen die Lost-Rigger-Bucht auf drei Seiten ein, die den Hafen der Südmeerpiraten an der Küste von Tanaris verbirgt. Eine Werft hier ist damit beschäftigt, ein neues Schiff zu bauen. Das Steamwheedle-Kartell hat seinen Sicherheitschef beauftragt, diesen Piraten eine Lektion zu erteilen.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Rigger_Cove",
		},
		["noonshade ruins"] = {
			name = "Ruinen von Noonshade",
			short = "Banditen der Wüstenwanderer haben die Ruinen von Noonshade überrannt, abgenutzten Stein, den längst verschwundene Trolle zurückließen, östlich von Gadgetzan im Nordosten von Tanaris.",
			full = "Banditen der Wüstenwanderer haben die Ruinen von Noonshade überrannt, abgenutzten Stein, den längst verschwundene Trolle zurückließen, östlich von Gadgetzan im Nordosten von Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "Der giftige Unterschlupf",
			short = "Etwas Breites und Flaches, ein Fluss oder ein See, lag einst über diesem Boden im Südwesten von Tanaris. Die Oberfläche sinkt dort, wo er war, noch ein wenig ein, mit Blick auf den Un'Goro-Krater.",
			full = "Etwas Breites und Flaches, ein Fluss oder ein See, lag einst über diesem Boden im Südwesten von Tanaris. Die Oberfläche sinkt dort, wo er war, noch ein wenig ein, mit Blick auf den Un'Goro-Krater. Dann zogen die Silithiden der Centipaar ein und entzogen dem westlichen Tanaris alle Reserven. Große Klauen stehen zuckend im Sand, offenbar von riesigen Silithiden, die darunter vergraben sind, und der Boden um jede ist getränkt mit Silithidenschleim, der einzigen Feuchtigkeit, die an einem Ort geblieben ist, der einmal einen See barg.\n\nUnter der Oberfläche ist der Bau feucht, warm und unheimlich. Tunnel verbinden seine zwei Eingänge mit den Brutkammern, und die Wände sind mit Silithidensäure überzogen und mit ungeborenen Insekten behangen.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "Sandsorrow-Wache",
			short = "Von einer Kette von Wachtürmen namens Sandsorrow-Wache halten die Sandfurytrolle ihre Besitzungen in einem weiten Gebiet westlich von Gadgetzan im Auge.",
			full = "Von einer Kette von Wachtürmen namens Sandsorrow-Wache halten die Sandfurytrolle ihre Besitzungen in einem weiten Gebiet westlich von Gadgetzan im Auge. Sie mussten im Lauf der Jahre den größten Teil von Tanaris an Fremde abtreten, und was ihnen bleibt, bewachen sie erbittert. Die Sandfurytrolle brauchen jeden Troll, der mit anpackt, nur um durchzukommen, also lernten sie, mit Voodoo Tote zu erwecken. Trollzombies arbeiten unter den Lebenden weiter.",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "Die südlichen Meere",
			short = "Die Gewässer südlich der bekannten Kontinente öffnen sich zu einem weiten Teil des Großen Meeres und tragen Strömungen an Inseln vorbei, deren Namen vor allem Seeleuten bekannt sind.",
			full = "Die Gewässer südlich der bekannten Kontinente öffnen sich zu einem weiten Teil des Großen Meeres und tragen Strömungen an Inseln vorbei, deren Namen vor allem Seeleuten bekannt sind. Zandalar erhebt sich aus diesen Wassern, die uralte Heimat des Trollreichs. Auch Kezan liegt in ihnen, eine Vulkaninsel, deren Volk sich von den Mächten des Festlands fernhält.\n\nNäher am Schlingendorntal wird das Meer tückisch mit Riffen und verborgenen Buchten, die Art von Gewässern, in denen ein Kapitän entweder jeden Felsen beim Namen kennt oder sein Schiff verliert. Kleine Inseln sprenkeln diesen Abschnitt, manche nicht mehr als eine Sandbank, andere mit Ruinen, deren Erbauer längst unter den Wellen verschwunden sind.\n\nWas dieses Meer nennenswert macht, ist weniger eine einzelne Schlacht, die auf ihm geschlagen wurde, als die Dinge, die es verschlungen und halb wieder preisgegeben hat: versunkene Tempel, ertrunkene Küsten, Ruinen, die man bei Ebbe durch klares Wasser erblickt. Es ist ein Meer der Ränder und Zwischenorte, das sich entlang der Grenzen des Schlingendorntals und von Tanaris erstreckt und an die Küsten, die es trennt, trägt, was immer die Gezeiten bringen wollen.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "Southbreak Shore",
			short = "Ein flacher Strandstreifen verläuft am Südrand von Tanaris, südlich der Lost-Rigger-Bucht, ruhig und fast verlassen. Schildkröten und Meeresriesen streifen durch die Brandung.",
			full = "Ein flacher Strandstreifen verläuft am Südrand von Tanaris, südlich der Lost-Rigger-Bucht, ruhig und fast verlassen. Schildkröten und Meeresriesen streifen durch die Brandung.",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "Southmoon-Ruinen",
			short = "Alte Trollruinen liegen im Süden von Tanaris, gleich nördlich vom Tal der Behüter, ihre Steine verwittert und halb im Wüstensand begraben.",
			full = "Alte Trollruinen liegen im Süden von Tanaris, gleich nördlich vom Tal der Behüter, ihre Steine verwittert und halb im Wüstensand begraben. Oger der Dünenbrecher halten sie.",
			source = "https://warcraft.wiki.gg/wiki/Southmoon_Ruins",
		},
		["steamwheedle port"] = {
			name = "Steamwheedle",
			short = "Der Hafen von Steamwheedle liegt an der Ostküste von Tanaris, eine Straße führt nach Westen zu seiner Mutterstadt Gadgetzan, und ein Anleger reicht in Richtung Kezan hinaus.",
			full = "Der Hafen von Steamwheedle liegt an der Ostküste von Tanaris, eine Straße führt nach Westen zu seiner Mutterstadt Gadgetzan, und ein Anleger reicht in Richtung Kezan hinaus. Er gehört dem Steamwheedle-Kartell, Goblins, die mit jedem Geschäfte machen, solange das Gold stimmt.\n\nUnter den Bewohnern des Hafens ist Yeh'kinya, dessen Machenschaften die Rückkehr von Hakkar dem Seelenschinder in Gang setzten.",
			source = "https://warcraft.wiki.gg/wiki/Steamwheedle_Port",
		},
		["thistleshrub valley"] = {
			name = "Disteltal",
			short = "Riesige Kakteen stehen dicht im Disteltal, seltsam für eine so karge Wüste, die sie am Leben hält. Auch wüstenbewohnende Distelsträucher drängen sich im Tal.",
			full = "Riesige Kakteen stehen dicht im Disteltal, seltsam für eine so karge Wüste, die sie am Leben hält. Auch wüstenbewohnende Distelsträucher drängen sich im Tal.",
			source = "https://warcraft.wiki.gg/wiki/Thistleshrub_Valley",
		},
		["uldum"] = {
			name = "Uldum",
			short = "Die Titanen haben im südlichen Teil der Wüste eine Stätte hinterlassen, die uralte Stadt Uldum, reich an ihrem Wissen.",
			full = "Die Titanen haben im südlichen Teil der Wüste eine Stätte hinterlassen, die uralte Stadt Uldum, reich an ihrem Wissen. Sie ist eine Forschungsanlage, in der sie daran arbeiten, die lebendige Welt von Azeroth zu verbessern.",
			source = "https://warcraft.wiki.gg/wiki/Uldum",
		},
		["valley of the watchers"] = {
			name = "Tal der Behüter",
			short = "Ein großes Tor steht im Tal der Behüter, undurchdringlich gegen Uldum dahinter. Berggiganten, die Dünenzerkracher heißen, streifen durch das Tal.",
			full = "Ein großes Tor steht im Tal der Behüter, undurchdringlich gegen Uldum dahinter. Berggiganten, die Dünenzerkracher heißen, streifen durch das Tal.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_the_Watchers",
		},
		["waterspring field"] = {
			name = "Waterspring-Feld",
			short = "Wassertürme ragen über dem Waterspring-Feld auf und pumpen Wasser aus Reserven tief im Untergrund herauf. Die Goblins von Gadgetzan haben sie gebaut, um ihre Unternehmungen in der Wüste zu versorgen.",
			full = "Wassertürme ragen über dem Waterspring-Feld auf und pumpen Wasser aus Reserven tief im Untergrund herauf. Die Goblins von Gadgetzan haben sie gebaut, um ihre Unternehmungen in der Wüste zu versorgen. Dann kamen die Wüstenwanderer, eine nomadische Banditenbande, und beanspruchten das Feld und die Türme für sich.\n\nSie hocken auf dem Land unter ihrem Anführer, Kalif Skorpidstich, und hoffen, dass es freundlicher zu ihnen ist als das Ogerlager, in dem sie einst lebten. Sie schaudern noch immer bei der Erinnerung. Die Gadgetzan Water Company will ihre Türme zurück.",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
		},
		["wavestrider beach"] = {
			name = "Wellenschreiterstrand",
			short = "Zwei Schiffe brennen vor der Küste des Wellenschreiterstrands, und sie scheinen gegeneinander zu kämpfen. Der Strand zieht sich an der Ostküste von Tanaris entlang, nahe Steamwheedle.",
			full = "Zwei Schiffe brennen vor der Küste des Wellenschreiterstrands, und sie scheinen gegeneinander zu kämpfen. Der Strand zieht sich an der Ostküste von Tanaris entlang, nahe Steamwheedle. Wüstenkriecher huschen über den Sand, neben Stahlkieferschnappern.",
			source = "https://warcraft.wiki.gg/wiki/Wavestrider_Beach",
		},
		["zalashjis den"] = {
			name = "Zalashjis Bau",
			short = "Ein Naga namens Zalashji lebt in diesem Bau im Osten von Tanaris. Er wandert zwischen der Höhle und dem nahen Strand umher, von wo er über das Wasser blickt.",
			full = "Ein Naga namens Zalashji lebt in diesem Bau im Osten von Tanaris. Er wandert zwischen der Höhle und dem nahen Strand umher, von wo er über das Wasser blickt.",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "Zul'Farrak",
			short = "Häuptling Ukorz Sandskalp herrscht über Zul'Farrak, die Stadt der Sandfurytrolle im Nordwesten von Tanaris. Die Sandfurytrolle sind für ihre besondere Skrupellosigkeit und dunkle Mystik bekannt.",
			full = "Häuptling Ukorz Sandskalp herrscht über Zul'Farrak, die Stadt der Sandfurytrolle im Nordwesten von Tanaris. Die Sandfurytrolle sind für ihre besondere Skrupellosigkeit und dunkle Mystik bekannt. Ukorz wuchs mit Geschichten aus einer Zeit auf, in der Trolle ohne Fremde im Weg über diese Länder herrschten, und er will diese Zeit zurück. Die Sandfurytrolle stellen ein Heer untoter Trolle auf, um sie zu gewinnen.\n\nZul'Farrak war einst das strahlende Juwel von Tanaris, und seine Trolle haben seitdem viel von ihrem Gebiet aufgeben müssen. Oger und Banditen hocken nun in ihren alten Städten. Trollsagen erzählen von Sul'thraze dem Peitscher, einem Schwert, das selbst den stärksten Feind mit Furcht und Schwäche erfüllt. Es wurde vor langer Zeit in zwei Hälften geteilt, und Gerüchte setzen beide Hälften hinter diese sonnenverbrannten Mauern. Andere sagen, ein Halbgott schlafe in einem heiligen Teich im Herzen der Stadt.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
		},
	},
	-- Azshara: 26 subzones
	[1447] = {
		["bay of storms"] = {
			name = "Die Bucht der Stürme",
			short = "Die Bucht der Stürme ist ein Stück des Großen Meeres vor der Ostküste von Azshara, und Reisende kennen sie für die Stürme, die sich darüber zusammenbrauen.",
			full = "Die Bucht der Stürme ist ein Stück des Großen Meeres vor der Ostküste von Azshara, und Reisende kennen sie für die Stürme, die sich darüber zusammenbrauen. Als die Welt zerbrach, versank ein Großteil der nachtelfischen Stadt Eldarath in ihrem Wasser, und die ertrunkenen Steine liegen noch unter der Oberfläche.",
			source = "https://warcraft.wiki.gg/wiki/Bay_of_Storms",
		},
		["bears head"] = {
			name = "Bärenkopf",
			short = "Furbolg-Dörfer sprenkeln das Land am Bärenkopf, kleine Außenposten des Stammes der Holzschlund, die den größeren Siedlungen der Holzschlund im Norden dienen.",
			full = "Furbolg-Dörfer sprenkeln das Land am Bärenkopf, kleine Außenposten des Stammes der Holzschlund, die den größeren Siedlungen der Holzschlund im Norden dienen. Der Ort ist nach ihnen benannt.\n\nAuf einer Klippe über ihnen steht der Turm von Erzmagier Xylem, der dort mit mehreren Lehrlingen und Mitstreitern lebt.",
			source = "https://warcraft.wiki.gg/wiki/Bear's_Head",
		},
		["bitter reaches"] = {
			name = "Bittere Landzunge",
			short = "Der Nordosten von Azshara wird die Bittere Landzunge genannt. Hippogryphen, Schleime und Schimären füllen das Land.",
			full = "Der Nordosten von Azshara wird die Bittere Landzunge genannt. Hippogryphen, Schleime und Schimären füllen das Land. An seinem Nordrand haben Berggiganten den größten Teil der übrigen Tierwelt vertrieben und halten den Boden für sich.",
			source = "https://warcraft.wiki.gg/wiki/Bitter_Reaches",
		},
		["forlorn ridge"] = {
			name = "Der einsame Grat",
			short = "Der einsame Grat, ein Berg, erhebt sich über dem Südwesten von Azshara und beherrscht das Land ringsum. Sowohl die Allianz als auch die Horde haben an seinen Hängen Befestigungen gebaut.",
			full = "Der einsame Grat, ein Berg, erhebt sich über dem Südwesten von Azshara und beherrscht das Land ringsum. Sowohl die Allianz als auch die Horde haben an seinen Hängen Befestigungen gebaut.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Ridge",
		},
		["haldarr encampment"] = {
			name = "Lager der Haldarr",
			short = "Der Klan der Haldarr unter den Satyrn hat sein Lager im Westen von Azshara aufgeschlagen, nordöstlich des Shadowsong-Schreins und südwestlich von Valormok.",
			full = "Der Klan der Haldarr unter den Satyrn hat sein Lager im Westen von Azshara aufgeschlagen, nordöstlich des Shadowsong-Schreins und südwestlich von Valormok. Das Lager wimmelt von bösartigen Satyrn, einer verderbten Schar bocksbeiniger Unholde.",
			source = "https://warcraft.wiki.gg/wiki/Haldarr_Encampment",
		},
		["hetaeras clutch"] = {
			name = "Hetaeras Gelege",
			short = "Unter den Wassern der Bucht der Stürme liegt Hetaeras Gelege, ein großer Tempel der Elune, heute die Heimat von Hydren, den Kindern Hetaeras.",
			full = "Unter den Wassern der Bucht der Stürme liegt Hetaeras Gelege, ein großer Tempel der Elune, heute die Heimat von Hydren, den Kindern Hetaeras. Hetaera selbst schwimmt im Meer gleich nördlich davon, ruht manchmal auf einer winzigen Insel dort und nennt sich Herrscherin dieser Gewässer. Sie hat viele Söhne des Meeresriesen Lord Arkkoroc getötet, der sie eine falsche Göttin nennt.",
			source = "https://warcraft.wiki.gg/wiki/Hetaera's_Clutch",
		},
		["jagged reef"] = {
			name = "Gezacktes Riff",
			short = "Fontänen aus Stein durchbrechen immer wieder den sandigen Strand an Azsharas Nordküste, und kleine Buchten des Meeres schneiden ins Ufer.",
			full = "Fontänen aus Stein durchbrechen immer wieder den sandigen Strand an Azsharas Nordküste, und kleine Buchten des Meeres schneiden ins Ufer. Felsen und Untiefen verbergen sich unter der Oberfläche, deshalb ist das Reisen entlang der Küste gefährlich. Murlocs, Hydren und Makrura halten dieses Ufer, schwimmen durch die Untiefen oder stapfen auf der Suche nach Nahrung über den Sand.",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "Mennarsee",
			short = "Die Wasser des Mennarsees liegen in der Mitte still, obwohl Drachenbrut auf allen Seiten den Boden hält.",
			full = "Die Wasser des Mennarsees liegen in der Mitte still, obwohl Drachenbrut auf allen Seiten den Boden hält. Wer diesen Ring durchquert, findet den See selbst frei von Gefahr, einen Ort der Ruhe und Erfrischung innerhalb der bewachten Ufer.\n\nNur wenige Orte der Welt beherbergen den blauen Drachenschwarm, und der einzige andere ist Mazthoril in Winterspring. Junge azurblaue Welpen sind in der Nähe dieser Gewässer ein häufiger Anblick.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "Lager der Legashi",
			short = "Die Sekte der Legashi unter den Satyrn schlägt ihr Lager im Norden von Azshara auf, östlich von Ursolan. Meister Gräuelbart führt sie hier an.",
			full = "Die Sekte der Legashi unter den Satyrn schlägt ihr Lager im Norden von Azshara auf, östlich von Ursolan. Meister Gräuelbart führt sie hier an.",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["ravencrest monument"] = {
			name = "Ravencrest-Monument",
			short = "Zwei zerbrochene Beine stehen auf den Klippen an der Südspitze von Azshara, alles, was von einem uralten nachtelfischen Koloss übrig ist.",
			full = "Zwei zerbrochene Beine stehen auf den Klippen an der Südspitze von Azshara, alles, was von einem uralten nachtelfischen Koloss übrig ist. Der Rest der Gestalt liegt verstreut auf dem Stein um sie herum oder ist unter die Wellen darunter gerutscht. Wen sie ehrte, ist nicht bekannt.\n\nDie Naga der Grollflossen halten heute die Ruinen.",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "Rethress Sanktum",
			short = "Rethress Sanktum, ein zerfallener Schrein an der Südküste, steht zerbrochen inmitten der verfallenen Gegenden. Niemand hält ihn heute.",
			full = "Rethress Sanktum, ein zerfallener Schrein an der Südküste, steht zerbrochen inmitten der verfallenen Gegenden. Niemand hält ihn heute. Murlocs und Makrura wandern durch seine gefallenen Steine, die Einzigen, die überhaupt hierherkommen.",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "Die verfallenen Gegenden",
			short = "Die verfallenen Gegenden ziehen sich an der Südküste von Azshara entlang, nahe der Grenze zu Durotar. Klippen und Strände gehen in Buchten über, und Ruinen und Schiffswracks liegen über sie verstreut.",
			full = "Die verfallenen Gegenden ziehen sich an der Südküste von Azshara entlang, nahe der Grenze zu Durotar. Klippen und Strände gehen in Buchten über, und Ruinen und Schiffswracks liegen über sie verstreut. Untiefen dicht unter dem Wasser machen die Küste tückisch, und Murlocs, Hydren und Makrura halten das Ufer.\n\nAuf einem Hügel über dem westlichen Strand steht ein gnomisches Haus, in dem Blimo und Jubie Federdings leben und handeln. Im Obergeschoss ihres Schlafzimmers steht ein drittes Bett, und niemand weiß, wer, wenn überhaupt jemand, darin schläft.",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "Die Ruinen von Eldarath",
			short = "Eldarath war eine mächtige Festung der Hochgeborenen, bevor die Welt zerbrach.",
			full = "Eldarath war eine mächtige Festung der Hochgeborenen, bevor die Welt zerbrach. Ihre größten Magier meißelten Runen und Tafeln, die die Regeln des Arkanen und ihre Einsichten darin darlegten, und ließen sie an öffentlichen Orten zurück, damit jeder darüber nachsinnen konnte. Im Krieg der Ahnen kämpfte hier der nachtelfische Widerstand gegen die Brennende Legion. Dann kam die Große Zerschlagung, und der größte Teil der Stadt stürzte in die Bucht der Stürme.\n\nWas übrig ist, klammert sich an die östlichen Klippen, eine Ansammlung von Ruinen, die die Nachtelfen seit Langem meiden. Wilde Scharen von Naga haben sie in Besitz genommen, und Kriegsherr Krellian herrscht über sie vom Tempel von Zin-Malor aus. Viele der alten Tafeln stehen noch zwischen den Trümmern.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "Schuppenbarts Höhle",
			short = "Eine Höhle auf einer winzigen Insel in der westlichen Bucht der Stürme ist der Bau von Schuppenbart, einer seltenen Schildkröte. Er ist selten zu Hause, da er lieber weit draußen im Großen Meer jagt.",
			full = "Eine Höhle auf einer winzigen Insel in der westlichen Bucht der Stürme ist der Bau von Schuppenbart, einer seltenen Schildkröte. Er ist selten zu Hause, da er lieber weit draußen im Großen Meer jagt.",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "Shadowsong-Schrein",
			short = "Ein von Ruinen bedeckter Hügel im Westen von Azshara trägt den Namen Schattensang.",
			full = "Ein von Ruinen bedeckter Hügel im Westen von Azshara trägt den Namen Schattensang. Er teilt diesen Namen mit Jarod Schattensang, der im Krieg der Ahnen den Widerstand befehligte, und mit seiner älteren Schwester Maiev, der Wärterin, die Illidan Stormrage nach seinem Verrat am Berg Hyjal gefangen hielt. Was einer von beiden mit dem Hügel zu tun hat, weiß niemand.\n\nDie Geister der Hochgeborenen spuken zwischen den Steinen und im Land ringsum, darauf aus, jedes Leben auszulöschen, das sich nähert.",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "Der zertrümmerte Strand",
			short = "Der Nordstrand der Bucht der Stürme ist überfüllt. Hydren, Meeresriesen, Makrura und Murlocs halten je ein Stück des Sandes, und ein alter Tempel und ein Turm erheben sich zwischen ihnen vom Ufer.",
			full = "Der Nordstrand der Bucht der Stürme ist überfüllt. Hydren, Meeresriesen, Makrura und Murlocs halten je ein Stück des Sandes, und ein alter Tempel und ein Turm erheben sich zwischen ihnen vom Ufer.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southfury river"] = {
			name = "Der Südstrom",
			short = "Der Südstrom entspringt in einem See auf dem Berg Hyjal und stürzt in einer Reihe spektakulärer Wasserfälle ins Tiefland.",
			full = "Der Südstrom entspringt in einem See auf dem Berg Hyjal und stürzt in einer Reihe spektakulärer Wasserfälle ins Tiefland. Von dort fließt er breit und schnell, und er ist die Grenze zwischen dem Wald von Ashenvale und Azshara und weiter südlich zwischen dem Brachland und Durotar. Nahe seiner Mündung stürzt er über einen letzten Wasserfall ins Große Meer, nordöstlich des Goblinhafens Ratchet.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "Southridge-Strand",
			short = "Der Southridge-Strand säumt den Südrand der Bucht der Stürme, sein Sand übersät mit Ruinen der einst großen Stadt Eldarath.",
			full = "Der Southridge-Strand säumt den Südrand der Bucht der Stürme, sein Sand übersät mit Ruinen der einst großen Stadt Eldarath. Naga halten heute das Ufer und teilen es mit Makrura, Hydren, Murlocs und gelegentlich einem Meeresriesen, der aus tieferem Wasser aufgestiegen ist.",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "Sturmklippen",
			short = "Die Naga der Grollflossen haben sich zwischen dem Fels der Sturmklippen niedergelassen. Am äußersten östlichen Rand der Klippen steht das Ravencrest-Monument.",
			full = "Die Naga der Grollflossen haben sich zwischen dem Fels der Sturmklippen niedergelassen. Am äußersten östlichen Rand der Klippen steht das Ravencrest-Monument.",
			source = "https://warcraft.wiki.gg/wiki/Storm_Cliffs",
		},
		["talrendis point"] = {
			name = "Talrendisspitze",
			short = "Nachtelfen unterhalten ein kleines Lager an der Talrendisspitze, im Südwesten von Azshara an der Grenze zu Ashenvale. Es begann als Wache am Rand des Waldes.",
			full = "Nachtelfen unterhalten ein kleines Lager an der Talrendisspitze, im Südwesten von Azshara an der Grenze zu Ashenvale. Es begann als Wache am Rand des Waldes.",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "Der Tempel von Arkkoran",
			short = "Dieser Tempel am nordöstlichen Ufer von Azshara gehörte einst zur Verehrung der Elune. Heute lebt Lord Arkkoroc, ein Meeresriese, der als Halbgott verehrt wird, an seiner Spitze.",
			full = "Dieser Tempel am nordöstlichen Ufer von Azshara gehörte einst zur Verehrung der Elune. Heute lebt Lord Arkkoroc, ein Meeresriese, der als Halbgott verehrt wird, an seiner Spitze. Murlocs und Makrura bewachen den Tempel und greifen auf Sicht an, und seine Söhne patrouillieren ringsum. Hydren und wilde Meeresriesen beobachten das Ufer dahinter.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "Tempel von Zin-Malor",
			short = "Zwischen den Steinen von Eldarath steht ein Tempel der Elune, von Nachtelfen errichtet. Seine Bauweise ähnelt auffallend dem Tempel von Arkkoran und dem Tempel des Mondes in Darnassus.",
			full = "Zwischen den Steinen von Eldarath steht ein Tempel der Elune, von Nachtelfen errichtet. Seine Bauweise ähnelt auffallend dem Tempel von Arkkoran und dem Tempel des Mondes in Darnassus. Die Naga der Grollflossen halten ihn heute, und ihr grausamer Anführer, Kriegsherr Krellian, sitzt auf dem Ehrenplatz.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "Thalassischer Stützpunkt",
			short = "Blutelfen halten den Hügel über den Lagern der Legashi, eine Streuung kleiner befestigter Lager an seinen Hängen unter Magus Rimtori.",
			full = "Blutelfen halten den Hügel über den Lagern der Legashi, eine Streuung kleiner befestigter Lager an seinen Hängen unter Magus Rimtori. Sie schloss einen Handel mit der Horde, einen Anteil an allem, was ihre Expedition ausgrub, im Austausch für Gold und Stahl zu dessen Schutz, und sie brach ihn.\n\nRimtori ist selten hier. Sie erkundet Azshara unter einer eigenen Wache, und Magistrix Falkhelm hält das Lager in ihrer Abwesenheit. Auf einem Grat liegt ein nachtelfischer Beschwörungsfoliant, ein Buch, das Dämonen in die Welt rufen kann. Sein Vorhandensein lässt vermuten, dass die Expedition dunklere Ziele hat als Schätze.",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["tower of eldara"] = {
			name = "Turm von Eldara",
			short = "Der Turm von Eldara steht auf der äußersten nordöstlichen Landspitze über der Bucht der Stürme, sein sandiges Ufer von Murlocs, Makrura und Hydren bewacht.",
			full = "Der Turm von Eldara steht auf der äußersten nordöstlichen Landspitze über der Bucht der Stürme, sein sandiges Ufer von Murlocs, Makrura und Hydren bewacht. Er gehörte einst zu der nachtelfischen Zivilisation, die sich über diese Küste ausbreitete, doch heute steht der Turm verschlossen und verlassen.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["ursolan"] = {
			name = "Ursolan",
			short = "Die Furbolgs verehren Ursol, einen Bärenhalbgott, und Ursolan trägt seinen Namen von ihm.",
			full = "Die Furbolgs verehren Ursol, einen Bärenhalbgott, und Ursolan trägt seinen Namen von ihm. Das Gebiet ist heute eine große Siedlung der Holzschlund-Furbolgs, die sich südlich durch die Holzschlundfeste bis zum Bärenkopf erstreckt.",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "Valormok",
			short = "Valormok, ein Außenposten der Horde mit Orckriegern im Nordwesten von Azshara, steht kahl und schwach bewacht. Die Horde nahm an diesem feindlichen Land zunächst wenig Anteil.",
			full = "Valormok, ein Außenposten der Horde mit Orckriegern im Nordwesten von Azshara, steht kahl und schwach bewacht. Die Horde nahm an diesem feindlichen Land zunächst wenig Anteil. Ihre Krieger ertragen harte Zeiten und bewahren ihre Hoffnung.\n\nBelgrom Felshammer schickte die Blutelfe Magus Rimtori mit einer Schar Orckrieger in die Region, um Reichtümer und mächtige Artefakte zu finden. Sie fand, was sie suchte, tötete dann die Krieger, die sie begleitet hatten, und behielt die Beute. Ag'tor Blutfaust, der das Lager anführt, wird das Gemetzel nicht unbeantwortet lassen. Er will Rache für seine Toten und für Felshammers verletzten Stolz.",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
	},
	-- Teufelswald: 18 subzones
	[1448] = {
		["bloodvenom falls"] = {
			name = "Die Blutgiftfälle",
			short = "Vergiftetes Wasser stürzt an den Blutgiftfällen von den Höhen und speist den Blutgiftbach. Furbolgs sind zäh genug, es zu trinken und zu überleben, doch das Wasser vertieft nur ihren Wahnsinn.",
			full = "Vergiftetes Wasser stürzt an den Blutgiftfällen von den Höhen und speist den Blutgiftbach. Furbolgs sind zäh genug, es zu trinken und zu überleben, doch das Wasser vertieft nur ihren Wahnsinn.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Falls",
		},
		["bloodvenom post"] = {
			name = "Blutgiftposten",
			short = "Ein kleiner Außenposten der Horde steht auf den hohen Klippen über der Dunkelküste, nahe dem Blutgiftbach, wo er durch den Teufelswald schneidet.",
			full = "Ein kleiner Außenposten der Horde steht auf den hohen Klippen über der Dunkelküste, nahe dem Blutgiftbach, wo er durch den Teufelswald schneidet. Seine alte Bauweise und die Tauren, die ihn bewachen, lassen vermuten, dass Tauren ihn gegründet haben.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Post",
		},
		["bloodvenom river"] = {
			name = "Blutgiftbach",
			short = "Der Blutgiftbach fließt durch die Mitte des Teufelswaldes, und seine Ufer wimmeln von giftigen Schleimen und verderbten Tieren. Das Wasser ist weder zum Trinken noch zum Schwimmen geeignet.",
			full = "Der Blutgiftbach fließt durch die Mitte des Teufelswaldes, und seine Ufer wimmeln von giftigen Schleimen und verderbten Tieren. Das Wasser ist weder zum Trinken noch zum Schwimmen geeignet. Seine Verderbnis endet nicht am Rand des Waldes. Weiter flussabwärts kommt der Fluss die Berge herab und wird zum kranken Wildbend an der Dunkelküste.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_River",
		},
		["deadwood village"] = {
			name = "Lager der Totenwaldfelle",
			short = "Die Furbolgs der Totenwaldfelle halten dieses Dorf im Süden des Teufelswaldes. Wie die meisten ihrer Art sind sie von der Verderbnis des Waldes angesteckt worden, und sie greifen Fremde auf Sicht an.",
			full = "Die Furbolgs der Totenwaldfelle halten dieses Dorf im Süden des Teufelswaldes. Wie die meisten ihrer Art sind sie von der Verderbnis des Waldes angesteckt worden, und sie greifen Fremde auf Sicht an.",
			source = "https://warcraft.wiki.gg/wiki/Deadwood_Village",
		},
		["emerald sanctuary"] = {
			name = "Das Smaragdrefugium",
			short = "Druiden des Smaragdkreises unterhalten ein Lager im Südosten des Teufelswaldes. Sie arbeiten daran, die dämonische Verderbnis zu ersticken, die sich von Jaedenar ausbreitet.",
			full = "Druiden des Smaragdkreises unterhalten ein Lager im Südosten des Teufelswaldes. Sie arbeiten daran, die dämonische Verderbnis zu ersticken, die sich von Jaedenar ausbreitet. Eine von ihnen, Greta Mosshoof, bekämpft die bösen Satyrn, um die Verseuchung zu tilgen, die sie verbreitet haben.",
			source = "https://warcraft.wiki.gg/wiki/Emerald_Sanctuary",
		},
		["felpaw village"] = {
			name = "Revier der Teufelspfoten",
			short = "Das Revier der Teufelspfoten liegt im äußersten Norden des Teufelswaldes, nahe dem Eingang zur Holzschlundfeste.",
			full = "Das Revier der Teufelspfoten liegt im äußersten Norden des Teufelswaldes, nahe dem Eingang zur Holzschlundfeste. Es gehört den Totenwaldfellen, Furbolgs, deren Verderbnis sie von ihren Verwandten abgewandt hat, und ihre Verseuchung zeichnet noch den Boden, den sie halten.\n\nHäuptling Blutmagen lebt hier unter seinen Schamanen, Rächern und Höhlenbehütern.",
			source = "https://warcraft.wiki.gg/wiki/Felpaw_Village",
		},
		["irontree cavern"] = {
			name = "Eisenstammhöhle",
			short = "Wucherborkenschredder und Wucherborkenschinder streifen durch die Dunkelheit dieser tiefen Höhle.",
			full = "Wucherborkenschredder und Wucherborkenschinder streifen durch die Dunkelheit dieser tiefen Höhle.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree woods"] = {
			name = "Der Eisenwald",
			short = "Der Eisenwald war einst eine friedliche Lichtung im Norden des Teufelswaldes, bevor die Verderbnis der Brennenden Legion ihn zu etwas anderem verdrehte.",
			full = "Der Eisenwald war einst eine friedliche Lichtung im Norden des Teufelswaldes, bevor die Verderbnis der Brennenden Legion ihn zu etwas anderem verdrehte. Drei große Urtume der Nachtelfen lebten hier, lebende Bäume namens Hastat, Stoma und Vartrus. Die Verderbnis versteinerte alle drei, und sie bleiben im Wald eingeschlossen.\n\nWahnsinnige Treants, verdrehte Sumpfbestien, wilde Tiere und verderbte Wasserelementare streifen zwischen ihnen umher und greifen jeden an, der sich nähert.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "Jadefeuertal",
			short = "In den verderbten Wäldern des südlichen Teufelswaldes beherbergt das Jadefeuertal ein Lager der Jadefeuer-Satyrn, dämonische Geschöpfe, die sich die verseuchte Senke zu eigen gemacht haben, in ihrer Fäulnis gedeihen und die Verderbnis weiter durch die Bäume ringsum verbreiten.",
			full = "In den verderbten Wäldern des südlichen Teufelswaldes beherbergt das Jadefeuertal ein Lager der Jadefeuer-Satyrn, dämonische Geschöpfe, die sich die verseuchte Senke zu eigen gemacht haben, in ihrer Fäulnis gedeihen und die Verderbnis weiter durch die Bäume ringsum verbreiten.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
		},
		["jadefire run"] = {
			name = "Jadefeuerbach",
			short = "Die mächtigsten Satyrn des Teufelswaldes haben ihr Zuhause in diesem Lager im Norden des Waldes.",
			full = "Die mächtigsten Satyrn des Teufelswaldes haben ihr Zuhause in diesem Lager im Norden des Waldes.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "Jaedenar",
			short = "Jaedenar erhebt sich aus Boden, der einst den Nachtelfen gehörte, seine Ruinen älter als die Verderbnis, die nun Anspruch auf sie erhebt.",
			full = "Jaedenar erhebt sich aus Boden, der einst den Nachtelfen gehörte, seine Ruinen älter als die Verderbnis, die nun Anspruch auf sie erhebt. Unter ihm liegen zwei druidische Grabhügel, einst heilig, und sein Name wurde in Anbetung Kil'jaedens, des Betrügers, gegeben.\n\nNach dem Dritten Krieg fielen die Ruinen an den Schattenrat unter Lord Banehollow. Seine Kultisten sind meist Hexenmeister der Orcs und der Verlassenen, und Dämonen dienen neben ihnen, darunter Sukkubi, Teufelsjäger, Teufelswachen und Satyrn. In seinem Herzen steht die Schattenfeste, und daneben der Schrein des Betrügers.",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "Morlos'Aran",
			short = "Morlos'Aran war einst eine große nachtelfische Siedlung, lange vor der Großen Zerschlagung errichtet. Heute liegt sie in Ruinen am südlichen Rand des Teufelswaldes.",
			full = "Morlos'Aran war einst eine große nachtelfische Siedlung, lange vor der Großen Zerschlagung errichtet. Heute liegt sie in Ruinen am südlichen Rand des Teufelswaldes.\n\nNachtelfische Ruinen dieser Art liegen über die Dunkelküste, Ashenvale und Desolace verstreut. Einst blühende Städte, sind sie heute nur noch Stein und eine Erinnerung an ein goldenes Zeitalter, das lange vergangen ist.",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "Ruinen von Constellas",
			short = "Zerbrochene Säulen zeigen, was offenbar eine der nachtelfischen Siedlungen nahe dem Berg Hyjal war. Ein Mondbrunnen ruht noch zwischen ihnen, doch er enthält kein reines Licht mehr.",
			full = "Zerbrochene Säulen zeigen, was offenbar eine der nachtelfischen Siedlungen nahe dem Berg Hyjal war. Ein Mondbrunnen ruht noch zwischen ihnen, doch er enthält kein reines Licht mehr. Teufelsenergie hat sich in sein Wasser gesogen, und der Satyr Xavathras und seine Jadefeuer-Satyrn hegen die Verderbnis im Namen von Xavaric. Tiefer in den Ruinen versperrt eine Feuerwand den Weg zu Xavathras.\n\nDruidische Smaragdbärkin greifen hier die Dämonen an.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "Schattenfeste",
			short = "Ein gigantisches Labyrinth, das einst ein nachtelfischer Grabhügel war, liegt innerhalb von Jaedenar im Westen des Teufelswaldes.",
			full = "Ein gigantisches Labyrinth, das einst ein nachtelfischer Grabhügel war, liegt innerhalb von Jaedenar im Westen des Teufelswaldes. Es ist heute die Festung des Schattenrats auf Azeroth, und Hexenmeister und ihre dämonischen Diener streifen durch seine Tunnel. Der Satyr Prinz Xavalis und der Schreckenslord Lord Banehollow wohnen beide hier.\n\nDer Paladin Trey Lightforge und der Nachtelf Arko'narin Sternschatten kamen in den Teufelswald, um nach Spuren des Schattenrats zu suchen. Die Kultisten nahmen beide gefangen und sperrten sie in einen Käfig in der Feste. Trey wurde dort gefoltert. Arko'narin wird noch in den Tiefen festgehalten.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "Shatter Scar-Tal",
			short = "Viele Höllenbestien fielen hier, als die Brennende Legion im Dritten Krieg einfiel. Die Krater, die sie hinterließen, schwelen noch, und Dämonen wandern noch über den vernarbten Boden.",
			full = "Viele Höllenbestien fielen hier, als die Brennende Legion im Dritten Krieg einfiel. Die Krater, die sie hinterließen, schwelen noch, und Dämonen wandern noch über den vernarbten Boden.",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "Schrein des Betrügers",
			short = "Hexenmeister des Schattenrats füllen diesen verderbten Grabhügel in Jaedenar im Teufelswald. Er ist nach Kil'jaeden benannt, dem Betrüger, dem Herrn der Brennenden Legion.",
			full = "Hexenmeister des Schattenrats füllen diesen verderbten Grabhügel in Jaedenar im Teufelswald. Er ist nach Kil'jaeden benannt, dem Betrüger, dem Herrn der Brennenden Legion.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["talonbranch glade"] = {
			name = "Nachtlaublichtung",
			short = "Dieser kleine nachtelfische Posten im Norden des Teufelswaldes ist der einzige Außenposten der Allianz im Wald. Er liegt südlich der Holzschlundfeste, am Pfad, der weiter nach Moonglade und Winterspring führt.",
			full = "Dieser kleine nachtelfische Posten im Norden des Teufelswaldes ist der einzige Außenposten der Allianz im Wald. Er liegt südlich der Holzschlundfeste, am Pfad, der weiter nach Moonglade und Winterspring führt. Er besteht aus einem nachtelfischen Haus, einem Mondbrunnen und ein paar weiteren Teilen elfischer Baukunst.",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "Holzschlundfeste",
			short = "Als die Verderbnis der Brennenden Legion in die heiligen Wälder von Kalimdor kroch, fielen die meisten Furbolgs unter ihren Einfluss und wurden in den Wahnsinn verdreht.",
			full = "Als die Verderbnis der Brennenden Legion in die heiligen Wälder von Kalimdor kroch, fielen die meisten Furbolgs unter ihren Einfluss und wurden in den Wahnsinn verdreht. Der Stamm der Holzschlund entkam ihr. Sie suchten Zuflucht in ihrer Feste im Nordosten des Teufelswaldes und sahen zu, wie der Wald, den sie liebten, zu einer eiternden Ruine seiner selbst wurde. Selbst nachdem der Anführer der Dämonen gefallen war, blieb der Makel auf den Wäldern. Die Tunnel der Feste öffnen einen Durchgang nach Moonglade und Winterspring.\n\nDie Holzschlund sind einer der beiden letzten Stämme reiner Furbolgs. Sie sind misstrauisch gegenüber Fremden, aus Furcht, für ihre verderbten Verwandten gehalten und angegriffen zu werden, doch sie schätzen Freunde über alles. Ihr Wunsch ist es, das Leid ihrer verderbten Brüder zu beenden und ein Heilmittel für die Wunde zu finden, die der Teufelswald geworden ist, damit der uralte Wald wieder von friedlichen Gesängen und leisem Lachen erklingen kann.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Un'Goro-Krater: 10 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "Der Feuerfedergrat",
			short = "Der Feuerfedergrat erhebt sich im Herzen des Un'Goro-Kraters, ein Berg aus versengtem Fels, an dessen Hängen Lava kriecht und Feuerelementare sich in der Hitze regen.",
			full = "Der Feuerfedergrat erhebt sich im Herzen des Un'Goro-Kraters, ein Berg aus versengtem Fels, an dessen Hängen Lava kriecht und Feuerelementare sich in der Hitze regen. Hier endet der Dschungel, von der Lava weggebrannt. Der stärkste der Feuerelementare, Sturmflamme, lebt in einer Höhle auf dem Gipfel, Herr über das brennende Herz des Berges.\n\nFlache Magmaadern verlaufen unter dem Kraterboden und heizen die Dampftümpel und Geysire, die in ganz Un'Goro zischen, sodass das ganze Becken vom Feuer des Berges zu atmen scheint.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "Fungal Rock",
			short = "Eine große Höhle öffnet sich in der nordöstlichen Wand des Un'Goro-Kraters. Gorillas haben sich darin zwischen den Geisterpilzen eingenistet.",
			full = "Eine große Höhle öffnet sich in der nordöstlichen Wand des Un'Goro-Kraters. Gorillas haben sich darin zwischen den Geisterpilzen eingenistet. Vor dem Eingang liegt ein kleiner Teich mit einem Wasserfall, und dort steht A-Me 01, der mechanische Affe von Karna Remtravel.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "Die heißen Quellen von Golakka",
			short = "Dampf steigt ständig aus den heißen Quellen von Golakka auf, einem Stück des westlichen Kraters voller Tümpel und Geysire, die der nahe Vulkan erhitzt.",
			full = "Dampf steigt ständig aus den heißen Quellen von Golakka auf, einem Stück des westlichen Kraters voller Tümpel und Geysire, die der nahe Vulkan erhitzt. Dampfende Furien, Elementare, patrouillieren an den Ufern der Tümpel.",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["ironstone plateau"] = {
			name = "Eisensteinplateau",
			short = "Kahler Fels durchbricht das Grün von Un'Goro an mehreren Stellen entlang des Nordostrandes des Kraters, an die Kraterwand geschmiegt.",
			full = "Kahler Fels durchbricht das Grün von Un'Goro an mehreren Stellen entlang des Nordostrandes des Kraters, an die Kraterwand geschmiegt. Das Eisensteinplateau liegt still im Vergleich zum Rest des Kraters, und hier jagen keine Monster. Pterrordaxnestlinge leben darauf, und seine Stille unterscheidet es vom rastlosen Wuchern Un'Goros.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "Teergruben von Lakkari",
			short = "Seen aus dickem, übelriechendem schwarzem Teer liegen im nördlichen Teil des Un'Goro-Kraters. Der Teer hält Kreaturen in seinem Griff, und die Knochen Hunderter Tiere ragen aus seiner Oberfläche.",
			full = "Seen aus dickem, übelriechendem schwarzem Teer liegen im nördlichen Teil des Un'Goro-Kraters. Der Teer hält Kreaturen in seinem Griff, und die Knochen Hunderter Tiere ragen aus seiner Oberfläche. Aasfresser lungern in der Nähe und suchen leichte Beute, und Teerbestien leben in den Gruben.\n\nSeltene Teerblüten wachsen am Grund. Sie sind wegen ihrer Schönheit und Haltbarkeit begehrt, doch sie liegen tief im Teer und sind schwer zu ernten.",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "Marshals Zuflucht",
			short = "Marshals Zuflucht liegt am Nordrand des Un'Goro-Kraters, errichtet von Marshals Expeditionen unter Williden Marshal und Hol'anyee Marshal.",
			full = "Marshals Zuflucht liegt am Nordrand des Un'Goro-Kraters, errichtet von Marshals Expeditionen unter Williden Marshal und Hol'anyee Marshal. Ihr Vorstoß in den Krater war nicht auf das gefasst, was er vorfand. Die Bestien von Un'Goro erwiesen sich als zu wild, und die Basislager der Expedition wurden eines nach dem anderen überrannt. Die Überlebenden flohen auf höheres Gelände und schlugen hier am Rand des Kraters ihr Lager auf.\n\nDie Zuflucht ist das, was aus diesem Rückzug wurde, ein kaum gehaltener Stützpunkt. Sie ist neutraler Boden.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "Die Marschen",
			short = "Stehendes Wasser und üppiger Wuchs breiten sich über einen großen Teil des südöstlichen Kraters in einem weiten Sumpf aus. Raptoren ziehen in großer Zahl durch das Schilf, und manche von ihnen sind giftig.",
			full = "Stehendes Wasser und üppiger Wuchs breiten sich über einen großen Teil des südöstlichen Kraters in einem weiten Sumpf aus. Raptoren ziehen in großer Zahl durch das Schilf, und manche von ihnen sind giftig. Blaue Kraftkristalle findet man hier und nirgendwo sonst im Krater.\n\nAuf einem großen Hügel stehen Torwa Pfadfinder und Garl Sturmklaue, die offenbar von anderswo im Krater mit dem Kanu hierhergekommen sind. Im Norden hat Ithis Mondwärter ein kleines Lager und wacht über junge Blutblüten.",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["shapers terrace"] = {
			name = "Die Terrasse des Formers",
			short = "Eine Terrasse, die mit den Titanen verbunden ist, liegt auf den Klippen oberhalb und östlich von Marshals Zuflucht. Sie trägt ihren Namen nach Khaz'goroth, dem Titanen, der der Former genannt wird.",
			full = "Eine Terrasse, die mit den Titanen verbunden ist, liegt auf den Klippen oberhalb und östlich von Marshals Zuflucht. Sie trägt ihren Namen nach Khaz'goroth, dem Titanen, der der Former genannt wird.",
			source = "",
		},
		["slithering scar"] = {
			name = "Die wuchernde Narbe",
			short = "Die Gorishi, eine Sekte der Silithiden, halten mit ihrem Bau den größten Teil des südlichen Un'Goro-Kraters. Sie ziehen hier einen Koloss auf, und wenn er ausgewachsen ist, wird er in den Krater entlassen.",
			full = "Die Gorishi, eine Sekte der Silithiden, halten mit ihrem Bau den größten Teil des südlichen Un'Goro-Kraters. Sie ziehen hier einen Koloss auf, und wenn er ausgewachsen ist, wird er in den Krater entlassen.",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
		},
		["terror run"] = {
			name = "Terrorflucht",
			short = "Im Südwesten des Un'Goro-Kraters, gleich westlich der wuchernden Narbe, versammeln sich Stegodons, Dimetrodons, Pterrordax und Teufelssaurier in großer Zahl, und alle sind feindselig.",
			full = "Im Südwesten des Un'Goro-Kraters, gleich westlich der wuchernden Narbe, versammeln sich Stegodons, Dimetrodons, Pterrordax und Teufelssaurier in großer Zahl, und alle sind feindselig. Rote Kristalle wachsen hier und nirgendwo sonst im Krater.\n\nEntlang des Ostrandes liegt ein verlassenes Forschungslager, das Marshals Expeditionen zurückgelassen haben, die Ausrüstung noch dort, wo sie fallen gelassen wurde.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Run",
		},
	},
	-- Moonglade: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "Der Elune'ara See",
			short = "Kristallklares Wasser füllt das Herz von Moonglade, still wie Glas unter den Bäumen. Der See ist nach Elune selbst benannt.",
			full = "Kristallklares Wasser füllt das Herz von Moonglade, still wie Glas unter den Bäumen. Der See ist nach Elune selbst benannt.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "Nighthaven",
			short = "Am Ufer des Elune'ara Sees steht Nighthaven, ein Dorf aus nachtelfischem Mauerwerk mit einem Paar Mondbrunnen, die Heimat der Druiden des Zirkels des Cenarius.",
			full = "Am Ufer des Elune'ara Sees steht Nighthaven, ein Dorf aus nachtelfischem Mauerwerk mit einem Paar Mondbrunnen, die Heimat der Druiden des Zirkels des Cenarius. Es ist ein stiller, abgelegener Ort, gewöhnlich Fremden verschlossen, und seine Leute widmen sich dem Druidentum und der Pflege der Wildnis.",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "Der Schrein von Remulos",
			short = "Der Westen von Moonglade birgt einen Schrein, der Bewahrer Remulos gewidmet ist, dem Hüter des Tals. Die Nachtelfe Tajarri lebt darin.",
			full = "Der Westen von Moonglade birgt einen Schrein, der Bewahrer Remulos gewidmet ist, dem Hüter des Tals. Die Nachtelfe Tajarri lebt darin.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "Die Stormrage Grabhügel",
			short = "Unter dem stillen Rasen von Moonglade liegen die Grabhügel, in die Erde gesenkt, die viele nachtelfische Druiden nie wirklich verlassen, ihre Körper ruhend, während ihre Geister durch den Smaragdgrünen Traum wandern.",
			full = "Unter dem stillen Rasen von Moonglade liegen die Grabhügel, in die Erde gesenkt, die viele nachtelfische Druiden nie wirklich verlassen, ihre Körper ruhend, während ihre Geister durch den Smaragdgrünen Traum wandern.\n\nHier schlief einst Malfurion Stormrage, und die Hügel tragen deshalb seinen Namen. Als Tichondrius und seine Schreckenslords im Dritten Krieg kamen, griffen sie Malfurion dort an, wo er lag, und rissen seinen Grabhügel beinahe auseinander. Es war Tyrande Whisperwind, die ihn weckte und in die Welt zurückrief, damit er sich Archimonde und der Brennenden Legion entgegenstellte.\n\nSpäter, als der Zirkel des Cenarius davon sprach, einen zweiten Weltenbaum zu errichten, kehrte Malfurion in die Grabhügel zurück, um zu meditieren. Tyrande kam später, um ihn zu suchen, und fand seinen Körper still hingestreckt, als schliefe er, und nicht zu wecken. Der Zirkel hielt es für klüger, ihn nicht zu bewegen, denn wenn sein Geist noch durch den Traum wanderte und den Weg nach Hause suchte, musste er den Körper dort finden, wo er ihn verlassen hatte. So blieb er dort, bewacht vom Zirkel des Cenarius und der Schwesternschaft von Elune, sein Körper still liegend in dem Grabhügel, der seinen Namen trägt.",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "Holzschlundfeste",
			short = "Der Stamm der Holzschlund hat seine Hauptstadt im Nordosten des Teufelswaldes, und ein Tunnel durch die Feste führt hinaus nach Moonglade und Winterspring.",
			full = "Der Stamm der Holzschlund hat seine Hauptstadt im Nordosten des Teufelswaldes, und ein Tunnel durch die Feste führt hinaus nach Moonglade und Winterspring. Als die Verderbnis der Brennenden Legion in die heiligen Wälder von Kalimdor kroch, fielen die anderen Furbolgs unter ihren Einfluss. Die Holzschlund entkamen ihr und suchten Zuflucht in der Feste, und sie haben zugesehen, wie der Wald, den sie liebten, zu einer eiternden Ruine seiner selbst verdreht wurde. Selbst nachdem die Quelle dieser Verderbnis zerstört war, blieb der Makel auf den Wäldern.\n\nDie Holzschlund wollen ein Ende des Leidens ihrer verderbten Verwandten und ein Heilmittel für das Land, damit der uralte Wald eines Tages wieder von Gesängen und Lachen erklingen kann.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Silithus: 19 subzones
	[1451] = {
		["bones of grakkarond"] = {
			name = "Knochen von Grakkarond",
			short = "Die riesigen Knochen des Bronzedrachen Grakkarond liegen im mittleren Silithus. Ossirian der Narbenlose erschlug Grakkarond im Krieg der Sandstürme.",
			full = "Die riesigen Knochen des Bronzedrachen Grakkarond liegen im mittleren Silithus. Ossirian der Narbenlose erschlug Grakkarond im Krieg der Sandstürme. Die Anubisath halten die Knochen für heilig.",
			source = "https://warcraft.wiki.gg/wiki/Bones_of_Grakkarond",
		},
		["bronzebeard encampment"] = {
			name = "Bronzebeards Lager",
			short = "Rutgar Glyphenschnitzer arbeitet in einem Lager im südlichen Silithus, östlich des Skarabäuswalls, und fragt nach dem Verbleib des berühmten Forschers Brann Bronzebeard.",
			full = "Rutgar Glyphenschnitzer arbeitet in einem Lager im südlichen Silithus, östlich des Skarabäuswalls, und fragt nach dem Verbleib des berühmten Forschers Brann Bronzebeard.",
			source = "https://warcraft.wiki.gg/wiki/Bronzebeard_Encampment",
		},
		["cenarion hold"] = {
			name = "Burg Cenarius",
			short = "Burg Cenarius steht in Silithus auf dem Boden einer uralten nachtelfischen Siedlung. Sie ist eine der größten Druidenfestungen Kalimdors, fast so groß wie Moonglade selbst.",
			full = "Burg Cenarius steht in Silithus auf dem Boden einer uralten nachtelfischen Siedlung. Sie ist eine der größten Druidenfestungen Kalimdors, fast so groß wie Moonglade selbst. Nach dem Krieg der Sandstürme übernahm der Zirkel des Cenarius die Pflicht, sie gegen die Silithiden und die anderen Mächte zu verteidigen, die in dieser Region feindseliger werden, und den gefangenen Alten Gott C'Thun und seine Heere zu bewachen.\n\nEs ist ein harter, umkämpfter Ort zum Leben, und die Silithiden drängen unablässig gegen seine Mauern.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "Das Kristalltal",
			short = "In der äußersten nordwestlichen Ecke von Silithus liegt das Kristalltal, ein Tal in der Hand von Erd- und Luftelementaren. Thorium liegt dicht in seinem Stein.",
			full = "In der äußersten nordwestlichen Ecke von Silithus liegt das Kristalltal, ein Tal in der Hand von Erd- und Luftelementaren. Thorium liegt dicht in seinem Stein.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Vale",
		},
		["hiveashi"] = {
			name = "Bau des Ashischwarms",
			short = "Aluntir ist der Herrscher des Silithidenbaus im nördlichen Silithus. Seine Brut hat sich ausgebreitet und die Schwarmsäule befallen.",
			full = "Aluntir ist der Herrscher des Silithidenbaus im nördlichen Silithus. Seine Brut hat sich ausgebreitet und die Schwarmsäule befallen.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Ashi",
		},
		["hiveregal"] = {
			name = "Bau des Regalschwarms",
			short = "Im südlichen Silithus ragen die Hügel vom Bau des Regalschwarms aus dem Sand, Tunnel und Chitin dicht im Staub. Xil'xix ist der Herrscher dieses Silithidennestes.",
			full = "Im südlichen Silithus ragen die Hügel vom Bau des Regalschwarms aus dem Sand, Tunnel und Chitin dicht im Staub. Xil'xix ist der Herrscher dieses Silithidennestes.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Regal",
		},
		["hivezora"] = {
			name = "Bau des Zoraschwarms",
			short = "Draußen im westlichen Silithus liegt ein Silithidennest in den Sand gegraben. Arakis ist sein Herrscher.",
			full = "Draußen im westlichen Silithus liegt ein Silithidennest in den Sand gegraben. Arakis ist sein Herrscher.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Zora",
		},
		["ortells hideout"] = {
			name = "Ortells Unterschlupf",
			short = "Der Einsiedler Ortell wohnt in einer kleinen Höhle im südöstlichen Silithus.",
			full = "Der Einsiedler Ortell wohnt in einer kleinen Höhle im südöstlichen Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Ortell's_Hideout",
		},
		["ravaged twilight camp"] = {
			name = "Verwüsteter Twilight-Stützpunkt",
			short = "Hochlord Demitrian hat seinen Sitz im Verwüsteten Twilight-Stützpunkt, gelegen im Kristalltal im nordwestlichen Silithus.",
			full = "Hochlord Demitrian hat seinen Sitz im Verwüsteten Twilight-Stützpunkt, gelegen im Kristalltal im nordwestlichen Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Twilight_Camp",
		},
		["scarab dais"] = {
			name = "Die Skarabäushöhe",
			short = "Der Skarabäusgong steht auf der Skarabäushöhe im südlichen Silithus, nordwestlich des Skarabäuswalls, außerhalb von Ahn'Qiraj.",
			full = "Der Skarabäusgong steht auf der Skarabäushöhe im südlichen Silithus, nordwestlich des Skarabäuswalls, außerhalb von Ahn'Qiraj.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "Der Skarabäuswall",
			short = "Am Südrand von Silithus, zwischen der von Silithiden gehaltenen Wüste und der zerstörten Stadt Ahn'Qiraj, verläuft der Skarabäuswall.",
			full = "Am Südrand von Silithus, zwischen der von Silithiden gehaltenen Wüste und der zerstörten Stadt Ahn'Qiraj, verläuft der Skarabäuswall. Er wurde am Ende des Krieges der Sandstürme aus dem Sand selbst geformt, und seine Sandsteinmasse ragt hoch über die Wüste. Wo der Stein nicht höher steigen konnte, übernahm die Magie des bronzenen Drachenschwarms und formte eine Barriere, die um ein Vielfaches höher ist.\n\nDie Nachtelfen und Bronzedrachen, die ihn schufen, nannten ihr Werk Irana'ethil, Schild gegen den Schatten. Er hält C'Thun und seine kriechenden Diener im Innern eingesperrt.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "Südwindposten",
			short = "Der Südwindposten war ein nachtelfischer Stützpunkt, bis die Qiraji im Krieg der Sandstürme darüber hinwegfegten.",
			full = "Der Südwindposten war ein nachtelfischer Stützpunkt, bis die Qiraji im Krieg der Sandstürme darüber hinwegfegten. Valstann Staghelm, Sohn des Erzdruiden Fandral Staghelm, führte eine Abteilung des nachtelfischen Heeres zu seiner Verteidigung. Die Qiraji schlachteten seine Truppen ab, und General Rajaxx nahm Valstann gefangen, während hinter ihm das Dorf zerrissen wurde.\n\nDie Silithiden haben die Ruinen seither überrannt. Die Geister der Druiden und Schildwachen, die im Gemetzel fielen, verweilen zwischen den Trümmern, wandern ziellos umher, an den Ort ihres Todes gebunden und angeführt vom Schemen von Mondglanz.",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "Staghelms Stätte",
			short = "Ein nachtelfischer Turm krönt einen Gipfel im Nordosten von Silithus. Ralo'shan die ewige Wächterin hält den Posten, und ein Bronzedrache aus Nozdormus Brut kreist am Himmel darüber.",
			full = "Ein nachtelfischer Turm krönt einen Gipfel im Nordosten von Silithus. Ralo'shan die ewige Wächterin hält den Posten, und ein Bronzedrache aus Nozdormus Brut kreist am Himmel darüber.",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "Die Schwarmsäule",
			short = "Ein großer Gipfel in der Mitte von Silithus, gleich südlich der Burg Cenarius, ist von Silithidentunneln durchlöchert und von einem Bau erfüllt.",
			full = "Ein großer Gipfel in der Mitte von Silithus, gleich südlich der Burg Cenarius, ist von Silithidentunneln durchlöchert und von einem Bau erfüllt. Ein Dunst kleiner Silithiden kreist zu jeder Stunde um den Stein, eine lebende Wolke, die der Säule ihren Namen gab. Von den vielen Bauen unter den Sanden von Silithus ist dieser der größte.",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
			name = "Basislager der Twilight",
			short = "Der Kult des Schattenhammers unterhält vier Lager in den Einöden von Silithus, und dies ist eines davon, ein Stützpunkt im Staub und in den Trümmern dieses kahlgefegten Landes.",
			full = "Der Kult des Schattenhammers unterhält vier Lager in den Einöden von Silithus, und dies ist eines davon, ein Stützpunkt im Staub und in den Trümmern dieses kahlgefegten Landes. Zwielichtbewahrer Havunth ist hier stationiert, und im Lager stehen Windsteine.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Base_Camp",
		},
		["twilight outpost"] = {
			name = "Twilight-Außenposten",
			short = "Zwielichtbewahrer Exeter ist an einem Außenposten des Kults des Schattenhammers in der äußersten südwestlichen Ecke von Silithus stationiert, gleich nordwestlich des Skarabäuswalls und westlich von Bronzebeards Lager.",
			full = "Zwielichtbewahrer Exeter ist an einem Außenposten des Kults des Schattenhammers in der äußersten südwestlichen Ecke von Silithus stationiert, gleich nordwestlich des Skarabäuswalls und westlich von Bronzebeards Lager. Im Lager stehen Windsteine.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Outpost",
		},
		["twilight post"] = {
			name = "Twilight-Posten",
			short = "Windsteine stehen in einem Lager, das der Kult des Schattenhammers im Nordwesten von Silithus hält, weit westlich der Burg Cenarius und nordwestlich vom Basislager der Twilight.",
			full = "Windsteine stehen in einem Lager, das der Kult des Schattenhammers im Nordwesten von Silithus hält, weit westlich der Burg Cenarius und nordwestlich vom Basislager der Twilight. Zwielichtbewahrerin Mayna ist hier stationiert.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Post",
		},
		["twilights run"] = {
			name = "Kavernen der Twilight",
			short = "Die Kavernen der Twilight liegen im Fels verborgen am Fuß von Staghelms Stätte im Norden von Silithus.",
			full = "Die Kavernen der Twilight liegen im Fels verborgen am Fuß von Staghelms Stätte im Norden von Silithus. Eine Höhle dort ist voller Mitglieder des Kults des Schattenhammers, die die Aushöhlung im Berg zu ihrer eigenen gemacht haben, während der Wüstenwind den Stein über ihnen abschleift.",
			source = "https://warcraft.wiki.gg/wiki/Twilight's_Run",
		},
		["valors rest"] = {
			name = "Heldenwacht",
			short = "Allianz und Horde finden gleichermaßen Zuflucht in der Heldenwacht, einem kleinen Lager am Rand von Silithus, wo der Pfad aus dem Un'Goro-Krater die Wüste erreicht.",
			full = "Allianz und Horde finden gleichermaßen Zuflucht in der Heldenwacht, einem kleinen Lager am Rand von Silithus, wo der Pfad aus dem Un'Goro-Krater die Wüste erreicht. Mitglieder des Zirkels des Cenarius betreuen es, und am Rand liegen stille Gräber.",
			source = "https://warcraft.wiki.gg/wiki/Valor's_Rest",
		},
	},
	-- Winterspring: 18 subzones
	[1452] = {
		["banthallow barrow den"] = {
			name = "Grabhügel von Ban'Thallow",
			short = "Der Grabhügel von Ban'Thallow liegt im Hang hinter Starfall. Er steht ungenutzt und leer.",
			full = "Der Grabhügel von Ban'Thallow liegt im Hang hinter Starfall. Er steht ungenutzt und leer.",
			source = "https://warcraft.wiki.gg/wiki/Ban'Thallow_Barrow_Den",
		},
		["darkwhisper gorge"] = {
			name = "Die flüsternde Schlucht",
			short = "Als Archimonde in der Schlacht am Berg Hyjal fiel, lösten sich die überlebenden Dämonen der Brennenden Legion nicht auf.",
			full = "Als Archimonde in der Schlacht am Berg Hyjal fiel, lösten sich die überlebenden Dämonen der Brennenden Legion nicht auf. Sie flohen in die flüsternde Schlucht, ein Netz aus Tunneln und Abgründen im äußersten Süden von Winterspring, und suchten dort Zuflucht. Dämonen von Hederine halten sie jetzt, offenbar angeführt von Lady Hederine.",
			source = "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge",
		},
		["dun mandarr"] = {
			name = "Dun Mandarr",
			short = "Ein Zwerg namens Jaron Steinschleifer schlug neben einer eisigen Höhle im Südosten von Winterspring ein kleines Lager auf. Dann fand er ein Amulett mit blauen Federn, und das brachte die Mondkin in Rage.",
			full = "Ein Zwerg namens Jaron Steinschleifer schlug neben einer eisigen Höhle im Südosten von Winterspring ein kleines Lager auf. Dann fand er ein Amulett mit blauen Federn, und das brachte die Mondkin in Rage. Sie jagten ihn davon und zerstörten sein Lager. Nun überrennen grimmige Wesen den Ort.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
		},
		["everlook"] = {
			name = "Everlook",
			short = "Goblins des Steamwheedle-Kartells führen Everlook, einen Handelsposten, an dem sich die wichtigsten Handelswege von Winterspring kreuzen.",
			full = "Goblins des Steamwheedle-Kartells führen Everlook, einen Handelsposten, an dem sich die wichtigsten Handelswege von Winterspring kreuzen. Zwischen seinen Gebäuden steht ein Goblinlabor. Die Argentumdämmerung hat Gregor Graustein hierhergeschickt, damit er ihre Interessen gegenüber der örtlichen Leitung des Kartells vertritt.",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "Die heißen Quellen von Frostfire",
			short = "Eine Kette dampfender Teiche liegt am äußersten westlichen Ende von Winterspring, warmes Wasser in einem Land aus Eis. Niemand hat erklärt, warum die Quellen unter Schnee und Eis heiß brennen.",
			full = "Eine Kette dampfender Teiche liegt am äußersten westlichen Ende von Winterspring, warmes Wasser in einem Land aus Eis. Niemand hat erklärt, warum die Quellen unter Schnee und Eis heiß brennen. Donova Schneeweh hat in der Nähe ein Lager aufgeschlagen. Sie will wissen, warum die Quellen entstanden sind und welche Macht in ihnen steckt, und sie vermutet dämonischen Einfluss, der sie aus der flüsternden Schlucht im fernen Süden erreicht. Furbolgs vom Stamm der Winterfelle leben rund um die Teiche und halten den, der der Holzschlundfeste am nächsten liegt.",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
		},
		["frostsaber rock"] = {
			name = "Frostsäblerfelsen",
			short = "Ganz oben auf einer großen Felskuppe im Norden von Winterspring steht Rivern Frostwind von den Wintersäblerausbildern, Hüter des Bandes zwischen den Frostsäblern und denen, die sie reiten wollen.",
			full = "Ganz oben auf einer großen Felskuppe im Norden von Winterspring steht Rivern Frostwind von den Wintersäblerausbildern, Hüter des Bandes zwischen den Frostsäblern und denen, die sie reiten wollen. Er arbeitet mit der Allianz zusammen, und die schönen weißen Katzen streifen unten über den eisigen Stein.",
			source = "https://warcraft.wiki.gg/wiki/Frostsaber_Rock",
		},
		["frostwhisper gorge"] = {
			name = "Frostwhisperschlucht",
			short = "Nachtelfische Ruinen liegen verstreut über den Grund und die Grate der Frostwhisperschlucht, einer Schlucht im Süden von Winterspring.",
			full = "Nachtelfische Ruinen liegen verstreut über den Grund und die Grate der Frostwhisperschlucht, einer Schlucht im Süden von Winterspring. Eine große Brücke überspannt den Abgrund in Richtung der flüsternden Schlucht, gleich im Süden. Gewaltige Frosthagelriesen und ihre Frosthagelbewahrer leben zwischen den alten Steinen.",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["hidden grove"] = {
			name = "Der versteckte Hain",
			short = "Der versteckte Hain liegt in einem bewaldeten Krater im Nordosten von Winterspring, auf allen Seiten von hohen Klippen umschlossen. Eine einzige Höhle im südöstlichen Grat ist der einzige Weg hinein.",
			full = "Der versteckte Hain liegt in einem bewaldeten Krater im Nordosten von Winterspring, auf allen Seiten von hohen Klippen umschlossen. Eine einzige Höhle im südöstlichen Grat ist der einzige Weg hinein. An manchen Stellen ist ein Abstieg von den Höhen darüber möglich, und er ist sehr gefährlich.\n\nBevor die Mondkin kamen, lebte hier eine blühende Schar harmloser weißer Hasen. Jetzt halten die Mondkin den Hain und sind jedem feindlich gesinnt, der ihn betritt, und ihre Anwesenheit hat den Ort so sicher abgeriegelt, wie es seine Klippen je taten.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "Eisdistelberge",
			short = "Die Eisdistelberge erheben sich südöstlich von Everlook, Heimat der Eisdistelyetis, die in und um eine Höhle hoch an den Hängen leben.",
			full = "Die Eisdistelberge erheben sich südöstlich von Everlook, Heimat der Eisdistelyetis, die in und um eine Höhle hoch an den Hängen leben. Draußen auf den offenen Hängen wächst Eiskappe, und drinnen durchziehen Thoriumadern den Fels.",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "Kel'Therilsee",
			short = "Die gefrorenen Wasser des Kel'Therilsees liegen still in der Mitte von Winterspring, umringt von alten Ruinen der Hochgeborenen, die seinen Namen tragen.",
			full = "Die gefrorenen Wasser des Kel'Therilsees liegen still in der Mitte von Winterspring, umringt von alten Ruinen der Hochgeborenen, die seinen Namen tragen. Die gequälten Geister, die in den Ruinen spuken, treiben auch hinaus über das Eis.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "Mazthoril",
			short = "Tief im Eis von Winterspring, nahe der Mitte des Tals, öffnet sich die Höhle von Mazthoril unter der Erde, weit und schwer von Magie.",
			full = "Tief im Eis von Winterspring, nahe der Mitte des Tals, öffnet sich die Höhle von Mazthoril unter der Erde, weit und schwer von Magie. Hier haben die blauen Drachen, die Malygos Treue geschworen haben, ihren Hort, und hier hält ihre Matriarchin Haleh ihre einsame Wache. Sie zeigt sich nur als Hochelfe, ganz oben in der Höhle, und eine Portalrune im Boden weit unten ist der Weg hinauf.\n\nVier mächtige Drachkin bewachen den Hort. Zaubermaul geht einen langsamen Pfad um ein Drittel des unteren Tals, während Manaklaue und Seher die Runen im hinteren Teil der Höhle bewachen. Azurous streift durch die nahen Lande, auf der Suche nach Bedrohungen für die Streitkräfte von Malygos, und eine beachtliche Armee aus Zauberbrut und jungen Welpen steht hinter ihnen.",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "Mondschreckensbau",
			short = "Rasende Eulenbestien leben im Mondschreckensbau, einer kleinen Höhle, einen kurzen Fußmarsch nordöstlich von Everlooks Toren. Das Lager der Winterfelle liegt ganz in der Nähe, doch ein Berg liegt zwischen beiden.",
			full = "Rasende Eulenbestien leben im Mondschreckensbau, einer kleinen Höhle, einen kurzen Fußmarsch nordöstlich von Everlooks Toren. Das Lager der Winterfelle liegt ganz in der Nähe, doch ein Berg liegt zwischen beiden.",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "Eulenflügeldickicht",
			short = "Im Süden von Winterspring durchzieht eine Reihe von Höhlen den Fels, Heimat von Eulenbestien, die in Raserei verfallen sind, vom Mond berührt und wahnsinnig.",
			full = "Im Süden von Winterspring durchzieht eine Reihe von Höhlen den Fels, Heimat von Eulenbestien, die in Raserei verfallen sind, vom Mond berührt und wahnsinnig. Ranshalla steht am Eingang, und die uralten Wächter von Elune erzählen hier, wie die Mondkin einst in die Welt kamen.",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "Die Ruinen von Kel'Theril",
			short = "Die Ruinen von Kel'Theril liegen zerbrochen am Ufer des Sees, der ihren Namen trägt. Vor zehntausend Jahren stand hier eine große Stadt der Hochgeborenen.",
			full = "Die Ruinen von Kel'Theril liegen zerbrochen am Ufer des Sees, der ihren Namen trägt. Vor zehntausend Jahren stand hier eine große Stadt der Hochgeborenen. Die Große Zerschlagung zerstörte sie, und sie wurde nie wieder aufgebaut.\n\nDie Hochgeborenen, die dort starben, gingen nicht ins Jenseits ein. Ihre gequälten Geister wandern noch immer zwischen den gefallenen Säulen und Steinen.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "Starfall",
			short = "Die Allianz hält eine Siedlung in Winterspring, Starfall, das an der Hauptstraße steht. Eine nachtelfische Hütte und ein kleineres Haus bilden das Dorf.",
			full = "Die Allianz hält eine Siedlung in Winterspring, Starfall, das an der Hauptstraße steht. Eine nachtelfische Hütte und ein kleineres Haus bilden das Dorf.",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "Holzschlundfeste",
			short = "Die Holzschlundfeste, die Hauptstadt der Holzschlund-Furbolgs, liegt im Nordosten des Teufelswalds, und ihr Tunnel kommt hier in Winterspring wieder heraus, ebenso wie in Moonglade.",
			full = "Die Holzschlundfeste, die Hauptstadt der Holzschlund-Furbolgs, liegt im Nordosten des Teufelswalds, und ihr Tunnel kommt hier in Winterspring wieder heraus, ebenso wie in Moonglade.\n\nDie Furbolgs misstrauen allen Fremden, denn sie fürchten, für ihre verdorbenen Brüder gehalten und angegriffen zu werden. Ein Fremder, der sich als Freund erweist, erfährt, dass sie Freunde über alles schätzen. Sie besitzen keine feinen Juwelen und keinen weltlichen Reichtum, aber ihre schamanistische Tradition ist stark, und sie wissen viel über die Herstellung von Rüstungen aus Tierhäuten.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "Holzschlundposten",
			short = "Der Name sagt Holzschlund, doch das kleine Furbolglager am Holzschlundposten gehört dem verdorbenen Stamm der Winterfelle, der es vollständig hält.",
			full = "Der Name sagt Holzschlund, doch das kleine Furbolglager am Holzschlundposten gehört dem verdorbenen Stamm der Winterfelle, der es vollständig hält. Es liegt südöstlich gegenüber der Straße von den heißen Quellen von Frostfire und westlich vom Kel'Therilsee.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "Lager der Winterfelle",
			short = "Der Oberhäuptling der Winterfelle herrscht von einer kleinen Höhle an der Spitze der Siedlung aus über die verdorbenen Furbolgs im Lager der Winterfelle.",
			full = "Der Oberhäuptling der Winterfelle herrscht von einer kleinen Höhle an der Spitze der Siedlung aus über die verdorbenen Furbolgs im Lager der Winterfelle. Das Dorf zieht sich die Hänge im äußersten Osten von Winterspring hinauf, nahe Everlook.",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- Stormwind: 4 subzones
	[1453] = {
		["champions hall"] = {
			name = "Halle der Champions",
			short = "Im Süden der Altstadt haben die Offiziere der Allianz ihre Kaserne in der Halle der Champions.",
			full = "Im Süden der Altstadt haben die Offiziere der Allianz ihre Kaserne in der Halle der Champions. Im hinteren Teil versammeln sie sich um einen Tisch voller Karten von Azeroth, unter ihnen Erzmagier Gaiman von Stormwind und Stabsfeldwebel Himmelsschatten von Darnassus.",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["deeprun tram"] = {
			name = "Die Tiefenbahn",
			short = "Nach dem Zweiten Krieg eilten die Zwerge von Ironforge ihren menschlichen Verbündeten beim Wiederaufbau von Stormwind zu Hilfe, doch König Magni Bronzebeard fand, die Hilfe komme zu langsam.",
			full = "Nach dem Zweiten Krieg eilten die Zwerge von Ironforge ihren menschlichen Verbündeten beim Wiederaufbau von Stormwind zu Hilfe, doch König Magni Bronzebeard fand, die Hilfe komme zu langsam. Außerdem wollte er einen Weg, zwergische Soldaten schnell zu den Menschen zu schicken, falls der Krieg zurückkehrte. Er wandte sich an Hochtüftler Gelbin Mekkatorque, den besten Ingenieur von Azeroth, der eine Eisenbahn unter der Erde entwarf, um die beiden Hauptstädte zu verbinden.\n\nDie Erbauer stießen auf einen unterirdischen See und dann auf eine Rattenplage. Die Bahn wurde trotzdem fertig. Gnome arbeiten jeden Tag an der Strecke, und die Ratten sind nie ganz verschwunden.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["stormwind harbor"] = {
			name = "Hafen von Stormwind",
			short = "Als die Horde Stormwind plünderte, deckte Sir Anduin Lothar den Rückzug der Überlebenden zu den Kais.",
			full = "Als die Horde Stormwind plünderte, deckte Sir Anduin Lothar den Rückzug der Überlebenden zu den Kais. Sie segelten nach Lordaeron, und die meisten zurückgelassenen Schiffe wurden zerstört, damit die Orcs ihnen nicht folgen konnten. Der Hafen liegt im Nordwesten der Stadt, am Großen Meer.",
			source = "",
		},
		["valley of heroes"] = {
			name = "Das Tal der Helden",
			short = "Eine Brücke aus hellem Stein trägt jeden Reisenden über den Graben vor dem Südtor von Stormwind in ein grünes Tal, gesäumt von Statuen, die ebenso sehr aus Trauer wie zum Ruhm errichtet wurden.",
			full = "Eine Brücke aus hellem Stein trägt jeden Reisenden über den Graben vor dem Südtor von Stormwind in ein grünes Tal, gesäumt von Statuen, die ebenso sehr aus Trauer wie zum Ruhm errichtet wurden.\n\nNach dem Zweiten Krieg, als Stormwind aus seinen Trümmern wiederaufgebaut wurde, ehrte die Stadt jene, die die Expedition der Allianz durch das Dunkle Portal führten, um es von der anderen Seite zu versiegeln. Kurdran Wildhammer und Erzmagier Khadgar stehen links der Straße; Truppenkommandant Danath Trollbann und Waldläuferhauptmann Alleria Windläufer rechts; und am Ende der Straße, wo sie sich gabelt, um in die eigentliche Stadt zu führen, steht General Turalyon, der sie alle anführte. Keiner der fünf kehrte je zurück.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
	},
	-- Orgrimmar: 2 subzones
	[1454] = {
		["hall of legends"] = {
			name = "Halle der Legenden",
			short = "Die Offiziere der Horde haben ihre Kaserne in der Halle der Legenden.",
			full = "Die Offiziere der Horde haben ihre Kaserne in der Halle der Legenden. Um einen Tisch in der Mitte, auf dem Karten von Azeroth ausgebreitet sind, stehen Häuptling Erdbinder von Thunder Bluff, Berater Willington von Undercity und Blutwache Hini'wana von den Trollen der Darkspear.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Legends",
		},
		["ragefire chasm"] = {
			name = "Ragefireabgrund",
			short = "Unter Orgrimmar öffnet sich die Erde zu einem Abgrund aus Lava und Rauch. Troggs haben begonnen, aus den tiefen Tunneln zu klettern, ein Klan, den die Horde die Flammenschlundtroggs nennt.",
			full = "Unter Orgrimmar öffnet sich die Erde zu einem Abgrund aus Lava und Rauch. Troggs haben begonnen, aus den tiefen Tunneln zu klettern, ein Klan, den die Horde die Flammenschlundtroggs nennt. Magatha die Seherin von den Tauren versuchte, Frieden mit ihnen zu schließen, und stieß nur auf Feindseligkeit. Diese Kreaturen haben kein Interesse am Reden, und sich selbst überlassen könnten sie die ganze Horde überwältigen.\n\nEine Sekte des Schattenrats, die Sengende Klinge, hat sich ebenfalls in den Abgrund zurückgezogen. Taragaman der Hungerleider, eine Teufelswache, führt sie an, zusammen mit dem Hexenmeister Jergosh der Herbeirufer und dem Satyr Bazzalan. Aus ihrem Versteck planen sie den Sturz alles dessen, was die Horde in diesen Landen aufgebaut hat.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
	},
	-- Ironforge: 2 subzones
	[1455] = {
		["deeprun tram"] = {
			name = "Die Tiefenbahn",
			short = "Zwei Wagenzüge mit je drei Wagen fahren auf Doppelgleisen zwischen Ironforge und Stormwind und führen teilweise unter dem Wasser eines unterirdischen Sees hindurch.",
			full = "Zwei Wagenzüge mit je drei Wagen fahren auf Doppelgleisen zwischen Ironforge und Stormwind und führen teilweise unter dem Wasser eines unterirdischen Sees hindurch. Hochtüftler Gelbin Mekkatorque, der angesehenste Ingenieur von Azeroth, entwarf die Strecke für König Magni Bronzebeard, der einen Weg wollte, zwergische Soldaten zu den Menschen zu schicken, falls sie je gebraucht würden. Ratten überrannten die Tunnel, als sie gegraben wurden, und Gnome arbeiten jeden Tag daran, die Strecke sicher zu halten.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["gates of ironforge"] = {
			name = "Tore von Ironforge",
			short = "Die Tore von Ironforge erheben sich dort, wo die große Rampe des zentralen Dun Morogh zum Berg hinaufsteigt, ein prächtiger Anblick, meilenweit über den Schnee zu sehen.",
			full = "Die Tore von Ironforge erheben sich dort, wo die große Rampe des zentralen Dun Morogh zum Berg hinaufsteigt, ein prächtiger Anblick, meilenweit über den Schnee zu sehen. Sie bilden die Schwelle zwischen dem offenen Zwergenland und dem eigentlichen Ironforge.\n\nDrinnen steht eine riesige Statue von Hochkönig Modimus Ambossar, aufgestellt, um den Eingang zu bewachen, damit niemand die Stadt betritt, ohne unter seinem Blick hindurchzugehen.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
	},
	-- Thunder Bluff: 4 subzones
	[1456] = {
		["elder rise"] = {
			name = "Die Anhöhe der Ältesten",
			short = "Der Rat der Ältesten regiert von der Anhöhe der Ältesten aus, die direkt östlich des zentralen Tafelbergs liegt, und der Zirkel des Cenarius hat hier unter den Taurendruiden und Priestern sein Zuhause.",
			full = "Der Rat der Ältesten regiert von der Anhöhe der Ältesten aus, die direkt östlich des zentralen Tafelbergs liegt, und der Zirkel des Cenarius hat hier unter den Taurendruiden und Priestern sein Zuhause. Erzdruide Hamuul Runetotem lebt auf der Anhöhe, ein Jugendfreund von Cairne Bloodhoof. Die Hütte zwischen den beiden Brücken gehört Magatha Grimmtotem, die den Stamm der Grimmtotem anführt.",
			source = "https://warcraft.wiki.gg/wiki/Elder_Rise",
		},
		["hunter rise"] = {
			name = "Die Anhöhe der Jäger",
			short = "Die südliche Anhöhe von Thunder Bluff gehört denen, die jagen und kämpfen.",
			full = "Die südliche Anhöhe von Thunder Bluff gehört denen, die jagen und kämpfen. Fallensteller, Fährtenleser und Gerber arbeiten neben der berühmten Halle der Jäger, in der die Tauren ihre Krieger und Jäger ausbilden, und draußen stehen Übungspuppen, an denen Krieger üben können. Kampfmeister der Horde suchen hier nach Rekruten, die sie gegen die Allianz schicken.",
			source = "https://warcraft.wiki.gg/wiki/Hunter_Rise",
		},
		["pools of vision"] = {
			name = "Die Teiche der Visionen",
			short = "In einem Tunnelsystem direkt unter der Kuppe der Anhöhe der Geister haben die Verlassenen einen Stützpunkt tief im Land der Tauren.",
			full = "In einem Tunnelsystem direkt unter der Kuppe der Anhöhe der Geister haben die Verlassenen einen Stützpunkt tief im Land der Tauren. Ihre Magier und Priester versammeln sich um die Teiche der Visionen, und ein Gesandter der Entweihten der Verlassenen sucht Rekruten für den Kampf.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Vision",
		},
		["spirit rise"] = {
			name = "Die Anhöhe der Geister",
			short = "Schamanen studieren auf der Anhöhe der Geister, nordwestlich des zentralen Tafelbergs, und der Stamm der Himmelsjäger hat hier großen Einfluss.",
			full = "Schamanen studieren auf der Anhöhe der Geister, nordwestlich des zentralen Tafelbergs, und der Stamm der Himmelsjäger hat hier großen Einfluss. Die dampfenden Teiche der Visionen liegen unter der Oberfläche des Tafelbergs.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rise",
		},
	},
	-- Darnassus: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "Die Enklave des Cenarius",
			short = "Im Nordwesten von Darnassus umschließt die Enklave des Cenarius einen Hain, in dem Eichen und Eschen höher stehen als die steinernen Hallen anderswo in der Stadt.",
			full = "Im Nordwesten von Darnassus umschließt die Enklave des Cenarius einen Hain, in dem Eichen und Eschen höher stehen als die steinernen Hallen anderswo in der Stadt. Jeder Baum trägt mystische Runen, die aus seiner eigenen Rinde geformt sind. Innerhalb des Kreises versammeln sich die Druiden in Bauwerken aus lebendem Holz und sorgfältig geformtem Stein, und das größte, im Herzen des Hains, ist die Heimat des Erzdruiden Fandral Staghelm. Die Enklave trägt den Namen von Cenarius, dem uralten Halbgott, und Treants namens Beschützer von Darnassus bewachen sie anstelle von Schildwachen.\n\nDies ist der Sitz der Druiden der Stadt, so wie der Tempel des Mondes der Sitz ihrer Priester ist. Hier lernen Druiden die alten Wege, Jäger üben im östlichsten Baum der Enklave, und eine verschwiegene Gilde von Schurken hat ihr Quartier unter der Erde, nur denen bekannt, die schon wissen, wo sie suchen müssen.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "Die Terrasse der Handwerker",
			short = "Die Terrasse der Handwerker liegt im Norden von Darnassus, wo die Handwerker der Stadt ihre Läden haben und Reisende in einem ihrer Gasthäuser ein Zimmer finden.",
			full = "Die Terrasse der Handwerker liegt im Norden von Darnassus, wo die Handwerker der Stadt ihre Läden haben und Reisende in einem ihrer Gasthäuser ein Zimmer finden. Eine Botschaft der Argentumdämmerung steht ebenfalls hier, eine fremde Präsenz innerhalb der Elfenstadt.",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "Die Tempelgärten",
			short = "Im Herzen von Darnassus liegen die Tempelgärten, eine Fläche aus Wasser, Wegen und kleinen Inseln, benannt nach dem Tempel des Mondes, der unmittelbar südlich aufragt.",
			full = "Im Herzen von Darnassus liegen die Tempelgärten, eine Fläche aus Wasser, Wegen und kleinen Inseln, benannt nach dem Tempel des Mondes, der unmittelbar südlich aufragt. Brücken führen in alle Richtungen hinaus, sodass alle Straßen durch die Stadt sich hier zu sammeln scheinen. Die Inselchen tragen einige der prächtigsten Pflanzen der Stadt, und die Nachtelfen pflegen die Gewässer, damit das so bleibt. Tyrande Whisperwind hat hier meditiert.",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "Die Terrasse der Händler",
			short = "Die meisten Ladenbesitzer und Händler von Darnassus halten sich auf der Terrasse der Händler im Süden der Stadt auf. Sie ist das Handelszentrum der Nachtelfen.",
			full = "Die meisten Ladenbesitzer und Händler von Darnassus halten sich auf der Terrasse der Händler im Süden der Stadt auf. Sie ist das Handelszentrum der Nachtelfen. Ihre Gebäude sind aus Holz gewachsen, nach Art der Nachtelfen, leichte und anmutige Dinge.",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "Die Terrasse der Krieger",
			short = "Das Osttor von Darnassus, wo sich die Stadt zur Wildnis von Teldrassil öffnet, liegt auf der Terrasse der Krieger, die auch Halle der Gerechtigkeit genannt wird.",
			full = "Das Osttor von Darnassus, wo sich die Stadt zur Wildnis von Teldrassil öffnet, liegt auf der Terrasse der Krieger, die auch Halle der Gerechtigkeit genannt wird. Die Schildwachen halten hier ihr Revier, und Patrouillen auf Nachtsäblern bewachen die Tore. Nachtelfen mit militärischem Rang trainieren auf den Schießständen und Duellplätzen, und die Terrasse ist der Schild der Stadt gegen alles, was die Straße aus dem Wald heraufkommt.",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
	},
	-- Undercity: 1 subzones
	[1458] = {
		["ruins of lordaeron"] = {
			name = "Ruinen von Lordaeron",
			short = "Über der vergrabenen Stadt steht noch der Palast von Lordaeron, seine Hallen zum Himmel offen und seine Gärten verwildert.",
			full = "Über der vergrabenen Stadt steht noch der Palast von Lordaeron, seine Hallen zum Himmel offen und seine Gärten verwildert. Prinz Arthas Menethil kehrte an der Spitze eines Heeres dorthin zurück, durch die Tore empfangen von Glocken und Jubel, bevor irgendjemand begriff, was aus ihm geworden war. Im Thronsaal tötete er seinen Vater, König Terenas, und die Geißel zerstörte die Hauptstadt. Das Königreich fiel.\n\nDie Ruinen haben den Klang jenes Tages bewahrt. Glocken dröhnen im Eingang, ein leiser Jubel begrüßt den Prinzen, und Stimmen murmeln im Thronsaal, wo Arthas zu hören ist, wie er erklärt, dass das Königreich fallen und aus seiner Asche eine neue Ordnung entstehen wird. Die Geister der Bürger von Lordaeron spuken noch immer im Hof, und Schattenhunde und Nachtsauger streifen jenseits der Mauern.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
	},
	-- Hyjal: 3 subzones
	[2482] = {
		["cradle of tranquility"] = {
			name = "Wiege der Ruhe",
			short = "Jereman, ein Schreckensrabe und ein Geist der Wildnis, lebt in der Wiege der Ruhe.",
			full = "Jereman, ein Schreckensrabe und ein Geist der Wildnis, lebt in der Wiege der Ruhe.",
			source = "",
		},
		["malornes retreat"] = {
			name = "Malornes Zuflucht",
			short = "Hier liegt ein tiefes, dicht bewaldetes Tal mit einer großen Höhle an seinem Rand. Furbolgs haben die Höhle zu ihrem Zuhause gemacht, und sie sind feindselig.",
			full = "Hier liegt ein tiefes, dicht bewaldetes Tal mit einer großen Höhle an seinem Rand. Furbolgs haben die Höhle zu ihrem Zuhause gemacht, und sie sind feindselig.",
			source = "",
		},
		["mournings rest"] = {
			name = "Klageruh",
			short = "Marrosis, ein Geier und ein Geist der Wildnis, lebt am Ruheplatz der Trauer.",
			full = "Marrosis, ein Geier und ein Geist der Wildnis, lebt am Ruheplatz der Trauer.",
			source = "",
		},
	},
	-- Insel Zephras: 22 subzones
	[2521] = {
		["bandit hideout"] = {
			name = "Banditenversteck",
			short = "Banditen verstecken sich hier und stehlen Windsteine, um über die Runden zu kommen.",
			full = "Banditen verstecken sich hier und stehlen Windsteine, um über die Runden zu kommen. Manche von ihnen sind Flüchtlinge aus Siedlungen, die zerfielen, und sie wandten sich dem Verbrechen zu, als sie nirgendwo sonst hin konnten.",
			source = "",
		},
		["east pylon watchtower"] = {
			name = "Die Ostpylonenwacht",
			short = "Kultisten der Al'Aketh greifen die Ostpylonenwacht immer wieder an. Die Pylonen, nach denen sie benannt ist, sind uralte Anker, Geschenke der Windgeister, die die Insel in der Luft halten.",
			full = "Kultisten der Al'Aketh greifen die Ostpylonenwacht immer wieder an. Die Pylonen, nach denen sie benannt ist, sind uralte Anker, Geschenke der Windgeister, die die Insel in der Luft halten.",
			source = "",
		},
		["falaath village"] = {
			name = "Falaath",
			short = "Der Al'Aketh-Kult besetzt das Dorf Falaath. Hier lebte ein Schneider namens Zendraas, und als die Kultisten sein Zuhause übernahmen, zog er ihre Roben an und bekannte sich zu ihrem Glauben.",
			full = "Der Al'Aketh-Kult besetzt das Dorf Falaath. Hier lebte ein Schneider namens Zendraas, und als die Kultisten sein Zuhause übernahmen, zog er ihre Roben an und bekannte sich zu ihrem Glauben. Später entwarf er einen großen Teil ihrer Kleidung. Manche im Kult schlossen sich an, um am Leben zu bleiben, und teilen keinen seiner Glaubenssätze.",
			source = "",
		},
		["gustberry lowlands"] = {
			name = "Böenbeerentiefland",
			short = "Ein Fluss durchzieht das Böenbeerentiefland. An seinem Ufer leben Frösche, Schmetterlinge fliegen über das Land, und Wolkenreitermatriarchinnen ziehen mit ihren Jungen umher.",
			full = "Ein Fluss durchzieht das Böenbeerentiefland. An seinem Ufer leben Frösche, Schmetterlinge fliegen über das Land, und Wolkenreitermatriarchinnen ziehen mit ihren Jungen umher. Auch Kultisten der Al'Aketh, angeführt von einem Kommandanten namens Belguilos, sind eingezogen.",
			source = "",
		},
		["overlook standing stones"] = {
			name = "Die Menhire der Warte",
			short = "Windlinge, winzige Luftelementare, huschen zwischen den Menhiren der Warte umher. Sie quieken und verschwinden, wenn man sie erschreckt.",
			full = "Windlinge, winzige Luftelementare, huschen zwischen den Menhiren der Warte umher. Sie quieken und verschwinden, wenn man sie erschreckt.",
			source = "",
		},
		["rohashi spires"] = {
			name = "Die Türme der Rohashi",
			short = "Die Türme der Rohashi ragen am Himmel über dem Schrein von Akir auf. Luftelementare, die dem Windfürsten treu sind, versammeln sich auf ihnen und rufen Stürme an ihre Seite.",
			full = "Die Türme der Rohashi ragen am Himmel über dem Schrein von Akir auf. Luftelementare, die dem Windfürsten treu sind, versammeln sich auf ihnen und rufen Stürme an ihre Seite.",
			source = "",
		},
		["ruins of banaethal"] = {
			name = "Ruinen von Ban'aethal",
			short = "Die Magieschmiede von Ban'aethal waren die besten Kunsthandwerker der Inseln der Himmelsbewohner.",
			full = "Die Magieschmiede von Ban'aethal waren die besten Kunsthandwerker der Inseln der Himmelsbewohner. Als die Magie, die die Siedlung hielt, versagte, floh ihr Volk in der Nacht, als sie in den Himmel zu fallen begann, und ließ seine Habe zurück. Windhüllen, geisterhafte Luftelementare, treiben jetzt zwischen den Ruinen.",
			source = "",
		},
		["shadowgale forest"] = {
			name = "Schattenwindwald",
			short = "Die Druiden der Nachtklaue, ein verschwiegener Zirkel, leben im Schattenwindwald und halten sich von jeder anderen Fraktion der Insel fern.",
			full = "Die Druiden der Nachtklaue, ein verschwiegener Zirkel, leben im Schattenwindwald und halten sich von jeder anderen Fraktion der Insel fern. Der Al'Aketh-Kult hat sie angegriffen. Seit die Windgeister verschwunden sind, tauchen Windhüllen zwischen den Bäumen auf. Diese geisterhaften Überreste wirken voller Bosheit und Reue, und in ihrer Nähe ist ein trauriger Gesang zu hören.",
			source = "",
		},
		["shendar highlands"] = {
			name = "Shen'darhochland",
			short = "Die Windformer, Schamanen, die mit den Elementargeistern Zwiesprache halten, beschützen die Menhire im Shen'darhochland, einem heiligen Ort der Elementarmagie.",
			full = "Die Windformer, Schamanen, die mit den Elementargeistern Zwiesprache halten, beschützen die Menhire im Shen'darhochland, einem heiligen Ort der Elementarmagie. Banditen streifen ebenfalls durch das Hochland.",
			source = "",
		},
		["shendar village"] = {
			name = "Shen'dar",
			short = "Das Gasthaus im Dorf Shen'dar heißt Ruhbrise. In Befehlen, die dem Kult abgenommen wurden, ist von einem Spitzel unter den Dorfbewohnern die Rede.",
			full = "Das Gasthaus im Dorf Shen'dar heißt Ruhbrise. In Befehlen, die dem Kult abgenommen wurden, ist von einem Spitzel unter den Dorfbewohnern die Rede.",
			source = "",
		},
		["shriekling den"] = {
			name = "Kreischlingsbau",
			short = "Kreischlinge nisten in diesem Bau, und ihre Matriarchin lebt im Inneren.",
			full = "Kreischlinge nisten in diesem Bau, und ihre Matriarchin lebt im Inneren.",
			source = "",
		},
		["shrine of akir"] = {
			name = "Schrein von Akir",
			short = "Der Schrein von Akir wird vom Al'Aketh-Kult gehalten.",
			full = "Der Schrein von Akir wird vom Al'Aketh-Kult gehalten. Wächter, Klingenmeister, Ehrenwachen, Geisterrufer und Himmelspriester halten dort Wache, unter ihnen Zaal Stormshield und Tel'daeor der Sturmsprecher, und auch Bruder Zendraas dient dort.",
			source = "",
		},
		["skywall"] = {
			name = "Der Himmelswall",
			short = "Der Himmelswall ist die elementare Ebene der Luft, ein Reich, das von uralten Windgeistern beherrscht wird, und Zephras hängt darin.",
			full = "Der Himmelswall ist die elementare Ebene der Luft, ein Reich, das von uralten Windgeistern beherrscht wird, und Zephras hängt darin. Zwei weitere Inseln der Himmelsbewohner, Anvilas und Siroccas, schweben ebenfalls irgendwo darin, doch der Kontakt zu ihnen riss ab, als die Windgeister verschwanden.",
			source = "",
		},
		["thendal grove"] = {
			name = "Thendalhain",
			short = "Waldläufer wachen über den Thendalhain, von dem aus man hinüber zu einer der uralten Pylonen der Insel blickt. Seine Magie ist instabil und ungleichmäßig geworden.",
			full = "Waldläufer wachen über den Thendalhain, von dem aus man hinüber zu einer der uralten Pylonen der Insel blickt. Seine Magie ist instabil und ungleichmäßig geworden.",
			source = "",
		},
		["thendal standing stones"] = {
			name = "Die Menhire von Thendal",
			short = "Eine Leylinie ist bei den Menhiren von Thendal durch den Boden gebrochen, wie in letzter Zeit mehrere auf ganz Zephras, und bringt arkane Energie nah an die Oberfläche.",
			full = "Eine Leylinie ist bei den Menhiren von Thendal durch den Boden gebrochen, wie in letzter Zeit mehrere auf ganz Zephras, und bringt arkane Energie nah an die Oberfläche. Einfache Windlinge treiben hier, die auf die Stimmungen und Absichten jedes Anwesenden in ihrer Nähe antworten, und die Al'Aketh haben sie aufgewiegelt. Elementare der Tosenden Winde und Bekehrte des Kults streifen zwischen den Steinen umher.",
			source = "",
		},
		["thendal village"] = {
			name = "Thendal",
			short = "Die Waldläufer des Thendalhains patrouillieren durch die Wälder um das Dorf Thendal, ihre Heimat. Die Bewohner wissen seit einiger Zeit von den Al'Aketh und haben sich damit begnügt, den Kult aus der Ferne zu beobachten.",
			full = "Die Waldläufer des Thendalhains patrouillieren durch die Wälder um das Dorf Thendal, ihre Heimat. Die Bewohner wissen seit einiger Zeit von den Al'Aketh und haben sich damit begnügt, den Kult aus der Ferne zu beobachten.",
			source = "",
		},
		["valanaar"] = {
			name = "Valanaar",
			short = "Friedensbewahrer, die Miliz der Insel, wachen über die Straßen von Valanaar, einer Stadt der Himmelsbewohner mit einer Waffenhalle, einer Hafenbehörde und einem Gasthaus Ruhbrise.",
			full = "Friedensbewahrer, die Miliz der Insel, wachen über die Straßen von Valanaar, einer Stadt der Himmelsbewohner mit einer Waffenhalle, einer Hafenbehörde und einem Gasthaus Ruhbrise.",
			source = "",
		},
		["valanaar skydocks"] = {
			name = "Himmelsdocks von Valanaar",
			short = "Himmelskutter, die Luftschiffe, mit denen die Himmelsbewohner zwischen ihren Siedlungen reisen, legen hier an. Flüchtlinge kamen auf einigen der letzten an, bevor ihre Inseln auseinanderbrachen.",
			full = "Himmelskutter, die Luftschiffe, mit denen die Himmelsbewohner zwischen ihren Siedlungen reisen, legen hier an. Flüchtlinge kamen auf einigen der letzten an, bevor ihre Inseln auseinanderbrachen.",
			source = "",
		},
		["west pylon watchtower"] = {
			name = "Die Westpylonenwacht",
			short = "Krieger der Al'Aketh halten die Westpylonenwacht, und ganz oben steht ein Himmelspriester des Kults.",
			full = "Krieger der Al'Aketh halten die Westpylonenwacht, und ganz oben steht ein Himmelspriester des Kults.",
			source = "",
		},
		["windfield orchard"] = {
			name = "Obsthain der Windfields",
			short = "Die Familie Windfield betreibt hier einen Obstgarten. Ein riesiges Konstrukt aus der Zeit der Windgeister wandert seit Jahrzehnten über die Felder.",
			full = "Die Familie Windfield betreibt hier einen Obstgarten. Ein riesiges Konstrukt aus der Zeit der Windgeister wandert seit Jahrzehnten über die Felder. Die Familie glaubt, es habe einst Ernten geschleppt oder Vieh gehütet, damals, als das Land noch kein Obstgarten war, vielleicht vor tausend Jahren. Sie ignoriert es meistens.",
			source = "",
		},
		["windsong lake"] = {
			name = "Windweisensee",
			short = "Einige der Konstrukte, die die Windgeister den Himmelsbewohnern gaben, stürzten in den Windweisensee, als die Pylonen versagten. Ein Dreschadon, bekannt als der Verlorene, lebt in seinen Wassern.",
			full = "Einige der Konstrukte, die die Windgeister den Himmelsbewohnern gaben, stürzten in den Windweisensee, als die Pylonen versagten. Ein Dreschadon, bekannt als der Verlorene, lebt in seinen Wassern.",
			source = "",
		},
		["windsong standing stones"] = {
			name = "Die Menhire der Windweisen",
			short = "Kleine Luftelementare, Windlinge genannt, leben zwischen den Menhiren der Windweisen.",
			full = "Kleine Luftelementare, Windlinge genannt, leben zwischen den Menhiren der Windweisen.",
			source = "",
		},
	},
	-- Flusslande: 11 subzones
	[2548] = {
		["ashwoods fall"] = {
			name = "Ashwood's Fall",
			short = "Zerstörte Wagen liegen um einen ruinierten Wachturm, und Schutt und hölzerne Barrikaden füllen seine zerbrochenen Mauern.",
			full = "Zerstörte Wagen liegen um einen ruinierten Wachturm, und Schutt und hölzerne Barrikaden füllen seine zerbrochenen Mauern. Rosalind Ashwood, eine Späherin der Bruderschaft, ritt nach Windhof, um die dortigen Familien vor einem bevorstehenden Angriff der Horde zu warnen, und führte einen Konvoi von ihnen in Richtung Farholde. Die Horde holte den Konvoi an einem Wachturm ein, und niemand überlebte. Die Wagen und der Name legen nahe, dass dies jener Turm ist.",
			source = "",
		},
		["bolderok"] = {
			name = "Bolder'ok",
			short = "Oger halten Bolder'ok, eine Siedlung nordwestlich von Windhof. Sie standen einst beim Schattenhammer, haben ihn aber verlassen und sich mit der Horde verbündet.",
			full = "Oger halten Bolder'ok, eine Siedlung nordwestlich von Windhof. Sie standen einst beim Schattenhammer, haben ihn aber verlassen und sich mit der Horde verbündet.",
			source = "",
		},
		["farholde keep"] = {
			name = "Burg Farholde",
			short = "Farholde liegt auf einer Küsteninsel, die die Ritter der Bruderschaft des Pferdes wegen ihrer natürlichen Verteidigung wählten.",
			full = "Farholde liegt auf einer Küsteninsel, die die Ritter der Bruderschaft des Pferdes wegen ihrer natürlichen Verteidigung wählten. Sie befestigten sie mit den Überlebenden, die sie im Ersten Krieg gerettet hatten, weil die Horde den Heimweg versperrt hatte.\n\nJahre nach dem Zweiten Krieg belagerte ein Heer der Horde die Burg. Plünderer kamen über das Wasser und sabotierten die seetüchtigen Schiffe, die dort vertäut lagen, sodass niemand fliehen oder Hilfe holen konnte. Familien drängten sich im Inneren, die Rationen wurden knapp, und die Moral sank. In der Nacht schlich sich ein Agent der Bruderschaft namens Fern Crimsonleaf in das Lager der Feinde und tötete die Anführer der Horde. Im Morgengrauen führte Sir Howard Armstrong einen Sturmangriff aus dem Tor. Die Soldaten der Horde warteten auf Befehle, die nie kamen, und zerstreuten sich und flohen. Howard und mehrere seiner Gefährten starben im Sturmangriff. Ihre Denkmäler stehen in der Burg, und Demar Brant, der Ritterkommandant, hält sie noch immer.",
			source = "",
		},
		["kroldok stronghold"] = {
			name = "Feste Krol'dok",
			short = "Die Feste Krol'dok ist eine Ogerfestung. Das Heer der Horde, das Farholde belagert hatte, zog sich dorthin zurück, als die Belagerung zusammenbrach.",
			full = "Die Feste Krol'dok ist eine Ogerfestung. Das Heer der Horde, das Farholde belagert hatte, zog sich dorthin zurück, als die Belagerung zusammenbrach.",
			source = "",
		},
		["meadowsbrook"] = {
			name = "Wiesenbach",
			short = "Ritter, die die Gefangenen von Sonnengrund gerettet hatten, fanden den Heimweg von der Horde abgeschnitten und ließen sich mit den Überlebenden hier nieder.",
			full = "Ritter, die die Gefangenen von Sonnengrund gerettet hatten, fanden den Heimweg von der Horde abgeschnitten und ließen sich mit den Überlebenden hier nieder. Nach einiger Zeit stieß ein Trupp der Bruderschaft, der sich vor der Horde zurückzog, auf das Dorf, und seine Hilfe verschaffte der Bruderschaft einen Halt in den Flussauen.",
			source = "",
		},
		["powderfuse port"] = {
			name = "Hafen von Powderfuse",
			short = "Melbin Powderfuse, ein Goblin-Ingenieur, behauptet, er habe alles in diesem Hafen an der Ostküste gebaut und besitze alles davon. Er sagt, der Ort sei ein leeres Grundstück gewesen, als er ankam.",
			full = "Melbin Powderfuse, ein Goblin-Ingenieur, behauptet, er habe alles in diesem Hafen an der Ostküste gebaut und besitze alles davon. Er sagt, der Ort sei ein leeres Grundstück gewesen, als er ankam. Jazzle Cheapshot richtet hier eine Arena ein, die noch nicht läuft, und er beschwert sich, dass Horde und Allianz auf den Feldern gegeneinander kämpfen, statt dafür zu zahlen, in seiner zu kämpfen.",
			source = "",
		},
		["rogmar"] = {
			name = "Rog'mar",
			short = "Die Horde unterhält in den Flussauen bei Rog'mar eine ihrer wichtigsten Siedlungen.",
			full = "Die Horde unterhält in den Flussauen bei Rog'mar eine ihrer wichtigsten Siedlungen.",
			source = "",
		},
		["sunnyglade"] = {
			name = "Sonnengrund",
			short = "Sonnengrund war eine reiche und blühende Stadt des Königreichs Stormwind.",
			full = "Sonnengrund war eine reiche und blühende Stadt des Königreichs Stormwind. Im Ersten Krieg zerstörte die Alte Horde den größten Teil davon und nahm die Überlebenden als Sklaven, verschonte aber einen Magierturm, damit die Orcs lernen konnten, wie menschliche Magie funktionierte. Später hielt die Bruderschaft des Pferdes die Ruinen. Als die Horde erneut kam, hielt Roderick der Ungebrochene, ein Hauptmann der Bruderschaft, hier eine Brücke, während ein Späher Nachricht nach Farholde trug. Er verlor einen Arm und überlebte. Der Schattenhammer hält jetzt die Ruinen, und der Magierturm steht noch.",
			source = "",
		},
		["terrals watch"] = {
			name = "Terrals Wacht",
			short = "Über dem verriegelten Eingang von Terrals Wacht, einem steinernen Wachturm, dessen obere Mauern teilweise eingestürzt sind, hängt ein Banner mit einem Pferdewappen.",
			full = "Über dem verriegelten Eingang von Terrals Wacht, einem steinernen Wachturm, dessen obere Mauern teilweise eingestürzt sind, hängt ein Banner mit einem Pferdewappen. Eine breite Steintreppe führt hinauf zur Tür, mit je einer brennenden Lampe zu beiden Seiten.",
			source = "",
		},
		["wheelers grange"] = {
			name = "Wheelers Gehöft",
			short = "Benjy Wheeler steht vor dem Bauernhaus dieses Gehöfts nahe Burg Farholde, und feindselige Ernteschnitter drängen sich auf seinen Feldern.",
			full = "Benjy Wheeler steht vor dem Bauernhaus dieses Gehöfts nahe Burg Farholde, und feindselige Ernteschnitter drängen sich auf seinen Feldern.",
			source = "",
		},
		["windstead"] = {
			name = "Windhof",
			short = "Familien, die der Zerstörung von Sonnengrund entkamen, fanden einen in den Bergen verborgenen See und gründeten daneben Windhof, aus Angst, die Horde könnte sie eines Tages finden.",
			full = "Familien, die der Zerstörung von Sonnengrund entkamen, fanden einen in den Bergen verborgenen See und gründeten daneben Windhof, aus Angst, die Horde könnte sie eines Tages finden. Nach Jahren der Abgeschiedenheit schlugen die Dorfbewohner die Warnung von Farholde in den Wind, dass es sie in einer großen Schlacht nicht schützen könne. Einige gingen über die Küste und einige über die Straße, als die Gefahr nahe kam. Das Dorf steht nun leer, und Piraten des Ostmeers besetzen seine Ruinen.",
			source = "",
		},
	},
	-- Shen'dralas: 2 subzones
	[2652] = {
		["bristleback retreat"] = {
			name = "Rückzugsort der Borstennacken",
			short = "Borstennacken-Stacheleber unterhalten eine kleine Siedlung im Rückzugsort der Borstennacken.",
			full = "Borstennacken-Stacheleber unterhalten eine kleine Siedlung im Rückzugsort der Borstennacken.",
			source = "",
		},
		["evenshades overlook"] = {
			name = "Evenshades Warte",
			short = "Erzmagier Mordent Schattenfall ist hier zu finden, vor den Ruinen nördlich der Stadt. Er ist ein Hochgeborener der Shen'dralar und nennt die Stadt noch immer bei ihrem wahren Namen, Eldre'Thalas.",
			full = "Erzmagier Mordent Schattenfall ist hier zu finden, vor den Ruinen nördlich der Stadt. Er ist ein Hochgeborener der Shen'dralar und nennt die Stadt noch immer bei ihrem wahren Namen, Eldre'Thalas. Er sagt, der Tempel und sein Gelände seien nach Tausenden von Jahren in einem traurigen Zustand und Shen'dralas sei eine heimgesuchte Hülle dessen, was es einst war. Die Stadt überstand die Große Zerschlagung, doch so viele seines Volkes starben, dass er es nicht vergessen kann. Er blickt hinaus auf ein Massengrab seiner Verwandten. Er hat keine anderen Überlebenden getroffen, abgesehen von denen seines Ordens, die mit Prinz Tortheldrin tief in der Stadt abgeschieden bleiben, und er verbringt wenig Zeit in der Bibliothek, die er einst sein Zuhause nannte.",
			source = "",
		},
	},
}

